const SUPABASE_BUCKET_DOCS = "empleados-docs";
const SUPABASE_BUCKET_MEMORANDOS = SUPABASE_BUCKET_DOCS; // reutiliza el bucket existente

function slugifyPathSegment(texto) {
  if (!texto) return "archivo";
  let value = String(texto);
  if (typeof value.normalize === "function") {
    value = value.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  }
  value = value.replace(/[^a-zA-Z0-9]+/g, "-").replace(/^-+|-+$/g, "").toLowerCase();
  return value || "archivo";
}

/* ====================== NOTIFICACIONES SMS (TWILIO) ====================== */

// Función para formatear número de teléfono colombiano (sin + para Onurix)
function formatearTelefonoColombia(telefono) {
  if (!telefono) return null;
  let num = telefono.toString().replace(/\D/g, ''); // Solo dígitos
  
  // Si es número colombiano de 10 dígitos que empieza con 3, agregar 57
  if (num.length === 10 && num.startsWith('3')) {
    return '57' + num;
  }
  // Si ya tiene código de país (12 dígitos: 57 + 10), devolverlo limpio
  if (num.length === 12 && num.startsWith('57')) {
    return num;
  }
  // Si tiene 13 dígitos y empieza con 57, quitar el dígito extra
  if (num.length === 13 && num.startsWith('57')) {
    return num.slice(0, 12);
  }
  return num;
}

// Función para enviar SMS via API de Twilio
async function enviarSMS(telefono, mensaje) {
  if (!telefono) {
    console.warn("📱 No se puede enviar SMS: teléfono no proporcionado");
    return { ok: false, error: "Teléfono no proporcionado" };
  }

  // Formatear número antes de enviar
  const telefonoFormateado = formatearTelefonoColombia(telefono);
  console.log("📱 Enviando SMS a:", telefonoFormateado, "(original:", telefono, ")");

  try {
    // URL de la API de SMS en la intranet (Vercel)
    const API_SMS_URL = "https://intranetbigburguer.com/api/enviar-sms";
    
    const response = await fetch(API_SMS_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ telefono: telefonoFormateado, mensaje }),
    });

    const data = await response.json();

    if (!response.ok) {
      console.error("❌ Error enviando SMS:", data);
      return { ok: false, error: data.error || "Error al enviar SMS" };
    }

    console.log("✅ SMS enviado correctamente:", data);
    return { ok: true, sid: data.sid };
  } catch (error) {
    console.error("❌ Error de red al enviar SMS:", error);
    return { ok: false, error: error.message };
  }
}

// Función para notificar a un empleado por SMS sobre una nueva tarea asignada
async function notificarTareaAsignada(empleado, tarea) {
  if (!empleado?.telefono) {
    console.warn("📱 Empleado sin teléfono registrado, no se puede notificar");
    return;
  }

  const mensaje = `Nueva tarea asignada
Tipo: ${tarea.tipo || "Tarea"}
Sede: ${typeof tarea.sede === "object" ? tarea.sede?.nombre : tarea.sede || "N/A"}
Fecha limite: ${tarea.fechaLimite || "Sin fecha"}
Revise la intranet.`;

  return enviarSMS(empleado.telefono, mensaje);
}

// Función para notificar a un empleado sobre respuesta a su solicitud
async function notificarRespuestaSolicitud(empleado, solicitud, estado) {
  if (!empleado?.telefono) {
    console.warn("📱 Empleado sin teléfono registrado, no se puede notificar");
    return;
  }

  let mensaje = "";
  
  if (estado === "aprobado") {
    mensaje = `Su solicitud ha sido APROBADA. Ingrese a la intranet para ver los detalles.`;
  } else if (estado === "negado") {
    mensaje = `Su solicitud ha sido RECHAZADA. Ingrese a la intranet para ver los detalles.`;
  } else if (estado === "en_proceso") {
    mensaje = `Solicitud con REQUERIMIENTO. Ingrese a la intranet para ver los detalles y responder.`;
  } else {
    mensaje = `Su solicitud ha sido actualizada. Ingrese a la intranet para ver los detalles.`;
  }

  return enviarSMS(empleado.telefono, mensaje);
}

// Función para notificar a un empleado sobre una nueva solicitud del empleador
async function notificarSolicitudEmpleador(empleado, solicitud) {
  if (!empleado?.telefono) {
    console.warn("📱 Empleado sin teléfono registrado, no se puede notificar");
    return { ok: false, error: "Empleado sin teléfono" };
  }

  const mensaje = `BIGBURGUER - Nueva solicitud del empleador. 
Asunto: ${solicitud.asunto || "Solicitud"}
Ingrese a la intranet para ver los detalles y responder.`;

  return enviarSMS(empleado.telefono, mensaje);
}

