// Función helper para generar el resumen ejecutivo a partir de una nómina
function generarResumenEjecutivo(nomina, mesNomina, quincena) {
  const items = nomina.items || [];
  
  // Extraer año y mes del rango
  const fechaInicio = nomina.rango?.inicio || new Date().toISOString().slice(0, 10);
  const partes = fechaInicio.split("-");
  const anio = parseInt(partes[0]) || new Date().getFullYear();
  const mesNumero = parseInt(partes[1]) || (new Date().getMonth() + 1);
  
  // Calcular totales
  const totales = items.reduce((acc, item) => {
    acc.devengado += Math.round((item.bruto || 0) + (item.auxTransp || 0) + (item.adicionales?.bonificacion || 0) + (item.incapacidad?.valorTotal || 0));
    acc.salud += item.descuentos?.salud || 0;
    acc.pension += item.descuentos?.pension || 0;
    acc.prestamos += item.descuentos?.prestamos || 0;
    acc.comidas += item.descuentos?.comida || 0;
    acc.otrosDescuentos += item.descuentos?.otrosDescuentos || 0;
    acc.descuentos += (item.descuentos?.salud || 0) + (item.descuentos?.pension || 0) + 
                      (item.descuentos?.prestamos || 0) + (item.descuentos?.comida || 0) + 
                      (item.descuentos?.otrosDescuentos || 0);
    acc.neto += Math.round(item.neto || 0);
    acc.auxTransporte += item.auxTransp || 0;
    acc.bonificaciones += item.adicionales?.bonificacion || 0;
    acc.incapacidades += item.incapacidad?.valorTotal || 0;
    return acc;
  }, {
    devengado: 0, salud: 0, pension: 0, prestamos: 0, comidas: 0, 
    otrosDescuentos: 0, descuentos: 0, neto: 0, auxTransporte: 0, 
    bonificaciones: 0, incapacidades: 0
  });

  // Periodo en formato "YYYY-MM-QX"
  const periodo = `${anio}-${String(mesNumero).padStart(2, '0')}-Q${quincena}`;

  return {
    id: `resumen_${nomina.id}`,
    periodo: periodo,
    quincena: quincena,
    mes: mesNomina,
    anio: anio,
    mesNumero: mesNumero,
    fechaGeneracion: new Date().toISOString(),
    rangoInicio: nomina.rango?.inicio,
    rangoFin: nomina.rango?.fin,
    totalEmpleados: items.length,
    totalDevengado: totales.devengado,
    totalDescuentos: totales.descuentos,
    totalNeto: totales.neto,
    totalSalud: totales.salud,
    totalPension: totales.pension,
    totalPrestamos: totales.prestamos,
    totalComidas: totales.comidas,
    totalOtrosDescuentos: totales.otrosDescuentos,
    totalAuxTransporte: totales.auxTransporte,
    totalBonificaciones: totales.bonificaciones,
    totalIncapacidades: totales.incapacidades,
    empleadosDetalle: items.map(item => ({
      id: item.empleadoId,
      nombre: item.empleadoNombre,
      documento: item.documento,
      cargo: item.empleadoCargo,
      bruto: item.bruto,
      neto: item.neto,
    })),
    detalleCompleto: {
      nombre: nomina.nombre,
      fechaCreacion: nomina.fechaCreacion,
      items: items,
    },
  };
}

// Guardar nómina en Supabase
async function guardarNominaEnSupabase(nomina, empresaId = null) {
  try {
    console.log("📝 Guardando nómina en Supabase:", JSON.stringify(nomina, null, 2));
    
    // Guardar un registro por cada empleado en la nómina
    if (!nomina.items || nomina.items.length === 0) {
      console.warn("⚠️ No hay empleados en la nómina");
      return true;
    }

    const detallesPrestamos = nomina.detallesPrestamos || [];
    let todosGuardados = true;

    for (const item of nomina.items) {
      // Encontrar detalle de préstamos para este empleado
      const detallePrestamo = detallesPrestamos.find(
        (dp) => dp.empleadoId === item.empleadoId
      ) || { totalPrestamos: 0, detallePrestamosFull: [], cuotasProcesadas: [] };

      // Mapear a campos de Supabase
      const registroNomina = {
        id: `${nomina.id}_${item.empleadoId}`,
        empleadoid: item.empleadoId,
        periodo: nomina.rango?.inicio || new Date().toISOString(),
        fechageneracion: nomina.fechaCreacion || new Date().toISOString(),
        salariobase: item.bruto || 0,
        horasextras: item.detalleHoras?.hExDia || 0,
        valorextras: (item.detalleHoras?.hExDia || 0) * 8088, // Tarifa hora extra diurna
        bonificacion: item.adicionales?.bonificacion || 0,
        auxtransporte: item.auxTransp || 0,
        descuentosalud: item.descuentos?.salud || 0,
        descuentopension: item.descuentos?.pension || 0,
        descuentoarl: 0,
        descuentoprestamos: detallePrestamo.totalPrestamos || 0,
        descuentocomida: item.descuentos?.comida || 0,
        otros_descuentos: item.descuentos?.otrosDescuentos || 0,
        detalle_otros_descuentos: item.descuentos?.detalleOtros || [],
        detalle_horas_completo: { 
          ...(item.detalleHoras || { hNorm: 0, hNoct: 0, hFest: 0, hExDia: 0, hExNoc: 0, hExFest: 0 }),
          metodoLiquidacion: item.metodoLiquidacion || "con_recargos"
        },
        horas_totales: { 
          ...(item.horasTotales || item.detalleHoras || { hNorm: 0, hNoct: 0, hFest: 0, hExDia: 0, hExNoc: 0, hExFest: 0 }),
          metodoLiquidacion: item.metodoLiquidacion || "con_recargos"
        },
        detalle_por_fecha: item.detallePorFecha || [],
        detalle_prestamos: detallePrestamo.detallePrestamosFull || [],
        cuotas_procesadas: detallePrestamo.cuotasProcesadas || [],
        incapacidad_data: item.incapacidad || { dias: 0, valorDiario: 0, valorTotal: 0 },
        // Ajustes de nómina
        ajustes_nomina: item.ajustes || { sumaEmpleado: 0, restaEmpresa: 0, netoAjuste: 0, detalle: [], cantidad: 0 },
        totaldescuentos: 
          (item.descuentos?.salud || 0) +
          (item.descuentos?.pension || 0) +
          (item.descuentos?.prestamos || 0) +
          (item.descuentos?.comida || 0) +
          (item.descuentos?.otrosDescuentos || 0) +
          (item.ajustes?.restaEmpresa || 0),
        totaldevengado: item.bruto + (item.auxTransp || 0) + (item.adicionales?.bonificacion || 0) + (item.ajustes?.sumaEmpleado || 0),
        totalneto: item.neto || 0,
        estado: "Procesada",
      };
      
      // Agregar empresa_id si está disponible
      if (empresaId) {
        registroNomina.empresa_id = empresaId;
      }

      console.log(
        `📤 Guardando nómina para empleado ${item.empleadoId}:`,
        JSON.stringify(registroNomina, null, 2)
      );

      const { error } = await supabase
        .from("nominas")
        .upsert([registroNomina], { onConflict: "id" });

      if (error) {
        console.error(
          `❌ Error guardando nómina para empleado ${item.empleadoId}:`,
          error
        );
        todosGuardados = false;
      } else {
        console.log(`✅ Nómina guardada para empleado ${item.empleadoId}`);
      }
    }

    return todosGuardados;
  } catch (e) {
    console.error("❌ Error en guardarNominaEnSupabase:", e);
    return false;
  }
}

// Eliminar nómina de Supabase (para reabrir y editar)
