// ====== FUNCIONES CONTRATOS EN SUPABASE ======
async function guardarContratoEnSupabase(contrato, empresaId = null) {
  try {
    const nowISO = new Date().toISOString();
    
    // Payload completo con campos de firma
    const payloadCompleto = {
      id: contrato.id || uid(),
      empleadoid: contrato.empleadoId || null,
      empleadonombre: contrato.empleadoNombre || null,
      sedeid: contrato.sedeId || null,
      sedename: contrato.sedeName || null,
      tipocontrato: contrato.tipoContrato || "Indefinido",
      datos: contrato.datos || null,
      fechageneracion: contrato.fechaGeneracion || toISO(new Date()),
      firmado: contrato.firmado || false,
      firma_trabajador: contrato.firmaTrabajador || null,
      firma_empleador: contrato.firmaEmpleador || null,
      fecha_firma: contrato.fechaFirma || null,
      tipo_firma_empleador: contrato.tipoFirmaEmpleador || null,
      created_at: contrato.createdAt || nowISO,
      updated_at: nowISO,
    };
    
    // Payload básico sin campos de firma (para compatibilidad)
    const payloadBasico = {
      id: payloadCompleto.id,
      empleadoid: payloadCompleto.empleadoid,
      empleadonombre: payloadCompleto.empleadonombre,
      sedeid: payloadCompleto.sedeid,
      sedename: payloadCompleto.sedename,
      tipocontrato: payloadCompleto.tipocontrato,
      datos: payloadCompleto.datos,
      fechageneracion: payloadCompleto.fechageneracion,
      created_at: payloadCompleto.created_at,
      updated_at: payloadCompleto.updated_at,
    };
    
    // Agregar empresa_id si está disponible
    if (empresaId) {
      payloadCompleto.empresa_id = empresaId;
      payloadBasico.empresa_id = empresaId;
    }

    console.log("📦 Intentando guardar contrato con campos de firma...");
    
    const { data, error } = await supabase
      .from("contratos")
      .upsert(payloadCompleto, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.warn("⚠️ Error con campos de firma, intentando sin ellos:", error.message);
      
      // Intentar con payload básico
      const { data: data2, error: error2 } = await supabase
        .from("contratos")
        .upsert(payloadBasico, { onConflict: "id" })
        .select()
        .maybeSingle();
        
      if (error2) {
        console.error("❌ Error guardando contrato en Supabase:", error2);
        return false;
      }
      
      console.log("✅ Contrato guardado (sin campos de firma). Ejecuta el SQL para agregar las columnas de firma.");
      alert("⚠️ Contrato guardado pero SIN las firmas.\n\nPara guardar contratos firmados, ejecuta el SQL en Supabase para agregar las columnas:\n- firmado\n- firma_trabajador\n- firma_empleador\n- fecha_firma\n- tipo_firma_empleador");
      
      return {
        id: payloadBasico.id,
        empleadoId: payloadBasico.empleadoid,
        empleadoNombre: payloadBasico.empleadonombre,
        sedeId: payloadBasico.sedeid,
        sedeName: payloadBasico.sedename,
        tipoContrato: payloadBasico.tipocontrato,
        datos: contrato.datos || {},
        fechaGeneracion: payloadBasico.fechageneracion,
        firmado: false,
        createdAt: data2?.created_at || payloadBasico.created_at,
        updatedAt: data2?.updated_at || payloadBasico.updated_at,
      };
    }

    console.log("✅ Contrato guardado correctamente con firmas");
    
    return {
      id: payloadCompleto.id,
      empleadoId: payloadCompleto.empleadoid,
      empleadoNombre: payloadCompleto.empleadonombre,
      sedeId: payloadCompleto.sedeid,
      sedeName: payloadCompleto.sedename,
      tipoContrato: payloadCompleto.tipocontrato,
      datos: contrato.datos || {},
      fechaGeneracion: payloadCompleto.fechageneracion,
      firmado: payloadCompleto.firmado,
      firmaTrabajador: payloadCompleto.firma_trabajador,
      firmaEmpleador: payloadCompleto.firma_empleador,
      fechaFirma: payloadCompleto.fecha_firma,
      tipoFirmaEmpleador: payloadCompleto.tipo_firma_empleador,
      createdAt: data?.created_at || payloadCompleto.created_at,
      updatedAt: data?.updated_at || payloadCompleto.updated_at,
    };
  } catch (e) {
    console.error("❌ Error en guardarContratoEnSupabase:", e);
    return false;
  }
}

