function prepararVentasCuadreParaSupabase(cuadre) {
  const ventas = cuadre?.ventas || {};
  // Calcular totales de transferencias
  const transfer = Array.isArray(cuadre?.transfer) ? cuadre.transfer : [];
  let totalBancolombia = 0, totalDavivienda = 0, totalDaviplata = 0, totalNequi = 0;
  transfer.forEach((t) => {
    totalBancolombia += Number(t.bancolombia || 0);
    totalDavivienda += Number(t.davivienda || 0);
    totalDaviplata += Number(t.daviplata || 0);
    totalNequi += Number(t.nequi || 0);
  });
  // Calcular total datafonos
  const datafonos = Array.isArray(cuadre?.datafonos) ? cuadre.datafonos : [];
  const totalDatafonos = datafonos.reduce((sum, d) => sum + Number(d.valor || 0), 0);

  // Online Rappi
  const onlineRappi = Number(ventas.onlineRappi || 0);

  return {
    valorInicial: Number(cuadre?.valorInicial ?? 0) || 0,
    caja: {
      ventaEfectivo: ventas.ventaEfectivo || "",
      sobrante: ventas.sobrante || "",
      huboDescuadre: ventas.huboDescuadre === "Sí" ? "Sí" : "No",
      valorDescuadre: ventas.valorDescuadre || "",
      onlineRappi: ventas.onlineRappi || "",
      // 🔹 Campos de descuadre en transferencia
      huboDescuadreTransferencia: ventas.huboDescuadreTransferencia || "",
      valorDescuadreTransferencia: ventas.valorDescuadreTransferencia || "",
      numeroPedidoDescuadreTransferencia: ventas.numeroPedidoDescuadreTransferencia || "",
      bancoDescuadreTransferencia: ventas.bancoDescuadreTransferencia || "",
      // 🔹 Campos de descuadre en datáfono
      huboDescuadreDatafono: ventas.huboDescuadreDatafono || "",
      valorDescuadreDatafono: ventas.valorDescuadreDatafono || "",
      // 🔹 CRITICAL: Campos de efectivo confirmado (antes estaban faltando)
      efectivoEnCaja: ventas.efectivoEnCaja || "",
      efectivoEnCajaConfirmado: ventas.efectivoEnCajaConfirmado || false,
      fechaConfirmacionEfectivo: ventas.fechaConfirmacionEfectivo || null,
      // 🔹 Campos de totales FUDO
      ventaEfectivoFudo: ventas.ventaEfectivoFudo || null,
      onlineRappiFudo: ventas.onlineRappiFudo || null,
      datafonoFudo: ventas.datafonoFudo || null,
      totalesFudoFecha: ventas.totalesFudoFecha || null,
      totalesFudoPedidos: ventas.totalesFudoPedidos || null,
      // 🔹 Campo de efectivo final confirmado (segunda jornada)
      efectivoFinalConfirmado: ventas.efectivoFinalConfirmado || false,
    },
    ventasPorMedioPago: {
      efectivo: Number(ventas.ventaEfectivo || 0),
      bancolombia: totalBancolombia,
      davivienda: totalDavivienda,
      daviplata: totalDaviplata,
      nequi: totalNequi,
      datafono: totalDatafonos,
      onlineRappi: onlineRappi,
      totalTransferencias: totalBancolombia + totalDavivienda + totalDaviplata + totalNequi,
      totalGeneral: Number(ventas.ventaEfectivo || 0) + totalBancolombia + totalDavivienda + totalDaviplata + totalNequi + totalDatafonos + onlineRappi,
    },
    transfer: transfer,
    denoms: Array.isArray(cuadre?.denoms) ? cuadre.denoms : [],
    denominacionesActivas: !!cuadre?.denominacionesActivas,
    turnosActivos: !!cuadre?.turnosActivos,
    adelantosActivos: !!cuadre?.adelantosActivos,
    // 🔹 Ingresos Varios
    ingresosVarios: Array.isArray(cuadre?.ingresosVarios) ? cuadre.ingresosVarios : [],
    ingresosVariosActivos: !!cuadre?.ingresosVariosActivos,
  };
}

function prepararDomiciliosCuadreParaSupabase(cuadre) {
  return {
    domicilios: Array.isArray(cuadre?.domicilios) ? cuadre.domicilios : [],
    turnosActivos: !!cuadre?.turnosActivos,
    turnos: Array.isArray(cuadre?.turnos) ? cuadre.turnos : [],
    adelantosActivos: !!cuadre?.adelantosActivos,
    adelantos: Array.isArray(cuadre?.adelantos) ? cuadre.adelantos : [],
  };
}

function prepararDescuentosCuadreParaSupabase(cuadre) {
  return {
    novedadesActivas: !!cuadre?.novedadesActivas,
    novedades: Array.isArray(cuadre?.novedades) ? cuadre.novedades : [],
    comentarioModificacion: cuadre?.comentarioModificacion || "",
    totales: cuadre?.totales || {},
    // Facturas eliminadas (para sincronización colaborativa)
    facturasEliminadas: Array.isArray(cuadre?.facturasEliminadas) ? cuadre.facturasEliminadas : [],
  };
}

function mapearRowCuadreDesdeSupabase(row) {
  const ventasRaw = typeof row?.ventas === "string" ? safelyParseJSON(row.ventas, {}) : row?.ventas || {};
  const facturasRaw = typeof row?.facturas === "string" ? safelyParseJSON(row.facturas, []) : row?.facturas || [];
  const domiciliosRaw = typeof row?.domicilios === "string" ? safelyParseJSON(row.domicilios, {}) : row?.domicilios || {};
  const descuentosRaw = typeof row?.descuentos === "string" ? safelyParseJSON(row.descuentos, {}) : row?.descuentos || {};

  const caja = ventasRaw?.caja || ventasRaw?.ventas || {};
  const estadoNormalizado = (row?.estado || "").toLowerCase();
  const comentario =
    descuentosRaw?.comentarioModificacion ??
    descuentosRaw?.comentarios ??
    row?.observaciones ??
    "";

  const denomsDesdeBd = Array.isArray(ventasRaw?.denoms)
    ? ventasRaw.denoms
    : Array.isArray(ventasRaw?.denominaciones)
    ? ventasRaw.denominaciones
    : [];

  const denomsNormalizados =
    denomsDesdeBd && denomsDesdeBd.length
      ? denomsDesdeBd
      : DENOMINACIONES.map((valor) => ({ valor, cantidad: 0, subtotal: 0 }));

  return {
    id: row?.id,
    sede: row?.sede || "",
    fecha: row?.fecha || "",
    empleadoId: row?.responsable || "",
    estado: estadoNormalizado === "borrador" ? "borrador" : "final",
    valorInicial: Number(ventasRaw?.valorInicial ?? 0) || 0,
    ventas: {
      ventaEfectivo: caja?.ventaEfectivo || "",
      sobrante: caja?.sobrante || "",
      huboDescuadre: caja?.huboDescuadre === "Sí" ? "Sí" : "No",
      valorDescuadre: caja?.valorDescuadre || "",
      onlineRappi: caja?.onlineRappi || "",
      // 🔹 Campos de descuadre de transferencia
      huboDescuadreTransferencia: caja?.huboDescuadreTransferencia || "",
      valorDescuadreTransferencia: caja?.valorDescuadreTransferencia || "",
      numeroPedidoDescuadreTransferencia: caja?.numeroPedidoDescuadreTransferencia || "",
      bancoDescuadreTransferencia: caja?.bancoDescuadreTransferencia || "",
      // 🔹 Campos de descuadre de datáfono
      huboDescuadreDatafono: caja?.huboDescuadreDatafono || "",
      valorDescuadreDatafono: caja?.valorDescuadreDatafono || "",
      // 🔹 CRITICAL: Campos de efectivo confirmado (mapeados desde Supabase)
      efectivoEnCaja: caja?.efectivoEnCaja || "",
      efectivoEnCajaConfirmado: caja?.efectivoEnCajaConfirmado || false,
      fechaConfirmacionEfectivo: caja?.fechaConfirmacionEfectivo || null,
      // 🔹 Campos de totales FUDO (mapeados desde Supabase)
      ventaEfectivoFudo: caja?.ventaEfectivoFudo || null,
      onlineRappiFudo: caja?.onlineRappiFudo || null,
      datafonoFudo: caja?.datafonoFudo || null,
      totalesFudoFecha: caja?.totalesFudoFecha || null,
      totalesFudoPedidos: caja?.totalesFudoPedidos || null,
      // 🔹 Campo de efectivo final confirmado (segunda jornada)
      efectivoFinalConfirmado: caja?.efectivoFinalConfirmado || row?.efectivo_final_confirmado || false,
    },
    transfer: Array.isArray(ventasRaw?.transfer)
      ? ventasRaw.transfer
      : Array.isArray(ventasRaw?.transferencias)
      ? ventasRaw.transferencias
      : [],
    denoms: denomsNormalizados,
    denominacionesActivas: !!(ventasRaw?.denominacionesActivas),
    facturas: Array.isArray(facturasRaw) ? facturasRaw : [],
    domicilios: Array.isArray(domiciliosRaw?.domicilios)
      ? domiciliosRaw.domicilios
      : Array.isArray(domiciliosRaw)
      ? domiciliosRaw
      : [],
    turnosActivos: !!(domiciliosRaw?.turnosActivos ?? ventasRaw?.turnosActivos),
    turnos: Array.isArray(domiciliosRaw?.turnos)
      ? domiciliosRaw.turnos
      : Array.isArray(ventasRaw?.turnos)
      ? ventasRaw.turnos
      : [],
    adelantosActivos: !!(domiciliosRaw?.adelantosActivos ?? ventasRaw?.adelantosActivos),
    adelantos: Array.isArray(domiciliosRaw?.adelantos)
      ? domiciliosRaw.adelantos
      : Array.isArray(ventasRaw?.adelantos)
      ? ventasRaw.adelantos
      : [],
    novedadesActivas: !!descuentosRaw?.novedadesActivas,
    novedades: Array.isArray(descuentosRaw?.novedades) ? descuentosRaw.novedades : [],
    // Facturas eliminadas (para sincronización colaborativa - evita que facturas borradas reaparezcan)
    facturasEliminadas: Array.isArray(descuentosRaw?.facturasEliminadas) ? descuentosRaw.facturasEliminadas : [],
    // 🔹 Bases de domicilios
    basesDomiciliosActivas: !!(typeof row?.bases_domicilios === "string" 
      ? safelyParseJSON(row.bases_domicilios, []).length > 0 
      : (row?.bases_domicilios || []).length > 0),
    basesDomicilios: typeof row?.bases_domicilios === "string" 
      ? safelyParseJSON(row.bases_domicilios, []) 
      : Array.isArray(row?.bases_domicilios) ? row.bases_domicilios : [],
    // 🔹 Ingresos Varios (venta de materia prima, etc.)
    ingresosVariosActivos: !!(ventasRaw?.ingresosVariosActivos || (Array.isArray(ventasRaw?.ingresosVarios) && ventasRaw.ingresosVarios.length > 0)),
    ingresosVarios: Array.isArray(ventasRaw?.ingresosVarios) ? ventasRaw.ingresosVarios : [],
    // 🔹 Campo de efectivo final confirmado (leído de la columna de Supabase)
    efectivoFinalConfirmado: row?.efectivo_final_confirmado || false,
    ingresosVarios: Array.isArray(ventasRaw?.ingresosVarios) ? ventasRaw.ingresosVarios : [],
    datafonos: Array.isArray(row?.datafonos) ? row.datafonos : [],
    comentarioModificacion: comentario,
    totales: descuentosRaw?.totales || ventasRaw?.totales || {},
    cerradoPorId: row?.cerrado_por_id || null,
    cerradoPorNombre: row?.cerrado_por_nombre || null,
    fechaCierre: row?.fecha_cierre || null,
    // Campos de precierre
    precierreRealizado: row?.precierre_realizado || false,
    precierrePendienteConfirmacion: row?.precierre_pendiente_confirmacion || false,
    precierre: row?.precierre_realizado ? {
      fecha: row?.precierre_fecha || null,
      porId: row?.precierre_por_id || null,
      porNombre: row?.precierre_por_nombre || null,
      asignadoAId: row?.precierre_asignado_a_id || null,
      asignadoANombre: row?.precierre_asignado_a_nombre || null,
      observaciones: row?.precierre_observaciones || "",
      totales: typeof row?.precierre_totales === "string" ? safelyParseJSON(row.precierre_totales, {}) : row?.precierre_totales || {},
      confirmadoPorReceptor: row?.precierre_confirmado_por_receptor || false,
      fechaConfirmacion: row?.precierre_fecha_confirmacion || null,
      confirmadoPorNombre: row?.precierre_confirmado_por_nombre || null,
    } : null,
    // 🔹 Campos de colaborador
    colaboradorId: row?.colaborador_id || null,
    colaboradorNombre: row?.colaborador_nombre || null,
    createdAt: row?.created_at || null,
    updatedAt: row?.updated_at || null,
  };
}

// Función para eliminar un cuadre diario de Supabase Y marcarlo como eliminado en localStorage
// 🔐 SEGURIDAD: Solo permite eliminar cuadres de la empresa especificada
async function eliminarCuadreDiarioDeSupabase(cuadreId, empresaId = null) {
  try {
    if (!cuadreId) {
      console.error("❌ eliminarCuadreDiarioDeSupabase requiere un ID válido");
      return false;
    }

    console.log("🗑️ Eliminando cuadre de Supabase:", cuadreId);
    
    // PRIMERO: Marcar como eliminado en localStorage para evitar re-sincronización
    marcarCuadreComoEliminado(cuadreId);
    
    // SEGUNDO: Eliminar de Supabase (solo si pertenece a la empresa)
    let query = supabase
      .from("cuadres_diarios")
      .delete()
      .eq("id", cuadreId);
    
    // 🔐 Si hay empresaId, agregar filtro para solo eliminar cuadres de esa empresa
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { error } = await query;

    if (error) {
      console.error("❌ Error eliminando cuadre diario de Supabase:", error);
      // Reintentar una vez más
      let queryRetry = supabase
        .from("cuadres_diarios")
        .delete()
        .eq("id", cuadreId);
      if (empresaId) {
        queryRetry = queryRetry.eq("empresa_id", empresaId);
      }
      const { error: error2 } = await queryRetry;
      if (error2) {
        console.error("❌ Error eliminando cuadre (reintento):", error2);
        return false;
      }
    }

    console.log("✅ Cuadre eliminado de Supabase correctamente:", cuadreId);
    return true;
  } catch (e) {
    console.error("❌ Error en eliminarCuadreDiarioDeSupabase:", e);
    return false;
  }
}

async function guardarCuadreDiarioEnSupabase(cuadre, empresaId = null) {
  try {
    if (!cuadre?.id) {
      console.error("❌ guardarCuadreDiarioEnSupabase requiere un ID válido");
      return null;
    }
    
    // 🔐 SEGURIDAD: Si no hay empresaId, NO guardar el cuadre
    // Esto evita crear cuadres sin empresa que podrían verse por todos
    if (!empresaId) {
      console.error("❌ guardarCuadreDiarioEnSupabase: NO se proporcionó empresaId - cuadre NO guardado por seguridad");
      return null;
    }

    const payload = {
      id: cuadre.id,
      sede: cuadre?.sede || null,
      fecha: cuadre?.fecha || null,
      responsable: cuadre?.empleadoId || null,
      estado: (cuadre?.estado || "final").toLowerCase() === "borrador" ? "Borrador" : "Final",
      fue_reabierto: cuadre?.fueReabierto || false,
      ventas: prepararVentasCuadreParaSupabase(cuadre),
      facturas: Array.isArray(cuadre?.facturas) ? cuadre.facturas : [],
      domicilios: prepararDomiciliosCuadreParaSupabase(cuadre),
      descuentos: prepararDescuentosCuadreParaSupabase(cuadre),
      datafonos: Array.isArray(cuadre?.datafonos) ? cuadre.datafonos : [],
      observaciones: cuadre?.comentarioModificacion || "",
      cerrado_por_id: cuadre?.cerradoPorId || null,
      cerrado_por_nombre: cuadre?.cerradoPorNombre || null,
      fecha_cierre: cuadre?.fechaCierre || null,
      // Campos de precierre
      precierre_realizado: cuadre?.precierreRealizado || false,
      precierre_fecha: cuadre?.precierre?.fecha || null,
      precierre_por_id: cuadre?.precierre?.porId || null,
      precierre_por_nombre: cuadre?.precierre?.porNombre || null,
      precierre_asignado_a_id: cuadre?.precierre?.asignadoAId || null,
      precierre_asignado_a_nombre: cuadre?.precierre?.asignadoANombre || null,
      precierre_observaciones: cuadre?.precierre?.observaciones || null,
      precierre_totales: cuadre?.precierre?.totales || null,
      precierre_pendiente_confirmacion: cuadre?.precierrePendienteConfirmacion || false,
      precierre_confirmado_por_receptor: cuadre?.precierre?.confirmadoPorReceptor || false,
      precierre_fecha_confirmacion: cuadre?.precierre?.fechaConfirmacion || null,
      precierre_confirmado_por_nombre: cuadre?.precierre?.confirmadoPorNombre || null,
      // 🔹 Campos de acciones rápidas
      turnos: Array.isArray(cuadre?.turnos) ? cuadre.turnos : [],
      adelantos: Array.isArray(cuadre?.adelantos) ? cuadre.adelantos : [],
      novedades: Array.isArray(cuadre?.novedades) ? cuadre.novedades : [],
      bases_domicilios: Array.isArray(cuadre?.basesDomicilios) ? cuadre.basesDomicilios : [],
      // 🔹 Campos de colaborador
      colaborador_id: cuadre?.colaboradorId || null,
      colaborador_nombre: cuadre?.colaboradorNombre || null,
      // 🔹 Campo de efectivo final confirmado (segunda jornada)
      efectivo_final_confirmado: cuadre?.ventas?.efectivoFinalConfirmado || cuadre?.efectivoFinalConfirmado || false,
      empresa_id: empresaId, // 🔐 SIEMPRE incluir empresa_id
      updated_at: new Date().toISOString(),
    };

    const { data, error } = await supabase
      .from("cuadres_diarios")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.error("❌ Error guardando cuadre diario en Supabase:", error);
      return null;
    }

    return mapearRowCuadreDesdeSupabase(data || payload);
  } catch (e) {
    console.error("❌ Error en guardarCuadreDiarioEnSupabase:", e);
    return null;
  }
}

async function cargarCuadresDiariosDeSupabase(empresaId = null) {
  try {
    // 🔐 SEGURIDAD: Si no hay empresaId, NO cargar ningún cuadre
    // Esto evita que empleados vean cuadres de otras empresas
    if (!empresaId) {
      console.warn("⚠️ cargarCuadresDiariosDeSupabase: NO se proporcionó empresaId - retornando vacío por seguridad");
      return [];
    }
    
    // FILTRO: Excluir cuadres de prueba anteriores al 7 de febrero de 2026
    const FECHA_MINIMA_CUADRES = "2026-02-07";
    
    let query = supabase
      .from("cuadres_diarios")
      .select("*")
      .eq("empresa_id", empresaId) // 🔐 SIEMPRE filtrar por empresa
      .gte("fecha", FECHA_MINIMA_CUADRES) // Solo cuadres >= 7 de febrero de 2026
      .order("fecha", { ascending: false })
      .order("updated_at", { ascending: false });
    
    const { data, error } = await query;

    if (error) {
      console.error("❌ Error cargando cuadres diarios desde Supabase:", error);
      return [];
    }

    console.log(`✅ Cuadres cargados para empresa ${empresaId}: ${(data || []).length}`);
    return (data || []).map((row) => mapearRowCuadreDesdeSupabase(row));
  } catch (e) {
    console.error("❌ Error en cargarCuadresDiariosDeSupabase:", e);
    return [];
  }
}

/* ====================== SISTEMA DE REVISIÓN DE CUADRES ====================== */

// Guardar revisión de cuadre en Supabase
async function guardarRevisionCuadreEnSupabase(revision, empresaId = null) {
  try {
    if (!revision?.id) {
      console.error("❌ guardarRevisionCuadreEnSupabase requiere un ID válido");
      return null;
    }

    const payload = {
      id: revision.id,
      cuadre_id: revision.cuadre_id,
      fecha_revision: revision.fecha_revision || new Date().toISOString(),
      fecha_cierre: revision.fecha_cierre || null,
      estado: revision.estado || 'en_revision',
      revisor_principal_id: revision.revisor_principal_id || null,
      revisor_principal_nombre: revision.revisor_principal_nombre || null,
      observaciones_generales: revision.observaciones_generales || '',
      sede: revision.sede || null,
      fecha_cuadre: revision.fecha_cuadre || null,
      empleado_cuadre_id: revision.empleado_cuadre_id || null,
      empleado_cuadre_nombre: revision.empleado_cuadre_nombre || null,
      revision_facturas: revision.revision_facturas || { aprobado: null, observaciones: '', items: [] },
      revision_domicilios: revision.revision_domicilios || { aprobado: null, observaciones: '', items: [] },
      revision_transferencias: revision.revision_transferencias || { aprobado: null, observaciones: '', items: [] },
      revision_turnos: revision.revision_turnos || { aprobado: null, observaciones: '', items: [] },
      revision_adelantos: revision.revision_adelantos || { aprobado: null, observaciones: '', items: [] },
      revision_denominaciones: revision.revision_denominaciones || { aprobado: null, observaciones: '' },
      revision_novedades: revision.revision_novedades || { aprobado: null, observaciones: '', items: [] },
      revision_datafonos: revision.revision_datafonos || { aprobado: null, observaciones: '', items: [] },
      total_cuadre: revision.total_cuadre || 0,
      diferencia: revision.diferencia || 0,
      empresa_id: empresaId || null,
      updated_at: new Date().toISOString()
    };

    const { data, error } = await supabase
      .from("revisiones_cuadre")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.error("❌ Error guardando revisión de cuadre:", error);
      return null;
    }

    // Actualizar estado de revisión en el cuadre original
    if (revision.cuadre_id) {
      await supabase
        .from("cuadres_diarios")
        .update({ 
          estado_revision: revision.estado,
          revision_id: revision.id 
        })
        .eq("id", revision.cuadre_id);
    }

    return data || payload;
  } catch (e) {
    console.error("❌ Error en guardarRevisionCuadreEnSupabase:", e);
    return null;
  }
}

// Cargar revisiones de cuadres desde Supabase
async function cargarRevisionesCuadresDeSupabase(empresaId = null, filtros = {}) {
  try {
    let query = supabase
      .from("revisiones_cuadre")
      .select("*")
      .order("fecha_revision", { ascending: false });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    if (filtros.sede) {
      query = query.eq("sede", filtros.sede);
    }
    if (filtros.estado) {
      query = query.eq("estado", filtros.estado);
    }
    if (filtros.fechaDesde) {
      query = query.gte("fecha_cuadre", filtros.fechaDesde);
    }
    if (filtros.fechaHasta) {
      query = query.lte("fecha_cuadre", filtros.fechaHasta);
    }
    if (filtros.empleadoId) {
      query = query.eq("empleado_cuadre_id", filtros.empleadoId);
    }
    
    const { data, error } = await query;

    if (error) {
      console.error("❌ Error cargando revisiones de cuadres:", error);
      return [];
    }

    return data || [];
  } catch (e) {
    console.error("❌ Error en cargarRevisionesCuadresDeSupabase:", e);
    return [];
  }
}

// Cargar una revisión específica por ID
async function cargarRevisionCuadrePorId(revisionId) {
  try {
    const { data, error } = await supabase
      .from("revisiones_cuadre")
      .select("*")
      .eq("id", revisionId)
      .maybeSingle();

    if (error) {
      console.error("❌ Error cargando revisión:", error);
      return null;
    }

    return data;
  } catch (e) {
    console.error("❌ Error en cargarRevisionCuadrePorId:", e);
    return null;
  }
}

// Verificar si un cuadre ya tiene revisión
async function verificarRevisionExistente(cuadreId) {
  try {
    const { data, error } = await supabase
      .from("revisiones_cuadre")
      .select("id, estado")
      .eq("cuadre_id", cuadreId)
      .maybeSingle();

    if (error) {
      console.error("❌ Error verificando revisión existente:", error);
      return null;
    }

    return data; // null si no existe, objeto con id y estado si existe
  } catch (e) {
    console.error("❌ Error en verificarRevisionExistente:", e);
    return null;
  }
}

// Guardar asignación de sección a empleado
async function guardarAsignacionRevision(asignacion, empresaId = null) {
  try {
    if (!asignacion?.id) {
      console.error("❌ guardarAsignacionRevision requiere un ID válido");
      return null;
    }

    const payload = {
      id: asignacion.id,
      revision_id: asignacion.revision_id,
      empleado_id: asignacion.empleado_id,
      empleado_nombre: asignacion.empleado_nombre,
      seccion: asignacion.seccion,
      estado: asignacion.estado || 'pendiente',
      aprobado: asignacion.aprobado !== undefined ? asignacion.aprobado : null,
      observaciones: asignacion.observaciones || '',
      items_revisados: asignacion.items_revisados || [],
      fecha_asignacion: asignacion.fecha_asignacion || new Date().toISOString(),
      fecha_completado: asignacion.fecha_completado || null,
      asignado_por_id: asignacion.asignado_por_id || null,
      asignado_por_nombre: asignacion.asignado_por_nombre || null,
      updated_at: new Date().toISOString()
    };

    const { data, error } = await supabase
      .from("asignaciones_revision")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.error("❌ Error guardando asignación:", error);
      return null;
    }

    return data || payload;
  } catch (e) {
    console.error("❌ Error en guardarAsignacionRevision:", e);
    return null;
  }
}

// Cargar asignaciones de una revisión
