// ====================== FUNCIONES DE FUSIÓN SIN PÉRDIDA DE DATOS ======================
// Cuando dos usuarios editan el mismo campo, NINGUNO se pierde
// Uno se queda en el campo original, el otro se crea en una fila nueva

/**
 * Fusiona dos arrays SIN CREAR DUPLICADOS
 * Usa estrategia "el más reciente gana" basado en updatedAt
 * NO crea items nuevos por conflicto - solo mantiene el más actualizado
 */
function fusionarArraysSinPerder(arrayLocal, arrayRemoto, camposAFusionar, generarId) {
  const resultado = [];
  const mapLocal = new Map();
  const mapRemoto = new Map();
  const idsVistos = new Set();
  
  // Indexar por ID
  (arrayLocal || []).forEach(item => {
    if (item && item.id) mapLocal.set(item.id, item);
  });
  (arrayRemoto || []).forEach(item => {
    if (item && item.id) mapRemoto.set(item.id, item);
  });
  
  // Procesar items locales
  mapLocal.forEach((itemLocal, id) => {
    if (idsVistos.has(id)) return;
    idsVistos.add(id);
    
    const itemRemoto = mapRemoto.get(id);
    
    if (!itemRemoto) {
      // Solo existe en local - conservar
      resultado.push(itemLocal);
    } else {
      // Existe en ambos - usar el MÁS RECIENTE (basado en updatedAt)
      const timestampLocal = itemLocal.updatedAt || 0;
      const timestampRemoto = itemRemoto.updatedAt || 0;
      
      if (timestampRemoto > timestampLocal) {
        // Remoto es más reciente - usar remoto
        resultado.push({ ...itemRemoto, updatedAt: Date.now() });
      } else {
        // Local es más reciente o igual - usar local
        resultado.push({ ...itemLocal, updatedAt: Date.now() });
      }
    }
  });
  
  // Agregar items que solo existen en remoto
  mapRemoto.forEach((itemRemoto, id) => {
    if (!idsVistos.has(id)) {
      idsVistos.add(id);
      resultado.push(itemRemoto);
    }
  });
  
  // Eliminar items marcados como creados por conflicto que sean duplicados
  // (Limpia duplicados históricos)
  const resultadoLimpio = eliminarDuplicadosPorValores(resultado, camposAFusionar);
  
  return resultadoLimpio;
}

/**
 * Elimina items duplicados basándose en los valores de los campos (no solo el ID)
 * Esto limpia duplicados creados por la fusión anterior
 */
function eliminarDuplicadosPorValores(items, campos) {
  const vistos = new Map();
  const resultado = [];
  
  items.forEach(item => {
    // Crear una clave basada en los valores de los campos
    const clave = campos.map(c => String(item[c] || "").trim().toLowerCase()).join("|");
    
    // Si la clave está vacía (todos los campos vacíos), usar el ID
    const claveReal = clave.replace(/\|/g, "").trim() === "" ? item.id : clave;
    
    if (!vistos.has(claveReal)) {
      vistos.set(claveReal, item);
      resultado.push(item);
    } else {
      // Si ya existe, conservar el más reciente
      const existente = vistos.get(claveReal);
      if ((item.updatedAt || 0) > (existente.updatedAt || 0)) {
        // Reemplazar el existente con el más reciente
        const idx = resultado.indexOf(existente);
        if (idx >= 0) {
          resultado[idx] = item;
          vistos.set(claveReal, item);
        }
      }
      console.log(`🧹 Eliminado duplicado: ${claveReal}`);
    }
  });
  
  return resultado;
}

/**
 * Fusiona un campo simple sin perder datos
 * Si ambos tienen valor diferente, retorna ambos concatenados o un array
 */
function fusionarCampoSinPerder(valorLocal, valorRemoto, esNumerico = false) {
  const localTieneValor = valorLocal !== undefined && valorLocal !== null && String(valorLocal).trim() !== "";
  const remotoTieneValor = valorRemoto !== undefined && valorRemoto !== null && String(valorRemoto).trim() !== "";
  
  // Si solo uno tiene valor, usar ese
  if (localTieneValor && !remotoTieneValor) return valorLocal;
  if (remotoTieneValor && !localTieneValor) return valorRemoto;
  
  // Si ambos tienen el mismo valor, retornar cualquiera
  if (String(valorLocal).trim() === String(valorRemoto).trim()) return valorLocal;
  
  // CONFLICTO: Ambos tienen valores diferentes
  if (esNumerico) {
    // Para números, sumar o conservar el mayor
    const numLocal = parseFloat(valorLocal) || 0;
    const numRemoto = parseFloat(valorRemoto) || 0;
    console.log(`⚠️ Conflicto numérico: ${numLocal} vs ${numRemoto} - conservando mayor`);
    return Math.max(numLocal, numRemoto);
  } else {
    // Para texto, concatenar con separador
    console.log(`⚠️ Conflicto texto: "${valorLocal}" vs "${valorRemoto}" - concatenando`);
    return `${valorLocal} | ${valorRemoto}`;
  }
}

// ====================== FIN FUNCIONES DE FUSIÓN SIN PÉRDIDA ======================

// Fusionar cuadres de forma colaborativa - SIN PÉRDIDA DE DATOS
// localPrioridad: true = usuario está editando, false = sincronización normal
function fusionarCuadresColaborativo(cuadreLocal, cuadreRemoto, localPrioridad = false) {
  // Si no hay cuadre remoto, retornar local
  if (!cuadreRemoto) return cuadreLocal;
  
  // 🔐 PRIORIDAD ABSOLUTA: Si el cuadre remoto está cerrado (estado "final"),
  // aceptar TODOS los datos del remoto sin fusionar. El cierre es irreversible.
  if (cuadreRemoto.estado === "final" && cuadreLocal.estado !== "final") {
    console.log("🔐 Cuadre remoto está CERRADO - aceptando todos los datos del remoto");
    return { ...cuadreRemoto };
  }
  
  // Crear una copia del cuadre local
  const resultado = { ...cuadreLocal };
  
  console.log(`🔀 Fusionando cuadres - ${localPrioridad ? 'LOCAL' : 'REMOTO'} tiene PRIORIDAD...`);
  
  // Helper: fusionar un campo
  // Si localPrioridad=true: local gana siempre (usuario está editando)
  // Si localPrioridad=false: REMOTO SIEMPRE GANA (incluso si está vacío - para propagar borrados)
  const fusionarCampo = (valorLocal, valorRemoto, campoExisteEnRemoto = true) => {
    const localTieneValor = valorLocal !== undefined && valorLocal !== null && String(valorLocal).trim() !== "";
    
    if (localPrioridad) {
      // Usuario editando: local gana siempre
      if (localTieneValor) return valorLocal;
      // Si local no tiene valor, usar remoto
      return valorRemoto !== undefined ? valorRemoto : valorLocal;
    } else {
      // Sincronización normal: REMOTO SIEMPRE GANA (incluso vacío = borrado)
      // Esto permite que los borrados se propaguen correctamente
      if (campoExisteEnRemoto) {
        return valorRemoto; // Usar remoto aunque esté vacío
      }
      return valorLocal;
    }
  };
  
  // Helper: fusionar un item completo campo por campo
  // MEJORADO: Usa timestamps para determinar qué versión es más reciente
  const fusionarItem = (itemLocal, itemRemoto, campos) => {
    if (!itemRemoto) return itemLocal;
    if (!itemLocal) return itemRemoto;
    
    const fusionado = { ...itemLocal };
    
    // Si tenemos timestamps, comparar para decidir prioridad
    const timestampLocal = itemLocal.updatedAt || 0;
    const timestampRemoto = itemRemoto.updatedAt || 0;
    
    // SIEMPRE priorizar el que tenga timestamp más reciente
    // Esto asegura que los cambios de cualquier usuario se mantengan
    const localEsMasReciente = timestampLocal > timestampRemoto;
    const remotoEsMasReciente = timestampRemoto > timestampLocal;
    
    // Si el remoto es más reciente, usar TODOS sus campos (el usuario remoto hizo cambios después)
    if (remotoEsMasReciente && !localPrioridad) {
      console.log(`🔄 Item remoto es más reciente (${timestampRemoto} > ${timestampLocal}) - usando datos remotos`);
      campos.forEach(campo => {
        fusionado[campo] = itemRemoto[campo];
      });
      fusionado.updatedAt = timestampRemoto;
      return fusionado;
    }
    
    // Si el local es más reciente, mantenerlo (incluso durante sincronización normal)
    if (localEsMasReciente) {
      console.log(`✅ Item local es más reciente (${timestampLocal} > ${timestampRemoto}) - manteniendo datos locales`);
      fusionado.updatedAt = timestampLocal;
      return fusionado;
    }
    
    // Si tienen el mismo timestamp o no hay timestamps, usar lógica de fusión campo por campo
    campos.forEach(campo => {
      const campoExisteEnRemoto = itemRemoto.hasOwnProperty(campo) || campo in itemRemoto;
      
      if (localPrioridad) {
        // Usuario editando - local gana
        const localTieneValor = itemLocal[campo] !== undefined && itemLocal[campo] !== null && String(itemLocal[campo]).trim() !== "";
        if (localTieneValor) {
          fusionado[campo] = itemLocal[campo];
        } else {
          fusionado[campo] = itemRemoto[campo] !== undefined ? itemRemoto[campo] : itemLocal[campo];
        }
      } else {
        // Sincronización normal - remoto gana
        fusionado[campo] = fusionarCampo(itemLocal[campo], itemRemoto[campo], campoExisteEnRemoto);
      }
    });
    
    // Mantener el timestamp más reciente
    fusionado.updatedAt = Math.max(timestampLocal, timestampRemoto);
    
    // Mantener campos adicionales del remoto que no estén en la lista
    Object.keys(itemRemoto).forEach(key => {
      if (!campos.includes(key) && key !== 'id' && key !== 'updatedAt') {
        fusionado[key] = fusionarCampo(itemLocal[key], itemRemoto[key], true);
      }
    });
    return fusionado;
  };
  
  // ====================== FUSIONAR FACTURAS ELIMINADAS ======================
  // Primero fusionar las listas de facturas eliminadas de ambos cuadres
  const facturasEliminadasLocales = Array.isArray(cuadreLocal.facturasEliminadas) ? cuadreLocal.facturasEliminadas : [];
  const facturasEliminadasRemotas = Array.isArray(cuadreRemoto.facturasEliminadas) ? cuadreRemoto.facturasEliminadas : [];
  
  // Combinar todas las eliminadas (tanto locales como remotas)
  const facturasEliminadasMap = new Map();
  [...facturasEliminadasLocales, ...facturasEliminadasRemotas].forEach(fe => {
    if (fe.id && !facturasEliminadasMap.has(fe.id)) {
      facturasEliminadasMap.set(fe.id, fe);
    }
  });
  resultado.facturasEliminadas = Array.from(facturasEliminadasMap.values());
  
  // Crear sets para verificación rápida
  const idsEliminados = new Set(resultado.facturasEliminadas.map(fe => fe.id));
  
  console.log(`🗑️ Facturas eliminadas combinadas: ${resultado.facturasEliminadas.length} (IDs: ${Array.from(idsEliminados).join(', ')})`);
  
  // ====================== FUSIONAR FACTURAS: EL MÁS RECIENTE GANA ======================
  // IGUAL que domicilios y transfer: NO agregar nada del otro lado
  if (Array.isArray(cuadreRemoto.facturas) || Array.isArray(cuadreLocal.facturas)) {
    const timestampLocal = new Date(cuadreLocal.updated_at || 0).getTime();
    const timestampRemoto = new Date(cuadreRemoto.updated_at || 0).getTime();
    const remotoEsMasReciente = timestampRemoto > timestampLocal;
    
    if (localPrioridad) {
      // Usuario editando: conservar local
      resultado.facturas = Array.isArray(cuadreLocal.facturas) ? cuadreLocal.facturas : [];
    } else if (remotoEsMasReciente) {
      // Remoto es más reciente - usar remoto COMPLETO
      resultado.facturas = Array.isArray(cuadreRemoto.facturas) ? cuadreRemoto.facturas : [];
    } else {
      // Local es más reciente - conservar local
      resultado.facturas = Array.isArray(cuadreLocal.facturas) ? cuadreLocal.facturas : [];
    }
    console.log(`📋 Facturas: ${resultado.facturas.length} (${localPrioridad ? 'local-prioridad' : remotoEsMasReciente ? 'remoto-reciente' : 'local-reciente'})`);
  }
  
  // ====================== NUEVA ESTRATEGIA PARA ARRAYS ======================
  // NO fusionar elemento por elemento - usar el array del cuadre MÁS RECIENTE
  // Esto evita duplicados cuando hay múltiples usuarios
  // =========================================================================
  
  const timestampLocal = new Date(cuadreLocal.updated_at || 0).getTime();
  const timestampRemoto = new Date(cuadreRemoto.updated_at || 0).getTime();
  const remotoEsMasReciente = timestampRemoto > timestampLocal;
  
  // Fusionar domicilios: EL MÁS RECIENTE GANA (sin crear duplicados)
  if (Array.isArray(cuadreRemoto.domicilios) || Array.isArray(cuadreLocal.domicilios)) {
    if (localPrioridad) {
      // Usuario editando: conservar local
      resultado.domicilios = Array.isArray(cuadreLocal.domicilios) ? cuadreLocal.domicilios : [];
    } else if (remotoEsMasReciente) {
      // Remoto es más reciente - usar remoto
      resultado.domicilios = Array.isArray(cuadreRemoto.domicilios) ? cuadreRemoto.domicilios : [];
    } else {
      // Local es más reciente - conservar local
      resultado.domicilios = Array.isArray(cuadreLocal.domicilios) ? cuadreLocal.domicilios : [];
    }
    console.log(`🛵 Domicilios: ${resultado.domicilios.length} (${localPrioridad ? 'local-prioridad' : remotoEsMasReciente ? 'remoto-reciente' : 'local-reciente'})`);
  }
  
  // Fusionar transferencias: EL MÁS RECIENTE GANA
  if (Array.isArray(cuadreRemoto.transfer) || Array.isArray(cuadreLocal.transfer)) {
    if (localPrioridad) {
      resultado.transfer = Array.isArray(cuadreLocal.transfer) ? cuadreLocal.transfer : [];
    } else if (remotoEsMasReciente) {
      resultado.transfer = Array.isArray(cuadreRemoto.transfer) ? cuadreRemoto.transfer : [];
    } else {
      resultado.transfer = Array.isArray(cuadreLocal.transfer) ? cuadreLocal.transfer : [];
    }
    console.log(`💳 Transfer: ${resultado.transfer.length} (${localPrioridad ? 'local-prioridad' : remotoEsMasReciente ? 'remoto-reciente' : 'local-reciente'})`);
  }
  
  // Fusionar datafonos: EL MÁS RECIENTE GANA
  if (Array.isArray(cuadreRemoto.datafonos) || Array.isArray(cuadreLocal.datafonos)) {
    if (localPrioridad) {
      resultado.datafonos = Array.isArray(cuadreLocal.datafonos) ? cuadreLocal.datafonos : [];
    } else if (remotoEsMasReciente) {
      resultado.datafonos = Array.isArray(cuadreRemoto.datafonos) ? cuadreRemoto.datafonos : [];
    } else {
      resultado.datafonos = Array.isArray(cuadreLocal.datafonos) ? cuadreLocal.datafonos : [];
    }
    console.log(`📱 Datafonos: ${resultado.datafonos.length}`);
  }
  
  // Fusionar ventas (objeto, no array) - respeta localPrioridad
  if (cuadreRemoto.ventas && typeof cuadreRemoto.ventas === 'object') {
    const ventasLocal = cuadreLocal.ventas || {};
    const ventasRemoto = cuadreRemoto.ventas;
    resultado.ventas = {};
    
    // Combinar todos los campos de ambos
    const todosLosCampos = new Set([...Object.keys(ventasLocal), ...Object.keys(ventasRemoto)]);
    todosLosCampos.forEach(campo => {
      const valorLocal = ventasLocal[campo];
      const valorRemoto = ventasRemoto[campo];
      const localTieneValor = valorLocal !== undefined && valorLocal !== null && String(valorLocal).trim() !== "";
      const campoExisteEnRemoto = ventasRemoto.hasOwnProperty(campo);
      
      if (localPrioridad) {
        // Usuario editando: local gana
        if (localTieneValor) {
          resultado.ventas[campo] = valorLocal;
        } else if (campoExisteEnRemoto) {
          resultado.ventas[campo] = valorRemoto;
        }
      } else {
        // Sincronización: remoto gana (incluso si está vacío = borrado)
        if (campoExisteEnRemoto) {
          resultado.ventas[campo] = valorRemoto;
        } else if (localTieneValor) {
          resultado.ventas[campo] = valorLocal;
        }
      }
    });
  }
  
  // Fusionar turnos: EL MÁS RECIENTE GANA
  if (Array.isArray(cuadreRemoto.turnos) || Array.isArray(cuadreLocal.turnos)) {
    if (localPrioridad) {
      resultado.turnos = Array.isArray(cuadreLocal.turnos) ? cuadreLocal.turnos : [];
    } else if (remotoEsMasReciente) {
      resultado.turnos = Array.isArray(cuadreRemoto.turnos) ? cuadreRemoto.turnos : [];
    } else {
      resultado.turnos = Array.isArray(cuadreLocal.turnos) ? cuadreLocal.turnos : [];
    }
    console.log(`⏰ Turnos: ${resultado.turnos.length}`);
  }
  
  // Fusionar adelantos: EL MÁS RECIENTE GANA
  if (Array.isArray(cuadreRemoto.adelantos) || Array.isArray(cuadreLocal.adelantos)) {
    if (localPrioridad) {
      resultado.adelantos = Array.isArray(cuadreLocal.adelantos) ? cuadreLocal.adelantos : [];
    } else if (remotoEsMasReciente) {
      resultado.adelantos = Array.isArray(cuadreRemoto.adelantos) ? cuadreRemoto.adelantos : [];
    } else {
      resultado.adelantos = Array.isArray(cuadreLocal.adelantos) ? cuadreLocal.adelantos : [];
    }
    console.log(`💵 Adelantos: ${resultado.adelantos.length}`);
  }
  
  // Fusionar novedades: EL MÁS RECIENTE GANA
  if (Array.isArray(cuadreRemoto.novedades) || Array.isArray(cuadreLocal.novedades)) {
    if (localPrioridad) {
      resultado.novedades = Array.isArray(cuadreLocal.novedades) ? cuadreLocal.novedades : [];
    } else if (remotoEsMasReciente) {
      resultado.novedades = Array.isArray(cuadreRemoto.novedades) ? cuadreRemoto.novedades : [];
    } else {
      resultado.novedades = Array.isArray(cuadreLocal.novedades) ? cuadreLocal.novedades : [];
    }
    console.log(`📝 Novedades: ${resultado.novedades.length}`);
  }
  
  // Fusionar campos simples: usar el que tenga valor, preferir remoto si ambos tienen
  const valorInicialLocal = cuadreLocal.valorInicial;
  const valorInicialRemoto = cuadreRemoto.valorInicial;
  if (valorInicialRemoto !== undefined && valorInicialRemoto !== null && valorInicialRemoto !== 0) {
    resultado.valorInicial = valorInicialRemoto;
  } else if (valorInicialLocal !== undefined && valorInicialLocal !== null) {
    resultado.valorInicial = valorInicialLocal;
  }
  
  // Comentarios: fusionar EVITANDO DUPLICADOS
  const comentarioLocal = cuadreLocal.comentarioModificacion || "";
  const comentarioRemoto = cuadreRemoto.comentarioModificacion || "";
  if (comentarioRemoto && comentarioRemoto !== comentarioLocal) {
    // 🔹 Verificar si uno contiene al otro para evitar duplicados
    const localContieneRemoto = comentarioLocal.includes(comentarioRemoto);
    const remotoContieneLocal = comentarioRemoto.includes(comentarioLocal);
    
    if (localContieneRemoto) {
      // El local ya tiene todo lo del remoto, mantener local
      resultado.comentarioModificacion = comentarioLocal;
    } else if (remotoContieneLocal) {
      // El remoto tiene todo lo del local, usar remoto
      resultado.comentarioModificacion = comentarioRemoto;
    } else {
      // Son diferentes, usar el más largo (que probablemente tiene más información)
      resultado.comentarioModificacion = comentarioRemoto.length > comentarioLocal.length 
        ? comentarioRemoto 
        : comentarioLocal;
    }
  }
  
  // Totales: fusionar
  if (cuadreRemoto.totales && Object.keys(cuadreRemoto.totales).length > 0) {
    resultado.totales = { ...(cuadreLocal.totales || {}), ...cuadreRemoto.totales };
  }
  
  // Actualizar timestamp
  resultado.updated_at = cuadreRemoto.updated_at || cuadreLocal.updated_at;
  
  console.log("✅ Cuadres fusionados SIN PÉRDIDA DE DATOS - todos los registros combinados");
  return resultado;
}

function normalizarNumeroInventario(valor) {
  if (valor === null || valor === undefined) return 0;
  if (typeof valor === "number") return Number.isFinite(valor) ? valor : 0;
  if (typeof valor === "string") {
    const limpio = valor.replace(/[^0-9,.-]+/g, "").replace(/,/g, ".");
    const parsed = parseFloat(limpio);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
}

function mapearLineaInventario(inventario, linea, categoria, empresaId = null) {
  const cabecera = {
    fecha: inventario?.fecha || "",
    sede: inventario?.sede || "",
    encargadoId: inventario?.encargadoId || "",
    personalCocina: inventario?.personalCocina || "",
    novedades: inventario?.novedades || "",
    cerrado: !!inventario?.cerrado,
  };

  const row = {
    id: `${inventario.id}::${linea.id}`,
    sede: inventario?.sede || null,
    articulo: linea?.producto || null,
    cantidad: normalizarNumeroInventario(linea?.existencias),
    valorunitario: 0,
    valortotal:
      (linea?.solicitar === "Sí" || linea?.solicitar === "si")
        ? normalizarNumeroInventario(linea?.cantidad)
        : 0,
    responsable: inventario?.encargadoId || null,
    fecharegistro: inventario?.fecha || null,
    observaciones: JSON.stringify({
      inventarioId: inventario.id,
      categoria,
      lineaId: linea?.id,
      producto: linea?.producto,
      existencias: linea?.existencias ?? "",
      solicitar: linea?.solicitar ?? "No",
      cantidadSolicitada: linea?.cantidad ?? "",
      cabecera,
    }),
    updated_at: new Date().toISOString(),
  };
  
  // Agregar empresa_id si está disponible
  if (empresaId) {
    row.empresa_id = empresaId;
  }
  
  return row;
}

function mapearFilaInventarioDesdeSupabase(row) {
  const info = typeof row?.observaciones === "string"
    ? safelyParseJSON(row.observaciones, null)
    : row?.observaciones || null;

  const inventarioId =
    info?.inventarioId ||
    (row?.id && row.id.includes("::") ? row.id.split("::")[0] : row?.id);

  const cabecera = info?.cabecera || {};

  return {
    inventarioId,
    linea: {
      id: info?.lineaId || row?.id || uid(),
      producto: info?.producto || row?.articulo || "",
      existencias:
        info?.existencias !== undefined
          ? info.existencias
          : row?.cantidad !== null && row?.cantidad !== undefined
          ? String(row.cantidad)
          : "",
      solicitar: info?.solicitar || "No",
      cantidad: info?.cantidadSolicitada || "",
      categoria: info?.categoria || "diario",
    },
    cabecera: {
      fecha: cabecera?.fecha || row?.fecharegistro || "",
      sede: cabecera?.sede || row?.sede || "",
      encargadoId: cabecera?.encargadoId || row?.responsable || "",
      personalCocina: cabecera?.personalCocina || "",
      novedades: cabecera?.novedades || "",
      cerrado: !!cabecera?.cerrado,
    },
    raw: row,
  };
}

async function guardarInventarioEnSupabase(inventario, empresaId = null) {
  try {
    if (!inventario?.id) {
      console.error("Inventario sin id, no se puede guardar en Supabase");
      return null;
    }

    const lineas = Array.isArray(inventario?.lineas) ? inventario.lineas : [];
    const rows = lineas.map((linea) =>
      mapearLineaInventario(
        inventario,
        linea,
        linea?.categoria || "diario",
        empresaId
      )
    );

    if (!rows.length) {
      console.warn("Inventario sin líneas, se omite guardado en Supabase");
      return inventario;
    }

    await supabase
      .from("inventario")
      .delete()
      .like("id", `${inventario.id}::%`);

    const { data, error } = await supabase
      .from("inventario")
      .insert(rows)
      .select();

    if (error) {
      console.error("❌ Error guardando inventario en Supabase:", error);
      return null;
    }

    const agrupado = new Map();
    (data || rows).forEach((row) => {
      const mapped = mapearFilaInventarioDesdeSupabase(row);
      const key = mapped.inventarioId;
      if (!agrupado.has(key)) {
        agrupado.set(key, {
          id: key,
          fecha: mapped.cabecera.fecha,
          sede: mapped.cabecera.sede,
          encargadoId: mapped.cabecera.encargadoId,
          personalCocina: mapped.cabecera.personalCocina,
          novedades: mapped.cabecera.novedades,
          cerrado: mapped.cabecera.cerrado,
          lineas: [],
        });
      }
      agrupado.get(key).lineas.push({
        id: mapped.linea.id,
        producto: mapped.linea.producto,
        existencias: mapped.linea.existencias,
        solicitar: mapped.linea.solicitar,
        cantidad: mapped.linea.cantidad,
        categoria: mapped.linea.categoria,
      });
    });

    return agrupado.get(inventario.id) || inventario;
  } catch (e) {
    console.error("❌ Error en guardarInventarioEnSupabase:", e);
    return null;
  }
}

async function cargarInventariosDeSupabase(empresaId = null) {
  try {
    let query = supabase
      .from("inventario")
      .select("*")
      .order("fecharegistro", { ascending: false })
      .order("updated_at", { ascending: false });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { data, error } = await query;

    if (error) {
      console.error("❌ Error cargando inventarios desde Supabase:", error);
      return [];
    }

    const agrupado = new Map();

    (data || []).forEach((row) => {
      const mapped = mapearFilaInventarioDesdeSupabase(row);
      const key = mapped.inventarioId;
      if (!key) return;

      if (!agrupado.has(key)) {
        agrupado.set(key, {
          id: key,
          fecha: mapped.cabecera.fecha,
          sede: mapped.cabecera.sede,
          encargadoId: mapped.cabecera.encargadoId,
          personalCocina: mapped.cabecera.personalCocina,
          novedades: mapped.cabecera.novedades,
          cerrado: mapped.cabecera.cerrado,
          lineas: [],
        });
      } else {
        // Si cualquier línea tiene cerrado = true, marcar el inventario como cerrado
        if (mapped.cabecera.cerrado) {
          agrupado.get(key).cerrado = true;
        }
      }

      agrupado.get(key).lineas.push({
        id: mapped.linea.id,
        producto: mapped.linea.producto,
        existencias: mapped.linea.existencias,
        solicitar: mapped.linea.solicitar,
        cantidad: mapped.linea.cantidad,
        categoria: mapped.linea.categoria,
      });
    });

    return Array.from(agrupado.values()).sort((a, b) =>
      (a.fecha || "") < (b.fecha || "") ? 1 : -1
    );
  } catch (e) {
    console.error("❌ Error en cargarInventariosDeSupabase:", e);
    return [];
  }
}

async function eliminarInventarioDeSupabase(inventarioId) {
  try {
    if (!inventarioId) return false;
    const { error } = await supabase
      .from("inventario")
      .delete()
      .like("id", `${inventarioId}::%`);

    if (error) {
      console.error("❌ Error eliminando inventario en Supabase:", error);
      return false;
    }

    return true;
  } catch (e) {
    console.error("❌ Error en eliminarInventarioDeSupabase:", e);
    return false;
  }
}

function prepararProcesoPagoParaSupabase(tarea) {
  if (!tarea) return null;
  const detallesPlano = JSON.parse(JSON.stringify(tarea));
  const descripcion =
    tarea.comentariosGestion ||
    tarea.motivo ||
    tarea.novedades ||
    tarea.comunicacionTexto ||
    tarea.detalleSolicitud ||
    "";

  return {
    id: tarea.id || uid(),
    nombre: tarea.tipo || tarea.nombre || tarea.id || "Proceso",
    descripcion: descripcion || null,
    estado: tarea.estado || "Pendiente",
    fechacreacion: tarea.fechaCreacion || null,
    fechaejecucion: tarea.fechaLimite || null,
    responsable: tarea.responsableId || tarea.responsable || null,
    detalles: detallesPlano,
    updated_at: new Date().toISOString(),
  };
}

function mapearProcesoPagoDesdeSupabase(row) {
  const detalles =
    typeof row?.detalles === "string"
      ? safelyParseJSON(row.detalles, {})
      : row?.detalles || {};

  const soportes = Array.isArray(detalles?.soportes)
    ? detalles.soportes.map((s) => ({ ...s }))
    : [];
  if (!Array.isArray(detalles.soportes)) {
    detalles.soportes = soportes;
  }

  // Mapear pagosEfectivo para Pago de facturas en efectivo
  const pagosEfectivo = Array.isArray(detalles?.pagosEfectivo)
    ? detalles.pagosEfectivo.map((p) => ({ ...p }))
    : [];
  detalles.pagosEfectivo = pagosEfectivo;

  // Mapear documentosAdjuntos para Afiliación a seguridad social
  const documentosAdjuntos = Array.isArray(detalles?.documentosAdjuntos)
    ? detalles.documentosAdjuntos.map((d) => ({ ...d }))
    : [];
  detalles.documentosAdjuntos = documentosAdjuntos;

  // Mapear empleadosSeleccionados para liquidaciones
  const empleadosSeleccionados = Array.isArray(detalles?.empleadosSeleccionados)
    ? detalles.empleadosSeleccionados.map((e) => ({ ...e }))
    : [];
  detalles.empleadosSeleccionados = empleadosSeleccionados;

  // Mapear empleadosFirma para firma de documentos
  const empleadosFirma = Array.isArray(detalles?.empleadosFirma)
    ? detalles.empleadosFirma.map((e) => ({ ...e }))
    : [];
  detalles.empleadosFirma = empleadosFirma;

  // Mapear soportesFudo para cancelaciones FUDO
  const soportesFudo = Array.isArray(detalles?.soportesFudo)
    ? detalles.soportesFudo.map((s) => ({ ...s }))
    : [];
  detalles.soportesFudo = soportesFudo;

  let adjuntoGestion =
    detalles?.adjuntoGestion && typeof detalles.adjuntoGestion === "object"
      ? { ...detalles.adjuntoGestion }
      : null;
  if (
    adjuntoGestion &&
    typeof adjuntoGestion.url === "string" &&
    (adjuntoGestion.url.startsWith("blob:") || adjuntoGestion.url.startsWith("data:"))
  ) {
    adjuntoGestion = null;
  }
  detalles.adjuntoGestion = adjuntoGestion;

  const base = {
    id: row?.id || detalles.id || uid(),
    fechaCreacion: row?.fechacreacion || detalles.fechaCreacion || "",
    fechaLimite: row?.fechaejecucion || detalles.fechaLimite || "",
    estado: row?.estado || detalles.estado || "Pendiente",
    responsableId: row?.responsable || detalles.responsableId || "",
    tipo: detalles.tipo || row?.nombre || detalles.nombre || "",
    tipoModulo: detalles.tipoModulo || "ADMIN",
  };

  const descripcion = row?.descripcion || detalles.descripcion || "";
  if (!detalles.comentariosGestion && descripcion) {
    detalles.comentariosGestion = descripcion;
  }

  return {
    ...base,
    ...detalles,
    soportes,
    pagosEfectivo,
    documentosAdjuntos,
    empleadosSeleccionados,
    empleadosFirma,
    soportesFudo,
    adjuntoGestion,
  };
}

async function guardarProcesoPagoEnSupabase(tarea, empresaId = null) {
  try {
    const payload = prepararProcesoPagoParaSupabase(tarea);
    if (!payload) {
      console.error("❌ No se pudo preparar el payload para Supabase");
      return null;
    }
    
    // Agregar empresa_id si está disponible y no es "todas"
    if (empresaId && empresaId !== "todas") {
      payload.empresa_id = empresaId;
    }
    
    console.log("📝 Guardando proceso de pago en Supabase:", payload.id, "empresa_id:", empresaId);

    const { data, error } = await supabase
      .from("procesos_pago")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.error("❌ Error guardando proceso de pago en Supabase:", error);
      console.error("❌ Payload enviado:", JSON.stringify(payload, null, 2));
      return null;
    }
    
    console.log("✅ Proceso de pago guardado exitosamente:", data?.id);

    return mapearProcesoPagoDesdeSupabase(data || payload);
  } catch (e) {
    console.error("❌ Error en guardarProcesoPagoEnSupabase:", e);
    return null;
  }
}

async function cargarProcesosPagoDeSupabase(empresaId = null) {
  try {
    console.log("🔄 Cargando procesos de pago... empresaId recibido:", empresaId);
    
    let data, error;
    
    if (empresaId && empresaId !== "todas") {
      // 🔹 Filtrar por empresa específica + incluir tareas con empresa_id NULL (antiguas)
      const resultado = await supabase
        .from("procesos_pago")
        .select("*")
        .or(`empresa_id.eq.${empresaId},empresa_id.is.null`)
        .order("created_at", { ascending: false });
      
      data = resultado.data;
      error = resultado.error;
      
      console.log(`📊 Tareas encontradas (empresa ${empresaId} + NULL): ${(data || []).length}`);
    } else {
      // Sin empresa o "todas", cargar todas
      const resultado = await supabase
        .from("procesos_pago")
        .select("*")
        .order("created_at", { ascending: false });
      
      data = resultado.data;
      error = resultado.error;
    }

    if (error) {
      console.error("❌ Error cargando procesos de pago desde Supabase:", error);
      console.error("❌ Detalles del error:", JSON.stringify(error));
      return [];
    }

    console.log(`✅ Cargadas ${(data || []).length} tareas de procesos administrativos para empresa: ${empresaId || 'TODAS'}`);
    
    // Mostrar las primeras tareas para depuración
    if (data && data.length > 0) {
      console.log("📋 Primeras 3 tareas cargadas:");
      data.slice(0, 3).forEach((t, i) => {
        console.log(`   ${i + 1}. ID: ${t.id}, Estado: ${t.estado}, Tipo: ${t.nombre || t.detalles?.tipo}, empresa_id: ${t.empresa_id}`);
      });
    }
    
    return (data || []).map((row) => mapearProcesoPagoDesdeSupabase(row));
  } catch (e) {
    console.error("❌ Error en cargarProcesosPagoDeSupabase:", e);
    console.error("❌ Stack:", e.stack);
    return [];
  }
}

async function eliminarProcesoPagoEnSupabase(id) {
  try {
    if (!id) return false;
    const { error } = await supabase
      .from("procesos_pago")
      .delete()
      .eq("id", id);

    if (error) {
      console.error("❌ Error eliminando proceso de pago en Supabase:", error);
      return false;
    }

    return true;
  } catch (e) {
    console.error("❌ Error en eliminarProcesoPagoEnSupabase:", e);
    return false;
  }
}

async function subirSoporteProcesoPago(file, opciones = {}) {
  if (!file) return null;

  const nombreVisible = (opciones?.nombre || file.name || "Soporte").trim() || "Soporte";
  const carpetaBase = opciones?.carpeta || "procesos-admin";
  const tareaId = opciones?.tareaId ? slugifyPathSegment(opciones.tareaId) : null;
  const extension = file.name && file.name.includes(".")
    ? file.name.substring(file.name.lastIndexOf("."))
    : "";

  const identificadorArchivo = uid();
  const partesRuta = [slugifyPathSegment(carpetaBase)];
  if (tareaId) {
    partesRuta.push(tareaId);
  }
  const ruta = `${partesRuta.join("/")}/${Date.now()}_${identificadorArchivo}_${slugifyPathSegment(nombreVisible)}${extension}`;

  const { error: uploadError } = await supabase.storage
    .from(SUPABASE_BUCKET_DOCS)
    .upload(ruta, file, {
      cacheControl: "3600",
      upsert: false,
      contentType: file.type || undefined,
    });

  if (uploadError) {
    throw new Error(uploadError.message || "No se pudo subir el soporte a Supabase Storage.");
  }

  const { data: urlData, error: urlError } = supabase.storage
    .from(SUPABASE_BUCKET_DOCS)
    .getPublicUrl(ruta);

  if (urlError || !urlData?.publicUrl) {
    throw new Error(urlError?.message || "No se pudo obtener la URL pública del soporte subido.");
  }

  return {
    id: identificadorArchivo,
    nombre: nombreVisible,
    url: urlData.publicUrl,
    tipo: file.type || "",
    size: typeof file.size === "number" ? file.size : null,
    bucket: SUPABASE_BUCKET_DOCS,
    path: ruta,
    creadoEn: new Date().toISOString(),
  };
}

// Guardar liquidación en Supabase
async function guardarLiquidacionEnSupabase(liquidacion, empresaId = null) {
  try {
    // Convertir arrays/objetos a JSON strings para JSONB
    const detalle = liquidacion.detalle ? JSON.stringify(liquidacion.detalle) : null;
    const vacacionesbuckets = liquidacion.vacacionesBuckets ? JSON.stringify(liquidacion.vacacionesBuckets) : null;
    
    // Usar nombres de columnas exactos (minúsculas) como existen en Supabase
    const payload = {
      id: liquidacion.id || uid(),
      empleadoid: liquidacion.empleadoId || null,
      empleadonombre: liquidacion.empleadoNombre || null,
      empleadodoc: liquidacion.empleadoDoc || null,
      tipo: liquidacion.tipo || null,
      valor: Number(liquidacion.total ?? liquidacion.valor ?? 0) || 0,
      fecha: liquidacion.fecha || toISO(new Date()),
      fechainicio: liquidacion.fechaInicio || null,
      fechafin: liquidacion.fechaFin || null,
      periodo: liquidacion.periodo || null,
      diasvacacionesliquidados: liquidacion.diasVacacionesLiquidados || null,
      detalle: detalle,
      vacacionesbuckets: vacacionesbuckets,
    };
    
    // Agregar empresa_id si está disponible y no es "todas"
    if (empresaId && empresaId !== "todas") {
      payload.empresa_id = empresaId;
    }
    
    console.log("📦 Preparando guardado en Supabase:", {
      id: payload.id,
      tipo: payload.tipo,
      valor: payload.valor,
      empleado: payload.empleadonombre,
    });

    console.log("📡 Conectando a tabla 'liquidaciones' en Supabase...");
    
    // Intentar insertar
    const { error: insertError } = await supabase
      .from("liquidaciones")
      .insert([payload]);

    if (insertError) {
      // Si el error es de duplicate key, intentamos actualizar
      if (insertError.code === '23505' || insertError.message.includes('duplicate')) {
        console.log("🔄 ID existe, intentando actualizar...");
        const { error: updateError } = await supabase
          .from("liquidaciones")
          .update(payload)
          .eq("id", payload.id);
        
        if (updateError) {
          console.error("❌ Error actualizando liquidación:", updateError.message);
          return false;
        }
        console.log("✅ Liquidación actualizada en Supabase:", payload.id);
      } else {
        console.error("❌ Error insertando liquidación:", insertError.message);
        return false;
      }
    } else {
      console.log("✅ Liquidación guardada en Supabase:", payload.id);
    }
    
    return true;
  } catch (e) {
    console.error("❌ Error en guardarLiquidacionEnSupabase:", e.message);
    return false;
  }
}

// Eliminar liquidación de Supabase
async function eliminarLiquidacionDeSupabase(liquidacionId) {
  try {
    const { error } = await supabase
      .from("liquidaciones")
      .delete()
      .eq("id", liquidacionId);

    if (error) {
      console.error("❌ Error eliminando liquidación:", error.message);
      return false;
    }
    
    console.log("✅ Liquidación eliminada de Supabase:", liquidacionId);
    return true;
  } catch (e) {
    console.error("❌ Error en eliminarLiquidacionDeSupabase:", e.message);
    return false;
  }
}

// Cargar liquidaciones desde Supabase
async function cargarLiquidacionesDeSupabase(empresaId = null) {
  try {
    let query = supabase
      .from("liquidaciones")
      .select("*")
      .order("fecha", { ascending: false });
    
    // 🔹 Filtrar por empresa si no es "todas" (para multi-empresa)
    // Incluir también los que tienen empresa_id NULL (liquidaciones antiguas)
    if (empresaId && empresaId !== "todas") {
      query = query.or(`empresa_id.eq.${empresaId},empresa_id.is.null`);
    }
    
    const { data, error } = await query;
    
    if (error) {
      console.error("Error cargando liquidaciones:", error);
      return [];
    }
    
    // Mapear desde la estructura real de la tabla (con nombres en minúsculas)
    const liquidaciones = (data || []).map((row) => {
      let detalle = [];
      let vacacionesbuckets = [];
      
      // Parsear detalle si viene como JSON
      if (row.detalle) {
        if (typeof row.detalle === 'string') {
          try {
            detalle = JSON.parse(row.detalle);
          } catch (e) {
            detalle = [];
          }
        } else if (Array.isArray(row.detalle)) {
          detalle = row.detalle;
        }
      }
      
      // Parsear vacacionesbuckets si viene como JSON
      if (row.vacacionesbuckets) {
        if (typeof row.vacacionesbuckets === 'string') {
          try {
            vacacionesbuckets = JSON.parse(row.vacacionesbuckets);
          } catch (e) {
            vacacionesbuckets = [];
          }
        } else if (Array.isArray(row.vacacionesbuckets)) {
          vacacionesbuckets = row.vacacionesbuckets;
        }
      }
      
      return {
        id: row.id,
        tipo: row.tipo || "",
        empleadoId: row.empleadoid || "",
        empleadoNombre: row.empleadonombre || "",
        empleadoDoc: row.empleadodoc || "",
        valor: row.valor || 0,
        total: row.valor || 0,
        fecha: row.fecha || "",
        fechaInicio: row.fechainicio || null,
        fechaFin: row.fechafin || null,
        periodo: row.periodo || "",
        diasVacacionesLiquidados: row.diasvacacionesliquidados || null,
        detalle: detalle,
        vacacionesBuckets: vacacionesbuckets,
        creadoEn: row.created_at || null,
        actualizadoEn: row.updated_at || null,
      };
    });
    
    console.log(`✅ ${liquidaciones.length} liquidaciones cargadas desde Supabase`);
    return liquidaciones;
  } catch (e) {
    console.error("Error en cargarLiquidacionesDeSupabase:", e);
    return [];
  }
}

// Mapear vacación desde Supabase a formato interno
function mapVacacionSupabase(row) {
  if (!row) return null;

  return {
    id: row.id,
    empleadoId: row.empleadoid || "",
    inicio: row.fechainicio || "",
    fin: row.fechafin || "",
    dias: row.diassolicitados ? Number(row.diassolicitados) : 0,
    estado: row.estado || "Pendiente",
    aprobadoPor: row.aprobadopor || "",
    fechaAprobacion: row.fechaaprobacion || "",
    creadoEn: row.created_at || null,
    actualizadoEn: row.updated_at || null,
  };
}

// Preparar vacación para guardar en Supabase
function prepararPayloadVacacion(v) {
  if (!v) return null;
  const orNull = (value) => {
    if (value === "" || typeof value === "undefined" || value === null) return null;
    if (typeof value === "string") {
      const trimmed = value.trim();
      return trimmed === "" ? null : trimmed;
    }
    return value;
  };

  return {
    id: v.id || uid(),
    empleadoid: orNull(v.empleadoId),
    fechainicio: orNull(v.inicio),
    fechafin: orNull(v.fin),
    diassolicitados: v.dias || 0,
    estado: v.estado || "Pendiente",
    aprobadopor: orNull(v.aprobadoPor),
    fechaaprobacion: orNull(v.fechaAprobacion),
    created_at: v.creadoEn || new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

// Guardar vacación en Supabase
async function guardarVacacionesEnSupabase(vacacion, empresaId = null) {
  try {
    console.log("📝 Vacación a guardar (original):", JSON.stringify(vacacion, null, 2));
    
    const payload = prepararPayloadVacacion(vacacion);
    if (!payload) {
      console.error("❌ No se pudo preparar el payload de la vacación");
      return null;
    }
    
    // Agregar empresa_id si está disponible
    if (empresaId) {
      payload.empresa_id = empresaId;
    }

    console.log("📤 Payload preparado para Supabase:", JSON.stringify(payload, null, 2));

    let result;
    if (vacacion.id) {
      console.log("🔄 Intentando UPDATE del registro...");
      // Intentar UPDATE
      result = await supabase
        .from("vacaciones")
        .update(payload)
        .eq("id", vacacion.id)
        .select();

      const { data: updateData, error: updateError } = result;

      // Si UPDATE no encontró el registro, hacer INSERT
      if (updateError) {
        console.log("⚠️  UPDATE falló, intentando INSERT...");
        result = await supabase
          .from("vacaciones")
          .insert([payload])
          .select();
      } else if (!updateData || updateData.length === 0) {
        console.log("⚠️  UPDATE no afectó ningún registro, intentando INSERT...");
        result = await supabase
          .from("vacaciones")
          .insert([payload])
          .select();
      }
    } else {
      console.log("✨ Haciendo INSERT de nuevo registro...");
      // INSERT
      result = await supabase
        .from("vacaciones")
        .insert([payload])
        .select();
    }

    const { data, error } = result;

    if (error) {
      console.error("❌ Error guardando vacación en Supabase:");
      console.error(JSON.stringify(error, null, 2));
      console.error("Código de error:", error.code);
      console.error("Mensaje:", error.message);
      return null;
    }

    console.log("✅ Respuesta de Supabase:", JSON.stringify(data, null, 2));
    const registro = Array.isArray(data) ? data[0] : data;
    const mapeada = mapVacacionSupabase(registro || payload);
    console.log("✅ Vacación mapeada:", JSON.stringify(mapeada, null, 2));
    return mapeada;
  } catch (e) {
    console.error("❌ Error en guardarVacacionesEnSupabase:", e.message);
    console.error("Stack:", e.stack);
    return null;
  }
}

// Cargar vacaciones desde Supabase
async function cargarVacacionesDeSupabase(empresaId = null) {
  try {
    console.log("🔍 Cargando vacaciones desde Supabase...");
    let query = supabase
      .from("vacaciones")
      .select("id, empleadoid, fechainicio, fechafin, diassolicitados, estado, aprobadopor, fechaaprobacion, created_at, updated_at, empresa_id")
      .order("created_at", { ascending: false });
    
    // Si se especifica empresaId, filtrar por empresa
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { data, error } = await query;

    if (error) {
      console.error("❌ Error cargando vacaciones:");
      console.error(JSON.stringify(error, null, 2));
      return [];
    }

    console.log("📊 Datos crudos de Supabase:", JSON.stringify(data, null, 2));
    const mapeadas = (data || []).map(mapVacacionSupabase).filter(Boolean);
    console.log("✅ Vacaciones mapeadas:", JSON.stringify(mapeadas, null, 2));
    return mapeadas;
  } catch (e) {
    console.error("❌ Error en cargarVacacionesDeSupabase:", e.message);
    console.error(e.stack);
    return [];
  }
}

/* ====================== PRESTAMOS SUPABASE ====================== */
function mapPrestamoSupabase(row) {
  if (!row) return null;

  // Parsear plan si viene como string JSON
  let plan = [];
  if (row.plan) {
    if (typeof row.plan === "string") {
      try {
        plan = JSON.parse(row.plan);
      } catch (e) {
        console.warn("Error al parsear plan de cuotas:", e);
        plan = [];
      }
    } else if (Array.isArray(row.plan)) {
      plan = row.plan;
    }
  }

  return {
    id: row.id,
    empleadoId: row.empleadoid || "",
    valor: row.valor ? Number(row.valor) : 0,
    monto: row.valor ? Number(row.valor) : 0,
    fecha: row.fechasolicitud || "",
    fechaSolicitud: row.fechasolicitud || "",
    fechaAprobacion: row.fechaaprobacion || "",
    formaPago: row.forma_pago || "Quincenal",
    tipo: row.tipo || "Préstamo",
    cuotas: row.cuotas ? Number(row.cuotas) : 12,
    cuotasRestantes: row.cuotasrestantes ? Number(row.cuotasrestantes) : (row.cuotas ? Number(row.cuotas) : 12),
    plan: plan,
    saldo: row.saldo ? Number(row.saldo) : (row.valor ? Number(row.valor) : 0),
    estado: row.estado || "Pendiente",
    razon: row.razon || "",
    motivo: row.motivo || "",
    descFecha: row.desc_fecha || "",
    descSede: row.desc_sede || "",
    motivoDanio: row.motivo_danio || "",
    creadoEn: row.created_at || null,
    actualizadoEn: row.updated_at || null,
  };
}

// Preparar préstamo para guardar en Supabase
function prepararPayloadPrestamo(p) {
  if (!p) return null;
  const orNull = (value) => {
    if (value === "" || typeof value === "undefined" || value === null) return null;
    if (typeof value === "string") {
      const trimmed = value.trim();
      return trimmed === "" ? null : trimmed;
    }
    return value;
  };

  return {
    id: p.id || uid(),
    empleadoid: orNull(p.empleadoId),
    valor: p.valor || p.monto || 0,
    cuotas: p.cuotas || 12,
    cuotasrestantes: p.cuotasRestantes || (p.cuotas || 12),
    saldo: p.saldo || p.valor || p.monto || 0,
    fechasolicitud: orNull(p.fecha || p.fechaSolicitud),
    fechaaprobacion: orNull(p.fechaAprobacion),
    estado: p.estado || "Pendiente",
    razon: orNull(p.razon),
    motivo: orNull(p.motivo),
    // Campos adicionales que faltaban
    tipo: orNull(p.tipo) || "Préstamo",
    forma_pago: orNull(p.formaPago) || "Quincenal",
    desc_fecha: orNull(p.descFecha),
    desc_sede: orNull(p.descSede),
    motivo_danio: orNull(p.motivoDanio),
    plan: p.plan ? JSON.stringify(p.plan) : "[]",
    created_at: p.creadoEn || new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

// Guardar préstamo en Supabase
