// Guardar en bitácora cuando se elimina un préstamo
async function guardarBitacoraPrestamoEliminado(prestamo, usuarioId, usuarioNombre, motivo) {
  try {
    const payload = {
      id: uid(),
      prestamo_id: prestamo.id,
      empleado_id: prestamo.empleadoId,
      empleado_nombre: prestamo.empleado?.nombre || "Desconocido",
      valor: prestamo.valor || 0,
      cuotas: prestamo.cuotas || 0,
      cuotas_descontadas: (prestamo.plan || []).filter(c => c.noDescontable).length,
      saldo: prestamo.saldo || prestamo.valor || 0,
      fecha_prestamo: prestamo.fecha || prestamo.fechaSolicitud || null,
      tipo_prestamo: prestamo.tipo || "Préstamo",
      estado_al_eliminar: prestamo.estado || "Pendiente",
      plan_cuotas: JSON.stringify(prestamo.plan || []),
      usuario_eliminador_id: usuarioId,
      usuario_eliminador_nombre: usuarioNombre,
      motivo_eliminacion: motivo,
      fecha_eliminacion: new Date().toISOString(),
      empresa_id: prestamo.empresa_id || null
    };

    console.log("📝 Guardando en bitácora de préstamos eliminados:", payload);

    const { data, error } = await supabase
      .from("bitacora_prestamos_eliminados")
      .insert([payload])
      .select();

    if (error) {
      console.error("❌ Error guardando bitácora:", error);
      // Intentar crear la tabla si no existe
      if (error.code === "42P01") {
        console.log("⚠️ La tabla bitacora_prestamos_eliminados no existe. Guardando en localStorage.");
        // Guardar en localStorage como respaldo
        const bitacoraLocal = JSON.parse(localStorage.getItem("bitacora_prestamos_eliminados") || "[]");
        bitacoraLocal.push(payload);
        localStorage.setItem("bitacora_prestamos_eliminados", JSON.stringify(bitacoraLocal));
      }
      return null;
    }

    console.log("✅ Bitácora guardada correctamente");
    return data;
  } catch (e) {
    console.error("❌ Error en guardarBitacoraPrestamoEliminado:", e);
    return null;
  }
}

