async function cargarInfoSedesDeSupabase(empresaId = null) {
  try {
    let query = supabase
      .from("directorio_sedes_info")
      .select("*")
      .order("sede_nombre", { ascending: true });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { data, error } = await query;
    if (error) {
      console.error("❌ Error cargando info sedes:", error);
      return [];
    }
    return (data || []).map(s => {
      const clavesRaw = typeof s.claves === 'string' ? JSON.parse(s.claves) : (s.claves || []);
      // Separar claves reales de bancos extra guardados
      const clavesReales = clavesRaw.filter(c => !c._esBanco);
      const bancosExtra = clavesRaw.filter(c => c._esBanco).map(c => ({
        id: c.id,
        banco: c.banco,
        tipo_cuenta: c.tipo_cuenta,
        numero_cuenta: c.numero_cuenta
      }));
      
      // Reconstruir array de bancos
      const bancosReconstruidos = [];
      if (s.banco) {
        bancosReconstruidos.push({
          id: 'banco_principal',
          banco: s.banco,
          tipo_cuenta: s.tipo_cuenta || '',
          numero_cuenta: s.numero_cuenta || ''
        });
      }
      bancosReconstruidos.push(...bancosExtra);
      
      return {
        ...s,
        claves: clavesReales,
        datos_importantes: typeof s.datos_importantes === 'string' ? JSON.parse(s.datos_importantes) : (s.datos_importantes || []),
        bancos: bancosReconstruidos
      };
    });
  } catch (e) {
    console.error("❌ Error en cargarInfoSedesDeSupabase:", e);
    return [];
  }
}

async function guardarInfoSedeEnSupabase(info, empresaId = null) {
  try {
    // Si hay múltiples bancos, guardarlos en el campo banco como JSON
    // Para compatibilidad con la BD existente que no tiene columna "bancos"
    let bancoData = info.banco || null;
    if (info.bancos && info.bancos.length > 0) {
      // Guardar el primer banco en los campos tradicionales para compatibilidad
      bancoData = info.bancos[0].banco || null;
    }
    
    const payload = {
      id: info.id || uid(),
      sede_id: info.sede_id || null,
      sede_nombre: info.sede_nombre || "",
      nit: info.nit || null,
      representante_legal: info.representante_legal || null,
      correo_notificaciones: info.correo_notificaciones || null,
      telefono_local: info.telefono_local || null,
      telefono_admin: info.telefono_admin || null,
      direccion: info.direccion || null,
      banco: bancoData,
      tipo_cuenta: info.bancos && info.bancos.length > 0 ? info.bancos[0].tipo_cuenta : (info.tipo_cuenta || null),
      numero_cuenta: info.bancos && info.bancos.length > 0 ? info.bancos[0].numero_cuenta : (info.numero_cuenta || null),
      claves: JSON.stringify([
        ...(info.claves || []),
        // Guardar bancos adicionales en claves con prefijo especial
        ...(info.bancos && info.bancos.length > 1 ? info.bancos.slice(1).map((b, i) => ({
          id: b.id || `banco_extra_${i}`,
          nombre: `🏦 Banco ${i + 2}: ${b.banco}`,
          valor: `${b.tipo_cuenta} - ${b.numero_cuenta}`,
          _esBanco: true,
          banco: b.banco,
          tipo_cuenta: b.tipo_cuenta,
          numero_cuenta: b.numero_cuenta
        })) : [])
      ]),
      datos_importantes: JSON.stringify(info.datos_importantes || []),
      observaciones: info.observaciones || null,
      updated_at: new Date().toISOString()
    };
    
    if (empresaId) {
      payload.empresa_id = empresaId;
    }

    const { data, error } = await supabase
      .from("directorio_sedes_info")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    if (error) {
      console.error("❌ Error guardando info sede:", error);
      return null;
    }
    
    if (data) {
      // Reconstruir bancos desde los datos guardados
      const clavesGuardadas = JSON.parse(data.claves || '[]');
      const clavesReales = clavesGuardadas.filter(c => !c._esBanco);
      const bancosExtra = clavesGuardadas.filter(c => c._esBanco).map(c => ({
        id: c.id,
        banco: c.banco,
        tipo_cuenta: c.tipo_cuenta,
        numero_cuenta: c.numero_cuenta
      }));
      
      const bancosReconstruidos = [];
      if (data.banco) {
        bancosReconstruidos.push({
          id: 'banco_principal',
          banco: data.banco,
          tipo_cuenta: data.tipo_cuenta || '',
          numero_cuenta: data.numero_cuenta || ''
        });
      }
      bancosReconstruidos.push(...bancosExtra);
      
      return {
        ...data,
        claves: clavesReales,
        datos_importantes: JSON.parse(data.datos_importantes || '[]'),
        bancos: bancosReconstruidos
      };
    }
    return null;
  } catch (e) {
    console.error("❌ Error en guardarInfoSedeEnSupabase:", e);
    return null;
  }
}

