async function cargarPlanesTrabajoDeSupabase(empresaId = null) {
  try {
    let query = supabase
      .from("planes_trabajo")
      .select("*")
      .order("created_at", { ascending: false });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { data, error } = await query;
    if (error) {
      console.error("❌ Error cargando planes de trabajo:", error);
      return [];
    }
    return (data || []).map(p => {
      // Parsear tareas - puede estar en 'tareas' o 'checklist'
      let tareasParseadas = [];
      if (p.tareas) {
        tareasParseadas = typeof p.tareas === 'string' ? JSON.parse(p.tareas) : p.tareas;
      } else if (p.checklist) {
        tareasParseadas = typeof p.checklist === 'string' ? JSON.parse(p.checklist) : p.checklist;
      }
      
      return {
        ...p,
        tareas: tareasParseadas,
        checklist: tareasParseadas,
        // Mapear campos legacy a nuevos campos si no existen
        empleado_asignado_id: p.empleado_asignado_id || p.responsable_id || null,
        empleado_asignado_nombre: p.empleado_asignado_nombre || p.responsable_nombre || null,
        fecha_limite: p.fecha_limite || p.fecha || null,
        cerrado: p.cerrado || false,
        porcentaje_completado: p.porcentaje_completado || 0
      };
    });
  } catch (e) {
    console.error("❌ Error en cargarPlanesTrabajoDeSupabase:", e);
    return [];
  }
}

async function guardarPlanTrabajoEnSupabase(plan, empresaId = null) {
  try {
    // Preparar las tareas como string JSON si no lo son
    let tareasJSON = plan.tareas;
    if (typeof tareasJSON !== 'string') {
      tareasJSON = JSON.stringify(tareasJSON || []);
    }
    
    const payload = {
      id: plan.id || uid(),
      nombre: plan.nombre || "",
      descripcion: plan.descripcion || "",
      fecha: plan.fecha || plan.fecha_limite || new Date().toISOString().split('T')[0],
      fecha_limite: plan.fecha_limite || plan.fecha || null,
      sede_id: plan.sede_id || null,
      sede_nombre: plan.sede_nombre || null,
      // Campos legacy para compatibilidad
      responsable_id: plan.empleado_asignado_id || plan.responsable_id || null,
      responsable_nombre: plan.empleado_asignado_nombre || plan.responsable_nombre || null,
      // Nuevos campos para asignación
      empleado_asignado_id: plan.empleado_asignado_id || plan.responsable_id || null,
      empleado_asignado_nombre: plan.empleado_asignado_nombre || plan.responsable_nombre || null,
      // Tareas - usar campo 'tareas' o 'checklist' según lo que exista
      tareas: tareasJSON,
      checklist: tareasJSON, // Mantener compatibilidad con campo anterior
      estado: plan.estado || "pendiente",
      porcentaje_completado: plan.porcentaje_completado || 0,
      observaciones_generales: plan.observaciones_generales || null,
      cerrado: plan.cerrado || false,
      cerrado_por: plan.cerrado_por || null,
      cerrado_por_nombre: plan.cerrado_por_nombre || null,
      fecha_cierre: plan.fecha_cierre || null,
      // Campos para devolución de planes
      observaciones_gerencia: plan.observaciones_gerencia || null,
      devuelto_por: plan.devuelto_por || null,
      devuelto_por_nombre: plan.devuelto_por_nombre || null,
      fecha_devolucion: plan.fecha_devolucion || null,
      created_at: plan.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
    
    if (empresaId) {
      payload.empresa_id = empresaId;
    }

    console.log("📦 Payload a guardar en planes_trabajo:", payload);

    // Intentar con todos los campos primero
    let { data, error } = await supabase
      .from("planes_trabajo")
      .upsert(payload, { onConflict: "id" })
      .select()
      .maybeSingle();

    // Si hay error, intentar con campos mínimos
    if (error) {
      console.warn("⚠️ Error con todos los campos, intentando con campos básicos...", error.message);
      
      // Payload mínimo con solo campos que probablemente existan
      const payloadMinimo = {
        id: payload.id,
        nombre: payload.nombre,
        descripcion: payload.descripcion,
        fecha: payload.fecha,
        sede_id: payload.sede_id,
        sede_nombre: payload.sede_nombre,
        responsable_id: payload.responsable_id,
        responsable_nombre: payload.responsable_nombre,
        checklist: payload.checklist,
        estado: payload.estado,
        observaciones_generales: payload.observaciones_generales,
        observaciones_gerencia: payload.observaciones_gerencia,
        devuelto_por: payload.devuelto_por,
        devuelto_por_nombre: payload.devuelto_por_nombre,
        fecha_devolucion: payload.fecha_devolucion,
        updated_at: payload.updated_at
      };
      
      if (empresaId) {
        payloadMinimo.empresa_id = empresaId;
      }

      console.log("📦 Intentando con payload mínimo:", payloadMinimo);

      const resultado2 = await supabase
        .from("planes_trabajo")
        .upsert(payloadMinimo, { onConflict: "id" })
        .select()
        .maybeSingle();
      
      if (resultado2.error) {
        console.error("❌ Error guardando plan de trabajo:", resultado2.error);
        return null;
      }
      
      data = resultado2.data;
    }
    
    if (data) {
      // Parsear tareas/checklist al retornar
      const tareasParseadas = data.tareas 
        ? (typeof data.tareas === 'string' ? JSON.parse(data.tareas) : data.tareas)
        : (data.checklist 
          ? (typeof data.checklist === 'string' ? JSON.parse(data.checklist) : data.checklist)
          : []);
      
      return { ...data, tareas: tareasParseadas, checklist: tareasParseadas };
    }
    
    return null;
  } catch (e) {
    console.error("❌ Error en guardarPlanTrabajoEnSupabase:", e);
    return null;
  }
}

async function eliminarPlanTrabajoEnSupabase(id) {
  try {
    const { error } = await supabase.from("planes_trabajo").delete().eq("id", id);
    return !error;
  } catch (e) {
    return false;
  }
}

