async function guardarBitacoraPlanTrabajo(registro, empresaId = null) {
  try {
    const payload = {
      id: uid(),
      plan_id: registro.plan_id,
      plan_nombre: registro.plan_nombre || "",
      accion: registro.accion, // "creado", "asignado", "tarea_completada", "guardado", "cerrado", "reabierto"
      descripcion: registro.descripcion || "",
      empleado_id: registro.empleado_id || null,
      empleado_nombre: registro.empleado_nombre || "",
      sede_id: registro.sede_id || null,
      sede_nombre: registro.sede_nombre || "",
      fecha: new Date().toISOString(),
      mes: new Date().getMonth() + 1,
      anio: new Date().getFullYear(),
      datos_adicionales: JSON.stringify(registro.datos_adicionales || {}),
      empresa_id: empresaId
    };
    
    const { error } = await supabase
      .from("planes_trabajo_bitacora")
      .insert([payload]);
    
    if (error) {
      console.error("❌ Error guardando bitácora:", error);
      return false;
    }
    return true;
  } catch (e) {
    console.error("❌ Error en guardarBitacoraPlanTrabajo:", e);
    return false;
  }
}

