// ============================================================
// =========== MARCACIONES REALES (HIKVISION) =================
// ============================================================

/**
 * Estructura tabla marcaciones_reales:
 * - id (uuid)
 * - empleado_id (uuid, FK a empleados)
 * - documento (text) - documento del empleado para match
 * - fecha (date) - fecha del registro
 * - entrada1 (text) - primera entrada (formato 12h: "8:00 AM")
 * - salida1 (text) - primera salida
 * - entrada2 (text) - segunda entrada (horario partido)
 * - salida2 (text) - segunda salida
 * - tipo_horario (text) - "DERECHO" | "PARTIDO" | "INCOMPLETO"
 * - sede (text) - sede del empleado
 * - estado (text) - "pendiente" | "aprobado"
 * - aprobado_por (uuid) - empleado que aprobó
 * - fecha_aprobacion (timestamp)
 * - empresa_id (uuid)
 * - created_at (timestamp)
 * - archivo_origen (text) - nombre del archivo CSV de origen
 */

// Convertir hora de 24h a 12h AM/PM
function convertir24hA12h(hora24) {
  if (!hora24) return "";
  const partes = hora24.toString().trim().split(":");
  if (partes.length < 2) return hora24;
  let hh = parseInt(partes[0], 10);
  const mm = partes[1].padStart(2, "0");
  if (isNaN(hh)) return hora24;
  const ampm = hh >= 12 ? "PM" : "AM";
  const hora12 = hh % 12 === 0 ? 12 : hh % 12;
  return `${hora12}:${mm} ${ampm}`;
}

// Parsear fecha del CSV (d/m/a) a formato ISO (YYYY-MM-DD)
function parsearFechaCSV(fechaStr) {
  if (!fechaStr) return null;
  const partes = fechaStr.trim().split("/");
  if (partes.length !== 3) return null;
  const [d, m, a] = partes;
  const dia = d.padStart(2, "0");
  const mes = m.padStart(2, "0");
  const anio = a.length === 2 ? `20${a}` : a;
  return `${anio}-${mes}-${dia}`;
}

// Extraer nombre de sede del departamento (quitar prefijo "bigburguer")
function extraerSedeDeDepto(depto) {
  if (!depto) return "";
  // Limpiar comillas y espacios
  const texto = depto.toString().trim().replace(/"/g, '').replace(/'/g, '');
  if (!texto) return "";
  
  const textoLower = texto.toLowerCase();
  
  // Quitar prefijos comunes (case insensitive) - con y sin espacio
  const prefijos = [
    "bigburguer ", "bigburguer-", "bigburguer_", "bigburguer",
    "big burguer ", "big burguer-", "big burguer_", "big burguer",
    "bigburger ", "bigburger-", "bigburger_", "bigburger",
    "big burger ", "big burger-", "big burger_", "big burger"
  ];
  
  for (const pref of prefijos) {
    if (textoLower.startsWith(pref)) {
      // Extraer la parte después del prefijo manteniendo el formato original
      let sedeExtraida = texto.substring(pref.length).trim();
      // Si quedó vacío, continuar buscando
      if (!sedeExtraida) continue;
      // Capitalizar primera letra de cada palabra
      sedeExtraida = sedeExtraida.split(' ')
        .map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
        .join(' ');
      console.log("📍 Sede extraída de '" + texto + "' -> '" + sedeExtraida + "'");
      return sedeExtraida;
    }
  }
  
  // Si no tiene prefijo bigburguer, devolver como está (capitalizado)
  const resultado = texto.split(' ')
    .map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(' ');
  console.log("📍 Sede sin prefijo de '" + texto + "' -> '" + resultado + "'");
  return resultado;
}

// Mapeo de número de serie del dispositivo biométrico a sede
const MAPA_DISPOSITIVO_SEDE = {
  "FH4126819": "Corales",
  "GB9478932": "Av Sur",
  "FH4126802": "Villa Del Prado"
};

// Función para obtener sede por número de serie del dispositivo
function obtenerSedePorDispositivo(numeroSerie) {
  if (!numeroSerie) return "";
  const serieNormalizado = numeroSerie.toString().trim().toUpperCase();
  
  // Buscar coincidencia exacta o parcial
  for (const [serie, sede] of Object.entries(MAPA_DISPOSITIVO_SEDE)) {
    if (serieNormalizado === serie.toUpperCase() || serieNormalizado.includes(serie.toUpperCase())) {
      console.log("📍 Sede identificada por dispositivo '" + numeroSerie + "' -> '" + sede + "'");
      return sede;
    }
  }
  
  console.log("⚠️ Dispositivo no reconocido:", numeroSerie);
  return "";
}

// Procesar CSV de HikVision y agrupar por empleado/fecha
function procesarCSVMarcaciones(csvText, empleados) {
  const lineas = csvText.split(/\r?\n/).filter(l => l.trim());
  if (lineas.length < 2) return { error: "El archivo está vacío o no tiene datos" };
  
  // Detectar encabezados - limpiar BOM y caracteres especiales
  const primeraLinea = lineas[0].replace(/^\uFEFF/, '').replace(/[""]/g, '"');
  const encabezados = primeraLinea.split(/[,;\t]/).map(h => h.trim().toLowerCase().replace(/"/g, ''));
  
  console.log("📋 Encabezados detectados:", encabezados);
  
  // Buscar índices de columnas - primero busca coincidencia exacta, luego parcial
  const buscarColumna = (variantes) => {
    // Primero buscar coincidencia exacta
    for (const v of variantes) {
      const idx = encabezados.findIndex(h => h === v);
      if (idx !== -1) return idx;
    }
    // Si no hay exacta, buscar que contenga (pero evitar falsos positivos)
    for (const v of variantes) {
      // Solo buscar parcial si la variante tiene más de 3 caracteres
      if (v.length > 3) {
        const idx = encabezados.findIndex(h => h.includes(v) && !h.includes("apellido"));
        if (idx !== -1) return idx;
      }
    }
    return -1;
  };
  
  const iNombre = buscarColumna(["nombre", "first name", "name"]);
  const iApellido = buscarColumna(["apellido", "surname", "last name", "lastname"]);
  const iID = buscarColumna(["id", "documento", "cedula", "identificacion", "cc", "nit"]);
  const iDepto = buscarColumna(["departamento", "depto", "department", "area", "sede", "sucursal"]);
  const iFecha = buscarColumna(["fecha", "date"]);
  const iTiempo = buscarColumna(["tiempo", "time", "hora"]);
  // Agregar detección de columna de número de serie del dispositivo biométrico
  const iNumeroSerie = buscarColumna(["n.º de serie del dispositivo", "numero de serie", "nº de serie", "serial", "device serial", "n° de serie del dispositivo", "no. serie dispositivo", "serie dispositivo", "device sn", "sn"]);
  
  console.log("📋 Índices: ID=" + iID + ", Depto=" + iDepto + ", Fecha=" + iFecha + ", Tiempo=" + iTiempo + ", NumSerie=" + iNumeroSerie);
  
  if (iID === -1 || iFecha === -1 || iTiempo === -1) {
    return { error: "El archivo no tiene las columnas requeridas (ID, Fecha, Tiempo). Encabezados encontrados: " + encabezados.join(", ") };
  }
  
  // Crear mapa de empleados por documento para match rápido
  const mapaPorDoc = {};
  empleados.forEach(emp => {
    if (emp.documento) {
      mapaPorDoc[emp.documento.toString().trim()] = emp;
    }
  });
  
  // Debug: mostrar algunos documentos del sistema
  const docsDelSistema = Object.keys(mapaPorDoc).slice(0, 10);
  console.log("📋 Documentos en el sistema (primeros 10):", docsDelSistema);
  console.log("📋 Total empleados con documento:", Object.keys(mapaPorDoc).length);
  
  // Agrupar transacciones por empleado+fecha
  const agrupado = {}; // { "doc_fecha": { doc, fecha, sede, nombre, transacciones: [{hora}] } }
  const empleadosNoEncontrados = new Set();
  const documentosDelCSV = new Set(); // Para debug
  
  for (let i = 1; i < lineas.length; i++) {
    // Limpiar línea de comillas innecesarias y BOM
    const lineaLimpia = lineas[i].replace(/^\uFEFF/, '').replace(/[""]/g, '"');
    const cols = lineaLimpia.split(/[,;\t]/).map(c => c.replace(/"/g, '').trim());
    
    if (cols.length < Math.max(iID, iFecha, iTiempo) + 1) continue;
    
    const documento = (cols[iID] || "").toString().trim();
    const fechaCSV = (cols[iFecha] || "").trim();
    const tiempoCSV = (cols[iTiempo] || "").trim();
    const depto = iDepto >= 0 ? (cols[iDepto] || "").trim() : "";
    const nombreCSV = iNombre >= 0 ? (cols[iNombre] || "").trim() : "";
    const apellidoCSV = iApellido >= 0 ? (cols[iApellido] || "").trim() : "";
    // Extraer número de serie del dispositivo biométrico
    const numeroSerieDispositivo = iNumeroSerie >= 0 ? (cols[iNumeroSerie] || "").trim() : "";
    
    // Guardar documento del CSV para debug
    if (documento) documentosDelCSV.add(documento);
    
    // Debug: mostrar primer registro
    if (i === 1) {
      console.log("📋 Primera línea datos:", { documento, fechaCSV, tiempoCSV, depto, nombreCSV, apellidoCSV, numeroSerieDispositivo });
      console.log("📋 Columnas raw:", cols);
      console.log("📋 ¿Documento existe en sistema?", !!mapaPorDoc[documento], "Buscando:", documento);
    }
    
    if (!documento || !fechaCSV || !tiempoCSV) continue;
    
    const fechaISO = parsearFechaCSV(fechaCSV);
    if (!fechaISO) {
      if (i <= 3) console.log("📋 Fecha no parseada:", fechaCSV, "-> null");
      continue;
    }
    
    const empleado = mapaPorDoc[documento];
    if (!empleado) {
      empleadosNoEncontrados.add(`${nombreCSV} ${apellidoCSV} (${documento})`);
      continue;
    }
    
    // Prioridad para determinar sede:
    // 1. Número de serie del dispositivo (más confiable)
    // 2. Departamento como fallback
    let sedeExtraida = "";
    if (numeroSerieDispositivo) {
      sedeExtraida = obtenerSedePorDispositivo(numeroSerieDispositivo);
    }
    // Si no se obtuvo sede por dispositivo, usar departamento como fallback
    if (!sedeExtraida && depto) {
      sedeExtraida = extraerSedeDeDepto(depto);
    }
    
    const key = `${documento}_${fechaISO}`;
    if (!agrupado[key]) {
      agrupado[key] = {
        documento,
        fecha: fechaISO,
        empleadoId: empleado.id,
        nombreEmpleado: empleado.nombre || `${nombreCSV} ${apellidoCSV}`,
        transacciones: [] // Ahora guarda {hora, sede}
      };
    }
    
    // Guardar hora Y sede de cada transacción
    agrupado[key].transacciones.push({ hora: tiempoCSV, sede: sedeExtraida });
  }
  
  // Procesar cada grupo y asignar entradas/salidas
  const marcaciones = [];
  
  for (const key of Object.keys(agrupado)) {
    const grupo = agrupado[key];
    let trans = grupo.transacciones;
    
    // Ordenar por hora
    trans.sort((a, b) => {
      const [hA, mA] = a.hora.split(":").map(Number);
      const [hB, mB] = b.hora.split(":").map(Number);
      return (hA * 60 + (mA || 0)) - (hB * 60 + (mB || 0));
    });
    
    // Eliminar duplicados (mismo minuto)
    const sinDuplicados = [];
    let ultimaHora = "";
    for (const t of trans) {
      const horaMinuto = t.hora.substring(0, 5); // HH:MM
      if (horaMinuto !== ultimaHora) {
        sinDuplicados.push(t);
        ultimaHora = horaMinuto;
      }
    }
    trans = sinDuplicados;
    
    // Asignar según cantidad de transacciones
    let entrada1 = "", salida1 = "", entrada2 = "", salida2 = "";
    let sede1 = "", sede2 = "";
    let tipoHorario = "";
    
    // trans ahora tiene objetos {hora, sede}
    if (trans.length >= 1) {
      entrada1 = convertir24hA12h(trans[0].hora);
      sede1 = trans[0].sede;
    }
    if (trans.length >= 2) {
      salida1 = convertir24hA12h(trans[1].hora);
      // Si la sede de salida1 es diferente, la tomamos para sede1 (aunque normalmente es la misma)
      if (!sede1) sede1 = trans[1].sede;
    }
    if (trans.length >= 3) {
      entrada2 = convertir24hA12h(trans[2].hora);
      sede2 = trans[2].sede; // Sede del segundo turno
    }
    if (trans.length >= 4) {
      salida2 = convertir24hA12h(trans[3].hora);
      if (!sede2) sede2 = trans[3].sede;
    }
    
    // Determinar tipo de horario
    if (trans.length === 0) {
      tipoHorario = "";
    } else if (trans.length === 1) {
      tipoHorario = "INCOMPLETO";
    } else if (trans.length === 2) {
      tipoHorario = "DERECHO";
    } else if (trans.length === 3) {
      tipoHorario = "INCOMPLETO";
    } else if (trans.length >= 4) {
      tipoHorario = "PARTIDO";
    }
    
    if (tipoHorario) {
      marcaciones.push({
        empleadoId: grupo.empleadoId,
        documento: grupo.documento,
        fecha: grupo.fecha,
        sede1: sede1,  // Sede del primer turno (E1/S1)
        sede2: sede2,  // Sede del segundo turno (E2/S2) - puede ser diferente en PARTIDO
        nombreEmpleado: grupo.nombreEmpleado,
        entrada1,
        salida1,
        entrada2,
        salida2,
        tipoHorario,
        incompleto: tipoHorario === "INCOMPLETO"
      });
    }
  }
  
  // Debug final
  console.log("📋 Resumen procesamiento CSV:");
  console.log("   - Documentos únicos en CSV:", documentosDelCSV.size, Array.from(documentosDelCSV).slice(0, 5));
  console.log("   - Empleados NO encontrados:", empleadosNoEncontrados.size);
  console.log("   - Marcaciones generadas:", marcaciones.length);
  
  return {
    marcaciones,
    empleadosNoEncontrados: Array.from(empleadosNoEncontrados),
    totalProcesadas: marcaciones.length,
    documentosDelCSV: Array.from(documentosDelCSV) // Para debug
  };
}

// Guardar marcaciones temporales (pendientes de aprobación)
async function guardarMarcacionesTemporalesEnSupabase(marcaciones, archivoOrigen, subidoPor, empresaId = null) {
  try {
    const id = ensureUuid();
    const payload = {
      id,
      nombre_archivo: archivoOrigen,
      fecha_subida: new Date().toISOString(),
      subido_por: subidoPor,
      estado: "pendiente",
      marcaciones_json: JSON.stringify(marcaciones),
      total_registros: marcaciones.length,
      empresa_id: empresaId
    };
    
    const { error } = await supabase
      .from("marcaciones_temporales")
      .insert([payload]);
    
    if (error) {
      console.error("❌ Error guardando marcaciones temporales:", error);
      return { success: false, error: error.message };
    }
    
    console.log("✅ Marcaciones temporales guardadas:", id);
    return { success: true, id };
  } catch (e) {
    console.error("❌ Error en guardarMarcacionesTemporalesEnSupabase:", e);
    return { success: false, error: e.message };
  }
}

// Cargar marcaciones temporales pendientes de aprobación
async function cargarMarcacionesTemporalesDeSupabase(empresaId = null) {
  try {
    let query = supabase
      .from("marcaciones_temporales")
      .select("*")
      .order("fecha_subida", { ascending: false });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    const { data, error } = await query;
    
    if (error) {
      console.error("❌ Error cargando marcaciones temporales:", error);
      return [];
    }
    
    return (data || []).map(row => ({
      id: row.id,
      nombreArchivo: row.nombre_archivo,
      fechaSubida: row.fecha_subida,
      subidoPor: row.subido_por,
      estado: row.estado,
      marcaciones: typeof row.marcaciones_json === "string" 
        ? JSON.parse(row.marcaciones_json) 
        : (row.marcaciones_json || []),
      totalRegistros: row.total_registros,
      empresaId: row.empresa_id
    }));
  } catch (e) {
    console.error("❌ Error en cargarMarcacionesTemporalesDeSupabase:", e);
    return [];
  }
}

// Aprobar marcaciones temporales y moverlas a marcaciones_reales
async function aprobarMarcacionesTemporales(archivoId, aprobadoPor, empresaId = null) {
  try {
    // 1. Cargar el archivo temporal
    const { data: archivo, error: errArchivo } = await supabase
      .from("marcaciones_temporales")
      .select("*")
      .eq("id", archivoId)
      .single();
    
    if (errArchivo || !archivo) {
      return { success: false, error: "No se encontró el archivo de marcaciones" };
    }
    
    const marcaciones = typeof archivo.marcaciones_json === "string"
      ? JSON.parse(archivo.marcaciones_json)
      : (archivo.marcaciones_json || []);
    
    // 2. Cargar marcaciones existentes para evitar duplicados
    let queryExistentes = supabase
      .from("marcaciones_reales")
      .select("empleado_id, fecha");
    
    if (empresaId) {
      queryExistentes = queryExistentes.eq("empresa_id", empresaId);
    }
    
    const { data: existentes } = await queryExistentes;
    const existentesSet = new Set((existentes || []).map(e => `${e.empleado_id}_${e.fecha}`));
    
    // 3. Filtrar solo las nuevas (acumular, no sobrescribir)
    const nuevasMarcaciones = marcaciones.filter(m => {
      const key = `${m.empleadoId}_${m.fecha}`;
      return !existentesSet.has(key);
    });
    
    if (nuevasMarcaciones.length === 0) {
      // Actualizar estado del archivo temporal a aprobado aunque no haya nuevas
      await supabase
        .from("marcaciones_temporales")
        .update({ 
          estado: "aprobado",
          aprobado_por: aprobadoPor,
          fecha_aprobacion: new Date().toISOString()
        })
        .eq("id", archivoId);
      
      return { 
        success: true, 
        insertadas: 0, 
        omitidas: marcaciones.length,
        mensaje: "Todas las marcaciones ya existían, no se insertaron duplicados"
      };
    }
    
    // 4. Preparar payloads para insertar
    const payloads = nuevasMarcaciones.map(m => ({
      id: ensureUuid(),
      empleado_id: m.empleadoId,
      documento: m.documento,
      fecha: m.fecha,
      entrada1: m.entrada1 || null,
      salida1: m.salida1 || null,
      entrada2: m.entrada2 || null,
      salida2: m.salida2 || null,
      tipo_horario: m.tipoHorario,
      sede: m.sede1 || m.sede || null,  // Compatibilidad con formato viejo
      sede1: m.sede1 || m.sede || null,
      sede2: m.sede2 || null,
      estado: "aprobado",
      aprobado_por: aprobadoPor,
      fecha_aprobacion: new Date().toISOString(),
      empresa_id: empresaId,
      archivo_origen: archivo.nombre_archivo
    }));
    
    // 5. Insertar en marcaciones_reales
    const { error: errInsert } = await supabase
      .from("marcaciones_reales")
      .insert(payloads);
    
    if (errInsert) {
      console.error("❌ Error insertando marcaciones reales:", errInsert);
      return { success: false, error: errInsert.message };
    }
    
    // 6. Actualizar estado del archivo temporal
    await supabase
      .from("marcaciones_temporales")
      .update({ 
        estado: "aprobado",
        aprobado_por: aprobadoPor,
        fecha_aprobacion: new Date().toISOString()
      })
      .eq("id", archivoId);
    
    console.log(`✅ Marcaciones aprobadas: ${nuevasMarcaciones.length} nuevas, ${marcaciones.length - nuevasMarcaciones.length} omitidas`);
    return { 
      success: true, 
      insertadas: nuevasMarcaciones.length,
      omitidas: marcaciones.length - nuevasMarcaciones.length
    };
  } catch (e) {
    console.error("❌ Error en aprobarMarcacionesTemporales:", e);
    return { success: false, error: e.message };
  }
}

// Rechazar/eliminar archivo de marcaciones temporales
async function rechazarMarcacionesTemporales(archivoId) {
  try {
    const { error } = await supabase
      .from("marcaciones_temporales")
      .delete()
      .eq("id", archivoId);
    
    if (error) {
      console.error("❌ Error rechazando marcaciones:", error);
      return false;
    }
    
    console.log("✅ Marcaciones temporales rechazadas/eliminadas:", archivoId);
    return true;
  } catch (e) {
    console.error("❌ Error en rechazarMarcacionesTemporales:", e);
    return false;
  }
}

// Cargar marcaciones reales aprobadas
async function cargarMarcacionesRealesDeSupabase(empresaId = null, filtros = {}) {
  try {
    let query = supabase
      .from("marcaciones_reales")
      .select("*")
      .order("fecha", { ascending: false });
    
    if (empresaId) {
      query = query.eq("empresa_id", empresaId);
    }
    
    if (filtros.fechaDesde) {
      query = query.gte("fecha", filtros.fechaDesde);
    }
    if (filtros.fechaHasta) {
      query = query.lte("fecha", filtros.fechaHasta);
    }
    if (filtros.empleadoId) {
      query = query.eq("empleado_id", filtros.empleadoId);
    }
    
    const { data, error } = await query;
    
    if (error) {
      console.error("❌ Error cargando marcaciones reales:", error);
      return [];
    }
    
    return (data || []).map(row => ({
      id: row.id,
      empleadoId: row.empleado_id,
      documento: row.documento,
      fecha: row.fecha,
      entrada1: row.entrada1,
      salida1: row.salida1,
      entrada2: row.entrada2,
      salida2: row.salida2,
      tipoHorario: row.tipo_horario,
      sede: row.sede,
      sede1: row.sede1 || row.sede,  // Compatibilidad con formato viejo
      sede2: row.sede2,
      estado: row.estado,
      aprobadoPor: row.aprobado_por,
      fechaAprobacion: row.fecha_aprobacion,
      archivoOrigen: row.archivo_origen,
      empresaId: row.empresa_id
    }));
  } catch (e) {
    console.error("❌ Error en cargarMarcacionesRealesDeSupabase:", e);
    return [];
  }
}

// Actualizar una marcación real (para corregir incompletos)
async function actualizarMarcacionReal(marcacionId, cambios) {
  try {
    const payload = {};
    if (cambios.entrada1 !== undefined) payload.entrada1 = cambios.entrada1;
    if (cambios.salida1 !== undefined) payload.salida1 = cambios.salida1;
    if (cambios.entrada2 !== undefined) payload.entrada2 = cambios.entrada2;
    if (cambios.salida2 !== undefined) payload.salida2 = cambios.salida2;
    if (cambios.tipoHorario !== undefined) payload.tipo_horario = cambios.tipoHorario;
    
    const { error } = await supabase
      .from("marcaciones_reales")
      .update(payload)
      .eq("id", marcacionId);
    
    if (error) {
      console.error("❌ Error actualizando marcación:", error);
      return false;
    }
    
    console.log("✅ Marcación actualizada:", marcacionId);
    return true;
  } catch (e) {
    console.error("❌ Error en actualizarMarcacionReal:", e);
    return false;
  }
}

// Eliminar una marcación real
async function eliminarMarcacionReal(marcacionId) {
  try {
    const { error } = await supabase
      .from("marcaciones_reales")
      .delete()
      .eq("id", marcacionId);
    
    return !error;
  } catch (e) {
    return false;
  }
}

let vista = null; 
 
/* ====================== UTILIDADES ====================== */
function uid() {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  const s4 = () => Math.floor((1 + Math.random()) * 0x10000).toString(16).slice(-4);
  return `${s4()}${s4()}-${s4()}-${s4()}-${s4()}-${s4()}${s4()}${s4()}`;
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function ensureUuid(value) {
  return value && UUID_REGEX.test(value) ? value : uid();
}

/**
 * Normaliza una fecha en varios formatos posibles a formato ISO 'yyyy-MM-dd'
 * Soporta: 'yyyy-MM-dd', 'd/MM/yy', 'd/MM/yyyy', 'dd/MM/yy', 'dd/MM/yyyy', Date object
 */
function normalizarFechaISO(fecha) {
  if (!fecha) return null;
  
  // Si ya es un objeto Date válido
  if (fecha instanceof Date) {
    if (isNaN(fecha.getTime())) return null;
    return fecha.toISOString().slice(0, 10);
  }
  
  const str = String(fecha).trim();
  if (!str) return null;
  
  // Ya está en formato ISO yyyy-MM-dd
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    const d = new Date(str + 'T00:00:00');
    if (!isNaN(d.getTime())) return str;
    return null;
  }
  
  // Formato d/MM/yy o dd/MM/yy o d/MM/yyyy o dd/MM/yyyy
  const match = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (match) {
    const dia = parseInt(match[1], 10);
    const mes = parseInt(match[2], 10);
    let anio = parseInt(match[3], 10);
    
    // Si el año es de 2 dígitos, convertir a 4 dígitos
    if (anio < 100) {
      // Asumimos 2000-2099 para años < 100
      anio = anio < 50 ? 2000 + anio : 1900 + anio;
    }
    
    const fechaObj = new Date(anio, mes - 1, dia);
    if (isNaN(fechaObj.getTime())) return null;
    
    const y = fechaObj.getFullYear();
    const m = String(fechaObj.getMonth() + 1).padStart(2, '0');
    const d = String(fechaObj.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  
  // Intentar parsear como Date nativa
  const parsed = new Date(str);
  if (!isNaN(parsed.getTime())) {
    return parsed.toISOString().slice(0, 10);
  }
  
  return null;
}

function toISO(d) {
  if (!d) return null;
  
  // Primero intentar normalizar la fecha
  const normalizado = normalizarFechaISO(d);
  if (normalizado) return normalizado;
  
  // Fallback: intentar con Date nativa
  try {
    const fecha = new Date(d);
    if (isNaN(fecha.getTime())) {
      console.warn('⚠️ Fecha inválida en toISO:', d);
      return null;
    }
    return fecha.toISOString().slice(0, 10);
  } catch (e) {
    console.warn('⚠️ Error procesando fecha en toISO:', d, e);
    return null;
  }
}

function parseISO(iso) {
  if (!iso) return new Date(NaN); // Fecha inválida
  
  // Primero normalizar la fecha
  const normalizado = normalizarFechaISO(iso);
  if (!normalizado) {
    console.warn('⚠️ Fecha inválida en parseISO:', iso);
    return new Date(NaN);
  }
  
  const [y, m, d] = normalizado.split("-").map(Number);
  return new Date(y, m - 1, d);
}
function addDaysLocal(iso, n) {
  const dt = parseISO(iso);
  dt.setDate(dt.getDate() + n);
  return toISO(dt);
}
 
/* ---------- Festivos Colombia ---------- */
function easterDate(year) {
  // Algoritmo de Butcher (Calendario Gregoriano)
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31); // 3=Marzo, 4=Abril
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(year, month - 1, day);
}

function moveToMonday(date) {
  // Mueve un Date a lunes siguiente según Ley Emiliani
  const d = new Date(date);
  const dow = d.getDay(); // 0=Domingo, 1=Lunes, ...
  if (dow === 1) return toISO(d);
  const diff = (8 - dow) % 7; // días hasta lunes siguiente
  d.setDate(d.getDate() + diff);
  return toISO(d);
}

function buildHolidaysCO(year) {
  const set = new Set();

  function addISO(iso) { set.add(iso); }
  function iso(y, m, d) { return toISO(new Date(y, m - 1, d)); }

  // Fijos
  addISO(iso(year, 1, 1));   // Año Nuevo
  addISO(iso(year, 5, 1));   // Día del Trabajo
  addISO(iso(year, 7, 20));  // Independencia de Colombia
  addISO(iso(year, 8, 7));   // Batalla de Boyacá
  addISO(iso(year, 12, 8));  // Inmaculada Concepción
  addISO(iso(year, 12, 25)); // Navidad

  // Trasladables a lunes (Ley Emiliani)
  addISO(moveToMonday(new Date(year, 0, 6)));   // Reyes Magos (6 Ene)
  addISO(moveToMonday(new Date(year, 2, 19)));  // San José (19 Mar)
  addISO(moveToMonday(new Date(year, 5, 29)));  // San Pedro y San Pablo (29 Jun)
  addISO(moveToMonday(new Date(year, 7, 15)));  // Asunción de la Virgen (15 Ago)
  addISO(moveToMonday(new Date(year, 9, 12)));  // Día de la Raza (12 Oct)
  addISO(moveToMonday(new Date(year, 10, 1)));  // Todos los Santos (1 Nov)
  addISO(moveToMonday(new Date(year, 10, 11))); // Independencia de Cartagena (11 Nov)

  // Basados en Pascua
  const easter = easterDate(year); // Domingo de Resurrección
  const addOffset = (days) => {
    const d = new Date(easter);
    d.setDate(d.getDate() + days);
    return toISO(d);
  };
  // Jueves y Viernes Santo (no trasladables)
  addISO(addOffset(-3)); // Jueves Santo
  addISO(addOffset(-2)); // Viernes Santo
  // Ascensión (39 días después, trasladada a lunes)
  addISO(moveToMonday(new Date(new Date(easter).setDate(easter.getDate() + 39))));
  // Corpus Christi (60 días después, trasladada a lunes)
  addISO(moveToMonday(new Date(new Date(easter).setDate(easter.getDate() + 60))));
  // Sagrado Corazón (68 días después, trasladada a lunes)
  addISO(moveToMonday(new Date(new Date(easter).setDate(easter.getDate() + 68))));

  return set;
}

const __holidayCacheDefault = {};
function isHolidayCO(iso, cache) {
  const c = cache || __holidayCacheDefault;
  const y = parseISO(iso).getFullYear();
  if (!c[y]) c[y] = buildHolidaysCO(y);
  return c[y].has(iso);
}
function isBusinessDayVac(iso, cache) {
  const d = parseISO(iso);
  const dow = d.getDay();
  if (dow === 0) return false;
  if (isHolidayCO(iso, cache)) return false;
  return true;
}
function nextBusinessDayVac(iso, cache) {
  let cur = iso;
  do {
    cur = addDaysLocal(cur, 1);
  } while (!isBusinessDayVac(cur, cache));
  return cur;
}
function addBusinessDaysVac(inicioISO, n, cache) {
  let counted = 0;
  let cur = inicioISO;
  while (true) {
    if (isBusinessDayVac(cur, cache)) counted++;
    if (counted === n) return cur;
    cur = addDaysLocal(cur, 1);
  }
}
 
function isDateInRange(iso, start, end) {
  if (!start && !end) return false;
  const d = parseISO(iso).getTime();
  const s = start ? parseISO(start).getTime() : d;
  const e = end ? parseISO(end).getTime() : d;
  return d >= s && d <= e;
}
function seTraslapaRangoFechas(desdeA, hastaA, desdeB, hastaB) {
  if (!desdeA || !hastaA || !desdeB || !hastaB) return false;
  const a0 = parseISO(desdeA);
  const a1 = parseISO(hastaA);
  const b0 = parseISO(desdeB);
  const b1 = parseISO(hastaB);
  return a0 <= b1 && b0 <= a1;
}
 
/* ====================== VACACIONES POR PERÍODO ====================== */
// Un período = desde el aniversario N al aniversario N+1 (15 días).
// Etiquetamos el período con el AÑO en que se CUMPLE el aniversario.
 
/* ====================== UTILIDADES LIQUIDACIONES ====================== */
function daysBetweenInclusive(aISO, bISO){
  if (!aISO || !bISO) return 0;
  const a = startOfDay(parseISO(aISO));
  const b = startOfDay(parseISO(bISO));
  return Math.floor((b - a) / (24*3600*1000)) + 1;
}
 
// Convenio 360 días (base tradicional en prestaciones)
function days360(aISO, bISO){
  const a = parseISO(aISO), b = parseISO(bISO);
  const d1 = a.getDate() === 31 ? 30 : a.getDate();
  const d2 = b.getDate() === 31 ? 30 : b.getDate();
  const m1 = a.getMonth()+1, m2 = b.getMonth()+1;
  const y1 = a.getFullYear(), y2 = b.getFullYear();
  return (y2 - y1)*360 + (m2 - m1)*30 + (d2 - d1) + 1;
}
 
// Ajusta el rango a partir de la fecha de ingreso
function clampByIngreso(ingresoISO, desdeISO, hastaISO){
  if (!ingresoISO) return { from: desdeISO, to: hastaISO };
  const ingreso = parseISO(ingresoISO);
  const d = parseISO(desdeISO), h = parseISO(hastaISO);
  const from = d < ingreso ? ingreso : d;
  const to   = h;
  if (from > to) return { from: toISO(from), to: toISO(from) };
  return { from: toISO(from), to: toISO(to) };
}
 
// Base salarial para liquidaciones (elige la que uses en tu negocio)
function baseVac(empleado){ return Number(empleado?.salarioProm6m || empleado?.salarioBase || 0); }
// (definida una sola vez)
 
// 🔹 NUEVA BASE CESANTÍAS: salario mensual + auxilio fijo de transporte
function baseCes(empleado) {
  const salario = Number(empleado?.salarioProm6m || empleado?.salarioBase || 0);
  const auxTransporteFijo = 200000; // aquí fijas el auxilio según tu ejemplo
  return salario + auxTransporteFijo;
}
 
function basePrima(empleado){
  // Puedes dejar prima solo con salario (como estaba)
  return Number(empleado?.salarioProm6m || empleado?.salarioBase || 0);
}
 
// daysBetweenInclusive ya está definida arriba; evitamos duplicados
 
/**
 * Cesantías:
 *  - Por cada 365 días trabajados → 30 días de salario (salario+auxilio).
 *  - Si el período es parcial, se prorratea:
 *      díasDerecho = 30 * (díasTrabajados / 365)
 *  - Valor cesantías = valorDía * díasDerecho
 */
function calcCesantias(empleado, desdeISO, hastaISO) {
  const base = baseCes(empleado);  // salario + auxilio
  const dias = Math.max(0, daysBetweenInclusive(desdeISO, hastaISO));
 
  if (!dias || !base) return { dias: 0, diasDerecho: 0, valor: 0 };
 
  const valorDia = base / 30;
  const diasDerecho = 30 * (dias / 365);  // 30 días por año, prorrateado
  const valor = Math.round(valorDia * diasDerecho);
 
  return { dias, diasDerecho, valor };
}
 
/**
 * Intereses a las cesantías:
 *  - 12% anual sobre el valor de las cesantías.
 *  - Proporcional a los días del mismo período: días / 365
 */
function calcInteresesCes(cesantiasValor, desdeISO, hastaISO) {
  const dias = Math.max(0, daysBetweenInclusive(desdeISO, hastaISO));
  if (!dias || !cesantiasValor) return 0;
 
  const interes = cesantiasValor * 0.12 * (dias / 365);
  return Math.round(interes);
}
 
// Prima semestral con recorte por ingreso
function rangoPrima(empleado, semestre, anio){
  const desde = semestre === 1 ? `${anio}-01-01` : `${anio}-07-01`;
  const hasta = semestre === 1 ? `${anio}-06-30` : `${anio}-12-31`;
  const cl = clampByIngreso(empleado?.fechaIngreso, desde, hasta);
  return cl;
}
function calcPrima(empleado, semestre, anio){
  const base = basePrima(empleado);
  const r = rangoPrima(empleado, semestre, anio);
  const d = Math.max(0, days360(r.from, r.to));
  return { desde:r.from, hasta:r.to, dias:d, valor: Math.round(base * d / 360) };
}
 
function startOfDay(d){ const x = new Date(d); x.setHours(0,0,0,0); return x; }
function addDays(d, n){ const x = new Date(d); x.setDate(x.getDate() + n); return x; }
 
/** Construye períodos completos (ya cumplidos respecto a "asOfISO") de 15 días */
function buildVacationPeriods(empleado, asOfISO = toISO(new Date())) {
  // Normalizar la fecha de ingreso para soportar varios formatos
  const fechaIngresoNorm = normalizarFechaISO(empleado?.fechaIngreso);
  if (!fechaIngresoNorm) {
    console.warn('⚠️ Empleado sin fecha de ingreso válida:', empleado?.nombre, 'Fecha:', empleado?.fechaIngreso);
    return [];
  }
  
  const ingreso = parseISO(fechaIngresoNorm);
  if (isNaN(ingreso.getTime())) {
    console.warn('⚠️ Fecha de ingreso inválida para empleado:', empleado?.nombre);
    return [];
  }
  const asOf = parseISO(asOfISO);
  if (isNaN(asOf.getTime())) {
    console.warn('⚠️ Fecha asOf inválida:', asOfISO);
    return [];
  }
 
  const periods = [];
  let i = 1;
 
  // (A) Períodos COMPLETOS (antiguos)
  while (true) {
    const from = new Date(ingreso);
    from.setFullYear(from.getFullYear() + (i - 1));
    const nextAnniv = new Date(ingreso);
    nextAnniv.setFullYear(nextAnniv.getFullYear() + i);
    const to = new Date(nextAnniv);
    to.setDate(to.getDate() - 1);
 
    if (to > asOf) break; // ya no hay completos
 
    const label = String(to.getFullYear()); // etiqueta por el año en que se cumple el aniversario
    periods.push({
      label,                    // p.ej. "2025"
      fromISO: toISO(startOfDay(from)),
      toISO:   toISO(startOfDay(to)),
      accrued: 15,             // periodo completo
      used: 0,
      pending: 15,
      ongoing: false,
    });
    i++;
  }

  // (B) Período EN CURSO desde el último aniversario hasta "asOf"
  const currentFrom = new Date(ingreso);
  currentFrom.setFullYear(currentFrom.getFullYear() + (i - 1));
  const theoreticalEnd = new Date(ingreso);
  theoreticalEnd.setFullYear(theoreticalEnd.getFullYear() + i);
  theoreticalEnd.setDate(theoreticalEnd.getDate() - 1);

  const fromISO = toISO(startOfDay(currentFrom));
  const toISOtheo = toISO(startOfDay(theoreticalEnd));
  const diasTranscurridos = Math.max(0, daysBetweenInclusive(fromISO, asOfISO));
  const accruedNowRaw = Math.min(15, 15 * (diasTranscurridos / 365));
  const accruedNow = Math.round(accruedNowRaw * 10) / 10; // entero y un decimal

  periods.push({
    label: `${parseISO(toISOtheo).getFullYear()} (en curso)`,
    fromISO,
    toISO: toISOtheo,
    accrued: accruedNow,
    used: 0,
    pending: accruedNow,
    ongoing: true,
  });
 
  return periods;
}
 
function contarDiasHabilesVacISO(inicioISO, finISO, holidaysCache){
  if (!inicioISO || !finISO) return 0;
  
  // Normalizar fechas
  const inicioNorm = normalizarFechaISO(inicioISO);
  const finNorm = normalizarFechaISO(finISO);
  if (!inicioNorm || !finNorm) return 0;
  
  let cur = parseISO(inicioNorm);
  const fin = parseISO(finNorm);
  if (isNaN(cur.getTime()) || isNaN(fin.getTime())) return 0;
  
  let count = 0;
  // Límite de seguridad para evitar bucles infinitos (máx 1000 días)
  let iteraciones = 0;
  while (cur <= fin && iteraciones < 1000) {
    const iso = toISO(cur);
    if (iso && isBusinessDayVac(iso, holidaysCache)) count++;
    cur.setDate(cur.getDate() + 1);
    iteraciones++;
  }
  return count;
}
 
/** Aplica ausencias de vacaciones a los períodos, descontando FIFO (antiguo→nuevo) */
/** Aplica ausencias de vacaciones a los períodos, descontando FIFO (antiguo→nuevo)
 * 🔹 MODIFICADO: Soporta ausencias con liquidacionDirecta (usa campo dias directamente)
 */
 function applyVacationUses(periods, ausenciasVac, holidaysCache) {
  const buckets = periods.map(p => ({...p}));
  
  // Ordenar ausencias por fecha de inicio (normalizando fechas)
  const ordenadas = [...ausenciasVac]
    .filter(a => a.inicio) // Filtrar ausencias sin fecha
    .sort((a, b) => {
      const fechaA = normalizarFechaISO(a.inicio);
      const fechaB = normalizarFechaISO(b.inicio);
      if (!fechaA && !fechaB) return 0;
      if (!fechaA) return 1;
      if (!fechaB) return -1;
      return parseISO(fechaA) - parseISO(fechaB);
    });
 
  for (const a of ordenadas) {
    // 🔹 Si es liquidación directa, usar el campo dias directamente
    const dias = a.liquidacionDirecta
      ? (a.dias || 0)
      : contarDiasHabilesVacISO(a.inicio, a.fin || a.inicio, holidaysCache);
 
    let rem = dias;
    for (const b of buckets) {
      if (rem <= 0) break;
      const can = Math.max(0, b.accrued - b.used);
      if (can <= 0) continue;
      const take = Math.min(can, rem);
      b.used += take;
      b.pending = Math.max(0, b.accrued - b.used);
      rem -= take;
    }
  }
  return buckets;
}
 
/** Dados N días por tomar, retorna detalle de qué períodos se descuentan (FIFO) */
function allocateVacationFromBuckets(buckets, diasSolicitados){
  let rem = Number(diasSolicitados||0);
  const detalle = [];
  for (const b of buckets) {
    if (rem <= 0) break;
    const can = b.pending;
    if (can <= 0) continue;
    const take = Math.min(can, rem);
    detalle.push({ periodo: b.label, dias: take });
    rem -= take;
  }
  return { detalle, faltantes: rem };
}
 
/* ====================== UI BASE ====================== */
function Field({ label, children }) {
  return (
    <label className="flex flex-col gap-1 text-sm mb-2">
      <span className="text-xs text-slate-600">{label}</span>
      {children}
    </label>
  );
}
function Input(props) {
  return (
    <input
      {...props}
      className={"border rounded px-2 py-1 text-sm w-full " + (props.className || "")}
    />
  );
}
function Button({ children, variant = "default", ...rest }) {
  // Estilos inline para el tema naranja/dorado
  const getButtonStyle = () => {
    const baseStyle = {
      padding: '10px 18px',
      borderRadius: '8px',
      fontSize: '13px',
      fontWeight: '600',
      cursor: rest.disabled ? 'not-allowed' : 'pointer',
      opacity: rest.disabled ? 0.5 : 1,
      border: 'none',
      transition: 'all 0.2s ease',
    };
    
    if (variant === "primary") {
      return {
        ...baseStyle,
        background: 'linear-gradient(135deg, #ff6b35 0%, #ffc53d 100%)',
        color: 'white',
        boxShadow: '0 2px 8px rgba(255, 107, 53, 0.3)',
      };
    }
    if (variant === "outline") {
      return {
        ...baseStyle,
        background: 'white',
        color: '#ff6b35',
        border: '2px solid #ffe4c9',
      };
    }
    if (variant === "danger") {
      return {
        ...baseStyle,
        background: 'linear-gradient(135deg, #ff4d4f 0%, #cf1322 100%)',
        color: 'white',
        boxShadow: '0 2px 8px rgba(255, 77, 79, 0.3)',
      };
    }
    // default
    return {
      ...baseStyle,
      background: '#334155',
      color: 'white',
    };
  };

  return (
    <button {...rest} style={getButtonStyle()}>
      {children}
    </button>
  );
}
 
