const STORAGE_KEY = "cuadresDiarios_v1";
const STORAGE_ELIMINADOS_KEY = "cuadresEliminados_v1";

// Obtener lista de cuadres que fueron eliminados permanentemente
function obtenerCuadresEliminadosGlobal() {
  try {
    const eliminados = localStorage.getItem(STORAGE_ELIMINADOS_KEY);
    return eliminados ? JSON.parse(eliminados) : [];
  } catch {
    return [];
  }
}

// Marcar un cuadre como eliminado en localStorage (para evitar re-sincronización)
function marcarCuadreComoEliminado(cuadreId) {
  if (!cuadreId) return false;
  try {
    const eliminados = obtenerCuadresEliminadosGlobal();
    if (!eliminados.includes(cuadreId)) {
      eliminados.push(cuadreId);
      localStorage.setItem(STORAGE_ELIMINADOS_KEY, JSON.stringify(eliminados));
      console.log("✅ Cuadre marcado como eliminado en localStorage:", cuadreId);
    }
    // También limpiar el cuadre de la lista de cuadres en localStorage
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        const filtrado = parsed.filter(c => c.id !== cuadreId);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(filtrado));
      }
    } catch (e) {
      console.error("Error limpiando cuadre de localStorage:", e);
    }
    return true;
  } catch (e) {
    console.error("Error marcando cuadre como eliminado:", e);
    return false;
  }
}
 
