export function CuadreDiarioRoot({ sedes, empleados, usuarioActual = null, empleadoActual = null, esGerente = false, tienePermiso = () => true, filtroEmpresa = null }) {
  const [cuadres, setCuadres] = useState(() => loadCuadres());
  // Determinar modo inicial según permisos
  const modoInicial = tienePermiso("admin_cuadre_abrir") ? "crear" : 
                      tienePermiso("admin_cuadre_consultar") ? "consultar" : "crear";
  const [modo, setModo] = useState(modoInicial); // "crear" | "consultar"
  const [cuadreActivoId, setCuadreActivoId] = useState(null);
  const [cargandoCuadres, setCargandoCuadres] = useState(false);
  const [cuadreEditando, setCuadreEditando] = useState(null); // Para modal de edición
  const [cuadreAsignarColaborador, setCuadreAsignarColaborador] = useState(null); // Para modal de asignar colaborador
  
  // Estados para el sistema de bloqueo y solicitudes
  const [solicitudesPendientes, setSolicitudesPendientes] = useState([]);
  const [bloqueoActual, setBloqueoActual] = useState(null); // Info del bloqueo si hay uno
  const [mostrarModalSolicitud, setMostrarModalSolicitud] = useState(false);
  const [cuadreBloqueadoInfo, setCuadreBloqueadoInfo] = useState(null);
  const [enviandoSolicitud, setEnviandoSolicitud] = useState(false);
  const [solicitudEnviada, setSolicitudEnviada] = useState(false);
  const [cuadresConAccesoAprobado, setCuadresConAccesoAprobado] = useState([]); // IDs de cuadres con acceso aprobado
  
  // Estados para gestión de accesos (solo gerentes)
  const [mostrarModalGestionAccesos, setMostrarModalGestionAccesos] = useState(false);
  const [cuadreGestionAccesos, setCuadreGestionAccesos] = useState(null);
  const [accesosDelCuadre, setAccesosDelCuadre] = useState([]);
  const [cargandoAccesos, setCargandoAccesos] = useState(false);
  
  // Estados para trabajo colaborativo en tiempo real
  const [usuariosActivosEnCuadre, setUsuariosActivosEnCuadre] = useState([]);
  const [ultimaActualizacionRemota, setUltimaActualizacionRemota] = useState(null);
  const [ultimaSincronizacion, setUltimaSincronizacion] = useState(null);
  const [sincronizando, setSincronizando] = useState(false);
  const ignorarProximaActualizacion = React.useRef(false);
  const broadcastChannelRef = React.useRef(null); // Canal de broadcast para sincronización instantánea
  const recibiendoBroadcastRef = React.useRef(false); // 🛡️ Flag para evitar loop de sincronización
  
  // 🔹 MODO COLABORADOR - Solo Transferencias y Domicilios
  const [modoColaborador, setModoColaborador] = useState(false);
  const [colaboradorCuadreId, setColaboradorCuadreId] = useState(null);
  const [colaboradorCuadre, setColaboradorCuadre] = useState(null);
  const [colaboradorSincronizando, setColaboradorSincronizando] = useState(false);
  
  // 🔒 BLOQUEO DE FILAS - Evita conflictos cuando dos editan
  // Formato: { "transfer_rowId": { usuarioId, usuarioNombre, timestamp }, "domicilios_rowId": {...} }
  const [filasBloqueadas, setFilasBloqueadas] = useState({});
  const bloqueoTimeout = React.useRef({});
  
  // Función para bloquear una fila (cuando el usuario empieza a editar)
  const bloquearFila = React.useCallback((seccion, filaId) => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const miNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario";
    const clave = `${seccion}_${filaId}`;
    
    // Actualizar estado local
    setFilasBloqueadas(prev => ({
      ...prev,
      [clave]: { usuarioId: miId, usuarioNombre: miNombre, timestamp: Date.now() }
    }));
    
    // Enviar broadcast
    if (broadcastChannelRef.current) {
      broadcastChannelRef.current.send({
        type: 'broadcast',
        event: 'fila_bloqueada',
        payload: {
          seccion,
          filaId,
          usuarioId: miId,
          usuarioNombre: miNombre,
          timestamp: Date.now()
        }
      }).catch(e => console.error("Error enviando bloqueo:", e));
    }
    
    // Auto-liberar después de 10 segundos de inactividad
    if (bloqueoTimeout.current[clave]) {
      clearTimeout(bloqueoTimeout.current[clave]);
    }
    bloqueoTimeout.current[clave] = setTimeout(() => {
      desbloquearFila(seccion, filaId);
    }, 10000);
  }, [empleadoActual, usuarioActual]);
  
  // Función para desbloquear una fila
  const desbloquearFila = React.useCallback((seccion, filaId) => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const clave = `${seccion}_${filaId}`;
    
    // Solo desbloquear si yo la tengo bloqueada
    setFilasBloqueadas(prev => {
      if (prev[clave]?.usuarioId === miId) {
        const nuevo = { ...prev };
        delete nuevo[clave];
        return nuevo;
      }
      return prev;
    });
    
    // Enviar broadcast
    if (broadcastChannelRef.current) {
      broadcastChannelRef.current.send({
        type: 'broadcast',
        event: 'fila_desbloqueada',
        payload: {
          seccion,
          filaId,
          usuarioId: miId,
          timestamp: Date.now()
        }
      }).catch(e => console.error("Error enviando desbloqueo:", e));
    }
    
    // Limpiar timeout
    if (bloqueoTimeout.current[clave]) {
      clearTimeout(bloqueoTimeout.current[clave]);
      delete bloqueoTimeout.current[clave];
    }
  }, [empleadoActual, usuarioActual]);
  
  // Verificar si una fila está bloqueada por OTRO usuario
  const filaEstaBloqueadaPorOtro = React.useCallback((seccion, filaId) => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const clave = `${seccion}_${filaId}`;
    const bloqueo = filasBloqueadas[clave];
    
    if (!bloqueo) return null;
    if (bloqueo.usuarioId === miId) return null; // Yo la tengo, no está bloqueada para mí
    
    // Verificar que el bloqueo no sea muy viejo (más de 15 segundos)
    if (Date.now() - bloqueo.timestamp > 15000) {
      return null;
    }
    
    return bloqueo;
  }, [filasBloqueadas, empleadoActual, usuarioActual]);
  
  // � SISTEMA DE DEBOUNCE - Evitar sincronización mientras el usuario escribe
  const ultimaEdicionRef = React.useRef(Date.now());
  const TIEMPO_ESPERA_SYNC = 3000; // Esperar 3 segundos después de la última edición
  
  // Función para marcar que el usuario está editando
  const marcarEdicion = React.useCallback(() => {
    ultimaEdicionRef.current = Date.now();
  }, []);
  
  // ==========================================
  // 🧹 LIMPIEZA AUTOMÁTICA DE LOCALSTORAGE AL MONTAR
  // Esto elimina cualquier dato corrupto o viejo de cuadres que pueda causar conflictos
  // SUPABASE es la ÚNICA fuente de verdad para cuadres
  // ==========================================
  useEffect(() => {
    try {
      // Limpiar todas las claves de localStorage relacionadas con cuadres
      localStorage.removeItem("cuadresDiarios_v1");
      localStorage.removeItem("cuadresDiarios");
      localStorage.removeItem("cuadres_borradores");
      localStorage.removeItem(STORAGE_KEY); // "cuadres_diarios_v2" o similar
      console.log("🧹 localStorage de cuadres limpiado - Supabase es la única fuente de verdad");
    } catch (e) {
      console.error("Error limpiando localStorage:", e);
    }
  }, []); // Solo al montar el componente
  
  // DETECTOR GLOBAL DE ACTIVIDAD - Pausa sync mientras escribes
  useEffect(() => {
    const handleInput = (e) => {
      const target = e.target;
      if (target && (
        target.tagName === 'INPUT' || 
        target.tagName === 'TEXTAREA' || 
        target.isContentEditable ||
        target.closest('.subcard')
      )) {
        ultimaEdicionRef.current = Date.now();
      }
    };
    
    document.addEventListener('input', handleInput, true);
    document.addEventListener('keydown', handleInput, true);
    document.addEventListener('change', handleInput, true);
    
    return () => {
      document.removeEventListener('input', handleInput, true);
      document.removeEventListener('keydown', handleInput, true);
      document.removeEventListener('change', handleInput, true);
    };
  }, []);
  
  // FUNCION DE SINCRONIZACION MANUAL/AUTOMATICA
  const sincronizarCuadreActivo = React.useCallback(async (mostrarIndicador = true) => {
    if (!cuadreActivoId || sincronizando) return;
    
    if (mostrarIndicador) setSincronizando(true);
    
    try {
      // Cargar el cuadre más reciente de Supabase
      const { data, error } = await supabase
        .from("cuadres_diarios")
        .select("*")
        .eq("id", cuadreActivoId)
        .maybeSingle();
      
      if (error) {
        console.error("❌ Error sincronizando:", error);
        return;
      }
      
      if (data) {
        const cuadreRemoto = mapearRowCuadreDesdeSupabase(data);
        
        setCuadres((prev) => {
          return prev.map((c) => {
            if (c.id === cuadreActivoId) {
              // Fusionar cambios remotos con locales
              return fusionarCuadresColaborativo(c, cuadreRemoto);
            }
            return c;
          });
        });
        
        setUltimaSincronizacion(new Date());
        console.log("✅ Sincronización completada");
      }
    } catch (e) {
      console.error("❌ Error en sincronización:", e);
    } finally {
      if (mostrarIndicador) setSincronizando(false);
    }
  }, [cuadreActivoId, sincronizando]);
  
  // ⏱️ AUTO-SYNC INTELIGENTE - Solo sincroniza si no estás escribiendo
  useEffect(() => {
    if (!cuadreActivoId) return;
    
    console.log("⏱️ Iniciando auto-sync inteligente para cuadre:", cuadreActivoId);
    
    const intervaloSync = setInterval(() => {
      const tiempoDesdeUltimaEdicion = Date.now() - ultimaEdicionRef.current;
      
      // Solo sincronizar si han pasado al menos 3 segundos desde la última edición
      if (tiempoDesdeUltimaEdicion >= TIEMPO_ESPERA_SYNC) {
        sincronizarCuadreActivo(false); // Sin mostrar indicador para auto-sync
      } else {
        console.log(`⏸️ Sincronización pausada - usuario editando (${Math.round(tiempoDesdeUltimaEdicion/1000)}s desde última edición)`);
      }
    }, 5000); // Verificar cada 5 segundos (antes era 2)
    
    return () => {
      clearInterval(intervaloSync);
      console.log("⏱️ Auto-sync detenido");
    };
  }, [cuadreActivoId, sincronizarCuadreActivo]);
 
  useEffect(() => {
    const borradores = cuadres.filter((c) => c.estado !== "final");
    saveCuadres(borradores);
  }, [cuadres]);
  
  // ====================== SUSCRIPCIÓN EN TIEMPO REAL PARA TRABAJO COLABORATIVO ======================
  useEffect(() => {
    if (!cuadreActivoId) {
      setUsuariosActivosEnCuadre([]);
      return;
    }
    
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const miNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario";
    
    console.log("🔴 Iniciando suscripción en tiempo real para cuadre:", cuadreActivoId);
    
    // 🚀 CANAL DE BROADCAST - Sincronización INSTANTÁNEA (menos de 100ms)
    const broadcastChannel = supabase
      .channel(`cuadre-broadcast-${cuadreActivoId}`, {
        config: {
          broadcast: { self: false, ack: true }, // No recibir propios mensajes, confirmar recepción
        }
      })
      .on('broadcast', { event: 'cuadre_update' }, (payload) => {
        console.log("⚡ Cambio recibido via Broadcast");
        
        // Si el cambio viene de nosotros mismos, ignorarlo
        if (payload.payload?.senderId === miId) {
          console.log("⏭️ Ignorando actualización propia (broadcast)");
          return;
        }
        
        const cuadreRemoto = payload.payload?.cuadre;
        if (cuadreRemoto) {
          // 🛡️ MARCAR QUE ESTAMOS RECIBIENDO BROADCAST - evita loop de sincronización
          recibiendoBroadcastRef.current = true;
          
          // 🛡️ Verificar si el usuario está editando activamente
          const tiempoDesdeUltimaEdicion = Date.now() - ultimaEdicionRef.current;
          const usuarioEditando = tiempoDesdeUltimaEdicion < TIEMPO_ESPERA_SYNC;
          
          // 🛡️ NUEVA PROTECCIÓN: Si el usuario editó en los últimos 5 segundos,
          // SOLO actualizar campos simples, NO arrays (para evitar perder lo que escribe)
          if (usuarioEditando) {
            console.log("⏸️ Usuario editando - SOLO sincronizar campos simples, NO arrays");
            
            setCuadres((prev) => {
              return prev.map((c) => {
                if (c.id === cuadreActivoId) {
                  // Solo actualizar campos que NO son arrays editables
                  return {
                    ...c,
                    // Mantener arrays locales intactos mientras edita
                    facturasEliminadas: [...(c.facturasEliminadas || []), ...(cuadreRemoto.facturasEliminadas || []).filter(fe => 
                      !(c.facturasEliminadas || []).some(local => local.id === fe.id)
                    )],
                    // Sincronizar estado y campos no editables
                    estado: cuadreRemoto.estado === "final" ? "final" : c.estado,
                    updated_at: c.updated_at, // Mantener timestamp local
                  };
                }
                return c;
              });
            });
          } else {
            console.log("🔄 Aplicando cambios remotos COMPLETOS");
            setUltimaActualizacionRemota(new Date().toISOString());
            ignorarProximaActualizacion.current = true;
            
            setCuadres((prev) => {
              return prev.map((c) => {
                if (c.id === cuadreActivoId) {
                  return fusionarCuadresColaborativo(c, cuadreRemoto, false);
                }
                return c;
              });
            });
          }
          
          // Resetear flag después de 500ms para permitir futuras sincronizaciones
          setTimeout(() => {
            recibiendoBroadcastRef.current = false;
          }, 500);
        }
      })
      // � NUEVO: Receptor de ACTUALIZACIONES PARCIALES (Modo Colaborador)
      .on('broadcast', { event: 'cuadre_partial_update' }, (payload) => {
        console.log("⚡ Actualización PARCIAL recibida via Broadcast");
        
        // Si el cambio viene de nosotros mismos, ignorarlo
        if (payload.payload?.senderId === miId) {
          console.log("⏭️ Ignorando actualización parcial propia");
          return;
        }
        
        const { cuadreId, seccion, datos, timestamp } = payload.payload || {};
        
        if (cuadreId && seccion && datos) {
          console.log(`🔄 Aplicando actualización parcial: ${seccion}`);
          
          // Aplicar SOLO la sección que cambió, sin tocar el resto
          setCuadres((prev) => {
            return prev.map((c) => {
              if (c.id === cuadreId) {
                // Solo actualizar si el timestamp remoto es más reciente
                const timestampLocal = c[`${seccion}_timestamp`] || 0;
                if (timestamp > timestampLocal) {
                  console.log(`✅ Aplicando ${seccion} (remoto más reciente)`);
                  return {
                    ...c,
                    [seccion]: datos,
                    [`${seccion}_timestamp`]: timestamp
                  };
                } else {
                  console.log(`⏭️ Ignorando ${seccion} (local más reciente)`);
                  return c;
                }
              }
              return c;
            });
          });
          
          // También actualizar colaboradorCuadre si está activo
          if (modoColaborador && colaboradorCuadreId === cuadreId) {
            setColaboradorCuadre(prev => {
              if (!prev) return prev;
              const timestampLocal = prev[`${seccion}_timestamp`] || 0;
              if (timestamp > timestampLocal) {
                return {
                  ...prev,
                  [seccion]: datos,
                  [`${seccion}_timestamp`]: timestamp
                };
              }
              return prev;
            });
          }
        }
      })
      // 🗑️ NUEVO: Escuchar evento de eliminación de cuadre
      .on('broadcast', { event: 'cuadre_eliminado' }, (payload) => {
        console.log("🗑️ Evento de eliminación recibido via Broadcast");
        
        const cuadreIdEliminado = payload.payload?.cuadreId;
        if (cuadreIdEliminado && cuadreIdEliminado === cuadreActivoId) {
          console.log("⚠️ El cuadre activo fue eliminado por otro usuario:", cuadreIdEliminado);
          
          // Marcar como eliminado en localStorage
          try {
            const eliminados = localStorage.getItem(STORAGE_ELIMINADOS_KEY);
            const listaEliminados = eliminados ? JSON.parse(eliminados) : [];
            if (!listaEliminados.includes(cuadreIdEliminado)) {
              listaEliminados.push(cuadreIdEliminado);
              localStorage.setItem(STORAGE_ELIMINADOS_KEY, JSON.stringify(listaEliminados));
            }
          } catch (e) {
            console.error("Error guardando lista de eliminados:", e);
          }
          
          // Eliminar del estado local
          setCuadres((prev) => prev.filter((c) => c.id !== cuadreIdEliminado));
          setCuadreActivoId(null);
          
          // Notificar al usuario
          alert("⚠️ El cuadre que estabas viendo fue eliminado por otro usuario.");
        }
      })
      // 🔒 NUEVO: Escuchar evento de CIERRE DEFINITIVO de cuadre
      .on('broadcast', { event: 'cuadre_cerrado' }, (payload) => {
        console.log("🔒 Evento de CIERRE DEFINITIVO recibido via Broadcast");
        
        // Si el cierre viene de nosotros mismos, ignorarlo
        if (payload.payload?.senderId === miId) {
          console.log("⏭️ Ignorando cierre propio");
          return;
        }
        
        const cuadreIdCerrado = payload.payload?.cuadreId;
        const cuadreCerrado = payload.payload?.cuadreCerrado;
        const cerradoPor = payload.payload?.cerradoPor || "otro usuario";
        
        if (cuadreIdCerrado && cuadreCerrado) {
          console.log("🔒 Cuadre CERRADO DEFINITIVAMENTE por:", cerradoPor, "ID:", cuadreIdCerrado);
          
          // 🔥 LIMPIAR INMEDIATAMENTE del localStorage
          try {
            const stored = localStorage.getItem(STORAGE_KEY);
            if (stored) {
              const locales = JSON.parse(stored);
              const limpios = locales.filter(c => c.id !== cuadreIdCerrado);
              if (limpios.length !== locales.length) {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(limpios));
                console.log("🧹 Cuadre cerrado eliminado del localStorage:", cuadreIdCerrado);
              }
            }
          } catch (e) {
            console.error("Error limpiando cuadre cerrado del localStorage:", e);
          }
          
          // FORZAR la actualización del estado - SIN importar si el usuario está editando
          // El cierre definitivo tiene PRIORIDAD ABSOLUTA
          setCuadres((prev) => {
            return prev.map((c) => {
              if (c.id === cuadreIdCerrado) {
                // Usar el cuadre cerrado completo, NO fusionar
                return {
                  ...cuadreCerrado,
                  estado: "final" // Asegurar estado cerrado
                };
              }
              return c;
            });
          });
          
          // Notificar al usuario solo si es el cuadre que estaba viendo
          if (cuadreIdCerrado === cuadreActivoId) {
            mostrarAlertaVisual('info', `🔒 El cuadre fue cerrado definitivamente por ${cerradoPor}. Ya no se puede modificar.`);
          }
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log("⚡ Canal Broadcast conectado - sincronización INSTANTÁNEA activa");
        }
      });
    
    broadcastChannelRef.current = broadcastChannel;
    
    // Canal de respaldo: postgres_changes (por si broadcast falla)
    const channel = supabase
      .channel(`cuadre-realtime-${cuadreActivoId}`, {
        config: {
          broadcast: { self: false },
          presence: { key: '' },
        }
      })
      .on(
        'postgres_changes',
        {
          event: '*', // Escuchar INSERT, UPDATE y DELETE
          schema: 'public',
          table: 'cuadres_diarios',
          filter: `id=eq.${cuadreActivoId}`
        },
        (payload) => {
          console.log("📡 Cambio recibido en tiempo real:", payload.eventType);
          
          // Si el cambio viene de nosotros mismos, ignorarlo
          if (ignorarProximaActualizacion.current) {
            console.log("⏭️ Ignorando actualización propia");
            ignorarProximaActualizacion.current = false;
            return;
          }
          
          if (payload.eventType === 'UPDATE' || payload.eventType === 'INSERT') {
            const cuadreRemoto = mapearRowCuadreDesdeSupabase(payload.new);
            if (cuadreRemoto) {
              // 🛡️ MARCAR QUE ESTAMOS RECIBIENDO DATOS REMOTOS - evita loop
              recibiendoBroadcastRef.current = true;
              
              // 🛡️ Verificar si el usuario está editando
              const tiempoDesdeUltimaEdicion = Date.now() - ultimaEdicionRef.current;
              const usuarioEditando = tiempoDesdeUltimaEdicion < TIEMPO_ESPERA_SYNC;
              
              if (usuarioEditando) {
                // Usuario editando - NO actualizar arrays para no perder sus cambios
                console.log("⏸️ Usuario editando - ignorando postgres_changes para proteger datos locales");
              } else {
                console.log("🔄 Aplicando cambios remotos al cuadre - EN LÍNEA");
                setUltimaActualizacionRemota(new Date().toISOString());
                
                // Fusionar cambios remotos con el estado local
                setCuadres((prev) => {
                  return prev.map((c) => {
                    if (c.id === cuadreActivoId) {
                      return fusionarCuadresColaborativo(c, cuadreRemoto, false);
                    }
                    return c;
                  });
                });
              }
              
              // Resetear flag después de 500ms
              setTimeout(() => {
                recibiendoBroadcastRef.current = false;
              }, 500);
            }
          }
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log("✅ Conectado en tiempo real - sincronización instantánea activa");
        } else {
          console.log("📡 Estado de suscripción realtime:", status);
        }
      });
    
    // Suscribirse a usuarios activos en el cuadre
    const channelUsuarios = supabase
      .channel(`cuadre-usuarios-${cuadreActivoId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'cuadres_usuarios_activos',
          filter: `cuadre_id=eq.${cuadreActivoId}`
        },
        async () => {
          // Recargar lista de usuarios activos
          const usuarios = await cargarUsuariosActivosEnCuadre(cuadreActivoId);
          setUsuariosActivosEnCuadre(usuarios);
        }
      )
      .subscribe();
    
    // Registrar usuario activo y cargar usuarios actuales
    if (miId) {
      registrarUsuarioActivoEnCuadre(cuadreActivoId, miId, miNombre);
      cargarUsuariosActivosEnCuadre(cuadreActivoId).then(setUsuariosActivosEnCuadre);
      
      // Actualizar presencia cada 15 segundos (más frecuente)
      const intervaloPresencia = setInterval(() => {
        registrarUsuarioActivoEnCuadre(cuadreActivoId, miId, miNombre);
      }, 15000);
      
      return () => {
        clearInterval(intervaloPresencia);
        removerUsuarioActivoEnCuadre(cuadreActivoId, miId);
        supabase.removeChannel(channel);
        supabase.removeChannel(channelUsuarios);
        supabase.removeChannel(broadcastChannel); // Limpiar canal broadcast
        broadcastChannelRef.current = null;
        console.log("🔴 Suscripción en tiempo real terminada");
      };
    }
    
    return () => {
      supabase.removeChannel(channel);
      supabase.removeChannel(channelUsuarios);
      supabase.removeChannel(broadcastChannel); // Limpiar canal broadcast
      broadcastChannelRef.current = null;
    };
  }, [cuadreActivoId, empleadoActual, usuarioActual]);

  // 🔹 SUSCRIPCIÓN PARA MODO COLABORADOR
  const colaboradorBroadcastRef = React.useRef(null);
  
  useEffect(() => {
    if (!modoColaborador || !colaboradorCuadreId) {
      if (colaboradorBroadcastRef.current) {
        supabase.removeChannel(colaboradorBroadcastRef.current);
        colaboradorBroadcastRef.current = null;
      }
      return;
    }
    
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    
    console.log("👥 [Colaborador] Iniciando suscripción para cuadre:", colaboradorCuadreId);
    
    const broadcastColaborador = supabase
      .channel(`cuadre-broadcast-${colaboradorCuadreId}`, {
        config: {
          broadcast: { self: false, ack: true },
        }
      })
      .on('broadcast', { event: 'cuadre_partial_update' }, (payload) => {
        console.log("👥 [Colaborador] Actualización parcial recibida");
        
        if (payload.payload?.senderId === miId) {
          return; // Ignorar propios mensajes
        }
        
        const { seccion, datos, timestamp } = payload.payload || {};
        
        if (seccion && datos) {
          setColaboradorCuadre(prev => {
            if (!prev) return prev;
            const timestampLocal = prev[`${seccion}_timestamp`] || 0;
            if (timestamp > timestampLocal) {
              console.log(`👥 [Colaborador] Aplicando ${seccion}`);
              return {
                ...prev,
                [seccion]: datos,
                [`${seccion}_timestamp`]: timestamp
              };
            }
            return prev;
          });
        }
      })
      .on('broadcast', { event: 'cuadre_update' }, (payload) => {
        console.log("👥 [Colaborador] Actualización completa recibida");
        
        if (payload.payload?.senderId === miId) {
          return;
        }
        
        const cuadreRemoto = payload.payload?.cuadre;
        if (cuadreRemoto) {
          // Solo actualizar transferencias y domicilios del colaborador
          setColaboradorCuadre(prev => {
            if (!prev) return prev;
            return {
              ...prev,
              transfer: cuadreRemoto.transfer || prev.transfer,
              domicilios: cuadreRemoto.domicilios || prev.domicilios
            };
          });
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log("👥 [Colaborador] Canal conectado");
        }
      });
    
    colaboradorBroadcastRef.current = broadcastColaborador;
    broadcastChannelRef.current = broadcastColaborador; // Para enviar actualizaciones
    
    return () => {
      if (colaboradorBroadcastRef.current) {
        supabase.removeChannel(colaboradorBroadcastRef.current);
        colaboradorBroadcastRef.current = null;
      }
    };
  }, [modoColaborador, colaboradorCuadreId, empleadoActual, usuarioActual]);

  useEffect(() => {
    let activo = true;
    setCargandoCuadres(true);
    console.log("🔄 Cargando cuadres desde Supabase, filtroEmpresa:", filtroEmpresa);
    
    // 🔐 SEGURIDAD: Si no hay filtroEmpresa, no cargar ningún cuadre
    if (!filtroEmpresa) {
      console.warn("⚠️ No hay filtroEmpresa definido - no se cargarán cuadres por seguridad");
      setCuadres([]);
      setCargandoCuadres(false);
      return;
    }
    
    // Obtener lista de cuadres que fueron eliminados (para no re-sincronizarlos)
    const cuadresEliminados = obtenerCuadresEliminadosGlobal();
    console.log("🗑️ Cuadres marcados como eliminados:", cuadresEliminados.length);
    
    cargarCuadresDiariosDeSupabase(filtroEmpresa).then(async (lista) => {
      if (!activo) return;
      console.log("✅ Cuadres cargados de Supabase:", lista.length);
      
      // IMPORTANTE: Filtrar la lista de Supabase para excluir cuadres eliminados localmente
      const listaFiltrada = lista.filter(c => !cuadresEliminados.includes(c.id));
      console.log("🗑️ Cuadres filtrados (eliminados):", lista.length - listaFiltrada.length);
      
      // 🔥 NUEVO: Eliminar DEFINITIVAMENTE de Supabase los cuadres que están en la lista de eliminados
      // 🔐 SEGURIDAD: Solo eliminar cuadres de la empresa actual
      const cuadresAEliminarDeSupabase = lista.filter(c => cuadresEliminados.includes(c.id));
      if (cuadresAEliminarDeSupabase.length > 0) {
        console.log("🔥 Eliminando", cuadresAEliminarDeSupabase.length, "cuadres de Supabase que están marcados como eliminados...");
        for (const cuadre of cuadresAEliminarDeSupabase) {
          try {
            let query = supabase
              .from("cuadres_diarios")
              .delete()
              .eq("id", cuadre.id);
            
            // 🔐 Filtrar por empresa para seguridad adicional
            if (filtroEmpresa) {
              query = query.eq("empresa_id", filtroEmpresa);
            }
            
            const { error } = await query;
            if (error) {
              console.error("❌ Error eliminando cuadre de Supabase:", cuadre.id, error);
            } else {
              console.log("✅ Cuadre eliminado de Supabase definitivamente:", cuadre.id);
            }
          } catch (e) {
            console.error("❌ Error eliminando cuadre:", cuadre.id, e);
          }
        }
      }
      console.log("📋 Borradores en Supabase:", listaFiltrada.filter(c => c.estado === "borrador").length);
      console.log("📋 Finales en Supabase:", listaFiltrada.filter(c => c.estado === "final").length);
      
      // 🔥 PRIORIDAD ABSOLUTA: Supabase SIEMPRE tiene prioridad sobre datos locales
      // Esto garantiza que si un cuadre fue cerrado por otro usuario, se refleje correctamente
      setCuadres((prev) => {
        const borradoresLocales = (prev || []).filter((c) => c.estado !== "final");
        console.log("💾 Borradores locales:", borradoresLocales.length);
        
        // 🔒 IMPORTANTE: Solo agregar borradores locales que:
        // 1. NO existen en Supabase (por ID)
        // 2. NO fueron eliminados
        // Si un cuadre existe en Supabase (aunque sea con diferente estado), SUPABASE GANA
        const idsEnSupabase = new Set(listaFiltrada.map(c => c.id));
        const borradoresSinDuplicados = borradoresLocales.filter(
          (b) => !idsEnSupabase.has(b.id) && !cuadresEliminados.includes(b.id)
        );
        console.log("🔀 Borradores locales NUEVOS (no en Supabase):", borradoresSinDuplicados.length);
        
        // Si hay borradores locales que no están en Supabase, sincronizarlos
        if (borradoresSinDuplicados.length > 0) {
          console.log("🔄 Sincronizando", borradoresSinDuplicados.length, "borradores locales a Supabase...");
          borradoresSinDuplicados.forEach((borrador) => {
            guardarCuadreDiarioEnSupabase(borrador, filtroEmpresa).then((resultado) => {
              if (resultado) {
                console.log("✅ Borrador local sincronizado a Supabase:", resultado.id);
              } else {
                console.error("❌ Error sincronizando borrador local:", borrador.id);
              }
            }).catch((e) => {
              console.error("❌ Error sincronizando borrador local:", borrador.id, e);
            });
          });
        }
        
        // 🔥 RESULTADO: Supabase primero, luego borradores locales NUEVOS
        // Los cuadres de Supabase tienen el estado actualizado (incluyendo los cerrados)
        const resultado = [...listaFiltrada, ...borradoresSinDuplicados];
        console.log("📊 Total cuadres después de merge:", resultado.length);
        
        // 🔒 Limpiar localStorage de borradores que ya están cerrados en Supabase
        const cuadresCerradosEnSupabase = listaFiltrada.filter(c => c.estado === "final").map(c => c.id);
        if (cuadresCerradosEnSupabase.length > 0) {
          try {
            const stored = localStorage.getItem(STORAGE_KEY);
            if (stored) {
              const locales = JSON.parse(stored);
              const limpios = locales.filter(c => !cuadresCerradosEnSupabase.includes(c.id));
              if (limpios.length !== locales.length) {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(limpios));
                console.log("🧹 Limpiados", locales.length - limpios.length, "cuadres cerrados del localStorage");
              }
            }
          } catch (e) {
            console.error("Error limpiando localStorage:", e);
          }
        }
        
        return resultado;
      });
      setCargandoCuadres(false);
    }).catch((e) => {
      console.error("❌ Fallo sincronizando cuadres con Supabase", e);
      if (activo) {
        setCargandoCuadres(false);
      }
    });
    return () => {
      activo = false;
    };
  }, [filtroEmpresa]);

  // 🔒 CANAL GENERAL: Escuchar cierres de cuadres de la empresa (aunque no tengamos cuadre activo)
  useEffect(() => {
    if (!filtroEmpresa) return;
    
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const canalGeneralId = `cuadres-empresa-${filtroEmpresa}`;
    
    console.log("📡 Suscribiéndose al canal general de cuadres:", canalGeneralId);
    
    const canalGeneral = supabase.channel(canalGeneralId)
      .on('broadcast', { event: 'cuadre_cerrado' }, (payload) => {
        // Ignorar nuestros propios cierres
        if (payload.payload?.senderId === miId) return;
        
        const cuadreIdCerrado = payload.payload?.cuadreId;
        const cuadreCerrado = payload.payload?.cuadreCerrado;
        const cerradoPor = payload.payload?.cerradoPor || "otro usuario";
        
        if (cuadreIdCerrado && cuadreCerrado) {
          console.log("📡 [Canal General] Cuadre cerrado:", cuadreIdCerrado, "por:", cerradoPor);
          
          // Limpiar de localStorage
          try {
            const stored = localStorage.getItem(STORAGE_KEY);
            if (stored) {
              const locales = JSON.parse(stored);
              const limpios = locales.filter(c => c.id !== cuadreIdCerrado);
              if (limpios.length !== locales.length) {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(limpios));
                console.log("🧹 [Canal General] Cuadre cerrado eliminado del localStorage");
              }
            }
          } catch (e) {
            console.error("Error limpiando localStorage desde canal general:", e);
          }
          
          // Actualizar estado local
          setCuadres((prev) => {
            const yaExiste = prev.some(c => c.id === cuadreIdCerrado);
            if (yaExiste) {
              return prev.map((c) => c.id === cuadreIdCerrado ? { ...cuadreCerrado, estado: "final" } : c);
            }
            // Si no existe, agregarlo como cerrado
            return [...prev, { ...cuadreCerrado, estado: "final" }];
          });
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          console.log("📡 Conectado al canal general de cuadres de la empresa");
        }
      });
    
    return () => {
      console.log("📡 Desconectando canal general de cuadres");
      supabase.removeChannel(canalGeneral);
    };
  }, [filtroEmpresa, empleadoActual, usuarioActual]);

  // Cargar solicitudes pendientes periódicamente
  useEffect(() => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    if (!miId) return;
    
    const cargarSolicitudes = async () => {
      const solicitudes = await cargarSolicitudesPendientes(miId, esGerente);
      setSolicitudesPendientes(solicitudes);
    };
    
    cargarSolicitudes();
    // Verificar cada 10 segundos
    const intervalo = setInterval(cargarSolicitudes, 10000);
    
    return () => clearInterval(intervalo);
  }, [empleadoActual, usuarioActual, esGerente]);

  // Cargar cuadres con acceso aprobado para el usuario actual
  useEffect(() => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    if (!miId) return;
    
    const cargarAccesosAprobados = async () => {
      try {
        const { data, error } = await supabase
          .from("cuadres_solicitudes")
          .select("cuadre_id")
          .eq("solicitante_id", String(miId))
          .eq("estado", "aprobado");
        
        if (error) {
          console.error("❌ Error cargando accesos aprobados:", error);
          return;
        }
        
        if (data && data.length > 0) {
          const ids = data.map(s => String(s.cuadre_id));
          setCuadresConAccesoAprobado(ids);
          console.log("✅ Cuadres con acceso aprobado para", miId, ":", ids);
        } else {
          setCuadresConAccesoAprobado([]);
          console.log("ℹ️ No hay cuadres con acceso aprobado para", miId);
        }
      } catch (e) {
        console.error("Error cargando accesos aprobados:", e);
      }
    };
    
    cargarAccesosAprobados();
    // Verificar cada 5 segundos (más frecuente para mejor experiencia)
    const intervalo = setInterval(cargarAccesosAprobados, 5000);
    
    return () => clearInterval(intervalo);
  }, [empleadoActual, usuarioActual]);

  // Bloquear cuadre cuando se abre y desbloquear cuando se cierra
  useEffect(() => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const miNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario";
    
    if (cuadreActivoId && miId) {
      bloquearCuadre(cuadreActivoId, miId, miNombre);
    }
    
    // Desbloquear al salir del cuadre
    return () => {
      if (cuadreActivoId) {
        desbloquearCuadre(cuadreActivoId);
      }
    };
  }, [cuadreActivoId, empleadoActual, usuarioActual]);

  // Manejar solicitud de acceso a cuadre bloqueado
  const handleSolicitarAcceso = async (cuadreId, propietarioId) => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const miNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario";
    
    if (!miId) {
      alert("Error: No se pudo identificar al usuario");
      return;
    }
    
    setEnviandoSolicitud(true);
    const resultado = await enviarSolicitudAcceso(cuadreId, miId, miNombre, propietarioId);
    setEnviandoSolicitud(false);
    
    if (resultado) {
      setSolicitudEnviada(true);
      alert("✅ Solicitud enviada. El empleado que tiene el cuadre abierto o un gerente debe aprobar tu acceso.");
    } else {
      alert("❌ Error al enviar la solicitud. Intenta nuevamente.");
    }
  };

  // Aprobar o rechazar solicitud
  const handleResponderSolicitud = async (solicitud, aprobado) => {
    console.log("🔄 Respondiendo solicitud:", solicitud.id, "Aprobado:", aprobado, "Cuadre:", solicitud.cuadre_id);
    const exito = await responderSolicitudAcceso(solicitud.id, aprobado, solicitud.cuadre_id);
    
    if (exito) {
      console.log("✅ Solicitud procesada exitosamente");
      setSolicitudesPendientes((prev) => prev.filter((s) => s.id !== solicitud.id));
      alert(aprobado ? "✅ Solicitud aprobada. El usuario puede acceder al cuadre." : "❌ Solicitud rechazada.");
    } else {
      console.error("❌ Error procesando solicitud");
      alert("Error al procesar la solicitud. Intenta nuevamente.");
    }
  };

  // Abrir modal de gestión de accesos (solo gerentes)
  const handleGestionarAccesos = async (cuadre) => {
    setCuadreGestionAccesos(cuadre);
    setCargandoAccesos(true);
    setMostrarModalGestionAccesos(true);
    
    const accesos = await cargarAccesosAprobadosPorCuadre(cuadre.id);
    
    // Verificar si el propietario tiene acceso revocado
    // El propietario revocado se identifica cuando solicitante_id = propietario_id y estado = revocado
    const { data: propietarioRevocado } = await supabase
      .from("cuadres_solicitudes")
      .select("*")
      .eq("cuadre_id", cuadre.id)
      .eq("solicitante_id", cuadre.empleadoId)
      .eq("propietario_id", cuadre.empleadoId)
      .eq("estado", "revocado")
      .maybeSingle();
    
    console.log("🔍 Verificando propietario revocado para cuadre:", cuadre.id, "empleadoId:", cuadre.empleadoId);
    console.log("🔍 Resultado:", propietarioRevocado);
    
    // Agregar al propietario del cuadre como primer elemento
    const propietario = empleados.find((e) => String(e.id) === String(cuadre.empleadoId));
    const listaTotalAccesos = [];
    
    if (propietario) {
      listaTotalAccesos.push({
        id: `propietario-${cuadre.id}`,
        solicitante_id: propietario.id,
        solicitante_nombre: propietario.nombre,
        esPropietario: true,
        accesoRevocado: !!propietarioRevocado,
        fecha_solicitud: cuadre.fecha,
        cuadre_id: cuadre.id
      });
    }
    
    // Agregar los accesos aprobados (excluyendo al propietario si ya está)
    accesos.forEach((acceso) => {
      if (String(acceso.solicitante_id) !== String(cuadre.empleadoId)) {
        listaTotalAccesos.push(acceso);
      }
    });
    
    setAccesosDelCuadre(listaTotalAccesos);
    setCargandoAccesos(false);
  };

  // Revocar acceso de un usuario a un cuadre
  const handleRevocarAcceso = async (acceso) => {
    const nombreUsuario = acceso.solicitante_nombre || 'este usuario';
    
    if (acceso.esPropietario) {
      // Si es el propietario, revocar su acceso pero mantener el registro de quién abrió el cuadre
      if (!window.confirm(`¿Seguro que deseas quitar el acceso de ${nombreUsuario} (propietario original) a este cuadre? El empleado ya no podrá editarlo pero seguirá apareciendo como quien lo abrió.`)) {
        return;
      }
      
      // Primero verificar si ya existe un registro de acceso revocado para el propietario
      const { data: existente } = await supabase
        .from("cuadres_solicitudes")
        .select("id")
        .eq("cuadre_id", acceso.cuadre_id)
        .eq("solicitante_id", acceso.solicitante_id)
        .eq("propietario_id", acceso.solicitante_id)
        .eq("estado", "revocado")
        .maybeSingle();
      
      if (existente) {
        // Ya existe, no hacer nada
        setAccesosDelCuadre((prev) => prev.map((a) => 
          a.id === acceso.id ? { ...a, accesoRevocado: true } : a
        ));
        alert(`✅ El acceso de ${nombreUsuario} ya estaba revocado.`);
        return;
      }
      
      // Crear un registro de acceso revocado para el propietario
      // El propietario se identifica porque solicitante_id === propietario_id
      console.log("📝 Insertando registro de revocación del propietario:", {
        cuadre_id: acceso.cuadre_id,
        solicitante_id: acceso.solicitante_id,
        solicitante_nombre: acceso.solicitante_nombre,
        propietario_id: acceso.solicitante_id,
        estado: "revocado"
      });
      
      const { data: insertedData, error } = await supabase
        .from("cuadres_solicitudes")
        .insert({
          cuadre_id: acceso.cuadre_id,
          solicitante_id: acceso.solicitante_id,
          solicitante_nombre: acceso.solicitante_nombre,
          propietario_id: acceso.solicitante_id,
          estado: "revocado",
          fecha_solicitud: new Date().toISOString()
        })
        .select();
      
      console.log("📝 Resultado del insert:", { data: insertedData, error });
      
      if (error) {
        console.error("❌ Error revocando acceso del propietario:", error);
        alert("❌ Error al revocar el acceso. Intenta nuevamente. Error: " + error.message);
        return;
      }
      
      if (!insertedData || insertedData.length === 0) {
        console.error("❌ No se insertó ningún registro");
        alert("❌ Error: No se pudo guardar la revocación. Verifica los permisos en Supabase.");
        return;
      }
      
      console.log("✅ Registro insertado exitosamente:", insertedData);
      
      setAccesosDelCuadre((prev) => prev.map((a) => 
        a.id === acceso.id ? { ...a, accesoRevocado: true } : a
      ));
      alert(`✅ Acceso de ${nombreUsuario} revocado. El empleado sigue apareciendo como quien abrió el cuadre pero ya no puede editarlo.`);
    } else {
      // Es un acceso aprobado normal
      if (!window.confirm(`¿Seguro que deseas revocar el acceso de ${nombreUsuario} a este cuadre?`)) {
        return;
      }
      
      const exito = await revocarAccesoCuadre(acceso.id);
      
      if (exito) {
        setAccesosDelCuadre((prev) => prev.filter((a) => a.id !== acceso.id));
        alert("✅ Acceso revocado exitosamente.");
      } else {
        alert("❌ Error al revocar el acceso. Intenta nuevamente.");
      }
    }
  };

  // Restaurar acceso de un usuario a un cuadre (solo para propietarios con acceso revocado)
  const handleRestaurarAcceso = async (acceso) => {
    const nombreUsuario = acceso.solicitante_nombre || 'este usuario';
    
    if (!window.confirm(`¿Seguro que deseas restaurar el acceso de ${nombreUsuario} a este cuadre?`)) {
      return;
    }
    
    // Eliminar el registro de acceso revocado del propietario
    // El propietario se identifica porque solicitante_id === propietario_id
    const { error } = await supabase
      .from("cuadres_solicitudes")
      .delete()
      .eq("cuadre_id", acceso.cuadre_id)
      .eq("solicitante_id", acceso.solicitante_id)
      .eq("propietario_id", acceso.solicitante_id)
      .eq("estado", "revocado");
    
    if (error) {
      console.error("❌ Error restaurando acceso:", error);
      alert("❌ Error al restaurar el acceso. Intenta nuevamente.");
      return;
    }
    
    setAccesosDelCuadre((prev) => prev.map((a) => 
      a.id === acceso.id ? { ...a, accesoRevocado: false } : a
    ));
    alert(`✅ Acceso de ${nombreUsuario} restaurado. El empleado puede editar el cuadre nuevamente.`);
  };

  // ====================== FUNCIÓN GLOBAL: Obtener facturas pendientes de días anteriores ======================
  // Esta función busca facturas pendientes de días anteriores que NO han sido pagadas
  // FILTRO: Solo considera cuadres a partir del 7 de febrero de 2026
  // IDENTIFICACIÓN: Por ID único (origenId), permitiendo múltiples facturas con el mismo nombre
  const FECHA_MINIMA_FACTURAS_GLOBAL = "2026-02-07";
  
  const obtenerFacturasPendientesAnterioresGlobal = (sede, fecha, facturasActuales = []) => {
    const pendientes = [];
    
    // 🔍 DIAGNÓSTICO: Ver todos los cuadres de esta sede
    const cuadresDeSede = cuadres.filter(c => c.sede === sede);
    console.log(`🔍 [DIAGNÓSTICO GLOBAL] Sede: ${sede}, Fecha actual: ${fecha}`);
    console.log(`🔍 [DIAGNÓSTICO GLOBAL] Total cuadres cargados: ${cuadres.length}`);
    console.log(`🔍 [DIAGNÓSTICO GLOBAL] Cuadres de esta sede: ${cuadresDeSede.length}`);
    cuadresDeSede.forEach(c => {
      console.log(`   📅 Cuadre ${c.fecha} - Estado: ${c.estado} - Facturas: ${(c.facturas || []).length}`);
      (c.facturas || []).forEach(f => {
        console.log(`      💰 ID: ${f.id} - OrigenId: ${f.origenId || 'N/A'} - Factura: ${f.factura || '(vacía)'} - Estado: ${f.estado}`);
      });
    });
    
    // 1. Recolectar todas las facturas que ya fueron pagadas en cualquier cuadre (por origenId Y por id)
    const facturasPagadasPorId = new Set();
    cuadres.forEach((c) => {
      if (c.sede === sede && c.fecha >= FECHA_MINIMA_FACTURAS_GLOBAL && Array.isArray(c.facturas)) {
        c.facturas.forEach((f) => {
          const estadoLower = (f.estado || "").toLowerCase();
          if (estadoLower.includes("pagada") || estadoLower.includes("caja") || estadoLower.includes("transferencia")) {
            // Agregar AMBOS IDs para cubrir todos los casos de rastreo
            if (f.id) {
              facturasPagadasPorId.add(String(f.id));
            }
            if (f.origenId) {
              facturasPagadasPorId.add(String(f.origenId));
            }
          }
        });
      }
    });
    
    // 2. Recolectar IDs de facturas que YA están en el cuadre actual (para evitar duplicados)
    const idsYaEnCuadre = new Set();
    (facturasActuales || []).forEach((f) => {
      // Agregar tanto el origenId como el id para cubrir todos los casos
      if (f.origenId) {
        idsYaEnCuadre.add(String(f.origenId));
      }
      if (f.id) {
        idsYaEnCuadre.add(String(f.id));
      }
    });
    
    console.log("📋 [GLOBAL] IDs de facturas ya pagadas:", Array.from(facturasPagadasPorId));
    console.log("📋 [GLOBAL] IDs ya en cuadre actual:", Array.from(idsYaEnCuadre));
    
    // 3. Buscar facturas pendientes de días anteriores que NO estén pagadas NI ya en el cuadre (por ID único)
    cuadres.forEach((c) => {
      if (c.sede === sede && c.fecha < fecha && c.fecha >= FECHA_MINIMA_FACTURAS_GLOBAL && Array.isArray(c.facturas)) {
        c.facturas.forEach((f) => {
          const estadoLower = (f.estado || "").toLowerCase();
          if (estadoLower === "pendiente" || estadoLower.includes("pendiente")) {
            // El ID único es el origenId si existe, sino el id de la factura
            const idUnico = f.origenId || f.id;
            
            // Solo agregar si:
            // - La factura tiene ID
            // - NO ha sido pagada en ningún cuadre (por ID)
            // - NO está ya en el cuadre actual (por ID)
            if (idUnico && !facturasPagadasPorId.has(String(idUnico)) && !idsYaEnCuadre.has(String(idUnico))) {
              // IMPORTANTE: Preservar el origenId original si ya existe (factura que pasó por múltiples cuadres)
              // Si no tiene origenId, usar su id como origenId
              const origenIdReal = f.origenId || f.id;
              pendientes.push({
                id: uid(),
                origenId: origenIdReal, // SIEMPRE el ID de la factura original
                factura: f.factura,
                valor: f.valor,
                estado: "Pendiente",
                origenFecha: f.origenFecha || c.fecha,
              });
              console.log(`⏳ [GLOBAL] Factura pendiente encontrada: ${f.factura} (origenId: ${origenIdReal}) - Origen: ${f.origenFecha || c.fecha}`);
            } else if (idUnico && facturasPagadasPorId.has(String(idUnico))) {
              console.log(`✅ [GLOBAL] Factura ${f.factura} (ID: ${idUnico}) ya fue pagada - NO se carga`);
            } else if (idUnico && idsYaEnCuadre.has(String(idUnico))) {
              console.log(`🔄 [GLOBAL] Factura ${f.factura} (ID: ${idUnico}) ya está en el cuadre actual - NO se duplica`);
            }
          }
        });
      }
    });
    
    console.log(`📊 [GLOBAL] Total facturas pendientes encontradas: ${pendientes.length}`);
    return pendientes;
  };
  // ====================== FIN FUNCIÓN GLOBAL ======================

  // Intentar abrir un cuadre verificando si está bloqueado
  const handleAbrirCuadre = async (cuadre) => {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const esMiCuadre = String(cuadre.empleadoId) === String(miId);
    const tieneAccesoAprobado = cuadresConAccesoAprobado.includes(String(cuadre.id));
    
    // ==========================================
    // 🔐 VERIFICAR ESTADO ACTUAL EN SUPABASE antes de abrir
    // Esto evita que aparezca como abierto si ya fue cerrado por otro usuario
    // ==========================================
    try {
      const { data: cuadreActualizado, error: errorVerificar } = await supabase
        .from("cuadres_diarios")
        .select("estado, fecha, sede")
        .eq("id", cuadre.id)
        .maybeSingle();
      
      if (errorVerificar) {
        console.error("❌ Error verificando estado del cuadre:", errorVerificar);
      } else if (cuadreActualizado) {
        // Si el cuadre ya está cerrado en Supabase pero local dice que no
        if (cuadreActualizado.estado === "final" && cuadre.estado !== "final") {
          console.log("🔐 El cuadre ya fue cerrado por otro usuario - actualizando estado local");
          setCuadres(prev => prev.map(c => 
            c.id === cuadre.id ? { ...c, estado: "final" } : c
          ));
          alert("ℹ️ Este cuadre ya fue cerrado. Se ha actualizado la información.");
          return; // No abrir - ya está cerrado
        }
      } else {
        // El cuadre no existe en Supabase - puede haber sido eliminado
        console.log("⚠️ El cuadre no existe en Supabase - posiblemente fue eliminado");
        setCuadres(prev => prev.filter(c => c.id !== cuadre.id));
        alert("⚠️ Este cuadre ya no existe. Se ha removido de la lista.");
        return;
      }
    } catch (e) {
      console.error("❌ Error en verificación de cuadre:", e);
      // Continuar de todos modos si hay error de conexión
    }
    
    // Verificar estrictamente si es gerente (doble verificación)
    const perfilActual = (empleadoActual?.perfil || usuarioActual?.perfil || usuarioActual?.rol || "").toString().toUpperCase();
    const esRealmenteGerente = esGerente && (
      perfilActual.includes("GERENCIA") || 
      perfilActual.includes("GERENTE") || 
      perfilActual.includes("ADMIN") ||
      perfilActual.includes("SUPERVISOR") ||
      perfilActual.includes("COORDINADOR") ||
      perfilActual === "SUPER_ADMIN"
    );
    
    console.log("🔍 Intentando abrir cuadre:", cuadre.id);
    console.log("   - Mi ID:", miId);
    console.log("   - Es mi cuadre:", esMiCuadre);
    console.log("   - Tiene acceso aprobado:", tieneAccesoAprobado);
    console.log("   - Es gerente (prop):", esGerente);
    console.log("   - Es REALMENTE gerente:", esRealmenteGerente);
    console.log("   - Perfil actual:", perfilActual);
    console.log("   - Lista de accesos aprobados:", cuadresConAccesoAprobado);
    
    // Verificar si el propietario tiene acceso revocado
    // El propietario revocado se identifica cuando solicitante_id = propietario_id y estado = revocado
    if (esMiCuadre) {
      const { data: propietarioRevocado } = await supabase
        .from("cuadres_solicitudes")
        .select("*")
        .eq("cuadre_id", cuadre.id)
        .eq("solicitante_id", miId)
        .eq("propietario_id", miId)
        .eq("estado", "revocado")
        .maybeSingle();
      
      if (propietarioRevocado) {
        alert("❌ Tu acceso a este cuadre ha sido revocado por un gerente. Contacta a un gerente para restaurar tu acceso.");
        return;
      }
    }
    
    // Si es mi cuadre (sin revocación), soy gerente REAL, o tengo acceso aprobado, abrir directamente
    if (esMiCuadre || esRealmenteGerente || tieneAccesoAprobado) {
      console.log("✅ Abriendo cuadre directamente");
      
      // ====================== VERIFICAR FACTURAS PENDIENTES FALTANTES ======================
      // Al abrir un cuadre existente, verificar si hay facturas pendientes de días anteriores
      // que NO están en este cuadre y agregarlas automáticamente
      if (cuadre.estado !== "final") {
        console.log("🔍 Verificando facturas pendientes faltantes...");
        const pendientesFaltantes = obtenerFacturasPendientesAnterioresGlobal(
          cuadre.sede,
          cuadre.fecha,
          cuadre.facturas || []
        );
        
        if (pendientesFaltantes.length > 0) {
          console.log(`📥 [ABRIR DIRECTO] Agregando ${pendientesFaltantes.length} facturas pendientes faltantes al cuadre`);
          
          // Agregar las facturas pendientes faltantes al inicio del array de facturas
          const facturasActualizadas = [...pendientesFaltantes, ...(cuadre.facturas || [])];
          
          // Actualizar el cuadre con las nuevas facturas
          actualizarCuadre(cuadre.id, {
            facturas: facturasActualizadas,
          });
          
          console.log(`✅ Se agregaron ${pendientesFaltantes.length} factura(s) pendiente(s) de días anteriores`);
        } else {
          console.log("✅ No hay facturas pendientes faltantes por agregar");
        }
      }
      // ====================== FIN VERIFICACIÓN ======================
      
      // Cargar los accesos del cuadre para mostrar en el precierre
      const accesos = await cargarAccesosAprobadosPorCuadre(cuadre.id);
      const propietario = empleados.find((e) => String(e.id) === String(cuadre.empleadoId));
      const listaTotalAccesos = [];
      
      if (propietario) {
        listaTotalAccesos.push({
          id: `propietario-${cuadre.id}`,
          solicitante_id: propietario.id,
          solicitante_nombre: propietario.nombre,
          esPropietario: true,
          estado: 'aprobado',
          fecha_solicitud: cuadre.fecha,
          cuadre_id: cuadre.id
        });
      }
      
      // Agregar los accesos aprobados (excluyendo al propietario si ya está)
      accesos.forEach((acceso) => {
        if (String(acceso.solicitante_id) !== String(cuadre.empleadoId)) {
          listaTotalAccesos.push({ ...acceso, estado: 'aprobado' });
        }
      });
      
      setAccesosDelCuadre(listaTotalAccesos);
      setCuadreActivoId(cuadre.id);
      return;
    }
    
    // No tiene acceso, mostrar modal para solicitar
    const emp = empleados.find((e) => e.id === cuadre.empleadoId);
    setCuadreBloqueadoInfo({
      cuadre: cuadre,
      bloqueo: {
        usuario_id: cuadre.empleadoId,
        usuario_nombre: emp?.nombre || "Otro usuario",
        bloqueado_en: new Date().toISOString()
      }
    });
    setMostrarModalSolicitud(true);
    setSolicitudEnviada(false);
  };

  // ====================== LIMPIAR DUPLICADOS AL ABRIR CUADRE ======================
  // Este efecto se ejecuta cuando se abre un cuadre para eliminar duplicados existentes
  const limpiezaDuplicadosRealizada = React.useRef({});
  
  React.useEffect(() => {
    if (!cuadreActivoId) return;
    
    // Evitar limpiar el mismo cuadre múltiples veces en la misma sesión
    if (limpiezaDuplicadosRealizada.current[cuadreActivoId]) {
      return;
    }
    
    const cuadre = cuadres.find(c => c.id === cuadreActivoId);
    if (!cuadre) return;
    
    // Marcar como procesado inmediatamente
    limpiezaDuplicadosRealizada.current[cuadreActivoId] = true;
    
    // Función para verificar si un item está completamente vacío
    const itemEstaVacio = (item, campos) => {
      return campos.every(campo => {
        const val = item[campo];
        return val === undefined || val === null || val === "" || val === 0;
      });
    };
    
    // Función para limpiar duplicados y vacíos de un array
    const limpiarArray = (items, campos) => {
      if (!Array.isArray(items) || items.length === 0) return { resultado: [], cambios: 0 };
      
      const vistos = new Map();
      const resultado = [];
      let cambios = 0;
      
      items.forEach(item => {
        if (!item || !item.id) {
          cambios++;
          return; // Ignorar items sin ID
        }
        
        // Verificar si está completamente vacío
        if (itemEstaVacio(item, campos)) {
          cambios++; // Eliminar filas vacías
          console.log(`🗑️ Eliminando fila vacía: ${item.id}`);
          return;
        }
        
        // Crear clave basada en valores (normalizada)
        const valores = campos.map(c => String(item[c] || "").trim().toLowerCase());
        const clave = valores.join("|");
        
        // Si la clave tiene contenido, usarla para detectar duplicados
        const tieneContenido = valores.some(v => v !== "");
        
        if (tieneContenido) {
          if (!vistos.has(clave)) {
            vistos.set(clave, item);
            resultado.push(item);
          } else {
            // Duplicado por valores - conservar el más reciente
            const existente = vistos.get(clave);
            if ((item.updatedAt || 0) > (existente.updatedAt || 0)) {
              const idx = resultado.indexOf(existente);
              if (idx >= 0) {
                resultado[idx] = item;
                vistos.set(clave, item);
              }
            }
            cambios++;
            console.log(`🧹 Duplicado encontrado: ${clave.substring(0, 40)}`);
          }
        } else {
          // Sin contenido real - eliminar
          cambios++;
        }
      });
      
      return { resultado, cambios };
    };
    
    const patch = {};
    let totalCambios = 0;
    
    // Limpiar domicilios
    if (Array.isArray(cuadre.domicilios) && cuadre.domicilios.length > 0) {
      const { resultado, cambios } = limpiarArray(cuadre.domicilios, ['pedido', 'valor', 'pago', 'obs', 'domiciliario']);
      if (cambios > 0 || resultado.length !== cuadre.domicilios.length) {
        patch.domicilios = resultado;
        totalCambios += Math.abs(cuadre.domicilios.length - resultado.length);
        console.log(`🧹 Domicilios: ${cuadre.domicilios.length} -> ${resultado.length}`);
      }
    }
    
    // Limpiar transferencias
    if (Array.isArray(cuadre.transfer) && cuadre.transfer.length > 0) {
      const { resultado, cambios } = limpiarArray(cuadre.transfer, ['pedido', 'bancolombia', 'davivienda', 'nequi', 'daviplata']);
      if (cambios > 0 || resultado.length !== cuadre.transfer.length) {
        patch.transfer = resultado;
        totalCambios += Math.abs(cuadre.transfer.length - resultado.length);
        console.log(`🧹 Transferencias: ${cuadre.transfer.length} -> ${resultado.length}`);
      }
    }
    
    // Limpiar facturas - detectar duplicados por múltiples campos
    if (Array.isArray(cuadre.facturas) && cuadre.facturas.length > 0) {
      const vistos = new Map();
      const facturasLimpias = [];
      let cambiosFacturas = 0;
      
      cuadre.facturas.forEach(f => {
        if (!f || !f.id) return;
        
        // Para facturas, usar múltiples campos como clave de duplicado
        const pedido = String(f.pedido || f.factura || "").trim().toLowerCase();
        const valor = String(f.valor || "").trim();
        const efectivo = String(f.efectivo || "").trim();
        const pago = String(f.pago || "").trim();
        const obs = String(f.obs || f.observaciones || "").trim().toLowerCase();
        
        // Crear clave combinando todos los campos relevantes
        const clave = `${pedido}|${valor}|${efectivo}|${pago}|${obs}`;
        
        // Verificar si está completamente vacía
        const estaVacia = !pedido && !valor && !efectivo && !pago && !obs;
        
        if (estaVacia) {
          cambiosFacturas++;
          console.log(`🗑️ Factura vacía eliminada: ${f.id}`);
          return;
        }
        
        if (vistos.has(clave)) {
          // Es duplicado
          const existente = vistos.get(clave);
          if ((f.updatedAt || 0) > (existente.updatedAt || 0)) {
            const idx = facturasLimpias.indexOf(existente);
            if (idx >= 0) {
              facturasLimpias[idx] = f;
              vistos.set(clave, f);
            }
          }
          cambiosFacturas++;
          console.log(`🧹 Factura duplicada: ${clave.substring(0, 50)}`);
        } else {
          vistos.set(clave, f);
          facturasLimpias.push(f);
        }
      });
      
      if (cambiosFacturas > 0) {
        patch.facturas = facturasLimpias;
        totalCambios += cambiosFacturas;
        console.log(`🧹 Facturas: ${cuadre.facturas.length} -> ${facturasLimpias.length}`);
      }
    }
    
    // Si hubo cambios, actualizar el cuadre directamente en el estado y Supabase
    // 🛡️ PERO SOLO SI NO ESTAMOS RECIBIENDO UN BROADCAST (evita loop)
    if (totalCambios > 0 && !recibiendoBroadcastRef.current) {
      console.log(`🧹 Limpieza completada: ${totalCambios} items eliminados/corregidos`);
      
      // Actualizar estado local
      setCuadres(prev => prev.map(c => 
        c.id === cuadreActivoId ? { ...c, ...patch, updated_at: new Date().toISOString() } : c
      ));
      
      // Guardar en Supabase solo si NO venimos de un broadcast
      ignorarProximaActualizacion.current = true;
      const cuadreLimpio = { ...cuadre, ...patch };
      guardarCuadreDiarioEnSupabase(cuadreLimpio, filtroEmpresa).then(() => {
        console.log("✅ Cuadre limpio guardado en Supabase");
      }).catch(e => {
        console.error("Error guardando cuadre limpio:", e);
        ignorarProximaActualizacion.current = false;
      });
    } else if (totalCambios > 0) {
      console.log(`🛡️ Limpieza detectada pero ignorada (viene de broadcast)`);
    }
  }, [cuadreActivoId, cuadres, filtroEmpresa]);
  // ====================== FIN LIMPIEZA DE DUPLICADOS ======================
 
  const cuadreActivo = useMemo(
    () => cuadres.find((c) => c.id === cuadreActivoId) || null,
    [cuadres, cuadreActivoId]
  );
 
  // FILTRO: Excluir cuadres de prueba anteriores al 7 de febrero de 2026
  const FECHA_MINIMA_CUADRES = "2026-02-07";
  
  const cuadresEnProceso = useMemo(
    () => cuadres.filter((c) => c.estado !== "final" && c.fecha >= FECHA_MINIMA_CUADRES),
    [cuadres]
  );
 
  function crearOBuscarBorrador({ sede, fecha }) {
    const borrador = cuadres.find(
      (c) => c.sede === sede && c.fecha === fecha && c.estado !== "final"
    );
    if (borrador) return borrador;
 
    const nuevo = {
      id: uid(),
      sede,
      fecha,
      empleadoId: "",
      valorInicial: 0,
      // 🔹 COLABORADOR - Solo este usuario puede colaborar
      colaboradorId: null,
      colaboradorNombre: null,
      ventas: {
        ventaEfectivo: "",
        sobrante: "",
        huboDescuadre: "No",
        valorDescuadre: "",
      },
      facturas: [],
      facturasEliminadas: [], // Para sincronización colaborativa - evita que facturas borradas reaparezcan
      domicilios: [],
      transfer: [],
      turnosActivos: false,
      turnos: [],
      adelantosActivos: false,
      adelantos: [],
      denominacionesActivas: false,
      denoms: [],
      novedadesActivas: false,
      novedades: [],
      datafonos: [],
      totales: {},
      estado: "borrador",
      comentarioModificacion: "",
    };
    setCuadres((prev) => [...prev, nuevo]);
    // Sincronizar borrador con Supabase para que esté disponible en otros equipos
    console.log("💾 Guardando nuevo borrador en Supabase:", nuevo.id, "sede:", nuevo.sede, "fecha:", nuevo.fecha, "empresaId:", filtroEmpresa);
    guardarCuadreDiarioEnSupabase(nuevo, filtroEmpresa).then((resultado) => {
      if (resultado) {
        console.log("✅ Borrador guardado exitosamente en Supabase:", resultado.id);
      } else {
        console.error("❌ Error: guardarCuadreDiarioEnSupabase retornó null");
      }
    }).catch((e) => {
      console.error("❌ Error sincronizando borrador de cuadre:", e);
    });
    return nuevo;
  }
 
  // Debounce para sincronización - evitar enviar cada tecla
  const cuadreUpdateTimeout = React.useRef({});
  const broadcastTimeout = React.useRef(null);
  const ultimoEnvio = React.useRef({});
  
  function actualizarCuadre(id, patch) {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    
    setCuadres((prev) => {
      const updated = prev.map((c) => (c.id === id ? { ...c, ...patch, updated_at: new Date().toISOString() } : c));
      const cuadreActualizado = updated.find((c) => c.id === id);
      
      // 🚀 ENVIAR VIA BROADCAST CON DEBOUNCE (evita enviar cada tecla)
      if (cuadreActualizado && broadcastChannelRef.current && id === cuadreActivoId) {
        // Cancelar broadcast anterior si existe
        if (broadcastTimeout.current) {
          clearTimeout(broadcastTimeout.current);
        }
        
        // Esperar 300ms después de última tecla antes de enviar
        broadcastTimeout.current = setTimeout(() => {
          // Obtener el cuadre MÁS ACTUAL del estado
          const cuadreActual = cuadres.find(c => c.id === id) || cuadreActualizado;
          
          broadcastChannelRef.current.send({
            type: 'broadcast',
            event: 'cuadre_update',
            payload: {
              cuadre: cuadreActual,
              senderId: miId,
              timestamp: Date.now()
            }
          }).then(() => {
            console.log("⚡ Cambio enviado por Broadcast (después de debounce)");
          }).catch((e) => {
            console.error("Error enviando por broadcast:", e);
          });
        }, 300); // 300ms de debounce - esperar que usuario termine de escribir
      }
      
      // Sincronizar con Supabase (para persistencia) con debounce de 500ms
      if (cuadreActualizado) {
        if (cuadreUpdateTimeout.current[id]) {
          clearTimeout(cuadreUpdateTimeout.current[id]);
        }
        
        // 🔴 DATOS CRÍTICOS - Guardar INMEDIATAMENTE sin delay
        const efectivoConfirmadoAhora = cuadreActualizado?.ventas?.efectivoEnCajaConfirmado === true;
        const efectivoConfirmadoAntes = cuadreActivo?.ventas?.efectivoEnCajaConfirmado === true;
        const efectivoFinalAhora = cuadreActualizado?.ventas?.efectivoFinalConfirmado === true;
        const efectivoFinalAntes = cuadreActivo?.ventas?.efectivoFinalConfirmado === true || cuadreActivo?.efectivoFinalConfirmado === true;
        
        if ((efectivoConfirmadoAhora && !efectivoConfirmadoAntes) || (efectivoFinalAhora && !efectivoFinalAntes)) {
          // El efectivo acaba de ser confirmado O el valor final acaba de ser confirmado - guardar INMEDIATAMENTE
          console.log("⚡ GUARDANDO INMEDIATAMENTE:", efectivoFinalAhora && !efectivoFinalAntes ? "Efectivo FINAL confirmado" : "Efectivo confirmado en caja");
          ignorarProximaActualizacion.current = true;
          ultimoEnvio.current[id] = Date.now();
          guardarCuadreDiarioEnSupabase(cuadreActualizado, filtroEmpresa).catch((e) => {
            console.error("Error guardando efectivo confirmado:", e);
            ignorarProximaActualizacion.current = false;
          });
        } else {
          // Otros cambios - guardar con debounce de 500ms
          cuadreUpdateTimeout.current[id] = setTimeout(() => {
            ignorarProximaActualizacion.current = true;
            ultimoEnvio.current[id] = Date.now();
            guardarCuadreDiarioEnSupabase(cuadreActualizado, filtroEmpresa).catch((e) => {
              console.error("Error sincronizando cuadre:", e);
              ignorarProximaActualizacion.current = false;
            });
          }, 500); // 500ms - esperar antes de persistir
        }
      }
      
      return updated;
    });
  }
  
  // 🔹 ACTUALIZACIÓN PARCIAL - Para Modo Colaborador (solo envía la sección modificada)
  function actualizarCuadreParcial(id, seccion, datos) {
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    const timestamp = Date.now();
    
    // Actualizar localmente
    setCuadres((prev) => {
      const updated = prev.map((c) => {
        if (c.id === id) {
          return {
            ...c,
            [seccion]: datos,
            [`${seccion}_timestamp`]: timestamp,
            updated_at: new Date().toISOString()
          };
        }
        return c;
      });
      
      const cuadreActualizado = updated.find((c) => c.id === id);
      
      // 🚀 ENVIAR VIA BROADCAST PARCIAL
      if (cuadreActualizado && broadcastChannelRef.current) {
        broadcastChannelRef.current.send({
          type: 'broadcast',
          event: 'cuadre_partial_update',
          payload: {
            cuadreId: id,
            seccion: seccion,
            datos: datos,
            timestamp: timestamp,
            senderId: miId
          }
        }).then(() => {
          console.log(`⚡ Actualización parcial (${seccion}) enviada`);
        }).catch((e) => {
          console.error("Error enviando actualización parcial:", e);
        });
      }
      
      // Sincronizar con Supabase (solo la sección afectada)
      if (cuadreActualizado) {
        if (cuadreUpdateTimeout.current[`${id}_${seccion}`]) {
          clearTimeout(cuadreUpdateTimeout.current[`${id}_${seccion}`]);
        }
        cuadreUpdateTimeout.current[`${id}_${seccion}`] = setTimeout(() => {
          ignorarProximaActualizacion.current = true;
          guardarCuadreDiarioEnSupabase(cuadreActualizado, filtroEmpresa).catch((e) => {
            console.error("Error sincronizando cuadre parcial:", e);
            ignorarProximaActualizacion.current = false;
          });
        }, 300); // Más rápido para parciales
      }
      
      return updated;
    });
    
    // También actualizar colaboradorCuadre si está en modo colaborador
    if (modoColaborador && colaboradorCuadreId === id) {
      setColaboradorCuadre(prev => {
        if (!prev) return prev;
        return {
          ...prev,
          [seccion]: datos,
          [`${seccion}_timestamp`]: timestamp
        };
      });
    }
  }
 
  function guardarFinal(id, totales) {
    const existente = cuadres.find((c) => c.id === id);
    if (!existente) {
      console.error("No se encontró el cuadre a guardar", id);
      return;
    }

    // Registrar quién cerró el cuadre
    const cerradoPorId = empleadoActual?.id || usuarioActual?.id || "";
    const cerradoPorNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario desconocido";
    const fechaNuevoCierre = new Date().toISOString();

    // Verificar si es un cuadre reabierto y agregar novedades
    // 🔹 EVITAR DUPLICADOS: Solo agregar si no existe ya la información
    const comentarioExistente = existente.comentarioModificacion || "";
    
    let novedadesReabierto = "";
    if (existente.fueReabierto && !comentarioExistente.includes("CUADRE REABIERTO")) {
      const fechaCierreOriginalFormateada = existente.fechaCierreOriginal 
        ? new Date(existente.fechaCierreOriginal).toLocaleString("es-CO")
        : "No registrada";
      const fechaNuevoCierreFormateada = new Date(fechaNuevoCierre).toLocaleString("es-CO");
      
      novedadesReabierto = `\n\n🔄 **CUADRE REABIERTO**\n` +
        `• Cierre inicial: ${fechaCierreOriginalFormateada} por ${existente.cerradoPorOriginal || "N/A"}\n` +
        `• Reabierto: ${existente.reabiertoEn ? new Date(existente.reabiertoEn).toLocaleString("es-CO") : "N/A"} por ${existente.reabiertoPor || "N/A"}\n` +
        `• Nuevo cierre: ${fechaNuevoCierreFormateada} por ${cerradoPorNombre}`;
    }

    // 🔹 Registrar bases de domicilios en el cierre (EVITAR DUPLICADOS)
    let notaBasesDomicilios = "";
    const basesDom = existente.basesDomicilios || [];
    // Solo agregar si hay bases y NO existe ya la información
    if (basesDom.length > 0 && !comentarioExistente.includes("BASES DE DOMICILIOS")) {
      const formatCOP = (val) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(val || 0);
      
      const basesPendientes = basesDom.filter(base => {
        const totalAbonos = (base.abonos || []).reduce((sum, a) => sum + Number(a.valor || 0), 0);
        return (Number(base.valorBase || 0) - totalAbonos) > 0;
      });
      
      const totalEntregado = basesDom.reduce((sum, b) => sum + Number(b.valorBase || 0), 0);
      const totalRecuperado = basesDom.reduce((sum, b) => {
        return sum + (b.abonos || []).reduce((s, a) => s + Number(a.valor || 0), 0);
      }, 0);
      const totalPendienteBases = totalEntregado - totalRecuperado;

      notaBasesDomicilios = `\n\n🚴 **BASES DE DOMICILIOS**\n` +
        `• Total bases entregadas: ${formatCOP(totalEntregado)}\n` +
        `• Total recuperado: ${formatCOP(totalRecuperado)}\n` +
        `• Saldo pendiente: ${formatCOP(totalPendienteBases)}`;

      if (basesPendientes.length > 0) {
        notaBasesDomicilios += `\n\n⚠️ DOMICILIARIOS CON SALDO PENDIENTE:\n`;
        basesPendientes.forEach(base => {
          const totalAbonos = (base.abonos || []).reduce((s, a) => s + Number(a.valor || 0), 0);
          const saldo = Number(base.valorBase || 0) - totalAbonos;
          notaBasesDomicilios += `  • ${base.empleado}: ${formatCOP(saldo)}\n`;
        });
      }
    }

    const actualizado = {
      ...existente,
      totales: totales || {},
      estado: "final",
      cerradoPorId: cerradoPorId,
      cerradoPorNombre: cerradoPorNombre,
      fechaCierre: fechaNuevoCierre,
      // Agregar novedades de reapertura y bases de domicilios si aplica
      comentarioModificacion: comentarioExistente + novedadesReabierto + notaBasesDomicilios,
    };

    setCuadres((prev) =>
      prev.map((c) => (c.id === id ? actualizado : c))
    );

    guardarCuadreDiarioEnSupabase(actualizado, filtroEmpresa).then((sincronizado) => {
      if (!sincronizado) {
        alert("No se pudo sincronizar el cuadre con Supabase. Verifica tu conexión y vuelve a intentar.");
        setCuadres((prev) =>
          prev.map((c) => (c.id === id ? existente : c))
        );
        return;
      }

      setCuadres((prev) =>
        prev.map((c) =>
          c.id === id
            ? {
                ...sincronizado,
                comentarioModificacion:
                  actualizado.comentarioModificacion || sincronizado.comentarioModificacion || "",
              }
            : c
        )
      );
      
      // 🔒 LIMPIAR INMEDIATAMENTE del localStorage local
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const locales = JSON.parse(stored);
          const limpios = locales.filter(c => c.id !== id);
          localStorage.setItem(STORAGE_KEY, JSON.stringify(limpios));
          console.log("🧹 Cuadre cerrado eliminado del localStorage local");
        }
      } catch (e) {
        console.error("Error limpiando localStorage:", e);
      }
      
      // 🔒 BROADCAST DE CIERRE DEFINITIVO - Notificar a TODOS los usuarios
      // Enviar a DOS canales: el específico del cuadre Y un canal general de la empresa
      const miId = empleadoActual?.id || usuarioActual?.id || "";
      
      // Canal 1: Específico del cuadre (para usuarios que lo tienen activo)
      const broadcastChannel = supabase.channel(`cuadre-broadcast-${id}`);
      broadcastChannel.subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          broadcastChannel.send({
            type: 'broadcast',
            event: 'cuadre_cerrado',
            payload: {
              cuadreId: id,
              senderId: miId,
              cuadreCerrado: sincronizado,
              cerradoPor: cerradoPorNombre,
              fechaCierre: fechaNuevoCierre
            }
          }).then(() => {
            console.log("🔒 Broadcast de CIERRE DEFINITIVO enviado (canal cuadre)");
            supabase.removeChannel(broadcastChannel);
          });
        }
      });
      
      // Canal 2: General de la empresa (para refrescar la lista)
      const canalGeneral = supabase.channel(`cuadres-empresa-${filtroEmpresa || 'global'}`);
      canalGeneral.subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          canalGeneral.send({
            type: 'broadcast',
            event: 'cuadre_cerrado',
            payload: {
              cuadreId: id,
              senderId: miId,
              cuadreCerrado: sincronizado,
              cerradoPor: cerradoPorNombre,
              fechaCierre: fechaNuevoCierre
            }
          }).then(() => {
            console.log("🔒 Broadcast de CIERRE DEFINITIVO enviado (canal empresa)");
            supabase.removeChannel(canalGeneral);
          });
        }
      });
      
      // 🚪 SACAR AL USUARIO DEL CUADRE CERRADO
      // Esto evita que el usuario siga viendo el cuadre como activo
      setCuadreActivoId(null);
      console.log("🚪 Usuario sacado del cuadre cerrado");
    });
  }
 
  function guardarComentario(id, comentario) {
    const existente = cuadres.find((c) => c.id === id);
    if (!existente) {
      console.error("No se encontró el cuadre para comentario", id);
      return;
    }

    const actualizado = { ...existente, comentarioModificacion: comentario };

    setCuadres((prev) =>
      prev.map((c) => (c.id === id ? actualizado : c))
    );

    if (existente.estado === "final") {
      guardarCuadreDiarioEnSupabase(actualizado, filtroEmpresa).then((sincronizado) => {
        if (!sincronizado) {
          alert("No se pudo guardar el comentario en Supabase. Intenta nuevamente.");
          setCuadres((prev) =>
            prev.map((c) => (c.id === id ? existente : c))
          );
          return;
        }

        setCuadres((prev) =>
          prev.map((c) =>
            c.id === id
              ? {
                  ...sincronizado,
                  comentarioModificacion: comentario,
                }
              : c
          )
        );
      });
    }
  }

  // Función para realizar PRECIERRE del cuadre (cambio de turno)
  function realizarPrecierre(id, asignadoAId, observaciones, totalesDetallados) {
    const existente = cuadres.find((c) => c.id === id);
    if (!existente) {
      console.error("No se encontró el cuadre para precierre", id);
      return;
    }

    if (existente.estado === "final") {
      alert("⚠️ Este cuadre ya está cerrado, no se puede hacer precierre.");
      return;
    }

    // Obtener datos del empleado que realiza el precierre
    const precierrePorId = empleadoActual?.id || usuarioActual?.id || "";
    const precierrePorNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario desconocido";
    
    // Obtener datos del empleado al que se asigna
    const empleadoAsignado = empleados.find(e => e.id === asignadoAId);
    const asignadoANombre = empleadoAsignado?.nombre || "No asignado";
    
    const fechaPrecierre = new Date().toISOString();
    const fechaPrecierreFormateada = new Date().toLocaleString("es-CO");
    
    // Formatear moneda para notas
    const formatCOP = (val) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(val || 0);
    
    // Crear registro de precierre con totales detallados
    const precierre = {
      fecha: fechaPrecierre,
      porId: precierrePorId,
      porNombre: precierrePorNombre,
      asignadoAId: asignadoAId,
      asignadoANombre: asignadoANombre,
      observaciones: observaciones || "",
      totales: totalesDetallados,
      confirmadoPorReceptor: false,
      fechaConfirmacion: null
    };
    
    // Agregar nota de precierre al comentario con detalle
    // 🔹 EVITAR DUPLICADOS: Solo agregar si no existe ya un precierre
    const comentarioExistente = existente.comentarioModificacion || "";
    const yaHayPrecierre = comentarioExistente.includes("PRECIERRE DE TURNO");
    
    const notaPrecierre = `\n\n📋 **PRECIERRE DE TURNO**\n` +
      `• Fecha: ${fechaPrecierreFormateada}\n` +
      `• Realizado por: ${precierrePorNombre}\n` +
      `• Asignado a: ${asignadoANombre}\n` +
      `• Observaciones: ${observaciones || "Sin observaciones"}\n\n` +
      `💰 VERIFICACIÓN DE EFECTIVO AL PRECIERRE:\n` +
      `  - Efectivo en caja confirmado: ${formatCOP(totalesDetallados?.efectivoEnCaja)}\n` +
      `  - Debía quedar en caja: ${formatCOP(totalesDetallados?.debeQuedarEnCaja)}\n` +
      `  - Diferencia: ${totalesDetallados?.diferenciaEfectivo >= 0 ? '+' : ''}${formatCOP(totalesDetallados?.diferenciaEfectivo)}\n` +
      `  - Estado: ${totalesDetallados?.estaCuadrado ? '✅ CUADRADO' : '⚠️ DESCUADRADO'}\n\n` +
      `💰 VENTAS AL PRECIERRE:\n` +
      `  - Efectivo: ${formatCOP(totalesDetallados?.ventaEfectivo)}\n` +
      `  - Bancolombia: ${formatCOP(totalesDetallados?.bancolombia)}\n` +
      `  - Davivienda: ${formatCOP(totalesDetallados?.davivienda)}\n` +
      `  - Daviplata: ${formatCOP(totalesDetallados?.daviplata)}\n` +
      `  - Nequi: ${formatCOP(totalesDetallados?.nequi)}\n` +
      `  - Datáfono: ${formatCOP(totalesDetallados?.totalDatafonos)}\n` +
      `  - Online Rappi: ${formatCOP(totalesDetallados?.onlineRappi)}\n` +
      `  - TOTAL VENTAS: ${formatCOP(totalesDetallados?.totalVentas)}\n\n` +
      `📋 GASTOS AL PRECIERRE:\n` +
      `  - Facturas Pendientes: ${formatCOP(totalesDetallados?.totalFacturasPendientes)}\n` +
      `  - Facturas Pagadas Caja: ${formatCOP(totalesDetallados?.totalFacturasCaja)}\n` +
      `  - Facturas Pagadas Transferencia: ${formatCOP(totalesDetallados?.totalFacturasTransferencia)}`;

    // Si ya hay un precierre, reemplazarlo con el nuevo en lugar de concatenar
    let nuevoComentario;
    if (yaHayPrecierre) {
      // Reemplazar el precierre anterior con el nuevo
      const indicePrecierre = comentarioExistente.indexOf("\n\n📋 **PRECIERRE DE TURNO**");
      if (indicePrecierre !== -1) {
        nuevoComentario = comentarioExistente.substring(0, indicePrecierre) + notaPrecierre;
      } else {
        nuevoComentario = comentarioExistente + notaPrecierre;
      }
    } else {
      nuevoComentario = comentarioExistente + notaPrecierre;
    }

    const actualizado = {
      ...existente,
      empleadoId: asignadoAId, // Cambiar el responsable al nuevo empleado
      precierreRealizado: true,
      precierre: precierre,
      precierrePendienteConfirmacion: true, // Nuevo: indica que el receptor debe confirmar
      comentarioModificacion: nuevoComentario,
    };

    setCuadres((prev) =>
      prev.map((c) => (c.id === id ? actualizado : c))
    );

    guardarCuadreDiarioEnSupabase(actualizado, filtroEmpresa).then((sincronizado) => {
      if (!sincronizado) {
        alert("No se pudo guardar el precierre en Supabase. Verifica tu conexión.");
        setCuadres((prev) =>
          prev.map((c) => (c.id === id ? existente : c))
        );
        return;
      }

      setCuadres((prev) =>
        prev.map((c) =>
          c.id === id
            ? {
                ...sincronizado,
                comentarioModificacion: actualizado.comentarioModificacion || sincronizado.comentarioModificacion || "",
              }
            : c
        )
      );
      
      alert(`✅ Precierre realizado exitosamente.\n\nEl cuadre fue asignado a: ${asignadoANombre}\n\nEl nuevo responsable puede continuar editando el cuadre.`);
    });
  }

  // Función para reabrir un cuadre cerrado (solo Gerencia)
  async function reabrirCuadre(id) {
    if (!esGerente) {
      alert("❌ Solo usuarios con perfil Gerencia pueden reabrir cuadres.");
      return;
    }

    const existente = cuadres.find((c) => c.id === id);
    if (!existente) {
      console.error("No se encontró el cuadre a reabrir", id);
      return;
    }

    if (existente.estado !== "final") {
      alert("⚠️ Este cuadre no está cerrado, no se puede reabrir.");
      return;
    }

    if (!window.confirm("¿Está seguro que desea REABRIR este cuadre?\n\nEl cuadre pasará a estado 'En proceso' y podrá ser editado nuevamente.\n\n⚠️ IMPORTANTE: Una vez reabierto, este cuadre NO podrá ser borrado.")) {
      return;
    }

    const reabrirNombre = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario desconocido";
    const fechaCierreAnterior = existente.fechaCierre || new Date().toISOString();
    
    const actualizado = {
      ...existente,
      estado: "borrador",
      fueReabierto: true, // Marcar que fue reabierto
      fechaCierreOriginal: existente.fechaCierreOriginal || fechaCierreAnterior, // Guardar fecha del primer cierre
      cerradoPorOriginal: existente.cerradoPorOriginal || existente.cerradoPorNombre, // Guardar quién cerró originalmente
      reabiertoEn: new Date().toISOString(),
      reabiertoPor: reabrirNombre,
      // Registrar quién reabrió en el comentario
      comentarioModificacion: (existente.comentarioModificacion || "") + 
        `\n[REABIERTO por ${reabrirNombre} el ${new Date().toLocaleString("es-CO")}]`,
    };

    setCuadres((prev) =>
      prev.map((c) => (c.id === id ? actualizado : c))
    );

    const sincronizado = await guardarCuadreDiarioEnSupabase(actualizado, filtroEmpresa);
    if (!sincronizado) {
      alert("❌ No se pudo sincronizar el cuadre reabierto con Supabase.");
      setCuadres((prev) =>
        prev.map((c) => (c.id === id ? existente : c))
      );
      return;
    }

    setCuadres((prev) =>
      prev.map((c) =>
        c.id === id
          ? {
              ...sincronizado,
              comentarioModificacion: actualizado.comentarioModificacion || sincronizado.comentarioModificacion || "",
            }
          : c
      )
    );

    alert("✅ Cuadre reabierto correctamente. Ahora puede editarlo en 'Cuadres en proceso'.");
    console.log("🔓 Cuadre reabierto:", id, "por:", reabrirNombre);
  }

  async function borrarCuadre(id) {
    const cuadreABorrar = cuadres.find((c) => c.id === id);
    
    // No permitir borrar cuadres que fueron reabiertos
    if (cuadreABorrar?.fueReabierto) {
      alert("❌ Este cuadre fue reabierto anteriormente y NO puede ser borrado.\n\nLos cuadres reabiertos quedan protegidos para mantener el historial de modificaciones.");
      return;
    }
    
    if (!window.confirm("¿Seguro que deseas borrar este cuadre en proceso?")) {
      return;
    }
    
    console.log("🗑️ Intentando eliminar cuadre:", id);
    const miId = empleadoActual?.id || usuarioActual?.id || "";
    
    // PRIMERO: Intentar eliminar de Supabase (ANTES de actualizar estado local)
    // 🔐 SEGURIDAD: Agregar filtro de empresa para no eliminar cuadres de otras empresas
    let eliminadoDeSupabase = false;
    try {
      let query = supabase
        .from("cuadres_diarios")
        .delete()
        .eq("id", id);
      
      // 🔐 Filtrar por empresa si está disponible
      if (filtroEmpresa) {
        query = query.eq("empresa_id", filtroEmpresa);
      }
      
      const { error } = await query;
      
      if (error) {
        console.error("❌ Error eliminando de Supabase (intento 1):", error);
        // Reintentar una vez más
        let queryRetry = supabase
          .from("cuadres_diarios")
          .delete()
          .eq("id", id);
        if (filtroEmpresa) {
          queryRetry = queryRetry.eq("empresa_id", filtroEmpresa);
        }
        const { error: error2 } = await queryRetry;
        if (error2) {
          console.error("❌ Error eliminando de Supabase (intento 2):", error2);
        } else {
          eliminadoDeSupabase = true;
        }
      } else {
        eliminadoDeSupabase = true;
        console.log("✅ Cuadre eliminado de Supabase correctamente:", id);
      }
    } catch (e) {
      console.error("❌ Error en borrarCuadre (Supabase):", e);
    }
    
    // 🚀 NUEVO: Enviar broadcast de eliminación a TODOS los usuarios conectados
    if (eliminadoDeSupabase) {
      try {
        const broadcastChannel = supabase.channel(`cuadre-broadcast-${id}`);
        await broadcastChannel.send({
          type: 'broadcast',
          event: 'cuadre_eliminado',
          payload: {
            cuadreId: id,
            senderId: miId,
            timestamp: Date.now()
          }
        });
        console.log("📢 Broadcast de eliminación enviado a todos los usuarios");
        await supabase.removeChannel(broadcastChannel);
      } catch (e) {
        console.error("Error enviando broadcast de eliminación:", e);
      }
    }
    
    // SEGUNDO: Marcar el ID como eliminado ANTES de todo (para evitar re-sincronización)
    try {
      const eliminados = localStorage.getItem(STORAGE_ELIMINADOS_KEY);
      const listaEliminados = eliminados ? JSON.parse(eliminados) : [];
      if (!listaEliminados.includes(id)) {
        listaEliminados.push(id);
        localStorage.setItem(STORAGE_ELIMINADOS_KEY, JSON.stringify(listaEliminados));
        console.log("✅ ID agregado a lista de eliminados:", id);
      }
    } catch (e) {
      console.error("Error guardando lista de eliminados:", e);
    }
    
    // TERCERO: Actualizar estado local
    setCuadres((prev) => prev.filter((c) => c.id !== id));
    if (cuadreActivoId === id) setCuadreActivoId(null);
    
    // NOTA: Ya no usamos localStorage para cuadres - Supabase es la única fuente de verdad
    // Esto evita conflictos entre usuarios y que aparezcan cuadres fantasma
    
    // Mostrar resultado al usuario
    if (eliminadoDeSupabase) {
      alert("✅ Cuadre eliminado correctamente");
    } else {
      alert("⚠️ El cuadre se eliminó localmente pero hubo un problema con el servidor.\n\nNo te preocupes, ya no volverá a aparecer porque está marcado como eliminado.");
    }
  }

  async function guardarEdicionCuadre() {
    if (!cuadreEditando) return;
    
    // Actualizar estado local primero
    const cuadreActualizado = { ...cuadreEditando };
    setCuadres((prev) =>
      prev.map((c) => (c.id === cuadreEditando.id ? cuadreActualizado : c))
    );
    
    // Guardar en Supabase
    try {
      const resultado = await guardarCuadreDiarioEnSupabase(cuadreActualizado, filtroEmpresa);
      if (resultado) {
        console.log("✅ Cuadre actualizado en Supabase");
      } else {
        console.error("❌ Error al sincronizar cuadre con Supabase");
      }
    } catch (e) {
      console.error("❌ Error guardando cuadre:", e);
    }
    
    setCuadreEditando(null);
    alert("Cuadre modificado exitosamente");
  }
 
  return (
    <div>
      {cargandoCuadres && (
        <div className="card" style={{ marginBottom: 12, backgroundColor: "#f1f5f9" }}>
          <p style={{ margin: 0, fontSize: 12, color: "#334155" }}>Sincronizando cuadres con Supabase…</p>
        </div>
      )}

      {/* PANEL DE SOLICITUDES PENDIENTES */}
      {solicitudesPendientes.length > 0 && (
        <div className="card" style={{ marginBottom: 12, backgroundColor: "#fef3c7", border: "2px solid #f59e0b" }}>
          <h3 style={{ margin: "0 0 8px 0", color: "#92400e", display: "flex", alignItems: "center", gap: 8 }}>
            🔔 Solicitudes de acceso pendientes ({solicitudesPendientes.length})
          </h3>
          <p style={{ margin: "0 0 12px 0", fontSize: 12, color: "#78350f" }}>
            Otros usuarios solicitan acceso a cuadres que tienes abiertos o en proceso.
          </p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {solicitudesPendientes.map((sol) => {
              const cuadreRelacionado = cuadres.find((c) => c.id === sol.cuadre_id);
              return (
                <div key={sol.id} style={{ 
                  background: "white", 
                  padding: 12, 
                  borderRadius: 8, 
                  border: "1px solid #fcd34d",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  flexWrap: "wrap",
                  gap: 8
                }}>
                  <div>
                    <div style={{ fontWeight: 600, color: "#1f2937" }}>
                      {sol.solicitante_nombre} solicita acceso
                    </div>
                    <div style={{ fontSize: 11, color: "#6b7280" }}>
                      Cuadre: {cuadreRelacionado?.fecha || "—"} - {cuadreRelacionado?.sede || "—"}
                    </div>
                    <div style={{ fontSize: 10, color: "#9ca3af" }}>
                      Solicitado: {new Date(sol.fecha_solicitud).toLocaleString()}
                    </div>
                  </div>
                  <div style={{ display: "flex", gap: 6 }}>
                    <button
                      type="button"
                      onClick={() => handleResponderSolicitud(sol, true)}
                      style={{ 
                        background: "#10b981", 
                        color: "white", 
                        border: "none", 
                        borderRadius: 6, 
                        padding: "6px 12px", 
                        fontSize: 12, 
                        fontWeight: 600,
                        cursor: "pointer" 
                      }}
                    >
                      ✅ Aprobar
                    </button>
                    <button
                      type="button"
                      onClick={() => handleResponderSolicitud(sol, false)}
                      style={{ 
                        background: "#ef4444", 
                        color: "white", 
                        border: "none", 
                        borderRadius: 6, 
                        padding: "6px 12px", 
                        fontSize: 12, 
                        fontWeight: 600,
                        cursor: "pointer" 
                      }}
                    >
                      ❌ Rechazar
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* MODAL DE CUADRE BLOQUEADO */}
      {mostrarModalSolicitud && cuadreBloqueadoInfo && (
        <div style={{
          position: "fixed",
          inset: 0,
          background: "rgba(0,0,0,0.5)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          zIndex: 9999,
          padding: 20
        }} onClick={() => setMostrarModalSolicitud(false)}>
          <div style={{
            background: "white",
            borderRadius: 12,
            padding: 24,
            maxWidth: 450,
            width: "100%",
            boxShadow: "0 8px 32px rgba(0,0,0,0.2)"
          }} onClick={(e) => e.stopPropagation()}>
            <div style={{ textAlign: "center", marginBottom: 16 }}>
              <span style={{ fontSize: 48 }}>🔒</span>
            </div>
            <h3 style={{ margin: "0 0 8px 0", textAlign: "center", color: "#1f2937" }}>
              Cuadre en uso
            </h3>
            <p style={{ margin: "0 0 16px 0", textAlign: "center", color: "#6b7280", fontSize: 14 }}>
              Este cuadre está siendo editado por <strong>{cuadreBloqueadoInfo.bloqueo.usuario_nombre}</strong>.
            </p>
            <div style={{ 
              background: "#f3f4f6", 
              padding: 12, 
              borderRadius: 8, 
              marginBottom: 16,
              fontSize: 13
            }}>
              <div><strong>Fecha:</strong> {cuadreBloqueadoInfo.cuadre.fecha}</div>
              <div><strong>Sede:</strong> {cuadreBloqueadoInfo.cuadre.sede}</div>
              <div><strong>Bloqueado desde:</strong> {new Date(cuadreBloqueadoInfo.bloqueo.bloqueado_en).toLocaleString()}</div>
            </div>
            
            {solicitudEnviada ? (
              <div style={{ 
                background: "#d1fae5", 
                padding: 12, 
                borderRadius: 8, 
                textAlign: "center",
                color: "#065f46",
                fontSize: 13
              }}>
                ✅ Solicitud enviada. Espera la aprobación del empleado o de un gerente.
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                <button
                  type="button"
                  disabled={enviandoSolicitud}
                  onClick={() => handleSolicitarAcceso(
                    cuadreBloqueadoInfo.cuadre.id, 
                    cuadreBloqueadoInfo.bloqueo.usuario_id
                  )}
                  style={{ 
                    background: enviandoSolicitud ? "#9ca3af" : "#3b82f6", 
                    color: "white", 
                    border: "none", 
                    borderRadius: 8, 
                    padding: "12px 16px", 
                    fontSize: 14, 
                    fontWeight: 600,
                    cursor: enviandoSolicitud ? "not-allowed" : "pointer" 
                  }}
                >
                  {enviandoSolicitud ? "Enviando..." : "📤 Solicitar acceso"}
                </button>
                <p style={{ margin: 0, fontSize: 11, color: "#9ca3af", textAlign: "center" }}>
                  Se enviará una notificación al empleado que tiene el cuadre abierto y a los gerentes.
                </p>
              </div>
            )}
            
            <button
              type="button"
              onClick={() => setMostrarModalSolicitud(false)}
              style={{ 
                width: "100%",
                marginTop: 12,
                background: "#e5e7eb", 
                color: "#374151", 
                border: "none", 
                borderRadius: 8, 
                padding: "10px 16px", 
                fontSize: 13,
                cursor: "pointer" 
              }}
            >
              Cerrar
            </button>
          </div>
        </div>
      )}

      <div className="tabs">
        {tienePermiso("admin_cuadre_abrir") && (
        <button
          className={modo === "crear" && !modoColaborador ? "tab active" : "tab"}
          onClick={() => {
            setModo("crear");
            setCuadreActivoId(null);
            setModoColaborador(false);
          }}
        >
          Abrir cuadre
        </button>
        )}
        {tienePermiso("admin_cuadre_consultar") && (
        <button
          className={modo === "consultar" && !modoColaborador ? "tab active" : "tab"}
          onClick={() => {
            setModo("consultar");
            setCuadreActivoId(null);
            setModoColaborador(false);
          }}
        >
          Consultar cuadres
        </button>
        )}
        {/* 🔹 NUEVO: Botón Modo Colaborador */}
        <button
          className={modoColaborador ? "tab active" : "tab"}
          onClick={() => {
            setModoColaborador(true);
            setCuadreActivoId(null);
            setColaboradorCuadreId(null);
            setColaboradorCuadre(null);
          }}
          style={{
            background: modoColaborador ? 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)' : undefined,
            color: modoColaborador ? 'white' : undefined,
            border: modoColaborador ? 'none' : undefined
          }}
        >
          👥 Modo Colaborador
        </button>
      </div>
      
      {/* 🔹 VISTA MODO COLABORADOR - Solo Transferencias y Domicilios */}
      {modoColaborador && (
        <div className="card" style={{ marginTop: 16 }}>
          <div style={{
            background: 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)',
            color: 'white',
            padding: '16px 20px',
            marginBottom: '20px',
            borderRadius: '12px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px'
          }}>
            <span style={{ fontSize: '32px' }}>👥</span>
            <div>
              <div style={{ fontSize: '18px', fontWeight: '700' }}>MODO COLABORADOR</div>
              <div style={{ fontSize: '12px', opacity: 0.9 }}>
                Solo puedes ver y editar Transferencias y Domicilios. Sin conflictos con el usuario principal.
              </div>
            </div>
          </div>
          
          {!colaboradorCuadreId ? (
            // Seleccionar cuadre para colaborar
            (() => {
              const miId = empleadoActual?.id || usuarioActual?.id || "";
              // 🔹 FILTRAR: Solo cuadres donde YO soy el colaborador asignado
              const cuadresDisponiblesParaColaborar = cuadresEnProceso.filter(c => 
                String(c.colaboradorId) === String(miId)
              );
              
              return (
                <div>
                  <h3 style={{ marginTop: 0 }}>Cuadres asignados para colaborar</h3>
                  <p className="muted" style={{ marginBottom: 16 }}>
                    Solo puedes colaborar en cuadres donde el responsable te haya asignado como colaborador.
                  </p>
                  
                  {cuadresDisponiblesParaColaborar.length === 0 ? (
                    <div style={{
                      padding: 24,
                      textAlign: 'center',
                      backgroundColor: '#fef3c7',
                      borderRadius: 10,
                      border: '2px dashed #f59e0b'
                    }}>
                      <div style={{ fontSize: 40, marginBottom: 12 }}>🔒</div>
                      <p style={{ margin: 0, color: '#92400e', fontWeight: 600, fontSize: 14 }}>
                        No tienes cuadres asignados para colaborar
                      </p>
                      <p style={{ margin: '8px 0 0 0', color: '#a16207', fontSize: 12 }}>
                        El responsable del cuadre debe asignarte como colaborador desde su vista de cuadre.
                      </p>
                    </div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                      {cuadresDisponiblesParaColaborar.map((c) => {
                        const emp = empleados.find((e) => e.id === c.empleadoId);
                        return (
                          <div 
                            key={c.id}
                            style={{
                              display: 'flex',
                              justifyContent: 'space-between',
                              alignItems: 'center',
                              padding: '14px 18px',
                              backgroundColor: '#f0fdf4',
                              borderRadius: '10px',
                              border: '2px solid #22c55e'
                            }}
                          >
                            <div>
                              <div style={{ fontWeight: 600, fontSize: 14, display: 'flex', alignItems: 'center', gap: 6 }}>
                                <span style={{ color: '#22c55e' }}>✓</span>
                                {c.fecha} - {c.sede}
                              </div>
                              <div style={{ fontSize: 12, color: '#64748b' }}>
                                Responsable: {emp?.nombre || 'Sin asignar'}
                              </div>
                            </div>
                            <button
                              onClick={async () => {
                                setColaboradorSincronizando(true);
                                try {
                                  const { data, error } = await supabase
                                    .from("cuadres_diarios")
                                    .select("*")
                                    .eq("id", c.id)
                                    .maybeSingle();
                                  
                                  if (error) throw error;
                                  
                                  if (data) {
                                    const cuadreActualizado = mapearRowCuadreDesdeSupabase(data);
                                    setColaboradorCuadre(cuadreActualizado);
                                    setColaboradorCuadreId(c.id);
                                    setCuadres(prev => prev.map(cuadre => 
                                      cuadre.id === c.id ? cuadreActualizado : cuadre
                                    ));
                                  }
                                } catch (e) {
                                  console.error("Error cargando cuadre:", e);
                                  alert("Error al cargar el cuadre. Intenta de nuevo.");
                                } finally {
                                  setColaboradorSincronizando(false);
                                }
                              }}
                              style={{
                                padding: '10px 20px',
                                background: 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)',
                                color: 'white',
                                border: 'none',
                                borderRadius: '8px',
                                fontWeight: 600,
                                cursor: 'pointer'
                              }}
                            >
                              🚀 Colaborar
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()
          ) : (
            // Vista de colaboración activa
            <div>
              {colaboradorSincronizando && (
                <div style={{
                  padding: 12,
                  backgroundColor: '#fef3c7',
                  borderRadius: 8,
                  marginBottom: 16,
                  textAlign: 'center'
                }}>
                  ⏳ Sincronizando...
                </div>
              )}
              
              {/* Header con info del cuadre */}
              <div style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                marginBottom: 20,
                padding: '12px 16px',
                backgroundColor: '#f1f5f9',
                borderRadius: 10
              }}>
                <div>
                  <div style={{ fontWeight: 600, fontSize: 15 }}>
                    {colaboradorCuadre?.fecha} - {colaboradorCuadre?.sede}
                  </div>
                  <div style={{ fontSize: 12, color: '#64748b' }}>
                    Responsable: {empleados.find(e => e.id === colaboradorCuadre?.empleadoId)?.nombre || 'Sin asignar'}
                  </div>
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    onClick={async () => {
                      setColaboradorSincronizando(true);
                      try {
                        const { data, error } = await supabase
                          .from("cuadres_diarios")
                          .select("*")
                          .eq("id", colaboradorCuadreId)
                          .maybeSingle();
                        
                        if (error) throw error;
                        
                        if (data) {
                          const cuadreActualizado = mapearRowCuadreDesdeSupabase(data);
                          setColaboradorCuadre(cuadreActualizado);
                          setCuadres(prev => prev.map(c => 
                            c.id === colaboradorCuadreId ? cuadreActualizado : c
                          ));
                        }
                      } catch (e) {
                        console.error("Error sincronizando:", e);
                      } finally {
                        setColaboradorSincronizando(false);
                      }
                    }}
                    style={{
                      padding: '8px 16px',
                      backgroundColor: '#10b981',
                      color: 'white',
                      border: 'none',
                      borderRadius: 6,
                      fontWeight: 600,
                      cursor: 'pointer',
                      fontSize: 13
                    }}
                  >
                    🔄 Sincronizar
                  </button>
                  <button
                    onClick={() => {
                      setColaboradorCuadreId(null);
                      setColaboradorCuadre(null);
                    }}
                    style={{
                      padding: '8px 16px',
                      backgroundColor: '#ef4444',
                      color: 'white',
                      border: 'none',
                      borderRadius: 6,
                      fontWeight: 600,
                      cursor: 'pointer',
                      fontSize: 13
                    }}
                  >
                    ✕ Salir
                  </button>
                </div>
              </div>
              
              {/* Contenedor de Domicilios y Transferencias en dos columnas */}
              {colaboradorCuadre && (
                <div style={{ 
                  display: 'grid', 
                  gridTemplateColumns: '1fr 1fr', 
                  gap: '24px',
                  alignItems: 'start'
                }}>
                  <CuadroDomicilios
                    domicilios={colaboradorCuadre.domicilios || []}
                    onChange={(domicilios) => {
                      // Actualizar localmente
                      setColaboradorCuadre(prev => ({ ...prev, domicilios }));
                      // Enviar actualización parcial
                      actualizarCuadreParcial(colaboradorCuadreId, 'domicilios', domicilios);
                    }}
                    disabled={false}
                    bloquearFila={(filaId) => bloquearFila('domicilios', filaId)}
                    desbloquearFila={(filaId) => desbloquearFila('domicilios', filaId)}
                    filaEstaBloqueadaPorOtro={(filaId) => filaEstaBloqueadaPorOtro('domicilios', filaId)}
                    fecha={colaboradorCuadre.fecha}
                    sede={colaboradorCuadre.sede}
                    transferencias={colaboradorCuadre.transfer || []}
                  />
 
                  <CuadroTransfer
                    transfer={colaboradorCuadre.transfer || []}
                    onChange={(transfer) => {
                      // Actualizar localmente
                      setColaboradorCuadre(prev => ({ ...prev, transfer }));
                      // Enviar actualización parcial
                      actualizarCuadreParcial(colaboradorCuadreId, 'transfer', transfer);
                    }}
                    disabled={false}
                    bloquearFila={(filaId) => bloquearFila('transfer', filaId)}
                    desbloquearFila={(filaId) => desbloquearFila('transfer', filaId)}
                    filaEstaBloqueadaPorOtro={(filaId) => filaEstaBloqueadaPorOtro('transfer', filaId)}
                    fecha={colaboradorCuadre.fecha}
                    sede={colaboradorCuadre.sede}
                  />
                </div>
              )}
              
              {/* Indicador de modo colaborador */}
              <div style={{
                marginTop: 20,
                padding: 12,
                backgroundColor: '#ede9fe',
                borderRadius: 8,
                border: '1px solid #c4b5fd',
                fontSize: 12,
                color: '#5b21b6',
                textAlign: 'center'
              }}>
                ℹ️ Los cambios se sincronizan automáticamente con el usuario principal sin conflictos
              </div>
            </div>
          )}
        </div>
      )}
 
      {modo === "crear" && tienePermiso("admin_cuadre_abrir") && !modoColaborador && (
        <>
          {cuadresEnProceso.length > 0 && (
            <div className="card" style={{ marginBottom: 12 }}>
              <h2>Cuadres en proceso</h2>
              <p className="muted">
                {esGerente 
                  ? "Estos cuadres aún no han sido cerrados. Puedes retomarlos o eliminarlos."
                  : "Puedes ver todos los cuadres en proceso. Si otro usuario tiene uno abierto, puedes solicitar acceso."
                }
              </p>
              <table className="table table-small">
                <thead>
                  <tr>
                    <th>Fecha</th>
                    <th>Sede</th>
                    <th>Empleado</th>
                    <th>Estado</th>
                    <th>Acciones</th>
                  </tr>
                </thead>
                <tbody>
                  {cuadresEnProceso
                    .map((c) => {
                    const emp = empleados.find((e) => e.id === c.empleadoId);
                    const miId = empleadoActual?.id || usuarioActual?.id || "";
                    const esMiCuadre = String(c.empleadoId) === String(miId);
                    const tieneAccesoAprobado = cuadresConAccesoAprobado.includes(String(c.id));
                    
                    // Verificar estrictamente si es gerente (doble verificación)
                    const perfilActual = (empleadoActual?.perfil || usuarioActual?.perfil || usuarioActual?.rol || "").toString().toUpperCase();
                    const esRealmenteGerente = esGerente && (
                      perfilActual.includes("GERENCIA") || 
                      perfilActual.includes("GERENTE") || 
                      perfilActual.includes("ADMIN") ||
                      perfilActual.includes("SUPERVISOR") ||
                      perfilActual.includes("COORDINADOR") ||
                      perfilActual === "SUPER_ADMIN"
                    );
                    
                    // Solo puede retomar si: es gerente REAL, es su cuadre, o tiene acceso aprobado
                    const puedeRetomar = esRealmenteGerente || esMiCuadre || tieneAccesoAprobado;
                    const puedeBorrar = esRealmenteGerente; // Solo gerentes REALES pueden borrar
                    return (
                      <tr key={c.id} style={{ backgroundColor: esMiCuadre ? '#f0fdf4' : tieneAccesoAprobado ? '#eff6ff' : 'transparent' }}>
                        <td>{c.fecha}</td>
                        <td>{c.sede}</td>
                        <td>
                          {emp ? emp.nombre : "—"}
                          {esMiCuadre && <span style={{ marginLeft: 4, fontSize: 10, color: '#16a34a' }}>(Tuyo)</span>}
                          {tieneAccesoAprobado && !esMiCuadre && <span style={{ marginLeft: 4, fontSize: 10, color: '#2563eb' }}>(Acceso aprobado)</span>}
                        </td>
                        <td>
                          <span className="chip-borrador">
                            {c.estado === "final" ? "Final" : "En proceso"}
                          </span>
                        </td>
                        <td>
                          {puedeRetomar ? (
                            <Button
                              variant="outline"
                              style={tieneAccesoAprobado && !esMiCuadre ? { backgroundColor: '#10b981', color: 'white', border: 'none' } : {}}
                              onClick={() => handleAbrirCuadre(c)}
                            >
                              {tieneAccesoAprobado && !esMiCuadre ? '✅ Retomar (Aprobado)' : 'Retomar'}
                            </Button>
                          ) : (
                            <Button
                              variant="outline"
                              style={{ backgroundColor: '#3b82f6', color: 'white', border: 'none' }}
                              onClick={() => {
                                // Mostrar directamente el modal de solicitud
                                setCuadreBloqueadoInfo({
                                  cuadre: c,
                                  bloqueo: {
                                    usuario_id: c.empleadoId,
                                    usuario_nombre: emp?.nombre || "Otro usuario",
                                    bloqueado_en: new Date().toISOString()
                                  }
                                });
                                setMostrarModalSolicitud(true);
                                setSolicitudEnviada(false);
                              }}
                            >
                              🔓 Solicitar acceso
                            </Button>
                          )}
                          {esRealmenteGerente && (
                            <Button
                              variant="outline"
                              style={{ marginLeft: 4, backgroundColor: '#fbbf24', color: '#1a1a2e', border: 'none', fontWeight: 'normal', fontSize: 13 }}
                              onClick={() => setCuadreEditando({ ...c })}
                            >
                              ✏️ Modificar
                            </Button>
                          )}
                          {esRealmenteGerente && (
                            <Button
                              variant="outline"
                              style={{ marginLeft: 4, backgroundColor: '#8b5cf6', color: 'white', border: 'none', fontWeight: 'normal', fontSize: 13 }}
                              onClick={() => handleGestionarAccesos(c)}
                            >
                              👥 Accesos
                            </Button>
                          )}
                          {(esMiCuadre || esRealmenteGerente) && (
                            <Button
                              variant="outline"
                              style={{ 
                                marginLeft: 4, 
                                backgroundColor: c.colaboradorId ? '#10b981' : '#6366f1', 
                                color: 'white', 
                                border: 'none', 
                                fontWeight: 'normal', 
                                fontSize: 13 
                              }}
                              onClick={() => setCuadreAsignarColaborador(c)}
                            >
                              👥👥 {c.colaboradorId ? 'Colaborador ✓' : 'Colaborador'}
                            </Button>
                          )}
                          {puedeBorrar && !c.fueReabierto && (
                            <Button
                              variant="outline"
                              style={{ marginLeft: 4, backgroundColor: '#dc2626', color: 'white', border: 'none', fontWeight: 'normal', fontSize: 13 }}
                              onClick={() => borrarCuadre(c.id)}
                            >
                              Borrar
                            </Button>
                          )}
                          {c.fueReabierto && (
                            <span style={{ marginLeft: 8, fontSize: 11, color: '#dc2626', fontWeight: 'bold' }}>
                              🔒 Reabierto (no borrable)
                            </span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {/* Modal para modificar cuadre en proceso */}
          {cuadreEditando && (
            <div style={{
              position: 'fixed',
              inset: 0,
              background: 'rgba(0,0,0,0.5)',
              zIndex: 9999,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: 16
            }}>
              <div style={{
                background: 'white',
                borderRadius: 12,
                maxWidth: 500,
                width: '100%',
                maxHeight: '80vh',
                overflow: 'auto',
                padding: 24,
                boxShadow: '0 8px 32px rgba(0,0,0,0.3)'
              }}>
                <h2 style={{ marginBottom: 20, color: '#ff6b35' }}>✏️ Modificar Cuadre en Proceso</h2>
                
                {/* Fecha */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Fecha:</label>
                  <input
                    type="date"
                    value={cuadreEditando.fecha || ''}
                    onChange={(e) => setCuadreEditando({ ...cuadreEditando, fecha: e.target.value })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                  />
                </div>

                {/* Sede */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Sede:</label>
                  <select
                    value={cuadreEditando.sede || ''}
                    onChange={(e) => setCuadreEditando({ ...cuadreEditando, sede: e.target.value })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                  >
                    <option value="">Selecciona una sede</option>
                    {sedes.map((s) => {
                      const sedeNombre = typeof s === 'string' ? s : s.nombre;
                      return (
                        <option key={sedeNombre} value={sedeNombre}>{sedeNombre}</option>
                      );
                    })}
                  </select>
                </div>

                {/* Empleado */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Empleado Responsable:</label>
                  <select
                    value={cuadreEditando.empleadoId || ''}
                    onChange={(e) => setCuadreEditando({ ...cuadreEditando, empleadoId: e.target.value })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                  >
                    <option value="">Selecciona un empleado</option>
                    {[...(empleados || [])].sort((a, b) => ((a.nombre || "").localeCompare((b.nombre || ""), 'es', { sensitivity: 'base' }))).map((emp) => (
                      <option key={emp.id} value={emp.id}>{emp.nombre}</option>
                    ))}
                  </select>
                </div>

                {/* Valor Inicial */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Valor Inicial ($):</label>
                  <input
                    type="number"
                    value={cuadreEditando.valorInicial || ''}
                    onChange={(e) => setCuadreEditando({ ...cuadreEditando, valorInicial: parseFloat(e.target.value) || 0 })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                    placeholder="0"
                  />
                </div>

                {/* Ventas - Venta Efectivo */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Venta Efectivo ($):</label>
                  <input
                    type="number"
                    value={cuadreEditando.ventas?.ventaEfectivo || ''}
                    onChange={(e) => setCuadreEditando({ 
                      ...cuadreEditando, 
                      ventas: { ...cuadreEditando.ventas, ventaEfectivo: e.target.value }
                    })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                    placeholder="0"
                  />
                </div>

                {/* Ventas - Sobrante */}
                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 600, fontSize: 14 }}>Sobrante ($):</label>
                  <input
                    type="number"
                    value={cuadreEditando.ventas?.sobrante || ''}
                    onChange={(e) => setCuadreEditando({ 
                      ...cuadreEditando, 
                      ventas: { ...cuadreEditando.ventas, sobrante: e.target.value }
                    })}
                    style={{ width: '100%', padding: '10px 12px', border: '2px solid #e2e8f0', borderRadius: 8, fontSize: 14 }}
                    placeholder="0"
                  />
                </div>

                {/* Botones */}
                <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', marginTop: 24 }}>
                  <button
                    onClick={() => setCuadreEditando(null)}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#94a3b8',
                      color: 'white',
                      border: 'none',
                      borderRadius: 8,
                      cursor: 'pointer',
                      fontWeight: 600
                    }}
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={guardarEdicionCuadre}
                    style={{
                      padding: '10px 20px',
                      background: 'linear-gradient(135deg, #ff6b35 0%, #ffc53d 100%)',
                      color: 'white',
                      border: 'none',
                      borderRadius: 8,
                      cursor: 'pointer',
                      fontWeight: 600
                    }}
                  >
                    💾 Guardar Cambios
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* 🔹 MODAL PARA ASIGNAR COLABORADOR */}
          {cuadreAsignarColaborador && (
            <div style={{
              position: 'fixed',
              inset: 0,
              background: 'rgba(0,0,0,0.6)',
              zIndex: 9999,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: 16
            }}>
              <div style={{
                background: 'white',
                borderRadius: 16,
                maxWidth: 500,
                width: '100%',
                overflow: 'hidden',
                boxShadow: '0 25px 50px -12px rgba(0,0,0,0.4)'
              }}>
                {/* Header */}
                <div style={{
                  background: 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)',
                  padding: '20px 24px',
                  color: 'white'
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                    <span style={{ fontSize: 32 }}>👥👥</span>
                    <div>
                      <h3 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>Asignar Colaborador</h3>
                      <p style={{ margin: 0, fontSize: 13, opacity: 0.9 }}>
                        {cuadreAsignarColaborador.fecha} - {cuadreAsignarColaborador.sede}
                      </p>
                    </div>
                  </div>
                </div>
                
                {/* Body */}
                <div style={{ padding: 24 }}>
                  <p style={{ margin: '0 0 16px 0', color: '#64748b', fontSize: 14 }}>
                    El colaborador solo podrá editar <strong>Transferencias</strong> y <strong>Domicilios</strong>.
                    Verá este cuadre en su "Modo Colaborador".
                  </p>
                  
                  {cuadreAsignarColaborador.colaboradorId ? (
                    // Ya hay colaborador
                    <div style={{
                      padding: 16,
                      backgroundColor: '#d1fae5',
                      borderRadius: 12,
                      border: '2px solid #22c55e'
                    }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div style={{ fontWeight: 700, color: '#166534', fontSize: 15 }}>
                            ✓ {cuadreAsignarColaborador.colaboradorNombre}
                          </div>
                          <div style={{ fontSize: 12, color: '#15803d', marginTop: 4 }}>
                            Actualmente asignado como colaborador
                          </div>
                        </div>
                        <button
                          onClick={() => {
                            if (window.confirm(`¿Quitar a ${cuadreAsignarColaborador.colaboradorNombre} como colaborador?`)) {
                              actualizarCuadre(cuadreAsignarColaborador.id, { 
                                colaboradorId: null, 
                                colaboradorNombre: null 
                              });
                              setCuadreAsignarColaborador(prev => prev ? {...prev, colaboradorId: null, colaboradorNombre: null} : null);
                            }
                          }}
                          style={{
                            padding: '10px 18px',
                            backgroundColor: '#ef4444',
                            color: 'white',
                            border: 'none',
                            borderRadius: 8,
                            fontWeight: 600,
                            cursor: 'pointer',
                            fontSize: 13
                          }}
                        >
                          ✕ Quitar Colaborador
                        </button>
                      </div>
                    </div>
                  ) : (
                    // Seleccionar colaborador
                    <div>
                      <label style={{ display: 'block', marginBottom: 8, fontWeight: 600, color: '#374151', fontSize: 14 }}>
                        Seleccionar empleado:
                      </label>
                      <select
                        id="selectColaboradorModal"
                        style={{
                          width: '100%',
                          padding: '12px 14px',
                          border: '2px solid #c4b5fd',
                          borderRadius: 10,
                          fontSize: 15,
                          backgroundColor: 'white'
                        }}
                        defaultValue=""
                      >
                        <option value="">-- Seleccionar empleado --</option>
                        {empleados
                          .filter(e => String(e.id) !== String(cuadreAsignarColaborador.empleadoId))
                          .map(e => (
                            <option key={e.id} value={e.id}>{e.nombre}</option>
                          ))
                        }
                      </select>
                      
                      <button
                        onClick={() => {
                          const select = document.getElementById('selectColaboradorModal');
                          const selectedId = select?.value;
                          if (!selectedId) {
                            alert("⚠️ Selecciona un empleado primero");
                            return;
                          }
                          const emp = empleados.find(e => String(e.id) === String(selectedId));
                          if (emp) {
                            actualizarCuadre(cuadreAsignarColaborador.id, { 
                              colaboradorId: emp.id, 
                              colaboradorNombre: emp.nombre 
                            });
                            setCuadreAsignarColaborador(prev => prev ? {...prev, colaboradorId: emp.id, colaboradorNombre: emp.nombre} : null);
                            alert(`✅ ${emp.nombre} ahora puede colaborar en este cuadre.\n\nEl empleado verá este cuadre en su "Modo Colaborador".`);
                          }
                        }}
                        style={{
                          marginTop: 16,
                          width: '100%',
                          padding: '14px',
                          background: 'linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%)',
                          color: 'white',
                          border: 'none',
                          borderRadius: 10,
                          fontWeight: 700,
                          cursor: 'pointer',
                          fontSize: 15,
                          boxShadow: '0 4px 12px rgba(139, 92, 246, 0.4)'
                        }}
                      >
                        ✓ Asignar Colaborador
                      </button>
                    </div>
                  )}
                </div>
                
                {/* Footer */}
                <div style={{ 
                  padding: '16px 24px', 
                  borderTop: '1px solid #e2e8f0',
                  display: 'flex',
                  justifyContent: 'flex-end'
                }}>
                  <button
                    onClick={() => setCuadreAsignarColaborador(null)}
                    style={{
                      padding: '10px 24px',
                      backgroundColor: '#94a3b8',
                      color: 'white',
                      border: 'none',
                      borderRadius: 8,
                      fontWeight: 600,
                      cursor: 'pointer',
                      fontSize: 14
                    }}
                  >
                    Cerrar
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Modal para gestionar accesos a cuadres (solo gerentes) */}
          {mostrarModalGestionAccesos && cuadreGestionAccesos && (
            <div style={{
              position: 'fixed',
              inset: 0,
              background: 'rgba(0,0,0,0.5)',
              zIndex: 9999,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: 16
            }}>
              <div style={{
                background: 'white',
                borderRadius: 12,
                maxWidth: 500,
                width: '100%',
                maxHeight: '80vh',
                overflow: 'auto',
                padding: 24,
                boxShadow: '0 8px 32px rgba(0,0,0,0.3)'
              }}>
                <h2 style={{ marginBottom: 8, color: '#6b21a8' }}>👥 Gestión de Accesos</h2>
                <p style={{ marginBottom: 20, color: '#64748b', fontSize: 14 }}>
                  Cuadre: {cuadreGestionAccesos.sede} - {cuadreGestionAccesos.fecha}
                </p>
                
                {cargandoAccesos ? (
                  <div style={{ textAlign: 'center', padding: 40 }}>
                    <div style={{ fontSize: 32 }}>⏳</div>
                    <p>Cargando accesos...</p>
                  </div>
                ) : accesosDelCuadre.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: 40, color: '#64748b' }}>
                    <div style={{ fontSize: 48, marginBottom: 12 }}>📭</div>
                    <p>No hay usuarios con acceso a este cuadre</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    {accesosDelCuadre.map((acceso) => (
                      <div 
                        key={acceso.id} 
                        style={{ 
                          padding: 16, 
                          background: acceso.accesoRevocado ? '#fef2f2' : (acceso.esPropietario ? '#fef3c7' : '#f8fafc'), 
                          borderRadius: 8, 
                          border: acceso.accesoRevocado ? '2px solid #dc2626' : (acceso.esPropietario ? '2px solid #f59e0b' : '1px solid #e2e8f0'),
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'center'
                        }}
                      >
                        <div>
                          <div style={{ fontWeight: 600, color: '#1e293b', display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                            {acceso.solicitante_nombre || 'Usuario desconocido'}
                            {acceso.esPropietario && (
                              <span style={{ 
                                fontSize: 10, 
                                backgroundColor: '#f59e0b', 
                                color: 'white', 
                                padding: '2px 6px', 
                                borderRadius: 4,
                                fontWeight: 600
                              }}>
                                ABRIÓ CUADRE
                              </span>
                            )}
                            {acceso.accesoRevocado && (
                              <span style={{ 
                                fontSize: 10, 
                                backgroundColor: '#dc2626', 
                                color: 'white', 
                                padding: '2px 6px', 
                                borderRadius: 4,
                                fontWeight: 600
                              }}>
                                SIN ACCESO
                              </span>
                            )}
                          </div>
                          <div style={{ fontSize: 12, color: '#64748b' }}>
                            {acceso.esPropietario 
                              ? `Creó el cuadre el ${acceso.fecha_solicitud}`
                              : acceso.respondido_en 
                                ? `Aprobado: ${new Date(acceso.respondido_en).toLocaleString()}`
                                : `Solicitud: ${new Date(acceso.fecha_solicitud).toLocaleString()}`
                            }
                          </div>
                          {!acceso.esPropietario && acceso.respondido_por_nombre && (
                            <div style={{ fontSize: 11, color: '#94a3b8' }}>
                              Por: {acceso.respondido_por_nombre}
                            </div>
                          )}
                        </div>
                        {acceso.accesoRevocado ? (
                          <button
                            onClick={() => handleRestaurarAcceso(acceso)}
                            style={{
                              padding: '8px 14px',
                              backgroundColor: '#16a34a',
                              color: 'white',
                              border: 'none',
                              borderRadius: 6,
                              cursor: 'pointer',
                              fontWeight: 600,
                              fontSize: 13
                            }}
                          >
                            ✅ Restaurar
                          </button>
                        ) : (
                          <button
                            onClick={() => handleRevocarAcceso(acceso)}
                            style={{
                              padding: '8px 14px',
                              backgroundColor: '#dc2626',
                              color: 'white',
                              border: 'none',
                              borderRadius: 6,
                              cursor: 'pointer',
                              fontWeight: 600,
                              fontSize: 13
                            }}
                          >
                            ❌ Revocar
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}

                <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 24 }}>
                  <button
                    onClick={() => {
                      setMostrarModalGestionAccesos(false);
                      setCuadreGestionAccesos(null);
                      setAccesosDelCuadre([]);
                    }}
                    style={{
                      padding: '10px 24px',
                      backgroundColor: '#94a3b8',
                      color: 'white',
                      border: 'none',
                      borderRadius: 8,
                      cursor: 'pointer',
                      fontWeight: 600
                    }}
                  >
                    Cerrar
                  </button>
                </div>
              </div>
            </div>
          )}
 
          <CrearCuadre
            sedes={sedes}
            empleados={empleados}
            cuadreActivo={cuadreActivo}
            setCuadreActivoId={setCuadreActivoId}
            crearOBuscarBorrador={crearOBuscarBorrador}
            actualizarCuadre={actualizarCuadre}
            actualizarCuadreParcial={actualizarCuadreParcial}
            cuadres={cuadres}
            guardarFinal={guardarFinal}
            guardarComentario={guardarComentario}
            realizarPrecierre={realizarPrecierre}
            usuarioActual={usuarioActual}
            empleadoActual={empleadoActual}
            esGerente={esGerente}
            tienePermiso={tienePermiso}
            accesosDelCuadre={accesosDelCuadre}
            usuariosActivosEnCuadre={usuariosActivosEnCuadre}
            ultimaActualizacionRemota={ultimaActualizacionRemota}
            filtroEmpresa={filtroEmpresa}
            bloquearFila={bloquearFila}
            desbloquearFila={desbloquearFila}
            filaEstaBloqueadaPorOtro={filaEstaBloqueadaPorOtro}
          />
        </>
      )}
 
      {modo === "consultar" && tienePermiso("admin_cuadre_consultar") && !modoColaborador && (
        <>
          <ConsultasCuadres
            sedes={sedes}
            empleados={empleados}
            cuadres={cuadres}
            setCuadreActivoId={setCuadreActivoId}
            esGerente={esGerente}
            onGestionarAccesos={handleGestionarAccesos}
            onReabrirCuadre={reabrirCuadre}
            tienePermiso={tienePermiso}
          />
 
          {cuadreActivo && (
            <div style={{ marginTop: "16px" }}>
              <CuadreSoloLectura
                cuadre={cuadreActivo}
                empleados={empleados}
                onGuardarComentario={guardarComentario}
                tienePermiso={tienePermiso}
              />
            </div>
          )}
        </>
      )}
      
      {/* 🔄 BOTÓN FLOTANTE DE SINCRONIZACIÓN */}
      {cuadreActivoId && (
        <div style={{
          position: "fixed",
          bottom: "20px",
          right: "20px",
          zIndex: 9999,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end",
          gap: "8px"
        }}>
          {/* Indicador de usuarios activos */}
          {usuariosActivosEnCuadre.length > 0 && (
            <div style={{
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              color: "white",
              padding: "8px 14px",
              borderRadius: "20px",
              fontSize: "12px",
              fontWeight: "600",
              boxShadow: "0 4px 15px rgba(102, 126, 234, 0.4)",
              display: "flex",
              alignItems: "center",
              gap: "6px"
            }}>
              <span style={{ fontSize: "14px" }}>👥</span>
              {usuariosActivosEnCuadre.length} usuario{usuariosActivosEnCuadre.length > 1 ? "s" : ""} trabajando
            </div>
          )}
          
          {/* Indicador de última sincronización */}
          <div style={{
            background: "rgba(0,0,0,0.75)",
            color: "#fff",
            padding: "6px 12px",
            borderRadius: "16px",
            fontSize: "11px",
            display: "flex",
            alignItems: "center",
            gap: "6px"
          }}>
            <span style={{ 
              width: "8px", 
              height: "8px", 
              borderRadius: "50%", 
              background: sincronizando ? "#ffc107" : "#4caf50",
              animation: sincronizando ? "pulse 1s infinite" : "none"
            }}></span>
            {sincronizando ? "Sincronizando..." : 
              ultimaSincronizacion 
                ? `Sync: ${Math.round((Date.now() - ultimaSincronizacion.getTime()) / 1000)}s`
                : "Auto-sync: 2s"
            }
          </div>
          
          {/* Botón de sincronización manual */}
          <button
            onClick={() => sincronizarCuadreActivo(true)}
            disabled={sincronizando}
            style={{
              width: "56px",
              height: "56px",
              borderRadius: "50%",
              border: "none",
              background: sincronizando 
                ? "linear-gradient(135deg, #ffc107 0%, #ff9800 100%)"
                : "linear-gradient(135deg, #4CAF50 0%, #45a049 100%)",
              color: "white",
              fontSize: "24px",
              cursor: sincronizando ? "wait" : "pointer",
              boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "all 0.3s ease",
              animation: sincronizando ? "spin 1s linear infinite" : "none"
            }}
            title="Sincronizar ahora"
          >
            🔄
          </button>
        </div>
      )}
      
      {/* Estilos para animaciones */}
      <style>{`
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.5; }
        }
        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

// ====================== ROOT INVENTARIO ======================
export function InventarioRoot({ sedes, empleados, tienePermiso = () => true, filtroEmpresa = null, usuarioActual = null, empleadoActual = null }) {
  const [inventarios, setInventarios] = useState(() => loadInventarios());
  // Determinar modo inicial según permisos
  const modoInicial = tienePermiso("admin_inventario_crear") ? "crear" : 
                      tienePermiso("admin_inventario_consultar") ? "consultar" : "crear";
  const [modo, setModo] = useState(modoInicial); // "crear" | "consultar"
  const [inventarioActivoId, setInventarioActivoId] = useState(null);
  const [cargandoInventarios, setCargandoInventarios] = useState(false);
  const [sincronizandoInventario, setSincronizandoInventario] = useState(false);

  const [cabecera, setCabecera] = useState(() => ({
    fecha: toISO(new Date()),
    sede: sedes && sedes.length ? sedes[0] : "",
    encargadoId: "",
    personalCocina: "",
    novedades: "",
  }));

  const [lineasDiario, setLineasDiario] = useState(() =>
    PRODUCTOS_INVENTARIO_DIARIO.map((nombre) => ({
      id: uid(),
      producto: nombre,
      existencias: "",
      solicitar: "No",
      cantidad: "",
    }))
  );

  const [adicionales, setAdicionales] = useState([]);
  const [productoAdicional, setProductoAdicional] = useState("");

  useEffect(() => {
    saveInventarios(inventarios);
  }, [inventarios]);

  useEffect(() => {
    let activo = true;
    setCargandoInventarios(true);
    console.log("🔄 Cargando inventarios desde Supabase, filtroEmpresa:", filtroEmpresa);
    cargarInventariosDeSupabase(filtroEmpresa)
      .then((lista) => {
        if (!activo) return;
        console.log("✅ Inventarios cargados de Supabase:", lista.length);
        console.log("📋 Inventarios abiertos en Supabase:", lista.filter(i => !i.cerrado).length);
        console.log("📋 Inventarios cerrados en Supabase:", lista.filter(i => i.cerrado).length);
        
        setInventarios((prev) => {
          const localesSinDuplicados = (prev || []).filter(
            (loc) => !lista.some((remoto) => remoto.id === loc.id)
          );
          console.log("💾 Inventarios locales:", (prev || []).length);
          console.log("🔀 Inventarios locales sin duplicados:", localesSinDuplicados.length);
          
          // NUEVO: Sincronizar inventarios locales que no están en Supabase
          if (localesSinDuplicados.length > 0) {
            console.log("🔄 Sincronizando", localesSinDuplicados.length, "inventarios locales a Supabase...");
            localesSinDuplicados.forEach((inv) => {
              guardarInventarioEnSupabase(inv, filtroEmpresa).then((resultado) => {
                if (resultado) {
                  console.log("✅ Inventario local sincronizado a Supabase:", resultado.id);
                } else {
                  console.error("❌ Error sincronizando inventario local:", inv.id);
                }
              }).catch((e) => {
                console.error("❌ Error sincronizando inventario local:", inv.id, e);
              });
            });
          }
          
          const resultado = [...lista, ...localesSinDuplicados];
          console.log("📊 Total inventarios después de merge:", resultado.length);
          return resultado;
        });
      })
      .catch((e) => {
        console.error("❌ No se pudieron cargar inventarios de Supabase", e);
      })
      .finally(() => {
        if (activo) setCargandoInventarios(false);
      });

    return () => {
      activo = false;
    };
  }, [filtroEmpresa]);

  const inventarioActivo = useMemo(
    () => inventarios.find((i) => i.id === inventarioActivoId) || null,
    [inventarios, inventarioActivoId]
  );

  const estaCerrado = !!(inventarioActivo && inventarioActivo.cerrado);

  // Cuando selecciono un inventario desde "consultar", cargo sus datos
  useEffect(() => {
    if (!inventarioActivo) return;

    setCabecera({
      fecha: inventarioActivo.fecha || "",
      sede: inventarioActivo.sede || "",
      encargadoId: inventarioActivo.encargadoId || "",
      personalCocina: inventarioActivo.personalCocina || "",
      novedades: inventarioActivo.novedades || "",
    });

    const lineasBase = inventarioActivo.lineas || [];
    const baseDiario = PRODUCTOS_INVENTARIO_DIARIO.map((nombre) => {
      const encontrada = lineasBase.find((l) => l.producto === nombre) || {};
      return {
        id: encontrada.id || uid(),
        producto: nombre,
        existencias: encontrada.existencias || "",
        solicitar: encontrada.solicitar || "No",
        cantidad: encontrada.cantidad || "",
      };
    });

    const adicionalesGuardados = lineasBase.filter(
      (l) => !PRODUCTOS_INVENTARIO_DIARIO.includes(l.producto)
    );

    setLineasDiario(baseDiario);
    setAdicionales(
      adicionalesGuardados.map((l) => ({
        id: l.id || uid(),
        producto: l.producto,
        existencias: l.existencias || "",
        solicitar: l.solicitar || "No",
        cantidad: l.cantidad || "",
      }))
    );
  }, [inventarioActivo]);

  // Crear inventario nuevo (limpiar formulario)
  function handleNuevo() {
    setInventarioActivoId(null);
    setCabecera({
      fecha: toISO(new Date()),
      sede: sedes && sedes.length ? sedes[0] : "",
      encargadoId: "",
      personalCocina: "",
      novedades: "",
    });
    setLineasDiario(
      PRODUCTOS_INVENTARIO_DIARIO.map((nombre) => ({
        id: uid(),
        producto: nombre,
        existencias: "",
        solicitar: "No",
        cantidad: "",
      }))
    );
    setAdicionales([]);
    setProductoAdicional("");
  }

  // Cambio de cabecera
  function updateCabecera(campo, valor) {
    setCabecera((prev) => ({ ...prev, [campo]: valor }));
  }

  // Cambio en una línea (diario o adicional)
  function updateLinea(lista, setLista, id, campo, valor) {
    setLista((prev) =>
      prev.map((l) =>
        l.id === id
          ? {
              ...l,
              [campo]: valor,
              ...(campo === "solicitar" && valor !== "Sí"
                ? { cantidad: "" }
                : {}),
            }
          : l
      )
    );
  }

  // Agregar producto adicional
  function handleAgregarAdicional() {
    if (!productoAdicional) {
      alert("Selecciona un producto adicional.");
      return;
    }
    if (
      lineasDiario.some((l) => l.producto === productoAdicional) ||
      adicionales.some((l) => l.producto === productoAdicional)
    ) {
      alert("Ese producto ya está incluido en el inventario.");
      return;
    }

    const nuevo = {
      id: uid(),
      producto: productoAdicional,
      existencias: "",
      solicitar: "No",
      cantidad: "",
    };
    setAdicionales((prev) => [...prev, nuevo]);
    setProductoAdicional("");
  }

  // Validar que todo el INVENTARIO DIARIO está diligenciado sin espacios en blanco
  function validarInventario() {
    const { fecha, sede, encargadoId, personalCocina, novedades } = cabecera;

    if (!fecha || !sede || !encargadoId || !personalCocina || !novedades) {
      alert(
        "Fecha, sede, encargado, personal en cocina y novedades son obligatorios."
      );
      return false;
    }

    const validarLinea = (l) => {
      if (!l.existencias) return false;
      if (!l.solicitar) return false;
      if (l.solicitar === "Sí" && !l.cantidad) return false;
      return true;
    };

    // INVENTARIO DIARIO obligatorio sin espacios en blanco
    for (const l of lineasDiario) {
      if (!validarLinea(l)) {
        alert(
          `En INVENTARIO DIARIO todos los campos son obligatorios. Revisa el producto "${l.producto}".`
        );
        return false;
      }
    }

    // Si hay adicionales, también validar los que el usuario haya agregado
    for (const l of adicionales) {
      if (!validarLinea(l)) {
        alert(
          `En INVENTARIO ADICIONAL todos los campos son obligatorios para los productos agregados. Revisa "${l.producto}".`
        );
        return false;
      }
    }

    return true;
  }
  function handleGuardar() {
    if (inventarioActivo && inventarioActivo.cerrado) {
      alert("Este inventario está cerrado y no se puede modificar.");
      return;
    }

    if (!validarInventario()) return;

    const lineasConCategoria = lineasDiario.map((l) => ({
      ...l,
      categoria: "diario",
    }));
    const adicionalesConCategoria = adicionales.map((l) => ({
      ...l,
      categoria: "adicional",
    }));

    const todasLineas = [...lineasConCategoria, ...adicionalesConCategoria];

    const base = {
      id: inventarioActivo ? inventarioActivo.id : uid(),
      fecha: cabecera.fecha,
      sede: cabecera.sede,
      encargadoId: cabecera.encargadoId,
      personalCocina: cabecera.personalCocina,
      novedades: cabecera.novedades,
      lineas: todasLineas,
      cerrado: inventarioActivo ? !!inventarioActivo.cerrado : false,
    };

    // Un solo inventario por fecha + sede
    const existente = inventarios.find(
      (i) =>
        i.fecha === base.fecha &&
        i.sede === base.sede &&
        i.id !== base.id
    );

    if (existente) {
      const ok = window.confirm(
        `Ya existe un inventario para la sede "${base.sede}" en la fecha ${base.fecha}. Se reemplazará por el nuevo. ¿Continuar?`
      );
      if (!ok) return;
    }

    setInventarios((prev) => {
      const sinActual = prev.filter((i) => i.id !== base.id);
      const sinDuplicados = sinActual.filter(
        (i) => !(i.fecha === base.fecha && i.sede === base.sede)
      );
      return [...sinDuplicados, base];
    });

    setInventarioActivoId(base.id);
    alert("Inventario guardado correctamente.");

    setSincronizandoInventario(true);
    guardarInventarioEnSupabase(base, filtroEmpresa)
      .then((guardado) => {
        if (!guardado) {
          alert("No se pudo sincronizar el inventario en Supabase. Intenta nuevamente.");
          return;
        }
        setInventarios((prev) =>
          prev.map((inv) => (inv.id === guardado.id ? guardado : inv))
        );
        // Limpiar el formulario después de guardar exitosamente
        handleNuevo();
      })
      .finally(() => setSincronizandoInventario(false));
  }

  function handleEliminar(id) {
    if (!window.confirm("¿Seguro que deseas eliminar este inventario?")) return;
    setInventarios((prev) => prev.filter((i) => i.id !== id));
    if (inventarioActivoId === id) {
      setInventarioActivoId(null);
      handleNuevo();
    }
    eliminarInventarioDeSupabase(id).catch((e) =>
      console.error("No se pudo eliminar inventario en Supabase", e)
    );
  }

  function handleCerrar() {
    if (!inventarioActivo) {
      alert("Primero guarda el inventario antes de cerrarlo.");
      return;
    }
  
    if (inventarioActivo.cerrado) {
      alert("Este inventario ya está cerrado.");
      return;
    }
  
    const ok = window.confirm(
      "Al cerrar el inventario ya no se podrá modificar, solo consultar o imprimir. ¿Deseas continuar?"
    );
    if (!ok) return;
  
    setInventarios((prev) =>
      prev.map((i) =>
        i.id === inventarioActivo.id ? { ...i, cerrado: true } : i
      )
    );
  
    alert("Inventario cerrado.");

    guardarInventarioEnSupabase({ ...inventarioActivo, cerrado: true }, filtroEmpresa).catch(
      (e) => console.error("No se pudo actualizar inventario cerrado en Supabase", e)
    );
  }
  
  function handleImprimir(inv) {
    if (!inv) return;

    const encargado =
      empleados.find((e) => e.id === inv.encargadoId)?.nombre || "—";

    const html = `
      <html>
        <head>
          <title>Inventario ${inv.fecha} - ${inv.sede}</title>
          <style>
            * {
              margin: 0;
              padding: 0;
              box-sizing: border-box;
            }
            body {
              font-family: 'Arial', sans-serif;
              padding: 15px;
              background: #fff;
            }
            .container {
              max-width: 900px;
              margin: 0 auto;
              background: white;
            }
            .header-section {
              border-bottom: 2px solid #1d4ed8;
              padding-bottom: 8px;
              margin-bottom: 12px;
            }
            .header-title {
              font-size: 18px;
              font-weight: bold;
              color: #1d4ed8;
              margin-bottom: 6px;
            }
            .header-info {
              display: grid;
              grid-template-columns: 1fr 1fr;
              gap: 12px;
              font-size: 11px;
              line-height: 1.5;
            }
            .info-row {
              display: flex;
              justify-content: space-between;
            }
            .info-label {
              font-weight: 600;
              color: #333;
              width: 100px;
            }
            .info-value {
              color: #555;
              flex: 1;
              text-align: left;
              padding-left: 8px;
            }
            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 10px;
              font-size: 11px;
            }
            thead {
              background: #1d4ed8;
              color: white;
              text-align: left;
            }
            th {
              padding: 8px 10px;
              font-weight: 600;
              border: none;
            }
            tbody tr {
              border-bottom: 1px solid #e2e8f0;
            }
            tbody tr:nth-child(even) {
              background: #f9fafb;
            }
            td {
              padding: 6px 10px;
              color: #333;
            }
            .col-producto {
              font-weight: 500;
            }
            .col-numero {
              text-align: center;
            }
            .col-solicitar {
              text-align: center;
            }
            .col-cantidad {
              text-align: center;
            }
            footer {
              margin-top: 16px;
              padding-top: 8px;
              border-top: 1px solid #e2e8f0;
              text-align: center;
              font-size: 9px;
              color: #999;
            }
            @media print {
              body {
                padding: 0;
              }
            }
          </style>
        </head>
        <body>
          <div class="container">
            <div class="header-section">
              <div class="header-title">INVENTARIO DIARIO</div>
              <div class="header-info">
                <div class="info-row">
                  <span class="info-label">Fecha:</span>
                  <span class="info-value">${inv.fecha}</span>
                </div>
                <div class="info-row">
                  <span class="info-label">Encargado:</span>
                  <span class="info-value">${encargado}</span>
                </div>
                <div class="info-row">
                  <span class="info-label">Sede:</span>
                  <span class="info-value">${inv.sede}</span>
                </div>
                <div class="info-row">
                  <span class="info-label">Personal:</span>
                  <span class="info-value">${inv.personalCocina || "—"}</span>
                </div>
              </div>
              ${inv.novedades ? `<div style="margin-top: 6px; padding-top: 6px; border-top: 1px solid #e5e7eb; font-size: 10px;"><strong>Novedades:</strong> ${inv.novedades}</div>` : ""}
            </div>

            <table>
              <thead>
                <tr>
                  <th style="width: 50%;">Producto</th>
                  <th style="width: 17%;">Existencias</th>
                  <th style="width: 17%;">Solicitar</th>
                  <th style="width: 16%;">Cantidad</th>
                </tr>
              </thead>
              <tbody>
                ${inv.lineas
                  .map(
                    (l) => `
                  <tr>
                    <td class="col-producto">${l.producto}</td>
                    <td class="col-numero">${l.existencias}</td>
                    <td class="col-solicitar">${l.solicitar}</td>
                    <td class="col-cantidad">${l.solicitar === "Sí" ? l.cantidad : "—"}</td>
                  </tr>
                `
                  )
                  .join("")}
              </tbody>
            </table>

            <footer>
              <p>Impreso: ${new Date().toLocaleString('es-CO')}</p>
            </footer>
          </div>
        </body>
      </html>
    `;

    const win = window.open("", "_blank");
    if (!win) return;
    win.document.write(html);
    win.document.close();
    win.focus();
    win.print();
  }


  // Filtros avanzados en "consultar"
  const [filtroSede, setFiltroSede] = useState("");
  const [filtroPeriodo, setFiltroPeriodo] = useState("semana"); // "dia" | "semana" | "mes" | "todos"
  const [filtroFechaEspecifica, setFiltroFechaEspecifica] = useState(toISO(new Date()));
  const [vistaConsulta, setVistaConsulta] = useState("lista"); // "lista" | "tarjetas" | "procesar" | "pedidos_guardados"
  
  // Estados para procesar pedidos
  const [productosSeleccionados, setProductosSeleccionados] = useState({});
  const [pedidosPorSede, setPedidosPorSede] = useState({});
  const [mostrarResumenPedido, setMostrarResumenPedido] = useState(false);
  const [novedadesPedido, setNovedadesPedido] = useState(""); // Novedades del pedido
  const [productosYaEnviados, setProductosYaEnviados] = useState(new Set()); // Productos ya enviados en pedidos anteriores
  
  // Estados para pedidos guardados
  const [pedidosGuardados, setPedidosGuardados] = useState([]);
  const [cargandoPedidos, setCargandoPedidos] = useState(false);
  
  // Cargar productos ya enviados hoy (para excluirlos de la lista)
  async function cargarProductosYaEnviados() {
    try {
      const hoy = toISO(new Date());
      const { data, error } = await supabase
        .from('pedidos_consolidados')
        .select('productos_keys')
        .gte('fecha', hoy + 'T00:00:00')
        .lte('fecha', hoy + 'T23:59:59');
      
      if (error) throw error;
      
      const enviados = new Set();
      (data || []).forEach(p => {
        (p.productos_keys || []).forEach(key => enviados.add(key));
      });
      setProductosYaEnviados(enviados);
    } catch (err) {
      console.error('Error cargando productos enviados:', err);
    }
  }
  
  // Cargar productos enviados al montar y al cambiar de vista
  React.useEffect(() => {
    if (vistaConsulta === "procesar") {
      cargarProductosYaEnviados();
    }
  }, [vistaConsulta]);
  
  // Cargar pedidos guardados
  async function cargarPedidosGuardados() {
    setCargandoPedidos(true);
    try {
      const { data, error } = await supabase
        .from('pedidos_consolidados')
        .select('*')
        .order('fecha', { ascending: false })
        .limit(50);
      if (error) throw error;
      setPedidosGuardados(data || []);
    } catch (err) {
      console.error('Error cargando pedidos:', err);
    } finally {
      setCargandoPedidos(false);
    }
  }
  
  // Cargar pedidos cuando se cambie a la vista de pedidos guardados
  useEffect(() => {
    if (vistaConsulta === "pedidos_guardados") {
      cargarPedidosGuardados();
    }
  }, [vistaConsulta]);

  // Calcular rango de fechas según período
  const rangoFechas = useMemo(() => {
    const fechaBase = new Date(filtroFechaEspecifica + "T12:00:00");
    let inicio, fin;
    
    if (filtroPeriodo === "dia") {
      inicio = fin = filtroFechaEspecifica;
    } else if (filtroPeriodo === "semana") {
      const diaSemana = fechaBase.getDay();
      const inicioSemana = new Date(fechaBase);
      inicioSemana.setDate(fechaBase.getDate() - diaSemana);
      const finSemana = new Date(inicioSemana);
      finSemana.setDate(inicioSemana.getDate() + 6);
      inicio = toISO(inicioSemana);
      fin = toISO(finSemana);
    } else if (filtroPeriodo === "mes") {
      const año = fechaBase.getFullYear();
      const mes = fechaBase.getMonth();
      inicio = toISO(new Date(año, mes, 1));
      fin = toISO(new Date(año, mes + 1, 0));
    } else {
      inicio = null;
      fin = null;
    }
    return { inicio, fin };
  }, [filtroPeriodo, filtroFechaEspecifica]);

  const inventariosFiltrados = useMemo(() => {
    let lista = [...inventarios];
    
    // Filtro por sede
    if (filtroSede) {
      lista = lista.filter((i) => i.sede === filtroSede);
    }
    
    // Filtro por período
    if (rangoFechas.inicio && rangoFechas.fin) {
      lista = lista.filter((i) => i.fecha >= rangoFechas.inicio && i.fecha <= rangoFechas.fin);
    }
    
    // más recientes primero
    return lista.sort((a, b) => (a.fecha < b.fecha ? 1 : -1));
  }, [inventarios, filtroSede, rangoFechas]);

  // Consolidar productos solicitados de los inventarios filtrados
  // SOLO de inventarios CERRADOS (para Procesar pedido)
  const productosSolicitadosConsolidados = useMemo(() => {
    const consolidado = {};
    // Filtrar solo inventarios cerrados para procesar pedido
    const inventariosCerrados = inventariosFiltrados.filter(inv => !!inv.cerrado);
    console.log("📦 Procesar pedido - Total inventarios filtrados:", inventariosFiltrados.length);
    console.log("📦 Procesar pedido - Inventarios cerrados:", inventariosCerrados.length);
    console.log("📦 Detalle inventarios:", inventariosFiltrados.map(i => ({ id: i.id, sede: i.sede, cerrado: i.cerrado, lineas: i.lineas?.length })));
    inventariosCerrados.forEach((inv) => {
      if (!inv.lineas) return;
      inv.lineas.forEach((linea) => {
        if (linea.solicitar === "Sí" && linea.cantidad) {
          const key = `${inv.sede}::${linea.producto}`;
          if (!consolidado[key]) {
            consolidado[key] = {
              sede: inv.sede,
              producto: linea.producto,
              cantidad: 0,
              fechas: [],
              existenciasUltimo: linea.existencias
            };
          }
          consolidado[key].cantidad += parseInt(linea.cantidad) || 0;
          if (!consolidado[key].fechas.includes(inv.fecha)) {
            consolidado[key].fechas.push(inv.fecha);
          }
          consolidado[key].existenciasUltimo = linea.existencias;
        }
      });
    });
    return Object.values(consolidado);
  }, [inventariosFiltrados]);

  // Agrupar productos por sede para las tarjetas
  const productosPorSede = useMemo(() => {
    const porSede = {};
    productosSolicitadosConsolidados.forEach((item) => {
      if (!porSede[item.sede]) {
        porSede[item.sede] = [];
      }
      porSede[item.sede].push(item);
    });
    return porSede;
  }, [productosSolicitadosConsolidados]);

  // NUEVO: Agrupar por FECHA con novedades de cada sede
  const productosPorFecha = useMemo(() => {
    const porFecha = {};
    const inventariosCerrados = inventariosFiltrados.filter(inv => !!inv.cerrado);
    
    inventariosCerrados.forEach((inv) => {
      if (!inv.lineas) return;
      const fecha = inv.fecha;
      
      if (!porFecha[fecha]) {
        porFecha[fecha] = {
          fecha: fecha,
          sedes: {}
        };
      }
      
      if (!porFecha[fecha].sedes[inv.sede]) {
        // Buscar nombre del encargado
        const encargadoNombre = empleados.find(e => e.id === inv.encargadoId)?.nombre || 'N/A';
        porFecha[fecha].sedes[inv.sede] = {
          sede: inv.sede,
          novedades: inv.novedades || '',
          encargadoNombre: encargadoNombre,
          horaCreacion: inv.hora_creacion || inv.created_at ? new Date(inv.created_at || Date.now()).toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' }) : '',
          productos: []
        };
      }
      
      // Agregar productos de esta sede
      inv.lineas.forEach((linea) => {
        if (linea.solicitar === "Sí" && linea.cantidad) {
          // Verificar si ya existe el producto para sumarlo
          const existente = porFecha[fecha].sedes[inv.sede].productos.find(p => p.producto === linea.producto);
          if (existente) {
            existente.cantidad += parseInt(linea.cantidad) || 0;
            existente.existencias = linea.existencias;
          } else {
            porFecha[fecha].sedes[inv.sede].productos.push({
              producto: linea.producto,
              cantidad: parseInt(linea.cantidad) || 0,
              existencias: linea.existencias
            });
          }
        }
      });
    });
    
    // Ordenar fechas de más reciente a más antigua
    return Object.values(porFecha).sort((a, b) => (a.fecha < b.fecha ? 1 : -1));
  }, [inventariosFiltrados, empleados]);

  // Filtrar productos que NO han sido enviados hoy
  const productosPorSedeDisponibles = useMemo(() => {
    const porSede = {};
    Object.entries(productosPorSede).forEach(([sede, productos]) => {
      const disponibles = productos.filter(p => !productosYaEnviados.has(`${p.sede}::${p.producto}`));
      if (disponibles.length > 0) {
        porSede[sede] = disponibles;
      }
    });
    return porSede;
  }, [productosPorSede, productosYaEnviados]);

  // Función para generar pedido final
  const [productosKeysSeleccionados, setProductosKeysSeleccionados] = useState([]);
  
  function generarPedidoFinal() {
    const pedidos = {};
    const keysSeleccionados = [];
    const empleadoNombre = empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email || 'Usuario';
    const horaActual = new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' });
    
    Object.entries(productosSeleccionados).forEach(([key, seleccionado]) => {
      if (seleccionado) {
        const item = productosSolicitadosConsolidados.find(
          (p) => `${p.sede}::${p.producto}` === key
        );
        if (item) {
          if (!pedidos[item.sede]) {
            pedidos[item.sede] = [];
          }
          pedidos[item.sede].push({
            producto: item.producto,
            cantidad: item.cantidad,
            existencias: item.existenciasUltimo,
            procesado_por: empleadoNombre,
            hora_procesado: horaActual
          });
          keysSeleccionados.push(key);
        }
      }
    });
    setPedidosPorSede(pedidos);
    setProductosKeysSeleccionados(keysSeleccionados);
    setNovedadesPedido(""); // Limpiar novedades al generar nuevo pedido
    setMostrarResumenPedido(true);
  }

  // Seleccionar/deseleccionar todos los productos de una sede
  function toggleSeleccionSede(sede, seleccionar) {
    const nuevaSeleccion = { ...productosSeleccionados };
    productosPorSedeDisponibles[sede]?.forEach((item) => {
      nuevaSeleccion[`${item.sede}::${item.producto}`] = seleccionar;
    });
    setProductosSeleccionados(nuevaSeleccion);
  }

  return (
    <div>
      {/* Cabecera ejecutiva */}
      <div
        style={{
          background:
            "linear-gradient(90deg, #0f172a 0%, #1e293b 40%, #0ea5e9 100%)",
          borderRadius: 8,
          padding: "12px 16px",
          marginBottom: 16,
          color: "white",
        }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <h2 className="text-sm font-semibold">
            Inventario – Ambiente administrativo
          </h2>
          <span style={{ fontSize: 11, opacity: 0.9 }}>
            Módulo ejecutivo de inventarios
          </span>
        </div>
      </div>

      {(cargandoInventarios || sincronizandoInventario) && (
        <div className="card" style={{ marginBottom: 12, backgroundColor: "#f8fafc" }}>
          <p style={{ margin: 0, fontSize: 12, color: "#0f172a" }}>
            {cargandoInventarios
              ? "Cargando inventarios desde Supabase…"
              : "Sincronizando inventario con Supabase…"}
          </p>
        </div>
      )}

      {/* Tabs Crear / Consultar */}
      <div className="tabs" style={{ marginBottom: 12 }}>
        {tienePermiso("admin_inventario_crear") && (
        <button
          className={modo === "crear" ? "tab active" : "tab"}
          onClick={() => {
            setModo("crear");
          }}
        >
          Crear inventario
        </button>
        )}
        {tienePermiso("admin_inventario_consultar") && (
        <button
          className={modo === "consultar" ? "tab active" : "tab"}
          onClick={() => {
            setModo("consultar");
            setInventarioActivoId(null);
          }}
        >
          Consultar inventarios
        </button>
        )}
      </div>

      {modo === "crear" && tienePermiso("admin_inventario_crear") && (
        <>
          {/* Formulario de cabecera */}
          <div className="card" style={{ marginBottom: 16 }}>
            <h3 className="text-sm font-semibold" style={{ marginBottom: 8 }}>
              Datos del inventario
            </h3>
            <div className="grid-3">
              <Field label="Fecha">
                <Input
                  type="date"
                  value={cabecera.fecha}
                  onChange={(e) => updateCabecera("fecha", e.target.value)}
                  disabled={estaCerrado}
                />
              </Field>

              <Field label="Sede">
                <select
                  className="input"
                  value={cabecera.sede}
                  onChange={(e) => updateCabecera("sede", e.target.value)}
                  disabled={estaCerrado}
                >
                  <option value="">-- Selecciona --</option>
                  {sedes.map((s) => {
                    const sedeNombre = typeof s === 'string' ? s : (s?.nombre || s?.razonSocial || '');
                    return (
                      <option key={sedeNombre} value={sedeNombre}>
                        {sedeNombre}
                      </option>
                    );
                  })}
                </select>
              </Field>

              <Field label="Encargado">
                <select
                  className="input"
                  value={cabecera.encargadoId}
                  onChange={(e) =>
                    updateCabecera("encargadoId", e.target.value)
                    
                  }
                >
                  <option value="">-- Selecciona --</option>
                  {[...(empleados || [])].sort((a, b) => ((a.nombre || "").localeCompare((b.nombre || ""), 'es', { sensitivity: 'base' }))).map((e) => (
                    <option key={e.id} value={e.id}>
                      {e.nombre}
                    </option>
                  ))}
                </select>
              </Field>
            </div>

            <div className="grid-3">
              <Field label="Personal en la cocina">
                <Input
                  value={cabecera.personalCocina}
                  onChange={(e) =>
                    updateCabecera("personalCocina", e.target.value)
                  }
                  placeholder="Nombres del personal en cocina"
                />
              </Field>

              <Field label="Novedades">
                <textarea
                  className="input"
                  rows={2}
                  value={cabecera.novedades}
                  onChange={(e) =>
                    updateCabecera("novedades", e.target.value)
                  }
                  placeholder="Observaciones o novedades del día"
                />
              </Field>
            </div>

  
          </div>

{/* INVENTARIO DIARIO - Vista Compacta tipo Excel */}
<div className="card" style={{ marginBottom: 16, overflow: 'auto' }}>
  <h3 style={{ marginBottom: 12, fontSize: 16, fontWeight: 600, color: '#1e293b' }}>
    INVENTARIO DIARIO (obligatorio sin espacios en blanco)
  </h3>

  <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 15 }}>
    <thead>
      <tr style={{ background: '#1e293b', color: 'white' }}>
        <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 600, fontSize: 15 }}>Producto</th>
        <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 110 }}>Existencia</th>
        <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 90 }}>Pedir</th>
        <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 110 }}>Cuántos</th>
      </tr>
    </thead>
    <tbody>
      {lineasDiario.map((l, idx) => (
        <tr 
          key={l.id} 
          style={{ 
            background: idx % 2 === 0 ? '#f8fafc' : '#ffffff',
            borderBottom: '1px solid #e2e8f0'
          }}
        >
          <td style={{ padding: '10px 16px', fontWeight: 500, color: '#0f172a', fontSize: 15 }}>
            {l.producto}
          </td>
          <td style={{ padding: '8px 12px', textAlign: 'center' }}>
            <Input
              value={l.existencias}
              onChange={(e) =>
                updateLinea(lineasDiario, setLineasDiario, l.id, "existencias", e.target.value)
              }
              placeholder="0"
              style={{ width: '100%', textAlign: 'center', padding: '8px 10px', fontSize: 15 }}
              disabled={estaCerrado}
            />
          </td>
          <td style={{ padding: '8px 12px', textAlign: 'center' }}>
            <select
              className="input"
              value={l.solicitar}
              onChange={(e) =>
                updateLinea(lineasDiario, setLineasDiario, l.id, "solicitar", e.target.value)
              }
              style={{ width: '100%', padding: '8px 6px', fontSize: 14, textAlign: 'center' }}
              disabled={estaCerrado}
            >
              <option value="No">No</option>
              <option value="Sí">Sí</option>
            </select>
          </td>
          <td style={{ padding: '8px 12px', textAlign: 'center' }}>
            <Input
              value={l.cantidad}
              onChange={(e) =>
                updateLinea(lineasDiario, setLineasDiario, l.id, "cantidad", e.target.value)
              }
              placeholder="0"
              style={{ 
                width: '100%', 
                textAlign: 'center', 
                padding: '8px 10px',
                fontSize: 15,
                background: l.solicitar !== "Sí" ? '#f1f5f9' : '#fff'
              }}
              disabled={l.solicitar !== "Sí" || estaCerrado}
            />
          </td>
        </tr>
      ))}
    </tbody>
  </table>
</div>
{/* INVENTARIO ADICIONAL - Vista Compacta tipo Excel */}
<div className="card" style={{ marginBottom: 16, overflow: 'auto' }}>
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: 12,
      flexWrap: "wrap",
      gap: 10
    }}
  >
    <h3 style={{ fontSize: 16, fontWeight: 600, color: '#0ea5e9' }}>Inventario adicional</h3>
    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
      <select
        className="input"
        value={productoAdicional}
        onChange={(e) => setProductoAdicional(e.target.value)}
        disabled={estaCerrado}
        style={{ fontSize: 14, padding: '8px 12px' }}
      >
        <option value="">-- Producto adicional --</option>
        {PRODUCTOS_INVENTARIO_ADICIONAL.map((p) => (
          <option key={p} value={p}>
            {p}
          </option>
        ))}
      </select>
      <Button variant="outline" onClick={handleAgregarAdicional} disabled={estaCerrado}>
        + Agregar
      </Button>
    </div>
  </div>

  {adicionales.length > 0 && (
    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 15, marginTop: 8 }}>
      <thead>
        <tr style={{ background: '#0ea5e9', color: 'white' }}>
          <th style={{ padding: '12px 16px', textAlign: 'left', fontWeight: 600, fontSize: 15 }}>Producto</th>
          <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 110 }}>Existencia</th>
          <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 90 }}>Pedir</th>
          <th style={{ padding: '12px 16px', textAlign: 'center', fontWeight: 600, fontSize: 15, width: 110 }}>Cuántos</th>
        </tr>
      </thead>
      <tbody>
        {adicionales.map((l, idx) => (
          <tr 
            key={l.id} 
            style={{ 
              background: idx % 2 === 0 ? '#f0f9ff' : '#ffffff',
              borderBottom: '1px solid #e2e8f0'
            }}
          >
            <td style={{ padding: '10px 16px', fontWeight: 500, color: '#0f172a', fontSize: 15 }}>
              {l.producto}
            </td>
            <td style={{ padding: '8px 12px', textAlign: 'center' }}>
              <Input
                value={l.existencias}
                onChange={(e) =>
                  updateLinea(adicionales, setAdicionales, l.id, "existencias", e.target.value)
                }
                placeholder="0"
                style={{ width: '100%', textAlign: 'center', padding: '8px 10px', fontSize: 15 }}
                disabled={estaCerrado}
              />
            </td>
            <td style={{ padding: '8px 12px', textAlign: 'center' }}>
              <select
                className="input"
                value={l.solicitar}
                onChange={(e) =>
                  updateLinea(adicionales, setAdicionales, l.id, "solicitar", e.target.value)
                }
                style={{ width: '100%', padding: '8px 6px', fontSize: 14, textAlign: 'center' }}
                disabled={estaCerrado}
              >
                <option value="No">No</option>
                <option value="Sí">Sí</option>
              </select>
            </td>
            <td style={{ padding: '8px 12px', textAlign: 'center' }}>
              <Input
                value={l.cantidad}
                onChange={(e) =>
                  updateLinea(adicionales, setAdicionales, l.id, "cantidad", e.target.value)
                }
                placeholder="0"
                style={{ 
                  width: '100%', 
                  textAlign: 'center', 
                  padding: '8px 10px',
                  fontSize: 15,
                  background: l.solicitar !== "Sí" ? '#f1f5f9' : '#fff'
                }}
                disabled={l.solicitar !== "Sí" || estaCerrado}
              />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  )}

  {adicionales.length === 0 && (
    <p style={{ fontSize: 14, color: '#64748b', textAlign: 'center', padding: 20 }}>
      No hay productos adicionales. Usa el selector de arriba para agregar.
    </p>
  )}
</div>


{/* BOTONES GUARDAR / CERRAR */}
<div
  style={{
    display: "flex",
    justifyContent: "flex-end",
    gap: 8,
    marginBottom: 24,
  }}
>
  {!estaCerrado && tienePermiso("admin_inventario_guardar") && (
    <Button onClick={handleGuardar}>Guardar inventario</Button>
  )}

  {inventarioActivo && tienePermiso("admin_inventario_cerrar") && (
    <Button
      variant={estaCerrado ? "outline" : "danger"}
      onClick={estaCerrado ? undefined : handleCerrar}
      disabled={estaCerrado}
    >
      {estaCerrado ? "Inventario cerrado" : "Cerrar inventario"}
    </Button>
  )}
</div>

        </>
      )}

      {modo === "consultar" && tienePermiso("admin_inventario_consultar") && (
        <div>
          {/* PANEL DE FILTROS INTERACTIVOS */}
          <div className="card" style={{ marginBottom: 16 }}>
            <h3 style={{ fontSize: 16, fontWeight: 600, color: '#1e293b', marginBottom: 16 }}>
              Consultar y Procesar Inventarios
            </h3>

            {/* Filtros en fila */}
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 16, alignItems: 'flex-end' }}>
              {/* Filtro por sede */}
              <div style={{ minWidth: 150 }}>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 500, marginBottom: 4, color: '#64748b' }}>Sede</label>
                <select
                  className="input"
                  value={filtroSede}
                  onChange={(e) => setFiltroSede(e.target.value)}
                  style={{ fontSize: 14, padding: '8px 12px', width: '100%' }}
                >
                  <option value="">Todas las sedes</option>
                  {sedes.map((s) => {
                    const sedeNombre = typeof s === 'string' ? s : (s?.nombre || s?.razonSocial || '');
                    return (
                      <option key={sedeNombre} value={sedeNombre}>
                        {sedeNombre}
                      </option>
                    );
                  })}
                </select>
              </div>

              {/* Filtro por período */}
              <div style={{ minWidth: 130 }}>
                <label style={{ display: 'block', fontSize: 12, fontWeight: 500, marginBottom: 4, color: '#64748b' }}>Período</label>
                <select
                  className="input"
                  value={filtroPeriodo}
                  onChange={(e) => setFiltroPeriodo(e.target.value)}
                  style={{ fontSize: 14, padding: '8px 12px', width: '100%' }}
                >
                  <option value="dia">Día específico</option>
                  <option value="semana">Semana</option>
                  <option value="mes">Mes</option>
                  <option value="todos">Todos</option>
                </select>
              </div>

              {/* Fecha de referencia */}
              {filtroPeriodo !== "todos" && (
                <div style={{ minWidth: 150 }}>
                  <label style={{ display: 'block', fontSize: 12, fontWeight: 500, marginBottom: 4, color: '#64748b' }}>
                    {filtroPeriodo === "dia" ? "Fecha" : filtroPeriodo === "semana" ? "Semana de" : "Mes de"}
                  </label>
                  <input
                    type="date"
                    className="input"
                    value={filtroFechaEspecifica}
                    onChange={(e) => setFiltroFechaEspecifica(e.target.value)}
                    style={{ fontSize: 14, padding: '8px 12px', width: '100%' }}
                  />
                </div>
              )}

              {/* Mostrar rango seleccionado */}
              {rangoFechas.inicio && rangoFechas.fin && (
                <div style={{ 
                  background: '#f0f9ff', 
                  padding: '8px 12px', 
                  borderRadius: 6, 
                  fontSize: 12,
                  color: '#0369a1',
                  border: '1px solid #bae6fd'
                }}>
                  {rangoFechas.inicio === rangoFechas.fin 
                    ? `Fecha: ${rangoFechas.inicio}`
                    : `Del ${rangoFechas.inicio} al ${rangoFechas.fin}`
                  }
                </div>
              )}
            </div>

            {/* Botones de vista */}
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
              <button
                onClick={() => setVistaConsulta("lista")}
                style={{
                  padding: '10px 16px',
                  borderRadius: 8,
                  border: vistaConsulta === "lista" ? '2px solid #1e293b' : '1px solid #e2e8f0',
                  background: vistaConsulta === "lista" ? '#1e293b' : '#fff',
                  color: vistaConsulta === "lista" ? '#fff' : '#1e293b',
                  fontWeight: 600,
                  fontSize: 13,
                  cursor: 'pointer'
                }}
              >
                📋 Lista de inventarios
              </button>
              <button
                onClick={() => setVistaConsulta("tarjetas")}
                style={{
                  padding: '10px 16px',
                  borderRadius: 8,
                  border: vistaConsulta === "tarjetas" ? '2px solid #0ea5e9' : '1px solid #e2e8f0',
                  background: vistaConsulta === "tarjetas" ? '#0ea5e9' : '#fff',
                  color: vistaConsulta === "tarjetas" ? '#fff' : '#0ea5e9',
                  fontWeight: 600,
                  fontSize: 13,
                  cursor: 'pointer'
                }}
              >
                🏢 Ver por sede
              </button>
              <button
                onClick={() => {
                  setVistaConsulta("procesar");
                  setProductosSeleccionados({});
                  setMostrarResumenPedido(false);
                }}
                style={{
                  padding: '10px 16px',
                  borderRadius: 8,
                  border: vistaConsulta === "procesar" ? '2px solid #16a34a' : '1px solid #e2e8f0',
                  background: vistaConsulta === "procesar" ? '#16a34a' : '#fff',
                  color: vistaConsulta === "procesar" ? '#fff' : '#16a34a',
                  fontWeight: 600,
                  fontSize: 13,
                  cursor: 'pointer'
                }}
              >
                📦 Procesar pedido
              </button>
              <button
                onClick={() => setVistaConsulta("pedidos_guardados")}
                style={{
                  padding: '10px 16px',
                  borderRadius: 8,
                  border: vistaConsulta === "pedidos_guardados" ? '2px solid #7c3aed' : '1px solid #e2e8f0',
                  background: vistaConsulta === "pedidos_guardados" ? '#7c3aed' : '#fff',
                  color: vistaConsulta === "pedidos_guardados" ? '#fff' : '#7c3aed',
                  fontWeight: 600,
                  fontSize: 13,
                  cursor: 'pointer'
                }}
              >
                📋 Pedidos Guardados
              </button>
            </div>

            {/* Resumen rápido */}
            <div style={{ 
              padding: 12, 
              background: '#f8fafc', 
              borderRadius: 8,
              display: 'flex',
              gap: 24,
              flexWrap: 'wrap'
            }}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: '#1e293b' }}>{inventariosFiltrados.length}</div>
                <div style={{ fontSize: 11, color: '#64748b' }}>Inventarios</div>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: '#0ea5e9' }}>
                  {[...new Set(inventariosFiltrados.map(i => i.sede))].length}
                </div>
                <div style={{ fontSize: 11, color: '#64748b' }}>Sedes</div>
              </div>
              <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 700, color: '#16a34a' }}>{productosSolicitadosConsolidados.length}</div>
                <div style={{ fontSize: 11, color: '#64748b' }}>Productos a pedir</div>
              </div>
            </div>
          </div>

          {/* VISTA: LISTA DE INVENTARIOS */}
          {vistaConsulta === "lista" && (
          <div className="card">
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14 }}>
                <thead>
                  <tr style={{ background: '#1e293b', color: 'white' }}>
                    <th style={{ padding: '12px 16px', textAlign: 'left' }}>Fecha</th>
                    <th style={{ padding: '12px 16px', textAlign: 'left' }}>Sede</th>
                    <th style={{ padding: '12px 16px', textAlign: 'left' }}>Encargado</th>
                    <th style={{ padding: '12px 16px', textAlign: 'center' }}>Estado</th>
                    <th style={{ padding: '12px 16px', textAlign: 'center' }}>Acciones</th>
                  </tr>
                </thead>

  <tbody>
    {inventariosFiltrados.map((inv, idx) => {
      const enc = empleados.find((e) => e.id === inv.encargadoId)?.nombre || "—";
      const cerrado = !!inv.cerrado;
      const productosPedidos = (inv.lineas || []).filter(l => l.solicitar === "Sí").length;

      return (
        <tr key={inv.id} style={{ background: idx % 2 === 0 ? '#f8fafc' : '#fff', borderBottom: '1px solid #e2e8f0' }}>
          <td style={{ padding: '10px 16px', fontWeight: 500 }}>{inv.fecha}</td>
          <td style={{ padding: '10px 16px' }}>{inv.sede}</td>
          <td style={{ padding: '10px 16px' }}>{enc}</td>
          <td style={{ padding: '10px 16px', textAlign: 'center', minWidth: 150 }}>
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
              <span style={{
                padding: '6px 14px',
                borderRadius: 12,
                fontSize: 14,
                fontWeight: 600,
                background: cerrado ? '#dcfce7' : '#fef3c7',
                color: cerrado ? '#16a34a' : '#d97706',
                whiteSpace: 'nowrap'
              }}>
                {cerrado ? "Cerrado" : "Abierto"}
              </span>
              {productosPedidos > 0 && (
                <span style={{
                  padding: '4px 10px',
                  borderRadius: 12,
                  fontSize: 12,
                  fontWeight: 600,
                  background: '#fee2e2',
                  color: '#dc2626',
                  whiteSpace: 'nowrap'
                }}>
                  {productosPedidos} productos a pedir
                </span>
              )}
            </div>
          </td>
          <td style={{ padding: '8px 16px', textAlign: 'center' }}>
            <div style={{ display: 'flex', gap: 4, justifyContent: 'center', flexWrap: 'wrap' }}>
              <Button variant="outline" onClick={() => { setInventarioActivoId(inv.id); setModo("crear"); }}>
                Ver
              </Button>
              {tienePermiso("admin_inventario_imprimir") && (
                <Button variant="outline" onClick={() => handleImprimir(inv)}>
                  Imprimir
                </Button>
              )}
              {tienePermiso("admin_inventario_eliminar") && (
                <Button variant="danger" onClick={() => handleEliminar(inv.id)}>
                  Eliminar
                </Button>
              )}
            </div>
          </td>
        </tr>
      );
    })}

    {inventariosFiltrados.length === 0 && (
      <tr>
        <td colSpan={5} style={{ textAlign: "center", padding: 24, color: '#64748b' }}>
          No hay inventarios con los filtros seleccionados.
        </td>
      </tr>
    )}
  </tbody>
              </table>
          </div>
          )}

          {/* VISTA: TARJETAS POR FECHA (UNIFICADO) */}
          {vistaConsulta === "tarjetas" && (
            <div>
              <div style={{ 
                background: '#fef3c7', 
                border: '1px solid #f59e0b', 
                borderRadius: 8, 
                padding: '10px 14px', 
                marginBottom: 16,
                display: 'flex',
                alignItems: 'center',
                gap: 8
              }}>
                <span style={{ fontSize: 18 }}>ℹ️</span>
                <span style={{ fontSize: 13, color: '#92400e' }}>
                  <strong>Nota:</strong> Vista unificada por fecha. Solo se muestran productos de inventarios <strong>cerrados</strong>. Las novedades aparecen junto a cada sede.
                </span>
              </div>
              
              {/* Iterar por cada fecha */}
              {productosPorFecha.map((fechaData) => (
                <div key={fechaData.fecha} style={{ marginBottom: 24 }}>
                  {/* Encabezado de fecha */}
                  <div style={{ 
                    background: 'linear-gradient(90deg, #1e293b 0%, #334155 100%)', 
                    color: 'white', 
                    padding: '14px 20px',
                    borderRadius: '12px 12px 0 0',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                  }}>
                    <h3 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>
                      📅 {new Date(fechaData.fecha + 'T12:00:00').toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                    </h3>
                    <span style={{ 
                      background: 'rgba(255,255,255,0.2)', 
                      padding: '6px 14px', 
                      borderRadius: 20,
                      fontSize: 13
                    }}>
                      {Object.keys(fechaData.sedes).length} sedes
                    </span>
                  </div>
                  
                  {/* Grid de sedes para esa fecha */}
                  <div style={{ 
                    background: '#f8fafc', 
                    border: '2px solid #1e293b',
                    borderTop: 'none',
                    borderRadius: '0 0 12px 12px',
                    padding: 16
                  }}>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: 16 }}>
                      {Object.values(fechaData.sedes).map((sedeData) => (
                        <div key={sedeData.sede} className="card" style={{ 
                          border: '2px solid #0ea5e9',
                          borderRadius: 12,
                          overflow: 'hidden',
                          boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                        }}>
                          {/* Encabezado de sede */}
                          <div style={{ 
                            background: 'linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%)', 
                            color: 'white', 
                            padding: '12px 16px'
                          }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                              <h4 style={{ margin: 0, fontSize: 16, fontWeight: 600 }}>🏢 {sedeData.sede}</h4>
                              <span style={{ 
                                background: 'rgba(255,255,255,0.2)', 
                                padding: '4px 10px', 
                                borderRadius: 12,
                                fontSize: 12
                              }}>
                                {sedeData.productos.length} productos
                              </span>
                            </div>
                            {/* Info del encargado y hora */}
                            <div style={{ fontSize: 11, opacity: 0.9 }}>
                              <span>👤 {sedeData.encargadoNombre}</span>
                              {sedeData.horaCreacion && <span> • 🕐 {sedeData.horaCreacion}</span>}
                            </div>
                          </div>
                          
                          {/* Novedades de esta sede (si existen) */}
                          {sedeData.novedades && (
                            <div style={{ 
                              background: '#fef3c7', 
                              padding: '10px 14px', 
                              borderBottom: '1px solid #fcd34d'
                            }}>
                              <div style={{ fontSize: 11, fontWeight: 600, color: '#92400e', marginBottom: 4 }}>📝 Novedades:</div>
                              <div style={{ fontSize: 12, color: '#78350f', whiteSpace: 'pre-wrap' }}>{sedeData.novedades}</div>
                            </div>
                          )}
                          
                          {/* Lista de productos */}
                          <div style={{ padding: 12, maxHeight: 250, overflowY: 'auto' }}>
                            {sedeData.productos.map((p, idx) => (
                              <div key={idx} style={{ 
                                display: 'flex', 
                                justifyContent: 'space-between', 
                                alignItems: 'center',
                                padding: '8px 0',
                                borderBottom: idx < sedeData.productos.length - 1 ? '1px solid #e2e8f0' : 'none'
                              }}>
                                <span style={{ fontWeight: 500, fontSize: 14 }}>{p.producto}</span>
                                <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                                  <span style={{ fontSize: 11, color: '#64748b' }}>Exist: {p.existencias}</span>
                                  <span style={{ 
                                    background: '#fee2e2', 
                                    color: '#dc2626', 
                                    padding: '4px 10px', 
                                    borderRadius: 12,
                                    fontSize: 13,
                                    fontWeight: 600
                                  }}>
                                    Pedir: {p.cantidad}
                                  </span>
                                </div>
                              </div>
                            ))}
                            {sedeData.productos.length === 0 && (
                              <div style={{ textAlign: 'center', padding: 16, color: '#94a3b8', fontSize: 13 }}>
                                Sin productos solicitados
                              </div>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
              
              {productosPorFecha.length === 0 && (
                <div className="card" style={{ textAlign: 'center', padding: 32, color: '#64748b' }}>
                  No hay productos solicitados en el período seleccionado (solo se consideran inventarios cerrados).
                </div>
              )}
            </div>
          )}

          {/* VISTA: PROCESAR PEDIDO */}
          {vistaConsulta === "procesar" && !mostrarResumenPedido && (
            <div className="card">
              <div style={{ 
                background: '#fef3c7', 
                border: '1px solid #f59e0b', 
                borderRadius: 8, 
                padding: '10px 14px', 
                marginBottom: 16,
                display: 'flex',
                alignItems: 'center',
                gap: 8
              }}>
                <span style={{ fontSize: 18 }}>ℹ️</span>
                <span style={{ fontSize: 13, color: '#92400e' }}>
                  <strong>Nota:</strong> Solo se muestran productos de inventarios <strong>cerrados</strong> que aún no han sido enviados hoy. Los productos ya incluidos en pedidos anteriores no aparecerán.
                </span>
              </div>
              <p style={{ fontSize: 14, color: '#64748b', marginBottom: 16 }}>
                Selecciona los productos que deseas incluir en el pedido para cada sede.
              </p>
              
              {Object.entries(productosPorSedeDisponibles).map(([sede, productos]) => (
                <div key={sede} style={{ marginBottom: 20 }}>
                  <div style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'center',
                    padding: '10px 16px',
                    background: '#1e293b',
                    color: 'white',
                    borderRadius: '8px 8px 0 0'
                  }}>
                    <h4 style={{ margin: 0, fontSize: 15, fontWeight: 600 }}>🏢 {sede}</h4>
                    <div style={{ display: 'flex', gap: 8 }}>
                      <button
                        onClick={() => toggleSeleccionSede(sede, true)}
                        style={{ background: '#16a34a', color: 'white', border: 'none', padding: '4px 10px', borderRadius: 6, fontSize: 11, cursor: 'pointer' }}
                      >
                        ✓ Todos
                      </button>
                      <button
                        onClick={() => toggleSeleccionSede(sede, false)}
                        style={{ background: '#64748b', color: 'white', border: 'none', padding: '4px 10px', borderRadius: 6, fontSize: 11, cursor: 'pointer' }}
                      >
                        ✗ Ninguno
                      </button>
                    </div>
                  </div>
                  <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14 }}>
                    <thead>
                      <tr style={{ background: '#f1f5f9' }}>
                        <th style={{ padding: '8px 12px', textAlign: 'center', width: 50 }}>✓</th>
                        <th style={{ padding: '8px 12px', textAlign: 'left' }}>Producto</th>
                        <th style={{ padding: '8px 12px', textAlign: 'center', width: 100 }}>Existencia</th>
                        <th style={{ padding: '8px 12px', textAlign: 'center', width: 100 }}>Pedir</th>
                      </tr>
                    </thead>
                    <tbody>
                      {productos.map((p, idx) => {
                        const key = `${p.sede}::${p.producto}`;
                        const seleccionado = !!productosSeleccionados[key];
                        return (
                          <tr 
                            key={idx} 
                            style={{ background: seleccionado ? '#dcfce7' : (idx % 2 === 0 ? '#fff' : '#f8fafc'), borderBottom: '1px solid #e2e8f0', cursor: 'pointer' }}
                            onClick={() => setProductosSeleccionados(prev => ({ ...prev, [key]: !prev[key] }))}
                          >
                            <td style={{ padding: '10px 12px', textAlign: 'center' }}>
                              <input type="checkbox" checked={seleccionado} onChange={() => {}} style={{ width: 18, height: 18, cursor: 'pointer' }} />
                            </td>
                            <td style={{ padding: '10px 12px', fontWeight: 500 }}>{p.producto}</td>
                            <td style={{ padding: '10px 12px', textAlign: 'center', color: '#64748b' }}>{p.existenciasUltimo}</td>
                            <td style={{ padding: '10px 12px', textAlign: 'center' }}>
                              <span style={{ background: '#fee2e2', color: '#dc2626', padding: '4px 12px', borderRadius: 12, fontWeight: 600 }}>{p.cantidad}</span>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              ))}

              {Object.keys(productosPorSedeDisponibles).length === 0 && (
                <p style={{ textAlign: 'center', padding: 24, color: '#64748b' }}>No hay productos disponibles para enviar. Todos los productos ya fueron incluidos en pedidos anteriores o no hay inventarios cerrados.</p>
              )}

              {Object.keys(productosPorSedeDisponibles).length > 0 && (
                <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 16, gap: 8 }}>
                  <span style={{ padding: '10px 16px', background: '#f1f5f9', borderRadius: 8, fontSize: 13 }}>
                    {Object.values(productosSeleccionados).filter(Boolean).length} productos seleccionados
                  </span>
                  <Button onClick={generarPedidoFinal} disabled={Object.values(productosSeleccionados).filter(Boolean).length === 0}>
                    📦 Generar Pedido
                  </Button>
                </div>
              )}
            </div>
          )}

          {/* RESUMEN DE PEDIDO - TARJETAS POR SEDE */}
          {vistaConsulta === "procesar" && mostrarResumenPedido && (
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 12 }}>
                <h3 style={{ fontSize: 18, fontWeight: 600, color: '#16a34a', margin: 0 }}>📦 Pedido Consolidado</h3>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  <Button variant="outline" onClick={() => setMostrarResumenPedido(false)}>← Volver</Button>
                  <Button variant="outline" onClick={() => {
                    // Imprimir todas las sedes en columnas
                    const win = window.open("", "_blank");
                    if (!win) return;
                    const sedes = Object.entries(pedidosPorSede);
                    const maxProductos = Math.max(...sedes.map(([,p]) => p.length));
                    let html = `<html><head><title>Pedido Consolidado - Todas las Sedes</title>
                      <style>
                        body { font-family: Arial, sans-serif; padding: 20px; }
                        h1 { color: #16a34a; text-align: center; margin-bottom: 5px; }
                        .fecha { text-align: center; color: #666; margin-bottom: 20px; }
                        table { width: 100%; border-collapse: collapse; }
                        th { background: #16a34a; color: white; padding: 12px 8px; font-size: 14px; }
                        td { border: 1px solid #ddd; padding: 10px 8px; vertical-align: top; font-size: 13px; }
                        .producto { font-weight: 500; }
                        .cantidad { color: #16a34a; font-weight: bold; }
                        @media print { body { padding: 10px; } }
                      </style></head><body>
                      <h1>📦 Pedido Consolidado</h1>
                      <p class="fecha">Fecha: ${new Date().toLocaleDateString('es-CO')} - ${new Date().toLocaleTimeString('es-CO')}</p>
                      <table><thead><tr>`;
                    sedes.forEach(([sede]) => { html += `<th>🏢 ${sede}</th>`; });
                    html += '</tr></thead><tbody>';
                    for (let i = 0; i < maxProductos; i++) {
                      html += '<tr>';
                      sedes.forEach(([, productos]) => {
                        const p = productos[i];
                        html += p 
                          ? `<td><span class="producto">${p.producto}</span><br><span class="cantidad">Cantidad: ${p.cantidad}</span></td>`
                          : '<td></td>';
                      });
                      html += '</tr>';
                    }
                    html += '</tbody></table></body></html>';
                    win.document.write(html);
                    win.document.close();
                    win.print();
                  }}>🖨️ Imprimir Todas las Sedes</Button>
                </div>
              </div>

              {/* CAMPO DE NOVEDADES Y INFO DEL GENERADOR */}
              <div style={{ marginBottom: 16, padding: 16, background: '#f0fdf4', borderRadius: 8, border: '1px solid #86efac' }}>
                <div style={{ display: 'flex', gap: 16, marginBottom: 12, flexWrap: 'wrap' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontSize: 13, color: '#166534', fontWeight: 600 }}>👤 Generado por:</span>
                    <span style={{ fontSize: 14, fontWeight: 500 }}>{empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email || 'Usuario'}</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontSize: 13, color: '#166534', fontWeight: 600 }}>🕐 Hora:</span>
                    <span style={{ fontSize: 14, fontWeight: 500 }}>{new Date().toLocaleString('es-CO')}</span>
                  </div>
                </div>
                <label style={{ display: 'block', fontSize: 13, fontWeight: 600, color: '#166534', marginBottom: 6 }}>📝 Novedades del pedido:</label>
                <textarea
                  value={novedadesPedido}
                  onChange={(e) => setNovedadesPedido(e.target.value)}
                  placeholder="Escribe aquí cualquier novedad o instrucción especial para este pedido..."
                  style={{
                    width: '100%',
                    minHeight: 80,
                    padding: 12,
                    fontSize: 14,
                    border: '2px solid #86efac',
                    borderRadius: 8,
                    resize: 'vertical',
                    fontFamily: 'inherit'
                  }}
                />
              </div>

              {/* BOTÓN GUARDAR PEDIDO */}
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginBottom: 16 }}>
                <Button variant="outline" onClick={() => setMostrarResumenPedido(false)}>← Volver a selección</Button>
                <Button onClick={async () => {
                  const sedesActuales = Object.keys(pedidosPorSede).sort();
                  const empleadoNombre = empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email || 'Usuario';
                  const hoy = toISO(new Date());
                  
                  try {
                    // Buscar pedido existente del día para unificar
                    const { data: pedidoExistente } = await supabase
                      .from('pedidos_consolidados')
                      .select('*')
                      .gte('fecha', hoy + 'T00:00:00')
                      .lte('fecha', hoy + 'T23:59:59')
                      .limit(1)
                      .single();
                    
                    if (pedidoExistente) {
                      // UNIFICAR: Agregar productos al pedido existente
                      const productosExistentes = pedidoExistente.productos || {};
                      const keysExistentes = pedidoExistente.productos_keys || [];
                      const novedadesExistentes = pedidoExistente.novedades || '';
                      
                      // Identificador único para este envío (agrupar productos por empleado+hora+novedad)
                      const envioId = `${empleadoNombre}_${new Date().toLocaleTimeString('es-CO')}`;
                      
                      // Merge de productos por sede - INCLUIR NOVEDADES EN CADA PRODUCTO
                      Object.entries(pedidosPorSede).forEach(([sede, prods]) => {
                        if (!productosExistentes[sede]) {
                          productosExistentes[sede] = [];
                        }
                        // Agregar novedades_envio y envio_id a cada producto
                        const prodsConNovedad = prods.map(p => ({
                          ...p,
                          novedades_envio: novedadesPedido || '',
                          envio_id: envioId
                        }));
                        productosExistentes[sede] = [...productosExistentes[sede], ...prodsConNovedad];
                      });
                      
                      // Merge de keys
                      const nuevasKeys = [...new Set([...keysExistentes, ...productosKeysSeleccionados])];
                      
                      // Merge de sedes
                      const todasSedes = [...new Set([...(pedidoExistente.sedes || []), ...sedesActuales])].sort();
                      
                      // Concatenar novedades si hay nuevas
                      let novedadesFinales = novedadesExistentes;
                      if (novedadesPedido) {
                        novedadesFinales = novedadesExistentes 
                          ? `${novedadesExistentes}\n---\n[${empleadoNombre} - ${new Date().toLocaleTimeString('es-CO')}]: ${novedadesPedido}`
                          : `[${empleadoNombre} - ${new Date().toLocaleTimeString('es-CO')}]: ${novedadesPedido}`;
                      }
                      
                      // Actualizar pedido existente
                      const { error } = await supabase
                        .from('pedidos_consolidados')
                        .update({
                          sedes: todasSedes,
                          productos: productosExistentes,
                          productos_keys: nuevasKeys,
                          total_productos: Object.values(productosExistentes).flat().length,
                          novedades: novedadesFinales || null
                        })
                        .eq('id', pedidoExistente.id);
                      
                      if (error) throw error;
                    } else {
                      // CREAR NUEVO: No hay pedido del día
                      // Identificador único para este envío
                      const envioId = `${empleadoNombre}_${new Date().toLocaleTimeString('es-CO')}`;
                      
                      // Agregar novedades_envio y envio_id a cada producto
                      const productosConNovedad = {};
                      Object.entries(pedidosPorSede).forEach(([sede, prods]) => {
                        productosConNovedad[sede] = prods.map(p => ({
                          ...p,
                          novedades_envio: novedadesPedido || '',
                          envio_id: envioId
                        }));
                      });
                      
                      const pedidoData = {
                        id: crypto.randomUUID(),
                        fecha: new Date().toISOString(),
                        sedes: sedesActuales,
                        productos: productosConNovedad,
                        estado: 'pendiente',
                        total_productos: Object.values(productosConNovedad).flat().length,
                        productos_keys: productosKeysSeleccionados || [],
                        novedades: novedadesPedido ? `[${empleadoNombre} - ${new Date().toLocaleTimeString('es-CO')}]: ${novedadesPedido}` : null,
                        generado_por_nombre: empleadoNombre,
                        hora_generacion: new Date().toLocaleTimeString('es-CO')
                      };
                      
                      const { error } = await supabase.from('pedidos_consolidados').insert([pedidoData]);
                      if (error) throw error;
                    }
                    
                    // Limpiar selección de productos que se guardaron
                    const nuevaSeleccion = { ...productosSeleccionados };
                    productosKeysSeleccionados.forEach(key => {
                      delete nuevaSeleccion[key];
                    });
                    setProductosSeleccionados(nuevaSeleccion);
                    
                    // Actualizar la lista de productos ya enviados
                    setProductosYaEnviados(prev => new Set([...prev, ...productosKeysSeleccionados]));
                    
                    // Limpiar y volver
                    setMostrarResumenPedido(false);
                    setNovedadesPedido("");
                    setPedidosPorSede({});
                    setProductosKeysSeleccionados([]);
                    
                    alert('✅ Pedido guardado correctamente. Los productos seleccionados ya no aparecerán para envíos posteriores.');
                  } catch (err) {
                    console.error('Error guardando pedido:', err);
                    alert('Error al guardar el pedido: ' + err.message);
                  }
                }}>💾 Guardar Pedido</Button>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))', gap: 16 }}>
                {Object.entries(pedidosPorSede).map(([sede, productos]) => (
                  <div key={sede} className="card" style={{ border: '3px solid #16a34a', borderRadius: 12, overflow: 'hidden', boxShadow: '0 4px 12px rgba(22, 163, 74, 0.2)' }}>
                    <div style={{ background: 'linear-gradient(135deg, #16a34a 0%, #15803d 100%)', color: 'white', padding: '16px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <h4 style={{ margin: 0, fontSize: 18, fontWeight: 700 }}>🏢 {sede}</h4>
                        <span style={{ fontSize: 12, opacity: 0.9 }}>Pedido generado</span>
                      </div>
                      <div style={{ background: 'rgba(255,255,255,0.2)', padding: '8px 14px', borderRadius: 20, fontSize: 14, fontWeight: 600 }}>{productos.length} items</div>
                    </div>
                    <div style={{ padding: 16 }}>
                      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 15 }}>
                        <thead>
                          <tr style={{ borderBottom: '2px solid #16a34a' }}>
                            <th style={{ padding: '8px 0', textAlign: 'left', fontWeight: 600 }}>Producto</th>
                            <th style={{ padding: '8px 0', textAlign: 'center', fontWeight: 600, width: 100 }}>Cantidad</th>
                          </tr>
                        </thead>
                        <tbody>
                          {productos.map((p, idx) => (
                            <tr key={idx} style={{ borderBottom: '1px solid #e2e8f0' }}>
                              <td style={{ padding: '12px 0', fontWeight: 500 }}>{p.producto}</td>
                              <td style={{ padding: '12px 0', textAlign: 'center' }}>
                                <span style={{ background: '#dcfce7', color: '#16a34a', padding: '6px 14px', borderRadius: 20, fontWeight: 700, fontSize: 16 }}>{p.cantidad}</span>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                    <div style={{ padding: '12px 16px', background: '#f0fdf4', display: 'flex', justifyContent: 'center', gap: 8 }}>
                      <Button variant="outline" onClick={() => {
                        const texto = productos.map(p => `• ${p.producto}: ${p.cantidad}`).join('\n');
                        navigator.clipboard.writeText(`📦 PEDIDO ${sede}\n${'─'.repeat(20)}\n${texto}`);
                        alert('Pedido copiado al portapapeles');
                      }}>📋 Copiar</Button>
                      <Button onClick={() => {
                        const win = window.open("", "_blank");
                        if (!win) return;
                        win.document.write(`<html><head><title>Pedido ${sede}</title><style>body{font-family:Arial;padding:20px}h1{color:#16a34a}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ddd;padding:12px}th{background:#16a34a;color:white}</style></head><body><h1>📦 Pedido - ${sede}</h1><p>Fecha: ${new Date().toLocaleDateString('es-CO')}</p><table><thead><tr><th>Producto</th><th>Cantidad</th></tr></thead><tbody>${productos.map(p => `<tr><td>${p.producto}</td><td style="text-align:center;font-weight:bold">${p.cantidad}</td></tr>`).join('')}</tbody></table></body></html>`);
                        win.document.close();
                        win.print();
                      }}>🖨️ Imprimir</Button>
                    </div>
                  </div>
                ))}
              </div>

              {Object.keys(pedidosPorSede).length === 0 && (
                <div className="card" style={{ textAlign: 'center', padding: 32, color: '#64748b' }}>No se seleccionaron productos para el pedido.</div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Vista de Pedidos Guardados */}
      {vistaConsulta === "pedidos_guardados" && (
        <div className="card" style={{ marginTop: 24 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
            <h3 style={{ fontSize: 18, fontWeight: 600, color: '#7c3aed', margin: 0 }}>📋 Pedidos Guardados</h3>
            <button
              onClick={cargarPedidosGuardados}
              style={{
                padding: '8px 16px',
                borderRadius: 8,
                border: '1px solid #7c3aed',
                background: '#fff',
                color: '#7c3aed',
                fontWeight: 600,
                fontSize: 13,
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: 6
              }}
            >
              🔄 Actualizar
            </button>
          </div>

          {cargandoPedidos ? (
            <div style={{ textAlign: 'center', padding: 40, color: '#64748b' }}>
              <div style={{ fontSize: 32, marginBottom: 12 }}>⏳</div>
              Cargando pedidos guardados...
            </div>
          ) : pedidosGuardados.length === 0 ? (
            <div style={{ textAlign: 'center', padding: 40, color: '#64748b' }}>
              <div style={{ fontSize: 48, marginBottom: 12 }}>📭</div>
              <p style={{ margin: 0, fontSize: 15 }}>No hay pedidos guardados aún</p>
              <p style={{ margin: '8px 0 0', fontSize: 13, color: '#94a3b8' }}>Los pedidos consolidados aparecerán aquí cuando los guardes</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {pedidosGuardados.map((pedido, idx) => (
                <div
                  key={pedido.id || idx}
                  className="card"
                  style={{
                    padding: 16,
                    background: '#faf5ff',
                    border: '1px solid #e9d5ff',
                    borderRadius: 12
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 15, color: '#7c3aed', marginBottom: 4 }}>
                        Pedido #{idx + 1} - {new Date(pedido.fecha).toLocaleDateString('es-CO', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
                      </div>
                      <div style={{ fontSize: 12, color: '#64748b' }}>
                        {new Date(pedido.fecha).toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })}
                      </div>
                    </div>
                    <span style={{
                      padding: '4px 12px',
                      borderRadius: 20,
                      fontSize: 12,
                      fontWeight: 600,
                      background: pedido.estado === 'procesado' ? '#dcfce7' : '#fef3c7',
                      color: pedido.estado === 'procesado' ? '#16a34a' : '#d97706'
                    }}>
                      {pedido.estado === 'procesado' ? '✓ Procesado' : '⏳ Pendiente'}
                    </span>
                  </div>

                  <div style={{ display: 'flex', gap: 16, marginBottom: 12, flexWrap: 'wrap' }}>
                    <div style={{ background: '#fff', padding: '8px 14px', borderRadius: 8, border: '1px solid #e9d5ff' }}>
                      <span style={{ fontSize: 12, color: '#64748b' }}>Sedes: </span>
                      <span style={{ fontWeight: 600, color: '#374151' }}>{pedido.sedes?.join(', ') || 'N/A'}</span>
                    </div>
                    <div style={{ background: '#fff', padding: '8px 14px', borderRadius: 8, border: '1px solid #e9d5ff' }}>
                      <span style={{ fontSize: 12, color: '#64748b' }}>Total productos: </span>
                      <span style={{ fontWeight: 600, color: '#374151' }}>{pedido.total_productos || 0}</span>
                    </div>
                  </div>

                  {/* MOSTRAR NOVEDADES SI EXISTEN */}
                  {pedido.novedades && (
                    <div style={{ background: '#fef3c7', padding: 12, borderRadius: 8, marginBottom: 12, border: '1px solid #fcd34d' }}>
                      <div style={{ fontSize: 12, fontWeight: 600, color: '#92400e', marginBottom: 4 }}>📝 Novedades:</div>
                      <div style={{ fontSize: 13, color: '#78350f', whiteSpace: 'pre-wrap' }}>{pedido.novedades}</div>
                    </div>
                  )}

                  {/* MOSTRAR GENERADO POR SI EXISTE */}
                  {pedido.generado_por_nombre && (
                    <div style={{ fontSize: 12, color: '#64748b', marginBottom: 12 }}>
                      <span>👤 Iniciado por: <strong>{pedido.generado_por_nombre}</strong></span>
                      {pedido.hora_generacion && <span> a las {pedido.hora_generacion}</span>}
                    </div>
                  )}

                  {/* MOSTRAR PRODUCTOS AGRUPADOS POR ENVÍO (EMPLEADO + HORA) */}
                  <div style={{ marginBottom: 12 }}>
                    {Object.entries(pedido.productos || {}).map(([sede, prods]) => {
                      // Agrupar productos por envio_id o procesado_por + hora_procesado
                      const gruposPorEnvio = {};
                      (prods || []).forEach(p => {
                        const envioKey = p.envio_id || `${p.procesado_por || 'N/A'}_${p.hora_procesado || ''}`;
                        if (!gruposPorEnvio[envioKey]) {
                          gruposPorEnvio[envioKey] = {
                            empleado: p.procesado_por || 'N/A',
                            hora: p.hora_procesado || '',
                            novedades: p.novedades_envio || '',
                            productos: []
                          };
                        }
                        gruposPorEnvio[envioKey].productos.push(p);
                      });
                      
                      return (
                        <div key={sede} style={{ marginBottom: 12, border: '1px solid #e2e8f0', borderRadius: 8, overflow: 'hidden' }}>
                          <div style={{ fontSize: 13, fontWeight: 600, color: '#16a34a', padding: '8px 12px', background: '#dcfce7' }}>🏢 {sede}</div>
                          {Object.entries(gruposPorEnvio).map(([envioKey, grupo], idx) => (
                            <div key={envioKey} style={{ padding: '8px 12px', borderTop: idx > 0 ? '1px dashed #e2e8f0' : 'none', background: idx % 2 === 0 ? '#fff' : '#f8fafc' }}>
                              {/* Encabezado del envío - Empleado y Hora (UNA SOLA VEZ) */}
                              <div style={{ fontSize: 12, fontWeight: 600, color: '#6366f1', marginBottom: 4 }}>
                                👤 {grupo.empleado} ({grupo.hora})
                              </div>
                              {/* Novedades del envío (si las hay) */}
                              {grupo.novedades && (
                                <div style={{ fontSize: 11, color: '#92400e', background: '#fef3c7', padding: '4px 8px', borderRadius: 4, marginBottom: 4 }}>
                                  📝 {grupo.novedades}
                                </div>
                              )}
                              {/* Lista de productos (sin repetir empleado) */}
                              <div style={{ fontSize: 12, color: '#374151', paddingLeft: 8 }}>
                                {grupo.productos.slice(0, 5).map((p, i) => (
                                  <div key={i}>• {p.producto} <span style={{ fontWeight: 600 }}>({p.cantidad})</span></div>
                                ))}
                                {grupo.productos.length > 5 && <div style={{ color: '#9ca3af', fontStyle: 'italic' }}>...y {grupo.productos.length - 5} más</div>}
                              </div>
                            </div>
                          ))}
                        </div>
                      );
                    })}
                  </div>

                  <div style={{ display: 'flex', gap: 8 }}>
                    <button
                      onClick={() => {
                        const productosData = pedido.productos || {};
                        const sedesPedido = pedido.sedes || [];
                        const win = window.open("", "_blank");
                        if (!win) return;
                        
                        // Generar tablas por sede AGRUPADAS POR ENVÍO (empleado + hora + novedades)
                        let tablasPorSede = '';
                        if (typeof productosData === 'object' && !Array.isArray(productosData)) {
                          Object.entries(productosData).forEach(([sede, prods]) => {
                            if (Array.isArray(prods) && prods.length > 0) {
                              // Agrupar productos por envio_id o procesado_por + hora_procesado
                              const gruposPorEnvio = {};
                              prods.forEach(p => {
                                const envioKey = p.envio_id || (p.procesado_por || 'N/A') + '_' + (p.hora_procesado || '');
                                if (!gruposPorEnvio[envioKey]) {
                                  gruposPorEnvio[envioKey] = {
                                    empleado: p.procesado_por || 'N/A',
                                    hora: p.hora_procesado || '',
                                    novedades: p.novedades_envio || '',
                                    productos: []
                                  };
                                }
                                gruposPorEnvio[envioKey].productos.push(p);
                              });
                              
                              tablasPorSede += '<div style="margin-bottom:25px;">';
                              tablasPorSede += '<h3 style="color:#16a34a;margin:0 0 10px 0;padding:8px 12px;background:#dcfce7;border-radius:6px;">🏢 ' + sede + '</h3>';
                              
                              // Iterar por cada grupo de envío
                              Object.entries(gruposPorEnvio).forEach(([envioKey, grupo]) => {
                                // Encabezado del envío (Empleado + Hora - UNA SOLA VEZ)
                                tablasPorSede += '<div style="background:#f0f9ff;padding:8px 12px;border:1px solid #bae6fd;border-radius:6px 6px 0 0;margin-top:10px;">';
                                tablasPorSede += '<strong style="color:#0369a1;">👤 ' + grupo.empleado + ' (' + grupo.hora + ')</strong>';
                                // Novedades del envío (si las hay)
                                if (grupo.novedades) {
                                  tablasPorSede += '<div style="margin-top:4px;padding:6px 8px;background:#fef3c7;border-radius:4px;font-size:12px;color:#92400e;">📝 Novedades: ' + grupo.novedades + '</div>';
                                }
                                tablasPorSede += '</div>';
                                
                                // Tabla de productos (solo Producto y Cantidad)
                                tablasPorSede += '<table style="border-radius:0 0 6px 6px;overflow:hidden;">';
                                tablasPorSede += '<thead><tr><th>Producto</th><th style="text-align:center;width:100px">Cantidad</th></tr></thead>';
                                tablasPorSede += '<tbody>';
                                grupo.productos.forEach(p => {
                                  tablasPorSede += '<tr><td>' + p.producto + '</td><td style="text-align:center;font-weight:bold">' + p.cantidad + '</td></tr>';
                                });
                                tablasPorSede += '</tbody></table>';
                              });
                              
                              tablasPorSede += '</div>';
                            }
                          });
                        }
                        
                        // Agregar novedades al HTML
                        const novedadesHTML = pedido.novedades ? `
                          <div style="background:#fef3c7;padding:12px;border-radius:8px;margin-bottom:20px;border:1px solid #fcd34d">
                            <strong style="color:#92400e">📝 Novedades:</strong><br>
                            <span style="white-space:pre-wrap">${pedido.novedades}</span>
                          </div>
                        ` : '';
                        
                        let html = `<html><head><title>Pedido Guardado</title>
                          <style>
                            body{font-family:Arial,sans-serif;padding:20px;max-width:900px;margin:0 auto}
                            h1{color:#7c3aed;border-bottom:2px solid #7c3aed;padding-bottom:10px}
                            .info{background:#f3e8ff;padding:12px;border-radius:8px;margin-bottom:20px}
                            table{width:100%;border-collapse:collapse;margin-top:10px}
                            th{background:#7c3aed;color:white;padding:10px;text-align:left}
                            td{border:1px solid #ddd;padding:10px}
                            tr:nth-child(even){background:#f9fafb}
                          </style>
                        </head><body>
                        <h1>📋 Pedido Guardado</h1>
                        <div class="info">
                          <strong>Fecha:</strong> ${new Date(pedido.fecha).toLocaleDateString('es-CO', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })} - ${new Date(pedido.fecha).toLocaleTimeString('es-CO')}<br>
                          <strong>Sedes:</strong> ${sedesPedido.join(', ')}<br>
                          <strong>Estado:</strong> ${pedido.estado === 'procesado' ? 'Procesado' : 'Pendiente'}
                        </div>
                        ${novedadesHTML}
                        ${tablasPorSede}
                        </body></html>`;
                        
                        win.document.write(html);
                        win.document.close();
                        win.print();
                      }}
                      style={{
                        padding: '8px 14px',
                        borderRadius: 6,
                        border: '1px solid #7c3aed',
                        background: '#fff',
                        color: '#7c3aed',
                        fontWeight: 500,
                        fontSize: 13,
                        cursor: 'pointer'
                      }}
                    >
                      🖨️ Imprimir
                    </button>
                    <button
                      onClick={async () => {
                        if (!confirm('¿Marcar este pedido como procesado?')) return;
                        const { error } = await supabase
                          .from('pedidos_consolidados')
                          .update({ estado: 'procesado' })
                          .eq('id', pedido.id);
                        if (error) {
                          alert('Error al actualizar: ' + error.message);
                        } else {
                          cargarPedidosGuardados();
                        }
                      }}
                      disabled={pedido.estado === 'procesado'}
                      style={{
                        padding: '8px 14px',
                        borderRadius: 6,
                        border: 'none',
                        background: pedido.estado === 'procesado' ? '#e2e8f0' : '#16a34a',
                        color: pedido.estado === 'procesado' ? '#94a3b8' : '#fff',
                        fontWeight: 500,
                        fontSize: 13,
                        cursor: pedido.estado === 'procesado' ? 'not-allowed' : 'pointer'
                      }}
                    >
                      ✓ Marcar procesado
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ====================== INVENTARIO INTEGRAL ======================

// Guardar inventario integral en Supabase
async function guardarInventarioIntegralEnSupabase(inventario, empresaId = null) {
  try {
    const payload = {
      id: inventario.id || crypto.randomUUID(),
      fecha: inventario.fecha,
      sede_id: inventario.sedeId,
      sede_nombre: inventario.sedeNombre,
      empleado_id: inventario.empleadoId,
      empleado_nombre: inventario.empleadoNombre,
      lineas: inventario.lineas || [], // JSONB - enviar como array directo, no string
      estado: inventario.estado || 'borrador', // borrador | enviado | gestionado
      novedades: inventario.novedades || null,
      gestionado_por_id: inventario.gestionadoPorId || null,
      gestionado_por_nombre: inventario.gestionadoPorNombre || null,
      fecha_gestion: inventario.fechaGestion || null,
      empresa_id: empresaId,
      created_at: inventario.createdAt || new Date().toISOString()
    };
    
    console.log("📦 Payload inventario integral:", payload);
    
    const { data, error } = await supabase
      .from('inventarios_integrales')
      .upsert([payload], { onConflict: 'id' })
      .select();
    
    if (error) {
      console.error("❌ Error guardando inventario integral:", error);
      console.error("❌ Detalle del error:", error.message, error.details, error.hint);
      throw error;
    }
    
    console.log("✅ Inventario integral guardado:", data);
    return data[0];
  } catch (e) {
    console.error("❌ Error en guardarInventarioIntegralEnSupabase:", e);
    throw e;
  }
}

// Cargar inventarios integrales desde Supabase
async function cargarInventariosIntegralesDeSupabase(empresaId = null, empleadoId = null, verTodos = false) {
  try {
    let query = supabase
      .from('inventarios_integrales')
      .select('*')
      .order('created_at', { ascending: false });
    
    if (empresaId) {
      query = query.eq('empresa_id', empresaId);
    }
    
    // Si no puede ver todos, solo mostrar los propios
    if (!verTodos && empleadoId) {
      query = query.eq('empleado_id', empleadoId);
    }
    
    const { data, error } = await query;
    
    if (error) {
      console.error("❌ Error cargando inventarios integrales:", error);
      return [];
    }
    
    return (data || []).map(row => ({
      id: row.id,
      fecha: row.fecha,
      sedeId: row.sede_id,
      sedeNombre: row.sede_nombre,
      empleadoId: row.empleado_id,
      empleadoNombre: row.empleado_nombre,
      lineas: typeof row.lineas === 'string' ? JSON.parse(row.lineas) : (row.lineas || []),
      estado: row.estado,
      novedades: row.novedades,
      gestionadoPorId: row.gestionado_por_id,
      gestionadoPorNombre: row.gestionado_por_nombre,
      fechaGestion: row.fecha_gestion,
      empresaId: row.empresa_id,
      createdAt: row.created_at
    }));
  } catch (e) {
    console.error("❌ Error en cargarInventariosIntegralesDeSupabase:", e);
    return [];
  }
}

// Componente principal de Inventario Integral
export function InventarioIntegralRoot({ 
  sedes, 
  empleados, 
  tienePermiso, 
  filtroEmpresa, 
  usuarioActual, 
  empleadoActual,
  productosBase = []
}) {
  const [vista, setVista] = useState("lista"); // "lista" | "crear" | "ver" | "gestionar"
  const [inventarios, setInventarios] = useState([]);
  const [cargando, setCargando] = useState(false);
  const [inventarioSeleccionado, setInventarioSeleccionado] = useState(null);
  const [guardando, setGuardando] = useState(false);
  
  // Estado para crear nuevo inventario
  const [nuevoInventario, setNuevoInventario] = useState({
    fecha: toISO(new Date()),
    sedeId: '',
    sedeNombre: '',
    lineas: productosBase.map(nombre => ({
      id: crypto.randomUUID(),
      producto: nombre,
      existencia: '',
      productoSolicitado: ''
    })),
    novedades: ''
  });
  
  // Filtros
  const [filtroEstado, setFiltroEstado] = useState("todos");
  const [filtroSede, setFiltroSede] = useState("");
  
  // Cargar inventarios al montar
  useEffect(() => {
    cargarInventarios();
  }, []);
  
  async function cargarInventarios() {
    setCargando(true);
    try {
      const puedeVerTodos = tienePermiso("admin_inventario_integral_ver_todos") || tienePermiso("admin_inventario_integral_gestionar");
      const data = await cargarInventariosIntegralesDeSupabase(
        filtroEmpresa, 
        empleadoActual?.id, 
        puedeVerTodos
      );
      setInventarios(data);
    } catch (e) {
      console.error("Error cargando inventarios:", e);
    }
    setCargando(false);
  }
  
  // Guardar nuevo inventario
  async function handleGuardarNuevo(estado = 'borrador') {
    if (!nuevoInventario.sedeId) {
      alert("Debes seleccionar una sede");
      return;
    }
    
    // Validar que al menos un producto tenga existencia
    const tieneExistencias = nuevoInventario.lineas.some(l => l.existencia && l.existencia.trim());
    if (!tieneExistencias && estado === 'enviado') {
      alert("Debes ingresar la existencia de al menos un producto antes de enviar");
      return;
    }
    
    setGuardando(true);
    try {
      const inventarioData = {
        id: crypto.randomUUID(),
        fecha: nuevoInventario.fecha,
        sedeId: nuevoInventario.sedeId,
        sedeNombre: nuevoInventario.sedeNombre,
        empleadoId: empleadoActual?.id || usuarioActual?.id,
        empleadoNombre: empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email,
        lineas: nuevoInventario.lineas,
        estado: estado,
        novedades: nuevoInventario.novedades,
        createdAt: new Date().toISOString()
      };
      
      await guardarInventarioIntegralEnSupabase(inventarioData, filtroEmpresa);
      
      // Notificar si se envió
      if (estado === 'enviado') {
        alert("✅ Inventario integral enviado correctamente. Ahora está disponible para gestión.");
      } else {
        alert("✅ Inventario guardado como borrador.");
      }
      
      // Resetear y volver a lista
      setNuevoInventario({
        fecha: toISO(new Date()),
        sedeId: '',
        sedeNombre: '',
        lineas: productosBase.map(nombre => ({
          id: crypto.randomUUID(),
          producto: nombre,
          existencia: '',
          productoSolicitado: ''
        })),
        novedades: ''
      });
      await cargarInventarios();
      setVista("lista");
    } catch (e) {
      console.error("Error guardando:", e);
      alert("Error al guardar: " + e.message);
    }
    setGuardando(false);
  }
  
  // Gestionar inventario (agregar producto solicitado)
  async function handleGestionar(inventario, nuevasLineas) {
    setGuardando(true);
    try {
      const inventarioActualizado = {
        ...inventario,
        lineas: nuevasLineas,
        estado: 'gestionado',
        gestionadoPorId: empleadoActual?.id || usuarioActual?.id,
        gestionadoPorNombre: empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email,
        fechaGestion: new Date().toISOString()
      };
      
      await guardarInventarioIntegralEnSupabase(inventarioActualizado, filtroEmpresa);
      alert("✅ Inventario gestionado correctamente.");
      await cargarInventarios();
      setVista("lista");
      setInventarioSeleccionado(null);
    } catch (e) {
      console.error("Error gestionando:", e);
      alert("Error al gestionar: " + e.message);
    }
    setGuardando(false);
  }
  
  // Filtrar inventarios
  const inventariosFiltrados = inventarios.filter(inv => {
    if (filtroEstado !== "todos" && inv.estado !== filtroEstado) return false;
    if (filtroSede && inv.sedeId !== filtroSede) return false;
    return true;
  });
  
  // Colores por estado
  const getEstadoStyle = (estado) => {
    switch(estado) {
      case 'borrador': return { bg: '#f3f4f6', color: '#6b7280', label: '📝 Borrador' };
      case 'enviado': return { bg: '#fef3c7', color: '#d97706', label: '📤 Enviado' };
      case 'gestionado': return { bg: '#dcfce7', color: '#16a34a', label: '✅ Gestionado' };
      default: return { bg: '#f3f4f6', color: '#6b7280', label: estado };
    }
  };

  return (
    <div style={{ padding: 0 }}>
      {/* Header */}
      <div style={{ 
        background: 'linear-gradient(135deg, #7c3aed 0%, #a78bfa 100%)', 
        borderRadius: 12, 
        padding: 20, 
        marginBottom: 20,
        color: 'white'
      }}>
        <h2 style={{ margin: 0, fontSize: 22, fontWeight: 700, display: 'flex', alignItems: 'center', gap: 10 }}>
          <span style={{ fontSize: 28 }}>📊</span>
          Inventario Integral
        </h2>
        <p style={{ margin: '8px 0 0', fontSize: 13, opacity: 0.9 }}>
          Conteo físico completo con flujo de gestión y solicitud de productos
        </p>
      </div>
      
      {/* Tabs de navegación */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
        {(tienePermiso("admin_inventario_integral_ver") || tienePermiso("admin_inventario_integral_ver_todos")) && (
          <button
            onClick={() => { setVista("lista"); setInventarioSeleccionado(null); }}
            style={{
              padding: '10px 18px',
              borderRadius: 10,
              border: 'none',
              cursor: 'pointer',
              fontSize: 13,
              fontWeight: 600,
              background: vista === "lista" ? 'linear-gradient(135deg, #7c3aed 0%, #a78bfa 100%)' : '#f3f4f6',
              color: vista === "lista" ? 'white' : '#374151'
            }}
          >
            📋 Ver Inventarios
          </button>
        )}
        {tienePermiso("admin_inventario_integral_crear") && (
          <button
            onClick={() => setVista("crear")}
            style={{
              padding: '10px 18px',
              borderRadius: 10,
              border: 'none',
              cursor: 'pointer',
              fontSize: 13,
              fontWeight: 600,
              background: vista === "crear" ? 'linear-gradient(135deg, #7c3aed 0%, #a78bfa 100%)' : '#f3f4f6',
              color: vista === "crear" ? 'white' : '#374151'
            }}
          >
            ➕ Crear Inventario
          </button>
        )}
      </div>
      
      {/* VISTA: LISTA DE INVENTARIOS */}
      {vista === "lista" && (
        <div>
          {/* Filtros */}
          <div style={{ display: 'flex', gap: 12, marginBottom: 16, flexWrap: 'wrap', alignItems: 'flex-end' }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: '#64748b', marginBottom: 4 }}>Estado</label>
              <select 
                value={filtroEstado} 
                onChange={(e) => setFiltroEstado(e.target.value)}
                style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e2e8f0', fontSize: 13 }}
              >
                <option value="todos">Todos</option>
                <option value="borrador">📝 Borrador</option>
                <option value="enviado">📤 Enviado</option>
                <option value="gestionado">✅ Gestionado</option>
              </select>
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 600, color: '#64748b', marginBottom: 4 }}>Sede</label>
              <select 
                value={filtroSede} 
                onChange={(e) => setFiltroSede(e.target.value)}
                style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #e2e8f0', fontSize: 13 }}
              >
                <option value="">Todas las sedes</option>
                {sedes.map(s => (
                  <option key={s.id} value={s.id}>{s.nombre}</option>
                ))}
              </select>
            </div>
            <button
              onClick={cargarInventarios}
              style={{
                padding: '8px 16px',
                borderRadius: 8,
                border: '1px solid #7c3aed',
                background: 'white',
                color: '#7c3aed',
                fontWeight: 600,
                fontSize: 13,
                cursor: 'pointer'
              }}
            >
              🔄 Actualizar
            </button>
          </div>
          
          {/* Lista de inventarios */}
          {cargando ? (
            <div style={{ textAlign: 'center', padding: 40, color: '#64748b' }}>
              <div style={{ fontSize: 40, marginBottom: 12 }}>⏳</div>
              Cargando inventarios...
            </div>
          ) : inventariosFiltrados.length === 0 ? (
            <div style={{ textAlign: 'center', padding: 40, color: '#64748b', background: '#faf5ff', borderRadius: 12, border: '2px dashed #e9d5ff' }}>
              <div style={{ fontSize: 48, marginBottom: 12 }}>📭</div>
              <p style={{ margin: 0, fontSize: 15 }}>No hay inventarios integrales</p>
              <p style={{ margin: '8px 0 0', fontSize: 13, color: '#a78bfa' }}>
                {tienePermiso("admin_inventario_integral_crear") ? "Crea uno nuevo usando el botón 'Crear Inventario'" : "No tienes inventarios registrados"}
              </p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {inventariosFiltrados.map((inv) => {
                const estadoStyle = getEstadoStyle(inv.estado);
                const puedeGestionar = tienePermiso("admin_inventario_integral_gestionar") && inv.estado === 'enviado';
                const puedeEditar = tienePermiso("admin_inventario_integral_editar") || (inv.empleadoId === empleadoActual?.id && inv.estado === 'borrador');
                
                return (
                  <div
                    key={inv.id}
                    style={{
                      background: 'white',
                      borderRadius: 12,
                      padding: 16,
                      border: '2px solid #e9d5ff',
                      boxShadow: '0 2px 8px rgba(124, 58, 237, 0.1)'
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12, flexWrap: 'wrap', gap: 12 }}>
                      <div>
                        <div style={{ fontSize: 16, fontWeight: 700, color: '#1a1a2e', marginBottom: 4 }}>
                          🏢 {inv.sedeNombre}
                        </div>
                        <div style={{ fontSize: 13, color: '#64748b' }}>
                          📅 {new Date(inv.fecha + 'T12:00:00').toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
                        </div>
                      </div>
                      <span style={{
                        padding: '6px 14px',
                        borderRadius: 20,
                        fontSize: 12,
                        fontWeight: 600,
                        background: estadoStyle.bg,
                        color: estadoStyle.color
                      }}>
                        {estadoStyle.label}
                      </span>
                    </div>
                    
                    <div style={{ display: 'flex', gap: 16, marginBottom: 12, flexWrap: 'wrap', fontSize: 13 }}>
                      <div>
                        <span style={{ color: '#64748b' }}>Creado por: </span>
                        <span style={{ fontWeight: 600 }}>{inv.empleadoNombre}</span>
                      </div>
                      <div>
                        <span style={{ color: '#64748b' }}>Productos: </span>
                        <span style={{ fontWeight: 600 }}>{inv.lineas?.filter(l => l.existencia).length || 0}/{inv.lineas?.length || 0}</span>
                      </div>
                      {inv.gestionadoPorNombre && (
                        <div>
                          <span style={{ color: '#64748b' }}>Gestionado por: </span>
                          <span style={{ fontWeight: 600, color: '#16a34a' }}>{inv.gestionadoPorNombre}</span>
                        </div>
                      )}
                    </div>
                    
                    {inv.novedades && (
                      <div style={{ background: '#fef3c7', padding: 10, borderRadius: 8, marginBottom: 12, fontSize: 12 }}>
                        <span style={{ fontWeight: 600, color: '#92400e' }}>📝 Novedades: </span>
                        <span style={{ color: '#78350f' }}>{inv.novedades}</span>
                      </div>
                    )}
                    
                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                      <button
                        onClick={() => { setInventarioSeleccionado(inv); setVista("ver"); }}
                        style={{
                          padding: '8px 14px',
                          borderRadius: 8,
                          border: '1px solid #7c3aed',
                          background: 'white',
                          color: '#7c3aed',
                          fontWeight: 600,
                          fontSize: 12,
                          cursor: 'pointer'
                        }}
                      >
                        👁️ Ver Detalle
                      </button>
                      {puedeGestionar && (
                        <button
                          onClick={() => { setInventarioSeleccionado(inv); setVista("gestionar"); }}
                          style={{
                            padding: '8px 14px',
                            borderRadius: 8,
                            border: 'none',
                            background: 'linear-gradient(135deg, #16a34a 0%, #22c55e 100%)',
                            color: 'white',
                            fontWeight: 600,
                            fontSize: 12,
                            cursor: 'pointer'
                          }}
                        >
                          ✅ Gestionar
                        </button>
                      )}
                      {puedeEditar && inv.estado === 'borrador' && (
                        <button
                          onClick={() => { 
                            setNuevoInventario({
                              ...inv,
                              sedeId: inv.sedeId,
                              sedeNombre: inv.sedeNombre
                            });
                            setInventarioSeleccionado(inv);
                            setVista("crear"); 
                          }}
                          style={{
                            padding: '8px 14px',
                            borderRadius: 8,
                            border: '1px solid #d97706',
                            background: 'white',
                            color: '#d97706',
                            fontWeight: 600,
                            fontSize: 12,
                            cursor: 'pointer'
                          }}
                        >
                          ✏️ Continuar
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
      
      {/* VISTA: CREAR INVENTARIO */}
      {vista === "crear" && tienePermiso("admin_inventario_integral_crear") && (
        <div style={{ background: 'white', borderRadius: 12, padding: 20, border: '2px solid #e9d5ff' }}>
          <h3 style={{ margin: '0 0 20px', fontSize: 18, fontWeight: 700, color: '#7c3aed' }}>
            ➕ {inventarioSeleccionado ? 'Editar' : 'Nuevo'} Inventario Integral
          </h3>
          
          {/* Cabecera del inventario */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16, marginBottom: 20 }}>
            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: '#374151', marginBottom: 6 }}>📅 Fecha</label>
              <input
                type="date"
                value={nuevoInventario.fecha}
                onChange={(e) => setNuevoInventario(prev => ({ ...prev, fecha: e.target.value }))}
                style={{ width: '100%', padding: '10px 12px', borderRadius: 8, border: '2px solid #e9d5ff', fontSize: 14 }}
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: '#374151', marginBottom: 6 }}>🏢 Sede *</label>
              <select
                value={nuevoInventario.sedeId}
                onChange={(e) => {
                  const sede = sedes.find(s => s.id === e.target.value);
                  setNuevoInventario(prev => ({ 
                    ...prev, 
                    sedeId: e.target.value,
                    sedeNombre: sede?.nombre || ''
                  }));
                }}
                style={{ width: '100%', padding: '10px 12px', borderRadius: 8, border: '2px solid #e9d5ff', fontSize: 14 }}
              >
                <option value="">Selecciona una sede</option>
                {sedes.map(s => (
                  <option key={s.id} value={s.id}>{s.nombre}</option>
                ))}
              </select>
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: '#374151', marginBottom: 6 }}>👤 Diligenciado por</label>
              <input
                type="text"
                value={empleadoActual?.nombre || usuarioActual?.nombre || usuarioActual?.email || 'Usuario'}
                disabled
                style={{ width: '100%', padding: '10px 12px', borderRadius: 8, border: '2px solid #e9d5ff', fontSize: 14, background: '#f8fafc', color: '#64748b' }}
              />
            </div>
          </div>
          
          {/* Tabla de productos - DOS COLUMNAS */}
          <div style={{ marginBottom: 20 }}>
            <h4 style={{ margin: '0 0 12px', fontSize: 14, fontWeight: 600, color: '#374151' }}>
              📦 Productos ({nuevoInventario.lineas.filter(l => l.existencia).length}/{nuevoInventario.lineas.length} diligenciados)
            </h4>
            <div style={{ overflowX: 'auto', border: '2px solid #e9d5ff', borderRadius: 10 }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                <thead>
                  <tr style={{ background: 'linear-gradient(135deg, #f5f3ff 0%, #ede9fe 100%)' }}>
                    <th style={{ padding: 10, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #e9d5ff', width: 35 }}>#</th>
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff' }}>Producto</th>
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff', minWidth: 150 }}>Existencia *</th>
                    <th style={{ padding: 10, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #e9d5ff', width: 35, background: '#ede9fe', borderLeft: '2px solid #e9d5ff' }}>#</th>
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff', background: '#ede9fe' }}>Producto</th>
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff', minWidth: 150, background: '#ede9fe' }}>Existencia *</th>
                  </tr>
                </thead>
                <tbody>
                  {(() => {
                    // Dividir productos en dos mitades para mostrar en dos columnas
                    const mitad = Math.ceil(nuevoInventario.lineas.length / 2);
                    const filas = [];
                    for (let i = 0; i < mitad; i++) {
                      const lineaIzq = nuevoInventario.lineas[i];
                      const lineaDer = nuevoInventario.lineas[i + mitad];
                      const idxIzq = i;
                      const idxDer = i + mitad;
                      
                      filas.push(
                        <tr key={lineaIzq.id} style={{ background: i % 2 === 0 ? 'white' : '#faf5ff', borderBottom: '1px solid #f3e8ff' }}>
                          {/* Columna izquierda */}
                          <td style={{ padding: '8px 10px', textAlign: 'center', color: '#64748b', fontWeight: 500, fontSize: 11 }}>{idxIzq + 1}</td>
                          <td style={{ padding: '8px 10px', fontWeight: 600, fontSize: 12 }}>{lineaIzq.producto}</td>
                          <td style={{ padding: '6px 8px' }}>
                            <input
                              type="text"
                              value={lineaIzq.existencia}
                              onChange={(e) => {
                                const nuevasLineas = [...nuevoInventario.lineas];
                                nuevasLineas[idxIzq].existencia = e.target.value;
                                setNuevoInventario(prev => ({ ...prev, lineas: nuevasLineas }));
                              }}
                              placeholder="Ej: 2 cajas"
                              style={{ 
                                width: '100%', 
                                padding: '6px 10px', 
                                borderRadius: 6, 
                                border: `2px solid ${lineaIzq.existencia ? '#a78bfa' : '#e9d5ff'}`,
                                fontSize: 12,
                                background: lineaIzq.existencia ? '#f5f3ff' : 'white'
                              }}
                            />
                          </td>
                          {/* Columna derecha */}
                          {lineaDer ? (
                            <>
                              <td style={{ padding: '8px 10px', textAlign: 'center', color: '#64748b', fontWeight: 500, fontSize: 11, borderLeft: '2px solid #e9d5ff', background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>{idxDer + 1}</td>
                              <td style={{ padding: '8px 10px', fontWeight: 600, fontSize: 12, background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>{lineaDer.producto}</td>
                              <td style={{ padding: '6px 8px', background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>
                                <input
                                  type="text"
                                  value={lineaDer.existencia}
                                  onChange={(e) => {
                                    const nuevasLineas = [...nuevoInventario.lineas];
                                    nuevasLineas[idxDer].existencia = e.target.value;
                                    setNuevoInventario(prev => ({ ...prev, lineas: nuevasLineas }));
                                  }}
                                  placeholder="Ej: 2 cajas"
                                  style={{ 
                                    width: '100%', 
                                    padding: '6px 10px', 
                                    borderRadius: 6, 
                                    border: `2px solid ${lineaDer.existencia ? '#a78bfa' : '#e9d5ff'}`,
                                    fontSize: 12,
                                    background: lineaDer.existencia ? '#f5f3ff' : 'white'
                                  }}
                                />
                              </td>
                            </>
                          ) : (
                            <>
                              <td style={{ padding: '8px 10px', borderLeft: '2px solid #e9d5ff', background: '#f8fafc' }}></td>
                              <td style={{ padding: '8px 10px', background: '#f8fafc' }}></td>
                              <td style={{ padding: '6px 8px', background: '#f8fafc' }}></td>
                            </>
                          )}
                        </tr>
                      );
                    }
                    return filas;
                  })()}
                </tbody>
              </table>
            </div>
          </div>
          
          {/* Novedades */}
          <div style={{ marginBottom: 20 }}>
            <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: '#374151', marginBottom: 6 }}>📝 Novedades (opcional)</label>
            <textarea
              value={nuevoInventario.novedades}
              onChange={(e) => setNuevoInventario(prev => ({ ...prev, novedades: e.target.value }))}
              placeholder="Observaciones, productos dañados, faltantes importantes, etc."
              rows={3}
              style={{ width: '100%', padding: '10px 12px', borderRadius: 8, border: '2px solid #e9d5ff', fontSize: 13, resize: 'vertical' }}
            />
          </div>
          
          {/* Botones de acción */}
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', flexWrap: 'wrap' }}>
            <button
              onClick={() => { setVista("lista"); setInventarioSeleccionado(null); }}
              style={{
                padding: '12px 24px',
                borderRadius: 10,
                border: '2px solid #e2e8f0',
                background: 'white',
                color: '#64748b',
                fontWeight: 600,
                fontSize: 14,
                cursor: 'pointer'
              }}
            >
              Cancelar
            </button>
            <button
              onClick={() => handleGuardarNuevo('borrador')}
              disabled={guardando}
              style={{
                padding: '12px 24px',
                borderRadius: 10,
                border: '2px solid #d97706',
                background: 'white',
                color: '#d97706',
                fontWeight: 600,
                fontSize: 14,
                cursor: guardando ? 'not-allowed' : 'pointer',
                opacity: guardando ? 0.7 : 1
              }}
            >
              {guardando ? '⏳ Guardando...' : '💾 Guardar Borrador'}
            </button>
            <button
              onClick={() => handleGuardarNuevo('enviado')}
              disabled={guardando}
              style={{
                padding: '12px 24px',
                borderRadius: 10,
                border: 'none',
                background: guardando ? '#94a3b8' : 'linear-gradient(135deg, #7c3aed 0%, #a78bfa 100%)',
                color: 'white',
                fontWeight: 600,
                fontSize: 14,
                cursor: guardando ? 'not-allowed' : 'pointer',
                boxShadow: '0 4px 12px rgba(124, 58, 237, 0.3)'
              }}
            >
              {guardando ? '⏳ Enviando...' : '📤 Guardar y Enviar'}
            </button>
          </div>
        </div>
      )}
      
      {/* VISTA: VER DETALLE */}
      {vista === "ver" && inventarioSeleccionado && (
        <div style={{ background: 'white', borderRadius: 12, padding: 20, border: '2px solid #e9d5ff' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
            <div>
              <h3 style={{ margin: '0 0 8px', fontSize: 18, fontWeight: 700, color: '#7c3aed' }}>
                📊 Detalle Inventario Integral
              </h3>
              <div style={{ fontSize: 14, color: '#64748b' }}>
                🏢 {inventarioSeleccionado.sedeNombre} • 📅 {new Date(inventarioSeleccionado.fecha + 'T12:00:00').toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
              </div>
            </div>
            <span style={{
              padding: '6px 14px',
              borderRadius: 20,
              fontSize: 12,
              fontWeight: 600,
              background: getEstadoStyle(inventarioSeleccionado.estado).bg,
              color: getEstadoStyle(inventarioSeleccionado.estado).color
            }}>
              {getEstadoStyle(inventarioSeleccionado.estado).label}
            </span>
          </div>
          
          {/* Info del creador y gestor */}
          <div style={{ display: 'flex', gap: 20, marginBottom: 20, flexWrap: 'wrap', fontSize: 13 }}>
            <div style={{ background: '#f5f3ff', padding: 12, borderRadius: 8 }}>
              <span style={{ color: '#64748b' }}>Creado por: </span>
              <span style={{ fontWeight: 600, color: '#7c3aed' }}>{inventarioSeleccionado.empleadoNombre}</span>
            </div>
            {inventarioSeleccionado.gestionadoPorNombre && (
              <div style={{ background: '#f0fdf4', padding: 12, borderRadius: 8 }}>
                <span style={{ color: '#64748b' }}>Gestionado por: </span>
                <span style={{ fontWeight: 600, color: '#16a34a' }}>{inventarioSeleccionado.gestionadoPorNombre}</span>
                <span style={{ color: '#64748b', marginLeft: 8, fontSize: 11 }}>
                  ({new Date(inventarioSeleccionado.fechaGestion).toLocaleString('es-CO')})
                </span>
              </div>
            )}
          </div>
          
          {inventarioSeleccionado.novedades && (
            <div style={{ background: '#fef3c7', padding: 12, borderRadius: 8, marginBottom: 16 }}>
              <span style={{ fontWeight: 600, color: '#92400e' }}>📝 Novedades: </span>
              <span style={{ color: '#78350f' }}>{inventarioSeleccionado.novedades}</span>
            </div>
          )}
          
          {/* Tabla de productos - DOS COLUMNAS */}
          <div style={{ overflowX: 'auto', border: '2px solid #e9d5ff', borderRadius: 10, marginBottom: 20 }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: 'linear-gradient(135deg, #f5f3ff 0%, #ede9fe 100%)' }}>
                  <th style={{ padding: 10, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #e9d5ff', width: 30 }}>#</th>
                  <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff' }}>Producto</th>
                  <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff' }}>Existencia</th>
                  {inventarioSeleccionado.estado === 'gestionado' && (
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#bbf7d0' }}>Solicitado</th>
                  )}
                  <th style={{ padding: 10, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #e9d5ff', width: 30, borderLeft: '2px solid #e9d5ff', background: '#ede9fe' }}>#</th>
                  <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff', background: '#ede9fe' }}>Producto</th>
                  <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #e9d5ff', background: '#ede9fe' }}>Existencia</th>
                  {inventarioSeleccionado.estado === 'gestionado' && (
                    <th style={{ padding: 10, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#bbf7d0' }}>Solicitado</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {(() => {
                  const mitad = Math.ceil(inventarioSeleccionado.lineas.length / 2);
                  const filas = [];
                  for (let i = 0; i < mitad; i++) {
                    const lineaIzq = inventarioSeleccionado.lineas[i];
                    const lineaDer = inventarioSeleccionado.lineas[i + mitad];
                    
                    filas.push(
                      <tr key={lineaIzq.id || i} style={{ background: i % 2 === 0 ? 'white' : '#faf5ff', borderBottom: '1px solid #f3e8ff' }}>
                        {/* Columna izquierda */}
                        <td style={{ padding: '8px 10px', textAlign: 'center', color: '#64748b', fontSize: 11 }}>{i + 1}</td>
                        <td style={{ padding: '8px 10px', fontWeight: 600, fontSize: 12 }}>{lineaIzq.producto}</td>
                        <td style={{ padding: '8px 10px', color: lineaIzq.existencia ? '#374151' : '#94a3b8', fontSize: 12 }}>
                          {lineaIzq.existencia || '—'}
                        </td>
                        {inventarioSeleccionado.estado === 'gestionado' && (
                          <td style={{ padding: '8px 10px', color: lineaIzq.productoSolicitado ? '#16a34a' : '#94a3b8', fontWeight: lineaIzq.productoSolicitado ? 600 : 400, fontSize: 12, background: i % 2 === 0 ? '#dcfce7' : '#bbf7d0' }}>
                            {lineaIzq.productoSolicitado || '—'}
                          </td>
                        )}
                        {/* Columna derecha */}
                        {lineaDer ? (
                          <>
                            <td style={{ padding: '8px 10px', textAlign: 'center', color: '#64748b', fontSize: 11, borderLeft: '2px solid #e9d5ff', background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>{i + mitad + 1}</td>
                            <td style={{ padding: '8px 10px', fontWeight: 600, fontSize: 12, background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>{lineaDer.producto}</td>
                            <td style={{ padding: '8px 10px', color: lineaDer.existencia ? '#374151' : '#94a3b8', fontSize: 12, background: i % 2 === 0 ? '#faf5ff' : '#f5f3ff' }}>
                              {lineaDer.existencia || '—'}
                            </td>
                            {inventarioSeleccionado.estado === 'gestionado' && (
                              <td style={{ padding: '8px 10px', color: lineaDer.productoSolicitado ? '#16a34a' : '#94a3b8', fontWeight: lineaDer.productoSolicitado ? 600 : 400, fontSize: 12, background: i % 2 === 0 ? '#dcfce7' : '#bbf7d0' }}>
                                {lineaDer.productoSolicitado || '—'}
                              </td>
                            )}
                          </>
                        ) : (
                          <>
                            <td style={{ padding: '8px 10px', borderLeft: '2px solid #e9d5ff', background: '#f8fafc' }}></td>
                            <td style={{ padding: '8px 10px', background: '#f8fafc' }}></td>
                            <td style={{ padding: '8px 10px', background: '#f8fafc' }}></td>
                            {inventarioSeleccionado.estado === 'gestionado' && (
                              <td style={{ padding: '8px 10px', background: '#dcfce7' }}></td>
                            )}
                          </>
                        )}
                      </tr>
                    );
                  }
                  return filas;
                })()}
              </tbody>
            </table>
          </div>
          
          <button
            onClick={() => { setVista("lista"); setInventarioSeleccionado(null); }}
            style={{
              padding: '12px 24px',
              borderRadius: 10,
              border: '2px solid #7c3aed',
              background: 'white',
              color: '#7c3aed',
              fontWeight: 600,
              fontSize: 14,
              cursor: 'pointer'
            }}
          >
            ← Volver a la lista
          </button>
        </div>
      )}
      
      {/* VISTA: GESTIONAR */}
      {vista === "gestionar" && inventarioSeleccionado && tienePermiso("admin_inventario_integral_gestionar") && (
        <GestionarInventarioIntegral
          inventario={inventarioSeleccionado}
          onGuardar={handleGestionar}
          onCancelar={() => { setVista("lista"); setInventarioSeleccionado(null); }}
          guardando={guardando}
        />
      )}
    </div>
  );
}

// Componente para gestionar inventario
function GestionarInventarioIntegral({ inventario, onGuardar, onCancelar, guardando }) {
  const [lineas, setLineas] = useState(inventario.lineas.map(l => ({
    ...l,
    productoSolicitado: l.productoSolicitado || ''
  })));
  
  return (
    <div style={{ background: 'white', borderRadius: 12, padding: 20, border: '2px solid #16a34a' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 20, flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h3 style={{ margin: '0 0 8px', fontSize: 18, fontWeight: 700, color: '#16a34a' }}>
            ✅ Gestionar Inventario Integral
          </h3>
          <div style={{ fontSize: 14, color: '#64748b' }}>
            🏢 {inventario.sedeNombre} • 📅 {new Date(inventario.fecha + 'T12:00:00').toLocaleDateString('es-CO', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}
          </div>
          <div style={{ fontSize: 13, color: '#64748b', marginTop: 4 }}>
            Creado por: <strong>{inventario.empleadoNombre}</strong>
          </div>
        </div>
      </div>
      
      {inventario.novedades && (
        <div style={{ background: '#fef3c7', padding: 12, borderRadius: 8, marginBottom: 16 }}>
          <span style={{ fontWeight: 600, color: '#92400e' }}>📝 Novedades del empleado: </span>
          <span style={{ color: '#78350f' }}>{inventario.novedades}</span>
        </div>
      )}
      
      <div style={{ background: '#f0fdf4', padding: 12, borderRadius: 8, marginBottom: 16, border: '1px solid #86efac' }}>
        <span style={{ fontSize: 13, color: '#166534' }}>
          💡 <strong>Indicación:</strong> Revisa las existencias y completa la columna "Producto Solicitado" para indicar cuánto se debe enviar.
        </span>
      </div>
      
      {/* Tabla de productos con columna editable - DOS COLUMNAS */}
      <div style={{ overflowX: 'auto', border: '2px solid #16a34a', borderRadius: 10, marginBottom: 20 }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 11 }}>
          <thead>
            <tr style={{ background: 'linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%)' }}>
              <th style={{ padding: 8, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #16a34a', width: 30 }}>#</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a' }}>Producto</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a' }}>Existencia</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#bbf7d0', minWidth: 120 }}>Solicitado *</th>
              <th style={{ padding: 8, textAlign: 'center', fontWeight: 700, borderBottom: '2px solid #16a34a', width: 30, borderLeft: '2px solid #16a34a', background: '#dcfce7' }}>#</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#dcfce7' }}>Producto</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#dcfce7' }}>Existencia</th>
              <th style={{ padding: 8, textAlign: 'left', fontWeight: 700, borderBottom: '2px solid #16a34a', background: '#86efac', minWidth: 120 }}>Solicitado *</th>
            </tr>
          </thead>
          <tbody>
            {(() => {
              const mitad = Math.ceil(lineas.length / 2);
              const filas = [];
              for (let i = 0; i < mitad; i++) {
                const lineaIzq = lineas[i];
                const lineaDer = lineas[i + mitad];
                const idxIzq = i;
                const idxDer = i + mitad;
                
                filas.push(
                  <tr key={lineaIzq.id || i} style={{ background: i % 2 === 0 ? 'white' : '#f0fdf4', borderBottom: '1px solid #dcfce7' }}>
                    {/* Columna izquierda */}
                    <td style={{ padding: '6px 8px', textAlign: 'center', color: '#64748b', fontSize: 10 }}>{idxIzq + 1}</td>
                    <td style={{ padding: '6px 8px', fontWeight: 600, fontSize: 11 }}>{lineaIzq.producto}</td>
                    <td style={{ padding: '6px 8px', color: lineaIzq.existencia ? '#374151' : '#94a3b8', fontSize: 11 }}>
                      {lineaIzq.existencia || '—'}
                    </td>
                    <td style={{ padding: '4px 6px' }}>
                      <input
                        type="text"
                        value={lineaIzq.productoSolicitado}
                        onChange={(e) => {
                          const nuevasLineas = [...lineas];
                          nuevasLineas[idxIzq].productoSolicitado = e.target.value;
                          setLineas(nuevasLineas);
                        }}
                        placeholder="Ej: 5 cajas"
                        style={{ 
                          width: '100%', 
                          padding: '5px 8px', 
                          borderRadius: 5, 
                          border: `2px solid ${lineaIzq.productoSolicitado ? '#16a34a' : '#86efac'}`,
                          fontSize: 11,
                          background: lineaIzq.productoSolicitado ? '#f0fdf4' : 'white'
                        }}
                      />
                    </td>
                    {/* Columna derecha */}
                    {lineaDer ? (
                      <>
                        <td style={{ padding: '6px 8px', textAlign: 'center', color: '#64748b', fontSize: 10, borderLeft: '2px solid #16a34a', background: i % 2 === 0 ? '#f0fdf4' : '#dcfce7' }}>{idxDer + 1}</td>
                        <td style={{ padding: '6px 8px', fontWeight: 600, fontSize: 11, background: i % 2 === 0 ? '#f0fdf4' : '#dcfce7' }}>{lineaDer.producto}</td>
                        <td style={{ padding: '6px 8px', color: lineaDer.existencia ? '#374151' : '#94a3b8', fontSize: 11, background: i % 2 === 0 ? '#f0fdf4' : '#dcfce7' }}>
                          {lineaDer.existencia || '—'}
                        </td>
                        <td style={{ padding: '4px 6px', background: i % 2 === 0 ? '#f0fdf4' : '#dcfce7' }}>
                          <input
                            type="text"
                            value={lineaDer.productoSolicitado}
                            onChange={(e) => {
                              const nuevasLineas = [...lineas];
                              nuevasLineas[idxDer].productoSolicitado = e.target.value;
                              setLineas(nuevasLineas);
                            }}
                            placeholder="Ej: 5 cajas"
                            style={{ 
                              width: '100%', 
                              padding: '5px 8px', 
                              borderRadius: 5, 
                              border: `2px solid ${lineaDer.productoSolicitado ? '#16a34a' : '#86efac'}`,
                              fontSize: 11,
                              background: lineaDer.productoSolicitado ? '#f0fdf4' : 'white'
                            }}
                          />
                        </td>
                      </>
                    ) : (
                      <>
                        <td style={{ padding: '6px 8px', borderLeft: '2px solid #16a34a', background: '#f8fafc' }}></td>
                        <td style={{ padding: '6px 8px', background: '#f8fafc' }}></td>
                        <td style={{ padding: '6px 8px', background: '#f8fafc' }}></td>
                        <td style={{ padding: '4px 6px', background: '#f8fafc' }}></td>
                      </>
                    )}
                  </tr>
                );
              }
              return filas;
            })()}
          </tbody>
        </table>
      </div>
      
      {/* Botones de acción */}
      <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end', flexWrap: 'wrap' }}>
        <button
          onClick={onCancelar}
          style={{
            padding: '12px 24px',
            borderRadius: 10,
            border: '2px solid #e2e8f0',
            background: 'white',
            color: '#64748b',
            fontWeight: 600,
            fontSize: 14,
            cursor: 'pointer'
          }}
        >
          Cancelar
        </button>
        <button
          onClick={() => onGuardar(inventario, lineas)}
          disabled={guardando}
          style={{
            padding: '12px 24px',
            borderRadius: 10,
            border: 'none',
            background: guardando ? '#94a3b8' : 'linear-gradient(135deg, #16a34a 0%, #22c55e 100%)',
            color: 'white',
            fontWeight: 600,
            fontSize: 14,
            cursor: guardando ? 'not-allowed' : 'pointer',
            boxShadow: '0 4px 12px rgba(22, 163, 74, 0.3)'
          }}
        >
          {guardando ? '⏳ Guardando...' : '✅ Finalizar Gestión'}
        </button>
      </div>
    </div>
  );
}


/* ====================== CREAR / EDITAR CUADRE ====================== */
 
// Denominaciones de billetes/monedas en COP usadas en el cuadre diario
const DENOMINACIONES = [
 
    100000,
    50000,
    20000,
    10000,
    5000,
    2000,
    1000,
    500,
    200,
    100,
    50,
  ];
  
  function CrearCuadre({
    sedes,
    empleados,
    cuadreActivo,
    setCuadreActivoId,
    crearOBuscarBorrador,
    actualizarCuadre,
    actualizarCuadreParcial,
    cuadres,
    guardarFinal,
    guardarComentario,
    realizarPrecierre,
    usuarioActual = null,
    empleadoActual = null,
    esGerente = false,
    tienePermiso = () => true,
    accesosDelCuadre = [],
    usuariosActivosEnCuadre = [],
    ultimaActualizacionRemota = null,
    filtroEmpresa = null,
    bloquearFila = () => {},
    desbloquearFila = () => {},
    filaEstaBloqueadaPorOtro = () => null,
  }) {
    const hoyISO = toISO(new Date());
  
    // Obtener el ID del empleado actual basado en el usuario autenticado
    const empleadoActualId = empleadoActual?.id || usuarioActual?.id || "";

    // Selección inicial
    const [sedeSel, setSedeSel] = useState("");
    // El empleado se asigna automáticamente al usuario autenticado
    const [empleadoSel, setEmpleadoSel] = useState(empleadoActualId);
    const [valorInicial, setValorInicial] = useState("");
    const [fechaSel, setFechaSel] = useState(hoyISO);
  
    const [totales, setTotales] = useState({});
    const [comentario, setComentario] = useState("");
    
    // Estados para el modal de precierre
    const [mostrarModalPrecierre, setMostrarModalPrecierre] = useState(false);
    const [precierreAsignadoA, setPrecierreAsignadoA] = useState("");
    const [precierreObservaciones, setPrecierreObservaciones] = useState("");
    
    // Estado para el modal de confirmación de precierre recibido
    const [mostrarAlertaConfirmarPrecierre, setMostrarAlertaConfirmarPrecierre] = useState(false);
    
    // 🔹 Estado para el efectivo que ingresa el receptor al confirmar precierre
    const [efectivoReceptor, setEfectivoReceptor] = useState("");
    const [efectivoReceptorConfirmado, setEfectivoReceptorConfirmado] = useState(false);
    
    // Estado para reasignar cuadre (solo Gerencia)
    const [reasignarACuadre, setReasignarACuadre] = useState("");
    
    // Estado para mostrar alertas visuales en la parte superior
    const [alertaCuadre, setAlertaCuadre] = useState({ visible: false, tipo: '', mensaje: '' });
    
    // Función para mostrar alerta visual (se mantiene hasta que el usuario la cierre)
    const mostrarAlertaVisual = (tipo, mensaje) => {
      setAlertaCuadre({ visible: true, tipo, mensaje });
    };

    // Actualizar empleadoSel cuando cambie el empleadoActual
    useEffect(() => {
      if (!cuadreActivo && empleadoActualId) {
        setEmpleadoSel(empleadoActualId);
      }
    }, [empleadoActualId, cuadreActivo]);
  
    // Sincronizar cuando cambio de cuadreActivo (retomar / consultar)
    useEffect(() => {
      if (cuadreActivo) {
        setSedeSel(cuadreActivo.sede || "");
        // Si es gerente, mantener el empleado del cuadre; si no, usar el actual
        setEmpleadoSel(cuadreActivo.empleadoId || empleadoActualId || "");
        setValorInicial(
          cuadreActivo.valorInicial !== undefined &&
          cuadreActivo.valorInicial !== null
            ? String(cuadreActivo.valorInicial)
            : ""
        );
        setFechaSel(cuadreActivo.fecha || hoyISO);
        setTotales(cuadreActivo.totales || {});
        setComentario(cuadreActivo.comentarioModificacion || "");
        
        // Verificar si hay un precierre pendiente de confirmación
        // y si el empleado actual es el receptor del precierre
        if (cuadreActivo.precierrePendienteConfirmacion && 
            cuadreActivo.precierre?.asignadoAId && 
            (cuadreActivo.precierre.asignadoAId === empleadoActualId || 
             cuadreActivo.precierre.asignadoAId === (empleadoActual?.id || usuarioActual?.id))) {
          setMostrarAlertaConfirmarPrecierre(true);
        }
      } else {
        // No hay cuadre activo → limpiar a valores por defecto
        setSedeSel("");
        setEmpleadoSel(empleadoActualId || "");
        setValorInicial("");
        setFechaSel(hoyISO);
        setTotales({});
        setComentario("");
      }
    }, [cuadreActivo, hoyISO, empleadoActualId]);
  
    function iniciarCuadre() {
      if (!sedeSel || !empleadoSel || !valorInicial || !fechaSel) {
        alert("Sede, empleado, fecha y valor inicial son obligatorios");
        return;
      }
  
      // ====================== RESTRICCIÓN: Solo un cuadre en proceso por sede ======================
      // Buscar si hay algún cuadre EN PROCESO (no cerrado) para esta sede, sin importar la fecha
      const cuadreEnProceso = cuadres.find(
        (c) => c.sede === sedeSel && c.estado !== "final"
      );
  
      if (cuadreEnProceso && cuadreEnProceso.fecha !== fechaSel) {
        alert(
          `⚠️ No puedes abrir un nuevo cuadre para la sede "${sedeSel}".

Ya existe un cuadre EN PROCESO del día ${cuadreEnProceso.fecha}.

Debes cerrar primero ese cuadre antes de abrir uno nuevo.`
        );
        return;
      }
      // ====================== FIN RESTRICCIÓN ======================
  
      // Buscar si ya existe un cuadre para esa sede + fecha
      const existente = cuadres.find(
        (c) => c.sede === sedeSel && c.fecha === fechaSel
      );
  
      if (existente && existente.estado === "final") {
        alert(
          `Ya existe un cuadre CERRADO para la sede "${sedeSel}" en la fecha ${fechaSel}. No es posible abrir otro.`
        );
        setCuadreActivoId(existente.id);
        return;
      }
  
      // ====================== FUNCIÓN HELPER: Obtener facturas pendientes de días anteriores ======================
      // Esta función busca facturas pendientes de días anteriores que NO han sido pagadas
      // FILTRO: Solo considera cuadres a partir del 7 de febrero de 2026
      // IDENTIFICACIÓN: Por ID único (origenId), permitiendo múltiples facturas con el mismo nombre
      const FECHA_MINIMA_FACTURAS = "2026-02-07";
      
      const obtenerFacturasPendientesAnteriores = (sede, fecha, facturasActuales = []) => {
        const pendientes = [];
        
        // 🔍 DIAGNÓSTICO: Ver todos los cuadres de esta sede
        const cuadresDeSede = cuadres.filter(c => c.sede === sede);
        console.log(`🔍 [DIAGNÓSTICO] Sede: ${sede}, Fecha actual: ${fecha}`);
        console.log(`🔍 [DIAGNÓSTICO] Total cuadres cargados: ${cuadres.length}`);
        console.log(`🔍 [DIAGNÓSTICO] Cuadres de esta sede: ${cuadresDeSede.length}`);
        cuadresDeSede.forEach(c => {
          console.log(`   📅 Cuadre ${c.fecha} - Estado: ${c.estado} - Facturas: ${(c.facturas || []).length}`);
          (c.facturas || []).forEach(f => {
            console.log(`      💰 ID: ${f.id} - OrigenId: ${f.origenId || 'N/A'} - Factura: ${f.factura || '(vacía)'} - Estado: ${f.estado}`);
          });
        });
        
        // 1. Recolectar todas las facturas que ya fueron pagadas en cualquier cuadre (por origenId Y por id)
        const facturasPagadasPorId = new Set();
        cuadres.forEach((c) => {
          if (c.sede === sede && c.fecha >= FECHA_MINIMA_FACTURAS && Array.isArray(c.facturas)) {
            c.facturas.forEach((f) => {
              const estadoLower = (f.estado || "").toLowerCase();
              if (estadoLower.includes("pagada") || estadoLower.includes("caja") || estadoLower.includes("transferencia")) {
                // Agregar AMBOS IDs para cubrir todos los casos de rastreo
                if (f.id) {
                  facturasPagadasPorId.add(String(f.id));
                }
                if (f.origenId) {
                  facturasPagadasPorId.add(String(f.origenId));
                }
              }
            });
          }
        });
        
        // 2. Recolectar IDs de facturas que YA están en el cuadre actual (para evitar duplicados)
        const idsYaEnCuadre = new Set();
        (facturasActuales || []).forEach((f) => {
          // Agregar tanto el origenId como el id para cubrir todos los casos
          if (f.origenId) {
            idsYaEnCuadre.add(String(f.origenId));
          }
          if (f.id) {
            idsYaEnCuadre.add(String(f.id));
          }
        });
        
        console.log("📋 IDs de facturas ya pagadas:", Array.from(facturasPagadasPorId));
        console.log("📋 IDs ya en cuadre actual:", Array.from(idsYaEnCuadre));
        
        // 3. Buscar facturas pendientes de días anteriores que NO estén pagadas NI ya en el cuadre (por ID único)
        cuadres.forEach((c) => {
          if (c.sede === sede && c.fecha < fecha && c.fecha >= FECHA_MINIMA_FACTURAS && Array.isArray(c.facturas)) {
            c.facturas.forEach((f) => {
              const estadoLower = (f.estado || "").toLowerCase();
              if (estadoLower === "pendiente" || estadoLower.includes("pendiente")) {
                // El ID único es el origenId si existe, sino el id de la factura
                const idUnico = f.origenId || f.id;
                
                // Solo agregar si:
                // - La factura tiene ID
                // - NO ha sido pagada en ningún cuadre (por ID)
                // - NO está ya en el cuadre actual (por ID)
                if (idUnico && !facturasPagadasPorId.has(String(idUnico)) && !idsYaEnCuadre.has(String(idUnico))) {
                  // IMPORTANTE: Preservar el origenId original si ya existe (factura que pasó por múltiples cuadres)
                  // Si no tiene origenId, usar su id como origenId
                  const origenIdReal = f.origenId || f.id;
                  pendientes.push({
                    id: uid(),
                    origenId: origenIdReal, // SIEMPRE el ID de la factura original
                    factura: f.factura,
                    valor: f.valor,
                    estado: "Pendiente",
                    origenFecha: f.origenFecha || c.fecha,
                  });
                  console.log(`⏳ Factura pendiente cargada: ${f.factura} (origenId: ${origenIdReal}) - Origen: ${f.origenFecha || c.fecha}`);
                } else if (idUnico && facturasPagadasPorId.has(String(idUnico))) {
                  console.log(`✅ Factura ${f.factura} (ID: ${idUnico}) ya fue pagada - NO se carga como pendiente`);
                } else if (idUnico && idsYaEnCuadre.has(String(idUnico))) {
                  console.log(`🔄 Factura ${f.factura} (ID: ${idUnico}) ya está en el cuadre actual - NO se duplica`);
                }
              }
            });
          }
        });
        
        return pendientes;
      };
      // ====================== FIN FUNCIÓN HELPER ======================
      
      if (existente && existente.estado !== "final") {
        // RETOMAR CUADRE EXISTENTE - pero verificar si hay nuevas facturas pendientes que agregar
        console.log("🔄 Retomando cuadre existente, verificando facturas pendientes faltantes...");
        
        const pendientesFaltantes = obtenerFacturasPendientesAnteriores(
          sedeSel, 
          fechaSel, 
          existente.facturas || []
        );
        
        if (pendientesFaltantes.length > 0) {
          console.log(`📥 Agregando ${pendientesFaltantes.length} facturas pendientes faltantes al cuadre existente`);
          
          // Agregar las facturas pendientes faltantes al inicio del array de facturas
          const facturasActualizadas = [...pendientesFaltantes, ...(existente.facturas || [])];
          
          // Actualizar el cuadre con las nuevas facturas
          actualizarCuadre(existente.id, {
            facturas: facturasActualizadas,
          });
          
          alert(
            `Ya existe un cuadre EN PROCESO para la sede "${sedeSel}" en la fecha ${fechaSel}. ` +
            `Se retomará y se agregaron ${pendientesFaltantes.length} factura(s) pendiente(s) de días anteriores.`
          );
        } else {
          alert(
            `Ya existe un cuadre EN PROCESO para la sede "${sedeSel}" en la fecha ${fechaSel}. Se retomará ese mismo.`
          );
        }
        
        setCuadreActivoId(existente.id);
        return;
      }
  
      // No existe ninguno → crear nuevo
      const base = crearOBuscarBorrador({ sede: sedeSel, fecha: fechaSel });
  
      actualizarCuadre(base.id, {
        empleadoId: empleadoSel,
        valorInicial: Number(valorInicial || 0),
      });
  
      // Cargar facturas pendientes de días anteriores de la misma sede
      const pendientes = obtenerFacturasPendientesAnteriores(sedeSel, fechaSel, base.facturas);
  
      let facturasInicial = base.facturas;
      if (!facturasInicial || !facturasInicial.length) {
        facturasInicial = [
          { id: uid(), factura: "", valor: "", estado: "Pagada de caja", origenFecha: fechaSel },
        ];
      }
      
      // Evitar duplicados por ID: solo agregar pendientes cuyos origenId no estén ya en facturasInicial
      const idsExistentes = new Set();
      facturasInicial.forEach(f => {
        if (f.id) idsExistentes.add(String(f.id));
        if (f.origenId) idsExistentes.add(String(f.origenId));
      });
      
      const pendientesSinDuplicar = pendientes.filter(p => {
        const idUnico = p.origenId || p.id;
        return idUnico && !idsExistentes.has(String(idUnico));
      });
      
      facturasInicial = [...pendientesSinDuplicar, ...facturasInicial];
  
      const domiciliosInicial =
        base.domicilios && base.domicilios.length
          ? base.domicilios
              .filter(d => d && d.id) // Solo conservar items con ID válido
              .map(d => ({
                ...d,
                pago_confirmado: d.pago_confirmado || false,
              }))
          : []; // NO crear filas vacías automáticamente - el usuario las agregará
  
      const transferInicial =
        base.transfer && base.transfer.length
          ? base.transfer
              .filter(t => t && t.id) // Solo conservar items con ID válido
              .map(t => ({
                ...t,
                bancolombia_confirmado: t.bancolombia_confirmado || false,
                davivienda_confirmado: t.davivienda_confirmado || false,
                daviplata_confirmado: t.daviplata_confirmado || false,
                nequi_confirmado: t.nequi_confirmado || false,
              }))
          : []; // NO crear filas vacías automáticamente
  
      const denomsBase =
        base.denoms && base.denoms.length
          ? base.denoms
          : DENOMINACIONES.map((v) => ({
              valor: v,
              cantidad: 0,
              subtotal: 0,
            }));
  
      actualizarCuadre(base.id, {
        facturas: facturasInicial,
        domicilios: domiciliosInicial,
        transfer: transferInicial,
        denoms: denomsBase,
      });
  
      setCuadreActivoId(base.id);
    }
  
    const bloqueado = cuadreActivo?.estado === "final";
    const empleado = cuadreActivo
      ? empleados.find((e) => e.id === cuadreActivo.empleadoId)
      : null;

    // Calcular totales de transferencias (debe estar antes de cualquier return)
    const totalesTransfer = useMemo(() => {
      const transfer = cuadreActivo?.transfer || [];
      let bancolombia = 0, davivienda = 0, daviplata = 0, nequi = 0;
      transfer.forEach((t) => {
        bancolombia += Number(t.bancolombia || 0);
        davivienda += Number(t.davivienda || 0);
        daviplata += Number(t.daviplata || 0);
        nequi += Number(t.nequi || 0);
      });
      return { bancolombia, davivienda, daviplata, nequi };
    }, [cuadreActivo?.transfer]);

    // Calcular total de datafonos (debe estar antes de cualquier return)
    const totalDatafonosCuadre = useMemo(() => {
      const datafonos = cuadreActivo?.datafonos || [];
      return datafonos.reduce((sum, d) => sum + Number(d.valor || 0), 0);
    }, [cuadreActivo?.datafonos]);

    // 🔹 Calcular total facturas pagadas de caja
    const totalFacturasCaja = useMemo(() => {
      const facturas = cuadreActivo?.facturas || [];
      return facturas
        .filter(f => f.estado === "Pagada de caja")
        .reduce((sum, f) => sum + Number(f.valor || 0), 0);
    }, [cuadreActivo?.facturas]);

    // 🔹 Calcular total facturas pendientes (quedan para el siguiente cuadre)
    const totalFacturasPendientes = useMemo(() => {
      const facturas = cuadreActivo?.facturas || [];
      return facturas
        .filter(f => f.estado === "Pendiente")
        .reduce((sum, f) => sum + Number(f.valor || 0), 0);
    }, [cuadreActivo?.facturas]);

    // 🔹 Calcular total domicilios (valor + cobro datafono)
    const totalDomiciliosCuadre = useMemo(() => {
      const domicilios = cuadreActivo?.domicilios || [];
      return domicilios.reduce((sum, d) => sum + Number(d.valor || 0) + Number(d.cobroDatafono || 0), 0);
    }, [cuadreActivo?.domicilios]);

    // 🔹 Calcular total ingresos varios
    const totalIngresosVariosCuadre = useMemo(() => {
      const ingresosVarios = cuadreActivo?.ingresosVarios || [];
      return ingresosVarios.reduce((sum, ing) => sum + Number(ing.valor || 0), 0);
    }, [cuadreActivo?.ingresosVarios]);

    // 🔹 Calcular total turnos
    const totalTurnosCuadre = useMemo(() => {
      const turnos = cuadreActivo?.turnos || [];
      return turnos.reduce((sum, t) => sum + Number(t.valor || 0), 0);
    }, [cuadreActivo?.turnos]);

    // 🔹 Calcular sobrante en efectivo automático
    // Fórmula: Valor venta efectivo - facturas pagadas de caja - total domicilio + total ingresos varios - total turnos
    const sobranteEfectivoCalculado = useMemo(() => {
      const ventaEfectivo = Number(cuadreActivo?.ventas?.ventaEfectivo || 0);
      return ventaEfectivo - totalFacturasCaja - totalDomiciliosCuadre + totalIngresosVariosCuadre - totalTurnosCuadre;
    }, [cuadreActivo?.ventas?.ventaEfectivo, totalFacturasCaja, totalDomiciliosCuadre, totalIngresosVariosCuadre, totalTurnosCuadre]);

    // 🔹 Actualizar automáticamente el sobrante en las ventas cuando cambie el cálculo
    useEffect(() => {
      if (cuadreActivo && cuadreActivo.estado !== "final") {
        const sobranteActual = Number(cuadreActivo?.ventas?.sobrante || 0);
        // Solo actualizar si es diferente para evitar bucle infinito
        if (sobranteActual !== sobranteEfectivoCalculado) {
          const ventasActualizadas = { ...(cuadreActivo.ventas || {}), sobrante: sobranteEfectivoCalculado };
          actualizarCuadre(cuadreActivo.id, { ventas: ventasActualizadas });
        }
      }
    }, [sobranteEfectivoCalculado]);
  
    // Vista inicial: sin cuadre activo → formulario de "Abrir cuadre"
    if (!cuadreActivo) {
      return (
        <div className="card">
          <h2>Abrir cuadre diario</h2>
          <div className="grid-3">
            <Field label="Sede">
              <select
                value={sedeSel}
                onChange={(e) => setSedeSel(e.target.value)}
                className="input"
              >
                <option value="">-- Selecciona --</option>
                {sedes.map((s) => {
                  const sedeNombre = typeof s === 'string' ? s : (s?.nombre || s?.razonSocial || '');
                  return (
                    <option key={sedeNombre} value={sedeNombre}>
                      {sedeNombre}
                    </option>
                  );
                })}
              </select>
            </Field>
  
            <Field label="Empleado responsable">
              <select
                value={empleadoSel}
                onChange={(e) => setEmpleadoSel(e.target.value)}
                className="input"
                disabled={!esGerente}
                style={!esGerente ? { backgroundColor: '#f0f0f0', cursor: 'not-allowed' } : {}}
              >
                <option value="">-- Selecciona --</option>
                {[...(empleados || [])].sort((a, b) => ((a.nombre || "").localeCompare((b.nombre || ""), 'es', { sensitivity: 'base' }))).map((e) => (
                  <option key={e.id} value={e.id}>
                    {e.nombre}
                  </option>
                ))}
              </select>
              {!esGerente && <span style={{ fontSize: '12px', color: '#666', marginTop: '4px' }}>Asignado automáticamente</span>}
            </Field>
  
            <Field label="Fecha del cuadre">
              <input
                className="input"
                type="date"
                value={fechaSel}
                onChange={(e) => setFechaSel(e.target.value)}
              />
            </Field>
  
            <Field label="Valor inicial de caja (COP)">
              <input
                className="input"
                type="number"
                value={valorInicial}
                onChange={(e) => setValorInicial(e.target.value)}
              />
            </Field>
          </div>
  
          {tienePermiso("admin_cuadre_abrir") && (
          <Button onClick={iniciarCuadre} style={{ marginTop: 12 }}>
            Abrir cuadre
          </Button>
          )}
        </div>
      );
    }
    
    // Verificar si el cuadre tiene precierre pendiente de confirmación
    // y si el usuario actual NO es el receptor asignado
    const usuarioActualId = empleadoActual?.id || usuarioActual?.id;
    const esReceptorPrecierre = cuadreActivo?.precierre?.asignadoAId === usuarioActualId;
    const precierrePendiente = cuadreActivo?.precierrePendienteConfirmacion;
    
    // Si hay precierre pendiente y el usuario NO es el receptor NI es gerencia, mostrar bloqueo
    if (precierrePendiente && !esReceptorPrecierre && !esGerente) {
      const empleadoAsignado = empleados.find(e => e.id === cuadreActivo?.precierre?.asignadoAId);
      return (
        <div className="card">
          <div style={{
            textAlign: 'center',
            padding: '40px 20px'
          }}>
            <div style={{ fontSize: '64px', marginBottom: '16px' }}>🔒</div>
            <h2 style={{ 
              margin: '0 0 16px 0', 
              color: '#dc2626',
              fontSize: '24px'
            }}>
              Cuadre en proceso de cambio de turno
            </h2>
            <div style={{
              padding: '20px',
              backgroundColor: '#fef2f2',
              border: '2px solid #f87171',
              borderRadius: '12px',
              marginBottom: '20px',
              maxWidth: '500px',
              margin: '0 auto 20px auto'
            }}>
              <p style={{ margin: '0 0 12px 0', fontSize: '15px', color: '#991b1b' }}>
                Este cuadre está esperando que <strong>{empleadoAsignado?.nombre || cuadreActivo?.precierre?.asignadoANombre || "el empleado asignado"}</strong> confirme el precierre del turno anterior.
              </p>
              <p style={{ margin: '0', fontSize: '13px', color: '#666' }}>
                Mientras no se confirme la recepción del cuadre, no es posible editarlo.
              </p>
            </div>
            <div style={{
              padding: '16px',
              backgroundColor: '#fef3c7',
              border: '1px solid #f59e0b',
              borderRadius: '10px',
              maxWidth: '500px',
              margin: '0 auto',
              fontSize: '13px',
              color: '#92400e'
            }}>
              <strong>📋 Información del precierre:</strong>
              <div style={{ marginTop: '8px', textAlign: 'left' }}>
                <div>• Realizado por: {cuadreActivo?.precierre?.porNombre || "N/A"}</div>
                <div>• Fecha: {cuadreActivo?.precierre?.fecha ? new Date(cuadreActivo.precierre.fecha).toLocaleString("es-CO") : "N/A"}</div>
                <div>• Asignado a: {empleadoAsignado?.nombre || cuadreActivo?.precierre?.asignadoANombre || "N/A"}</div>
              </div>
            </div>
            <button
              onClick={() => setCuadreActivoId(null)}
              style={{
                marginTop: '24px',
                padding: '12px 32px',
                backgroundColor: '#e5e7eb',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '15px'
              }}
            >
              ← Volver al listado
            </button>
          </div>
        </div>
      );
    }
  
    // Vista cuando YA hay un cuadre activo
    return (
      <div className="card" style={{ maxWidth: '100%', width: '100%' }}>
        <div className="cuadre-header">
          <div>
            <h2>
              Cuadre {cuadreActivo.sede} — {cuadreActivo.fecha}
            </h2>
            <p className="muted">
              Responsable: {empleado ? empleado.nombre : "SIN EMPLEADO"} — Valor
              inicial:{" "}
              {new Intl.NumberFormat("es-CO", {
                style: "currency",
                currency: "COP",
              }).format(cuadreActivo.valorInicial || 0)}
            </p>
            {cuadreActivo.estado === "final" && (
              <p className="badge-final">CUADRE CERRADO / NO MODIFICABLE</p>
            )}
          </div>
        </div>
        
        {/* ALERTA VISUAL SUPERPUESTA */}
        {alertaCuadre.visible && (
          <>
            {/* Fondo oscuro semi-transparente */}
            <div 
              onClick={() => setAlertaCuadre({ visible: false, tipo: '', mensaje: '' })}
              style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: 'rgba(0, 0, 0, 0.4)',
                zIndex: 9998
              }}
            />
            {/* Alerta flotante centrada */}
            <div style={{
              position: 'fixed',
              top: '30%',
              left: '50%',
              transform: 'translateX(-50%)',
              zIndex: 9999,
              padding: '24px 32px',
              borderRadius: '16px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '16px',
              fontSize: '16px',
              fontWeight: '600',
              backgroundColor: alertaCuadre.tipo === 'exito' ? '#dcfce7' : '#fee2e2',
              border: `3px solid ${alertaCuadre.tipo === 'exito' ? '#22c55e' : '#ef4444'}`,
              color: alertaCuadre.tipo === 'exito' ? '#166534' : '#991b1b',
              boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
              maxWidth: '550px',
              textAlign: 'left'
            }}>
              <span style={{ fontSize: '48px', alignSelf: 'center' }}>
                {alertaCuadre.tipo === 'exito' ? '✅' : '❌'}
              </span>
              <div style={{ lineHeight: '1.8', whiteSpace: 'pre-line', fontSize: '14px' }}>{alertaCuadre.mensaje}</div>
              <button
                onClick={() => setAlertaCuadre({ visible: false, tipo: '', mensaje: '' })}
                style={{
                  marginTop: '8px',
                  padding: '10px 32px',
                  backgroundColor: alertaCuadre.tipo === 'exito' ? '#22c55e' : '#ef4444',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  fontWeight: '600',
                  alignSelf: 'center'
                }}
              >
                Entendido
              </button>
            </div>
          </>
        )}
        
        {/* INDICADOR DE USUARIOS ACTIVOS - TRABAJO COLABORATIVO */}
        {usuariosActivosEnCuadre.length > 0 && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            padding: '10px 16px',
            backgroundColor: '#ecfdf5',
            border: '1px solid #10b981',
            borderRadius: '8px',
            marginBottom: '16px',
            flexWrap: 'wrap'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
              <span style={{ fontSize: '18px' }}>👥</span>
              <strong style={{ color: '#059669', fontSize: '14px' }}>
                Trabajando en este cuadre:
              </strong>
            </div>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
              {usuariosActivosEnCuadre.map((u, idx) => {
                const esSoyYo = u.usuario_id === (empleadoActual?.id || usuarioActual?.id);
                return (
                  <span 
                    key={u.usuario_id || idx}
                    style={{
                      padding: '4px 12px',
                      backgroundColor: esSoyYo ? '#10b981' : '#d1fae5',
                      color: esSoyYo ? 'white' : '#065f46',
                      borderRadius: '16px',
                      fontSize: '13px',
                      fontWeight: '500',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '4px'
                    }}
                  >
                    <span style={{ 
                      width: '8px', 
                      height: '8px', 
                      backgroundColor: '#22c55e', 
                      borderRadius: '50%',
                      animation: 'pulse 2s infinite'
                    }}></span>
                    {u.usuario_nombre}{esSoyYo ? ' (Tú)' : ''}
                  </span>
                );
              })}
            </div>
            {ultimaActualizacionRemota && (
              <span style={{ 
                fontSize: '11px', 
                color: '#6b7280', 
                marginLeft: 'auto' 
              }}>
                🔄 Sincronizado: {new Date(ultimaActualizacionRemota).toLocaleTimeString('es-CO')}
              </span>
            )}
          </div>
        )}

      {/* MENÚ DE ACCIONES RÁPIDAS */}
      <MenuAccionesCuadre
        cuadreActivo={cuadreActivo}
        actualizarCuadre={actualizarCuadre}
        bloqueado={bloqueado}
        tienePermiso={tienePermiso}
      />
  
 
      <CuadroVentas
        ventas={cuadreActivo.ventas}
        onChange={(ventas) => {
          // 🔹 Siempre actualizar el sobrante calculado automáticamente
          const ventaEfectivo = Number(ventas.ventaEfectivo || 0);
          const sobranteAuto = ventaEfectivo - totalFacturasCaja - totalDomiciliosCuadre + totalIngresosVariosCuadre - totalTurnosCuadre;
          actualizarCuadre(cuadreActivo.id, { ventas: { ...ventas, sobrante: sobranteAuto } });
        }}
        disabled={bloqueado}
        totalesTransfer={totalesTransfer}
        totalDatafonos={totalDatafonosCuadre}
        totalFacturasCaja={totalFacturasCaja}
        totalDomicilios={totalDomiciliosCuadre}
        totalIngresosVarios={totalIngresosVariosCuadre}
        totalTurnos={totalTurnosCuadre}
        sobranteEfectivoCalculado={sobranteEfectivoCalculado}
        totalFacturasPendientes={totalFacturasPendientes}
        valorInicial={Number(cuadreActivo?.valorInicial || 0)}
        esGerente={esGerente}
        tienePermiso={tienePermiso}
        precierreRealizado={cuadreActivo?.precierreRealizado || false}
        precierreConfirmadoPorReceptor={cuadreActivo?.precierre?.confirmadoPorReceptor || false}
        efectivoFinalConfirmado={cuadreActivo?.efectivoFinalConfirmado || false}
        fecha={cuadreActivo.fecha}
        sede={cuadreActivo.sede}
      />
 
      <CuadroFacturas
        facturas={cuadreActivo.facturas}
        onChange={(facturas) =>
          actualizarCuadre(cuadreActivo.id, { facturas })
        }
        disabled={bloqueado}
        sede={cuadreActivo.sede}
        filtroEmpresa={filtroEmpresa}
        esGerente={esGerente}
        responsableId={cuadreActivo.empleadoId}
        empleados={empleados}
        facturasEliminadas={cuadreActivo.facturasEliminadas || []}
        onFacturasEliminadasChange={(facturasEliminadas) =>
          actualizarCuadre(cuadreActivo.id, { facturasEliminadas })
        }
        fechaCuadre={cuadreActivo.fecha}
        tienePermiso={tienePermiso}
      />
 
      {/* Contenedor de dos columnas para Domicilios y Transferencias */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: '1fr 1fr', 
        gap: '24px',
        marginBottom: '24px',
        alignItems: 'start'
      }}>
        <CuadroDomicilios
          domicilios={cuadreActivo.domicilios}
          onChange={(domicilios) =>
            actualizarCuadreParcial(cuadreActivo.id, 'domicilios', domicilios)
          }
          disabled={bloqueado}
          bloquearFila={(filaId) => bloquearFila('domicilios', filaId)}
          desbloquearFila={(filaId) => desbloquearFila('domicilios', filaId)}
          filaEstaBloqueadaPorOtro={(filaId) => filaEstaBloqueadaPorOtro('domicilios', filaId)}
          fecha={cuadreActivo.fecha}
          sede={cuadreActivo.sede}
          transferencias={cuadreActivo.transfer || []}
        />
 
        <CuadroTransfer
          transfer={cuadreActivo.transfer}
          onChange={(transfer) =>
            actualizarCuadreParcial(cuadreActivo.id, 'transfer', transfer)
          }
          disabled={bloqueado}
          bloquearFila={(filaId) => bloquearFila('transfer', filaId)}
          desbloquearFila={(filaId) => desbloquearFila('transfer', filaId)}
          filaEstaBloqueadaPorOtro={(filaId) => filaEstaBloqueadaPorOtro('transfer', filaId)}
          fecha={cuadreActivo.fecha}
          sede={cuadreActivo.sede}
        />
      </div>

      <CuadroDatafonos
        datafonos={cuadreActivo.datafonos || []}
        onChange={(datafonos) =>
          actualizarCuadre(cuadreActivo.id, { datafonos })
        }
        disabled={bloqueado}
      />
 
      <hr className="divider" />
 
      <div className="grid-2">
        <div>
          <h3>Comentario de modificación</h3>
          <p className="muted">
            No se permite cambiar los valores del cuadre una vez guardado,
            pero aquí puedes justificar ajustes contables o notas internas.
          </p>
          <textarea
            className="textarea"
            rows={4}
            value={comentario}
            onChange={(e) => setComentario(e.target.value)}
            placeholder="Escribe comentarios de modificación (si aplica)"
          ></textarea>
          <Button
            variant="outline"
            style={{ marginTop: 8 }}
            onClick={() => {
              guardarComentario(cuadreActivo.id, comentario);
              alert("Comentario guardado para este cuadre.");
            }}
          >
            Guardar comentario
          </Button>
        </div>
 
        <div>
          <h3>Acciones sobre el cuadre</h3>
          <ul className="muted">
            <li>• <strong style={{color: '#dc2626'}}>Cierre Definitivo:</strong> Guarda y cierra el cuadre permanentemente.</li>
            <li>• Precierre: Cambio de turno (continúa otro empleado).</li>
            <li>• Imprimir cuadre completo (incluye totales y comentarios).</li>
          </ul>
          
          {/* Mostrar info de precierre si ya se realizó */}
          {cuadreActivo.precierreRealizado && cuadreActivo.precierre && (
            <div style={{
              padding: '12px',
              marginBottom: '12px',
              backgroundColor: '#fef3c7',
              border: '2px solid #f59e0b',
              borderRadius: '8px',
              fontSize: '12px'
            }}>
              <strong>📋 Precierre realizado:</strong>
              <div style={{ marginTop: '6px' }}>
                • {new Date(cuadreActivo.precierre.fecha).toLocaleString("es-CO")}<br/>
                • Por: {cuadreActivo.precierre.porNombre}<br/>
                • Asignado a: {cuadreActivo.precierre.asignadoANombre}
                {cuadreActivo.precierre.observaciones && (
                  <><br/>• Obs: {cuadreActivo.precierre.observaciones}</>
                )}
              </div>
            </div>
          )}
          
          {/* Botón de CIERRE DEFINITIVO - Primero y más llamativo */}
          {tienePermiso("admin_cuadre_guardar") && (
          <Button
            variant="solid"
            disabled={bloqueado}
            style={{
              marginRight: 8,
              marginBottom: 8,
              background: bloqueado ? '#9ca3af' : 'linear-gradient(135deg, #dc2626, #b91c1c)',
              color: 'white',
              fontWeight: 700,
              fontSize: '14px',
              padding: '12px 20px',
              border: 'none',
              boxShadow: bloqueado ? 'none' : '0 4px 6px rgba(185, 28, 28, 0.3)',
            }}
            onClick={() => {
              const ventas = cuadreActivo?.ventas || {};
              const facturas = cuadreActivo?.facturas || [];
              const errores = [];
              
              // 🔹 Validar que Venta en Efectivo tenga un valor (puede ser 0)
              if (ventas.ventaEfectivo === undefined || ventas.ventaEfectivo === null || ventas.ventaEfectivo === "") {
                errores.push("• Debes ingresar el valor de Venta en Efectivo (puede ser $0)");
              }
              
              // 🔹 Validar que Online Rappi tenga un valor (puede ser 0)
              if (ventas.onlineRappi === undefined || ventas.onlineRappi === null || ventas.onlineRappi === "") {
                errores.push("• Debes ingresar el valor de Online Rappi (puede ser $0)");
              }
              
              // 🔹 Validar que se haya seleccionado Sí o No en descuadre de transferencia
              if (!ventas.huboDescuadreTransferencia || ventas.huboDescuadreTransferencia === "") {
                errores.push("• Debes indicar si hubo descuadre de caja en transferencia (Sí o No)");
              }
              
              // 🔹 Validar que se haya seleccionado Sí o No en descuadre de datáfono
              if (!ventas.huboDescuadreDatafono || ventas.huboDescuadreDatafono === "") {
                errores.push("• Debes indicar si hubo descuadre de caja en datáfono (Sí o No)");
              }
              
              // 🔹 Si hubo descuadre de transferencia, validar campos obligatorios
              if (ventas.huboDescuadreTransferencia === "Sí") {
                if (!ventas.valorDescuadreTransferencia || ventas.valorDescuadreTransferencia === "") {
                  errores.push("• Indicaste descuadre en transferencia: falta el valor del descuadre");
                }
                if (!ventas.numeroPedidoDescuadreTransferencia || ventas.numeroPedidoDescuadreTransferencia === "") {
                  errores.push("• Indicaste descuadre en transferencia: falta el número de pedido");
                }
                if (!ventas.bancoDescuadreTransferencia || ventas.bancoDescuadreTransferencia === "") {
                  errores.push("• Indicaste descuadre en transferencia: falta seleccionar el banco");
                }
              }
              
              // 🔹 Si hubo descuadre de datáfono, validar que tenga valor
              if (ventas.huboDescuadreDatafono === "Sí" && (!ventas.valorDescuadreDatafono || ventas.valorDescuadreDatafono === "")) {
                errores.push("• Indicaste descuadre en datáfono: falta el valor del descuadre");
              }
              
              // 🔹 Validar que se haya confirmado el efectivo en caja
              if (!ventas.efectivoEnCajaConfirmado) {
                errores.push("• Debes confirmar cuánto efectivo tienes en caja (presiona el botón 'Confirmar' en la sección de Verificación de Efectivo)");
              }
              
              // 🔹 Facturas "Pagada transferencia" que NO han sido enviadas a procesos
              const facturasTransferenciaSinEnviar = facturas.filter(f => 
                f.estado === "Pagada transferencia" && 
                !f.tareaEnviadaId
              );
              if (facturasTransferenciaSinEnviar.length > 0) {
                errores.push(`• Tienes ${facturasTransferenciaSinEnviar.length} factura(s) "Pagada transferencia" sin enviar a Procesos Administrativos`);
              }
              
              // 🔹 Facturas "Pagada transferencia" que están en estado Pendiente
              const facturasPendientes = facturas.filter(f => 
                f.estado === "Pagada transferencia" && 
                f.tareaEnviadaId && 
                f.estadoTarea !== "Procesada" && 
                f.estadoTarea !== "Negada"
              );
              if (facturasPendientes.length > 0) {
                errores.push(`• Tienes ${facturasPendientes.length} factura(s) por transferencia pendiente(s) de procesar`);
              }
              
              // Si hay errores, mostrar todos juntos
              if (errores.length > 0) {
                mostrarAlertaVisual('error', `⚠️ No se puede cerrar el cuadre:\n\n${errores.join('\n')}`);
                return;
              }
              
              // 🔹 Validar descuadre en efectivo (calculado automáticamente) - esto es solo confirmación, no bloquea
              if (sobranteEfectivoCalculado !== 0) {
                const tipoDesc = sobranteEfectivoCalculado > 0 ? "SOBRANTE" : "DESCUADRE";
                const valorDesc = Math.abs(sobranteEfectivoCalculado);
                const formatCOP = (val) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(val || 0);
                const confirmar = window.confirm(
                  `⚠️ ATENCIÓN: Hay un ${tipoDesc} EN EFECTIVO de ${formatCOP(valorDesc)}.\n\n¿Deseas continuar y cerrar el cuadre con este ${tipoDesc.toLowerCase()}?`
                );
                if (!confirmar) {
                  return;
                }
              }
              
              const t = calcularTotalesCuadre(cuadreActivo);
              setTotales(t);
              guardarFinal(cuadreActivo.id, t);
              mostrarAlertaVisual('exito', '✅ Cuadre guardado y cerrado correctamente. Ya no se puede modificar.');
            }}
          >
            🔒 Cierre Definitivo de Cuadre
          </Button>
          )}
          
          {/* Botón de Precierre - solo si NO está cerrado */}
          {!bloqueado && tienePermiso("admin_cuadre_guardar") && (
          <Button
            variant="outline"
            style={{ 
              marginRight: 8, 
              marginBottom: 8,
              backgroundColor: '#fef3c7',
              borderColor: '#f59e0b',
              color: '#92400e'
            }}
            onClick={() => setMostrarModalPrecierre(true)}
          >
            📋 Precierre de Turno
          </Button>
          )}

          {tienePermiso("admin_cuadre_imprimir") && (
          <Button
            variant="outline"
            style={{ marginLeft: 8, marginTop: 8 }}
            onClick={() =>
              imprimirCuadreCompleto(cuadreActivo, empleados)
            }
          >
            Imprimir cuadre
          </Button>
          )}
        </div>
      </div>
      
      {/* MODAL DE PRECIERRE */}
      {mostrarModalPrecierre && (() => {
        // Calcular todos los totales para mostrar en el modal
        const ventas = cuadreActivo?.ventas || {};
        const facturas = cuadreActivo?.facturas || [];
        const transfer = cuadreActivo?.transfer || [];
        const datafonos = cuadreActivo?.datafonos || [];
        
        // Totales de transferencias
        let bancolombia = 0, davivienda = 0, daviplata = 0, nequi = 0;
        transfer.forEach(t => {
          bancolombia += Number(t.bancolombia || 0);
          davivienda += Number(t.davivienda || 0);
          daviplata += Number(t.daviplata || 0);
          nequi += Number(t.nequi || 0);
        });
        const totalTransferencias = bancolombia + davivienda + daviplata + nequi;
        
        // Total datafonos
        const totalDatafonosCalc = datafonos.reduce((s, d) => s + Number(d.valor || 0), 0);
        
        // Ventas
        const ventaEfectivo = Number(ventas.ventaEfectivo || 0);
        const onlineRappi = Number(ventas.onlineRappi || 0);
        const sobrante = Number(ventas.sobrante || 0);
        const huboDescuadre = ventas.huboDescuadre || "No";
        
        // 🔹 Valor inicial de caja para mostrar dos valores
        const valorInicialCaja = Number(cuadreActivo?.valorInicial || 0);

        // Totales de facturas (calculado aquí para usar en el cuadre)
        const totalPendientes = facturas.filter(f => f.estado === "Pendiente").reduce((s, f) => s + Number(f.valor || 0), 0);

        // Las facturas pendientes quedan en caja para el siguiente cuadre;
        // el empleado las retiene aparte, por lo que se restan del valor inicial.
        const valorDebeQuedarConCaja = valorInicialCaja - totalPendientes;
        const valorDebeQuedarSinCaja = sobrante - totalPendientes;

        // 🔹 Efectivo en caja ingresado por el usuario
        const efectivoEnCaja = Number(ventas.efectivoEnCaja || 0);
        const diferenciaEfectivo = efectivoEnCaja - valorDebeQuedarConCaja;
        const estaCuadrado = Math.abs(diferenciaEfectivo) < 1;
        const estaDescuadrado = !estaCuadrado;

        // Total ventas
        const totalVentas = ventaEfectivo + totalTransferencias + totalDatafonosCalc + onlineRappi;
        const totalCaja = facturas.filter(f => f.estado === "Pagada de caja").reduce((s, f) => s + Number(f.valor || 0), 0);
        const totalTransf = facturas.filter(f => f.estado === "Pagada transferencia").reduce((s, f) => s + Number(f.valor || 0), 0);
        const totalGastos = totalPendientes + totalCaja + totalTransf;
        
        const formatCOP = (val) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(val || 0);
        
        return (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.6)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 9999,
          overflow: 'auto',
          padding: '20px'
        }}>
          <div style={{
            backgroundColor: 'white',
            borderRadius: '16px',
            padding: '24px',
            width: '100%',
            maxWidth: '650px',
            maxHeight: '90vh',
            overflowY: 'auto',
            boxShadow: '0 20px 60px rgba(0,0,0,0.3)'
          }}>
            <h3 style={{ 
              margin: '0 0 16px 0', 
              color: '#92400e',
              display: 'flex',
              alignItems: 'center',
              gap: '8px'
            }}>
              📋 Precierre de Turno
            </h3>
            
            <p style={{ fontSize: '13px', color: '#666', marginBottom: '16px' }}>
              El precierre registra que tu turno terminó y asigna el cuadre a otro empleado para que continúe.
              <strong> El cuadre NO se cierra definitivamente</strong>, solo se registra el cambio de turno.
            </p>
            
            {/* 🔹 VERIFICACIÓN DE EFECTIVO - PRIMERO ANTES DE MOSTRAR VALORES */}
            {!ventas.efectivoEnCajaConfirmado && (
              <div style={{
                padding: '20px',
                backgroundColor: '#fef2f2',
                border: '3px solid #ef4444',
                borderRadius: '12px',
                marginBottom: '16px',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '40px', marginBottom: '12px' }}>⚠️</div>
                <h4 style={{ margin: '0 0 12px 0', color: '#dc2626', fontSize: '16px' }}>
                  DEBES CONFIRMAR EL EFECTIVO EN CAJA PRIMERO
                </h4>
                <p style={{ fontSize: '13px', color: '#991b1b', marginBottom: '16px' }}>
                  Para hacer el precierre, primero debes contar e ingresar cuánto efectivo tienes en caja.
                  <br/><br/>
                  <strong>Los valores del cuadre están ocultos</strong> hasta que confirmes el efectivo.
                </p>
                <div style={{ 
                  padding: '12px', 
                  backgroundColor: '#f1f5f9', 
                  borderRadius: '8px',
                  border: '2px dashed #94a3b8',
                  marginBottom: '16px'
                }}>
                  <div style={{ fontSize: '12px', color: '#64748b', fontWeight: '600' }}>
                    🔒 Valores ocultos: "Debe quedar en caja", "Sobrante neto", etc.
                  </div>
                </div>
                <button
                  onClick={() => setMostrarModalPrecierre(false)}
                  style={{
                    padding: '12px 24px',
                    background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)',
                    color: 'white',
                    border: 'none',
                    borderRadius: '8px',
                    cursor: 'pointer',
                    fontWeight: '700',
                    fontSize: '14px'
                  }}
                >
                  ← Ir a confirmar efectivo en caja
                </button>
              </div>
            )}
            
            {/* SOLO MOSTRAR SI YA CONFIRMÓ EL EFECTIVO */}
            {ventas.efectivoEnCajaConfirmado && (
              <>
                {/* RESUMEN DE VENTAS Y MEDIOS DE PAGO */}
                <div style={{
                  padding: '14px',
                  backgroundColor: '#f0fdf4',
                  border: '1px solid #22c55e',
                  borderRadius: '10px',
                  marginBottom: '12px',
                  fontSize: '12px'
                }}>
                  <h4 style={{ margin: '0 0 10px 0', color: '#166534', fontSize: '14px' }}>💰 Ventas y medios de pago</h4>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor venta efectivo:</span>
                      <strong style={{ color: '#166534' }}>{formatCOP(ventaEfectivo)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor Bancolombia:</span>
                      <strong style={{ color: '#166534' }}>{formatCOP(bancolombia)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor Davivienda:</span>
                      <strong style={{ color: '#92400e' }}>{formatCOP(davivienda)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor Daviplata:</span>
                      <strong style={{ color: '#991b1b' }}>{formatCOP(daviplata)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor Nequi:</span>
                      <strong style={{ color: '#5b21b6' }}>{formatCOP(nequi)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Valor Datáfono:</span>
                      <strong style={{ color: '#0369a1' }}>{formatCOP(totalDatafonosCalc)}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', backgroundColor: 'white', borderRadius: '4px' }}>
                      <span>Online Rappi:</span>
                      <strong style={{ color: '#dc2626' }}>{formatCOP(onlineRappi)}</strong>
                    </div>
                  </div>
                  
                  {/* 🔹 TRES VALORES EN LÍNEA - Efectivo en caja, Debe quedar, Sobrante neto */}
                  <div style={{ 
                    display: 'grid', 
                    gridTemplateColumns: '1fr 1fr 1fr', 
                    gap: '8px', 
                    marginTop: '12px',
                    padding: '8px',
                    backgroundColor: estaDescuadrado ? '#fef2f2' : '#f0fdf4',
                    borderRadius: '8px',
                    border: `2px solid ${estaDescuadrado ? '#ef4444' : '#22c55e'}`
                  }}>
                    {/* Efectivo en caja (ingresado) */}
                    <div style={{ 
                      padding: '8px', 
                      backgroundColor: '#eff6ff', 
                      borderRadius: '6px',
                      textAlign: 'center',
                      border: '2px solid #3b82f6'
                    }}>
                      <div style={{ fontSize: '10px', color: '#1e40af', marginBottom: '2px', fontWeight: '700' }}>💵 Tienes en caja</div>
                      <div style={{ fontSize: '16px', fontWeight: '700', color: '#1e40af' }}>
                        {formatCOP(efectivoEnCaja)}
                      </div>
                      <div style={{ fontSize: '9px', color: '#6b7280' }}>Valor confirmado ✅</div>
                    </div>
                    <div style={{ 
                      padding: '8px', 
                      backgroundColor: valorDebeQuedarConCaja >= 0 ? '#d1fae5' : '#fef2f2', 
                      borderRadius: '6px',
                      textAlign: 'center',
                      border: `1px solid ${valorDebeQuedarConCaja >= 0 ? '#10b981' : '#ef4444'}`
                    }}>
                      <div style={{ fontSize: '10px', color: '#6b7280', marginBottom: '2px' }}>📦 Debe quedar en caja</div>
                      <div style={{ fontSize: '16px', fontWeight: '700', color: valorDebeQuedarConCaja >= 0 ? '#047857' : '#dc2626' }}>
                        {formatCOP(valorDebeQuedarConCaja)}
                      </div>
                      <div style={{ fontSize: '9px', color: '#9ca3af' }}>Base: {formatCOP(valorInicialCaja)}</div>
                      {totalPendientes > 0 && (
                        <div style={{ fontSize: '9px', color: '#d97706', marginTop: '2px' }}>
                          Fact. pend. restadas: {formatCOP(totalPendientes)}
                        </div>
                      )}
                    </div>
                    <div style={{ 
                      padding: '8px', 
                      backgroundColor: valorDebeQuedarSinCaja >= 0 ? '#ecfdf5' : '#fef2f2', 
                      borderRadius: '6px',
                      textAlign: 'center',
                      border: `1px solid ${valorDebeQuedarSinCaja >= 0 ? '#059669' : '#ef4444'}`
                    }}>
                      <div style={{ fontSize: '10px', color: '#6b7280', marginBottom: '2px' }}>💵 Sobrante neto</div>
                      <div style={{ fontSize: '16px', fontWeight: '700', color: valorDebeQuedarSinCaja >= 0 ? '#059669' : '#dc2626' }}>
                        {formatCOP(valorDebeQuedarSinCaja)}
                      </div>
                      <div style={{ fontSize: '9px', color: '#9ca3af' }}>Sin base</div>
                    </div>
                  </div>
                  
                  {/* Estado del cuadre - Comparación real */}
                  <div style={{ 
                    marginTop: '8px',
                    padding: '8px 12px',
                    backgroundColor: estaCuadrado ? '#d1fae5' : '#fef2f2',
                    borderRadius: '10px',
                    textAlign: 'center',
                    border: `3px solid ${estaCuadrado ? '#10b981' : '#ef4444'}`
                  }}>
                    <div style={{ fontSize: '13px', fontWeight: '800', color: estaCuadrado ? '#065f46' : '#dc2626', marginBottom: '4px' }}>
                      {estaCuadrado 
                        ? "✅ ¡CUADRADO! El efectivo coincide"
                        : diferenciaEfectivo > 0 
                          ? `⚠️ SOBRANTE: Tienes ${formatCOP(diferenciaEfectivo)} de más`
                          : `🚨 DESCUADRADO: Te faltan ${formatCOP(Math.abs(diferenciaEfectivo))}`
                      }
                    </div>
                    <div style={{ fontSize: '10px', color: '#6b7280' }}>
                      Diferencia: <strong style={{ color: estaCuadrado ? '#065f46' : (diferenciaEfectivo > 0 ? '#d97706' : '#dc2626') }}>{diferenciaEfectivo >= 0 ? '+' : ''}{formatCOP(diferenciaEfectivo)}</strong>
                    </div>
                  </div>
                  
                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '4px 8px', marginTop: '6px' }}>
                    <span>¿Hubo descuadre?:</span>
                    <strong style={{ color: huboDescuadre === "Sí" ? '#dc2626' : '#166534' }}>{huboDescuadre}</strong>
                  </div>
                  <div style={{ 
                    borderTop: '2px solid #22c55e', 
                    marginTop: '10px', 
                    paddingTop: '10px',
                    display: 'grid',
                    gridTemplateColumns: '1fr 1fr',
                    gap: '4px',
                    fontSize: '11px'
                  }}>
                    <span>Total efectivo: <strong style={{ color: '#166534' }}>{formatCOP(ventaEfectivo)}</strong></span>
                    <span>Total transferencias: <strong style={{ color: '#059669' }}>{formatCOP(totalTransferencias)}</strong></span>
                    <span>Total datáfonos: <strong style={{ color: '#0369a1' }}>{formatCOP(totalDatafonosCalc)}</strong></span>
                    <span>Total Online Rappi: <strong style={{ color: '#dc2626' }}>{formatCOP(onlineRappi)}</strong></span>
                  </div>
                  <div style={{ 
                    marginTop: '8px', 
                    padding: '8px', 
                    backgroundColor: '#dcfce7', 
                    borderRadius: '6px', 
                    textAlign: 'center',
                    fontWeight: '700',
                    color: '#166534',
                    fontSize: '14px'
                  }}>
                    TOTAL VENTAS: {formatCOP(totalVentas)}
                  </div>
                </div>
                
                {/* RESUMEN DE GASTOS */}
                <div style={{
                  padding: '14px',
                  backgroundColor: '#fef2f2',
                  border: '1px solid #f87171',
                  borderRadius: '10px',
                  marginBottom: '16px',
                  fontSize: '12px'
                }}>
                  <h4 style={{ margin: '0 0 10px 0', color: '#991b1b', fontSize: '14px' }}>📋 Resumen de Facturas por Tipo de Pago</h4>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
                    <div style={{ padding: '10px', backgroundColor: '#fef3c7', borderRadius: '6px', textAlign: 'center', border: '1px solid #f59e0b' }}>
                      <div style={{ fontSize: '11px', color: '#92400e', marginBottom: '4px' }}>⏳ Pendientes</div>
                      <strong style={{ color: '#ea580c', fontSize: '14px' }}>{formatCOP(totalPendientes)}</strong>
                    </div>
                    <div style={{ padding: '10px', backgroundColor: '#d1fae5', borderRadius: '6px', textAlign: 'center', border: '1px solid #10b981' }}>
                      <div style={{ fontSize: '11px', color: '#065f46', marginBottom: '4px' }}>💵 Pagadas Caja</div>
                      <strong style={{ color: '#166534', fontSize: '14px' }}>{formatCOP(totalCaja)}</strong>
                    </div>
                    <div style={{ padding: '10px', backgroundColor: '#dbeafe', borderRadius: '6px', textAlign: 'center', border: '1px solid #3b82f6' }}>
                      <div style={{ fontSize: '11px', color: '#1e40af', marginBottom: '4px' }}>🏦 Pagadas Transfer</div>
                      <strong style={{ color: '#0369a1', fontSize: '14px' }}>{formatCOP(totalTransf)}</strong>
                    </div>
                  </div>
                </div>
            
            {/* 🔹 ALERTA DE BASES DE DOMICILIOS PENDIENTES */}
            {(() => {
              const basesDom = cuadreActivo?.basesDomicilios || [];
              const basesPendientes = basesDom.filter(base => {
                const totalAbonos = (base.abonos || []).reduce((sum, a) => sum + Number(a.valor || 0), 0);
                return (Number(base.valorBase || 0) - totalAbonos) > 0;
              });
              const totalPendienteBases = basesPendientes.reduce((sum, base) => {
                const totalAbonos = (base.abonos || []).reduce((s, a) => s + Number(a.valor || 0), 0);
                return sum + (Number(base.valorBase || 0) - totalAbonos);
              }, 0);

              if (basesPendientes.length === 0) return null;

              return (
                <div style={{
                  padding: '14px',
                  backgroundColor: '#fef3c7',
                  border: '2px solid #f59e0b',
                  borderRadius: '10px',
                  marginBottom: '16px'
                }}>
                  <h4 style={{ margin: '0 0 10px 0', color: '#92400e', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '6px' }}>
                    ⚠️ Bases de Domicilios Pendientes
                  </h4>
                  <p style={{ fontSize: '12px', color: '#78350f', marginBottom: '10px' }}>
                    Hay <strong>{basesPendientes.length}</strong> base(s) con saldo pendiente por cobrar:
                  </p>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                    {basesPendientes.map(base => {
                      const totalAbonos = (base.abonos || []).reduce((s, a) => s + Number(a.valor || 0), 0);
                      const saldo = Number(base.valorBase || 0) - totalAbonos;
                      return (
                        <div key={base.id} style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          padding: '8px 12px',
                          backgroundColor: 'white',
                          borderRadius: '6px',
                          border: '1px solid #fbbf24'
                        }}>
                          <span style={{ fontWeight: '600', color: '#1f2937' }}>🚴 {base.empleado}</span>
                          <span style={{ fontWeight: '700', color: '#dc2626' }}>{formatCOP(saldo)}</span>
                        </div>
                      );
                    })}
                  </div>
                  <div style={{
                    marginTop: '10px',
                    padding: '8px',
                    backgroundColor: '#fef9c3',
                    borderRadius: '6px',
                    textAlign: 'center',
                    fontWeight: '700',
                    color: '#92400e',
                    fontSize: '14px'
                  }}>
                    TOTAL PENDIENTE: {formatCOP(totalPendienteBases)}
                  </div>
                </div>
              );
            })()}
            
            {/* Selector de empleado */}
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: '600', fontSize: '13px' }}>
                👤 Asignar cuadre a:
              </label>
              <select
                value={precierreAsignadoA}
                onChange={(e) => setPrecierreAsignadoA(e.target.value)}
                style={{
                  width: '100%',
                  padding: '10px 12px',
                  border: '2px solid #e5e7eb',
                  borderRadius: '8px',
                  fontSize: '14px'
                }}
              >
                <option value="">-- Seleccionar empleado --</option>
                {empleados
                  .filter(e => e.id !== (empleadoActual?.id || usuarioActual?.id))
                  .map(e => (
                    <option key={e.id} value={e.id}>{e.nombre}</option>
                  ))
                }
              </select>
            </div>
            
            {/* Observaciones */}
            <div style={{ marginBottom: '20px' }}>
              <label style={{ display: 'block', marginBottom: '6px', fontWeight: '600', fontSize: '13px' }}>
                📝 Observaciones del turno (opcional):
              </label>
              <textarea
                value={precierreObservaciones}
                onChange={(e) => setPrecierreObservaciones(e.target.value)}
                placeholder="Ej: Todo en orden, sin novedades..."
                rows={3}
                style={{
                  width: '100%',
                  padding: '10px 12px',
                  border: '2px solid #e5e7eb',
                  borderRadius: '8px',
                  fontSize: '14px',
                  resize: 'vertical'
                }}
              />
            </div>
            
            {/* Botones */}
            <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
              <button
                onClick={() => {
                  setMostrarModalPrecierre(false);
                  setPrecierreAsignadoA("");
                  setPrecierreObservaciones("");
                }}
                style={{
                  padding: '10px 20px',
                  backgroundColor: '#e5e7eb',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontWeight: '600'
                }}
              >
                Cancelar
              </button>
              <button
                onClick={() => {
                  if (!precierreAsignadoA) {
                    alert("⚠️ Debes seleccionar un empleado para asignar el cuadre.");
                    return;
                  }
                  
                  // 🔹 Validar que el efectivo esté confirmado antes de hacer precierre
                  if (!ventas.efectivoEnCajaConfirmado) {
                    alert("⚠️ Para hacer el precierre, primero debes confirmar el efectivo en caja.\n\nVe a la sección 'Verificación de Efectivo en Caja' e ingresa cuánto efectivo tienes.");
                    setMostrarModalPrecierre(false);
                    return;
                  }
                  
                  // Pasar los totales calculados a la función (incluyendo efectivo confirmado)
                  realizarPrecierre(cuadreActivo.id, precierreAsignadoA, precierreObservaciones, {
                    ventaEfectivo,
                    bancolombia,
                    davivienda,
                    daviplata,
                    nequi,
                    totalTransferencias,
                    totalDatafonos: totalDatafonosCalc,
                    onlineRappi,
                    sobrante,
                    huboDescuadre,
                    totalVentas,
                    totalFacturasPendientes: totalPendientes,
                    totalFacturasCaja: totalCaja,
                    totalFacturasTransferencia: totalTransf,
                    totalGastos,
                    // 🔹 Agregar efectivo confirmado al precierre
                    efectivoEnCaja: Number(ventas.efectivoEnCaja || 0),
                    valorInicialCaja: valorInicialCaja,
                    debeQuedarEnCaja: valorDebeQuedarConCaja,
                    diferenciaEfectivo: diferenciaEfectivo,
                    estaCuadrado: estaCuadrado
                  });
                  setMostrarModalPrecierre(false);
                  setPrecierreAsignadoA("");
                  setPrecierreObservaciones("");
                }}
                style={{
                  padding: '10px 24px',
                  background: 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontWeight: '600',
                  boxShadow: '0 2px 8px rgba(245, 158, 11, 0.4)'
                }}
              >
                ✅ Confirmar Precierre
              </button>
            </div>
              </>
            )}
          </div>
        </div>
        );
      })()}
      
      {/* MODAL DE CONFIRMACIÓN DE PRECIERRE RECIBIDO */}
      {mostrarAlertaConfirmarPrecierre && cuadreActivo?.precierre && (() => {
        const p = cuadreActivo.precierre;
        const totales = p.totales || {};
        const formatCOP = (val) => new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(val || 0);
        const fechaPrecierre = p.fecha ? new Date(p.fecha).toLocaleString("es-CO") : "N/A";
        
        return (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10000,
            overflow: 'auto',
            padding: '20px'
          }}>
            <div style={{
              backgroundColor: 'white',
              borderRadius: '16px',
              padding: '28px',
              width: '100%',
              maxWidth: '600px',
              maxHeight: '90vh',
              overflowY: 'auto',
              boxShadow: '0 25px 80px rgba(0,0,0,0.4)',
              border: '3px solid #f59e0b',
              position: 'relative'
            }}>
              {/* Botón X para cerrar */}
              <button
                onClick={() => {
                  setMostrarAlertaConfirmarPrecierre(false);
                  // Opcional: volver al listado de cuadres
                  setCuadreActivoId(null);
                }}
                style={{
                  position: 'absolute',
                  top: '12px',
                  right: '12px',
                  width: '36px',
                  height: '36px',
                  borderRadius: '50%',
                  border: 'none',
                  backgroundColor: '#fee2e2',
                  color: '#dc2626',
                  fontSize: '20px',
                  fontWeight: '700',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'all 0.2s'
                }}
                onMouseOver={(e) => {
                  e.target.style.backgroundColor = '#fecaca';
                  e.target.style.transform = 'scale(1.1)';
                }}
                onMouseOut={(e) => {
                  e.target.style.backgroundColor = '#fee2e2';
                  e.target.style.transform = 'scale(1)';
                }}
                title="Salir sin confirmar"
              >
                ✕
              </button>
              
              <div style={{
                textAlign: 'center',
                marginBottom: '20px'
              }}>
                <div style={{ fontSize: '48px', marginBottom: '8px' }}>⚠️</div>
                <h2 style={{ 
                  margin: '0', 
                  color: '#92400e',
                  fontSize: '22px'
                }}>
                  PRECIERRE DE TURNO ANTERIOR
                </h2>
                <p style={{ 
                  margin: '8px 0 0 0', 
                  color: '#666',
                  fontSize: '14px'
                }}>
                  Debes confirmar que el turno anterior está correcto antes de continuar
                </p>
              </div>
              
              {/* Info del precierre */}
              <div style={{
                padding: '16px',
                backgroundColor: '#fef3c7',
                border: '2px solid #f59e0b',
                borderRadius: '12px',
                marginBottom: '16px'
              }}>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', fontSize: '13px' }}>
                  <div><strong>📅 Fecha precierre:</strong> {fechaPrecierre}</div>
                  <div><strong>👤 Realizado por:</strong> {p.porNombre}</div>
                  <div style={{ gridColumn: '1 / -1' }}>
                    <strong>📝 Observaciones:</strong> {p.observaciones || "Sin observaciones"}
                  </div>
                </div>
              </div>
              
              {/* 🔹 VERIFICACIÓN DE EFECTIVO - PRIMERO ANTES DE MOSTRAR VALORES */}
              <div style={{
                padding: '16px',
                backgroundColor: efectivoReceptorConfirmado ? '#d1fae5' : '#eff6ff',
                border: `3px solid ${efectivoReceptorConfirmado ? '#22c55e' : '#3b82f6'}`,
                borderRadius: '12px',
                marginBottom: '16px'
              }}>
                <h4 style={{ margin: '0 0 12px 0', color: efectivoReceptorConfirmado ? '#166534' : '#1e40af', fontSize: '14px', textAlign: 'center' }}>
                  💵 PASO 1: VERIFICA EL EFECTIVO EN CAJA
                </h4>
                
                {!efectivoReceptorConfirmado ? (
                  <>
                    <div style={{ 
                      padding: '16px', 
                      backgroundColor: '#fff7ed', 
                      borderRadius: '10px',
                      textAlign: 'center',
                      border: '2px solid #f59e0b'
                    }}>
                      <div style={{ fontSize: '12px', color: '#92400e', marginBottom: '8px', fontWeight: '700' }}>
                        📥 ¿Cuánto efectivo hay en caja? (Cuenta antes de ver los valores)
                      </div>
                      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', justifyContent: 'center', maxWidth: '300px', margin: '0 auto' }}>
                        <div style={{ position: 'relative', flex: 1 }}>
                          <span style={{ 
                            position: 'absolute', 
                            left: '12px', 
                            top: '50%', 
                            transform: 'translateY(-50%)', 
                            color: '#1e40af', 
                            fontWeight: '700',
                            fontSize: '18px'
                          }}>$</span>
                          <input
                            type="number"
                            placeholder="0"
                            value={efectivoReceptor}
                            onChange={(e) => setEfectivoReceptor(e.target.value)}
                            style={{ 
                              width: '100%',
                              padding: '12px 12px 12px 30px',
                              borderRadius: '8px',
                              border: '2px solid #3b82f6',
                              backgroundColor: 'white',
                              fontSize: '20px',
                              fontWeight: '700',
                              textAlign: 'center',
                              color: '#1e40af'
                            }}
                          />
                        </div>
                        <button
                          type="button"
                          disabled={!efectivoReceptor || Number(efectivoReceptor) < 0}
                          onClick={() => {
                            if (!efectivoReceptor || Number(efectivoReceptor) < 0) {
                              alert("⚠️ Ingresa un valor válido");
                              return;
                            }
                            const confirmar = window.confirm(`¿Confirmas que hay ${formatCOP(Number(efectivoReceptor))} en efectivo en caja?\n\nEste valor se comparará con lo que declaró el turno saliente.`);
                            if (confirmar) {
                              setEfectivoReceptorConfirmado(true);
                            }
                          }}
                          style={{ 
                            padding: '12px 20px',
                            borderRadius: '8px',
                            border: 'none',
                            backgroundColor: (!efectivoReceptor || Number(efectivoReceptor) < 0) ? '#94a3b8' : '#22c55e',
                            color: 'white',
                            fontSize: '14px',
                            fontWeight: '700',
                            cursor: (!efectivoReceptor || Number(efectivoReceptor) < 0) ? 'not-allowed' : 'pointer'
                          }}
                        >
                          ✓ Confirmar
                        </button>
                      </div>
                      <div style={{ fontSize: '10px', color: '#f59e0b', marginTop: '10px', fontWeight: '600' }}>
                        ⚠️ Debes contar e ingresar el efectivo antes de ver los valores del turno anterior
                      </div>
                    </div>
                    
                    {/* Mensaje de que los valores están ocultos */}
                    <div style={{ 
                      marginTop: '16px',
                      padding: '12px', 
                      backgroundColor: '#f1f5f9', 
                      borderRadius: '8px',
                      textAlign: 'center',
                      border: '2px dashed #94a3b8'
                    }}>
                      <div style={{ fontSize: '12px', color: '#64748b', fontWeight: '600' }}>
                        🔒 Los valores del turno anterior están ocultos
                      </div>
                      <div style={{ fontSize: '11px', color: '#94a3b8', marginTop: '4px' }}>
                        Se revelarán después de confirmar el efectivo en caja
                      </div>
                    </div>
                  </>
                ) : (
                  <>
                    {/* Ya confirmó - Mostrar comparación */}
                    <div style={{ 
                      display: 'grid', 
                      gridTemplateColumns: '1fr 1fr', 
                      gap: '12px',
                      marginBottom: '12px'
                    }}>
                      <div style={{ 
                        padding: '12px', 
                        backgroundColor: '#d1fae5', 
                        borderRadius: '8px',
                        textAlign: 'center',
                        border: '2px solid #22c55e'
                      }}>
                        <div style={{ fontSize: '11px', color: '#166534', marginBottom: '4px', fontWeight: '700' }}>
                          📥 Tú contaste:
                        </div>
                        <div style={{ fontSize: '20px', fontWeight: '700', color: '#166534' }}>
                          {formatCOP(Number(efectivoReceptor))}
                        </div>
                        <button
                          type="button"
                          onClick={() => setEfectivoReceptorConfirmado(false)}
                          style={{
                            marginTop: '4px',
                            padding: '2px 8px',
                            fontSize: '9px',
                            backgroundColor: '#f59e0b',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer'
                          }}
                        >
                          ✏️ Modificar
                        </button>
                      </div>
                      
                      <div style={{ 
                        padding: '12px', 
                        backgroundColor: '#dbeafe', 
                        borderRadius: '8px',
                        textAlign: 'center',
                        border: '2px solid #3b82f6'
                      }}>
                        <div style={{ fontSize: '11px', color: '#1e40af', marginBottom: '4px', fontWeight: '700' }}>
                          📤 Turno saliente dejó:
                        </div>
                        <div style={{ fontSize: '20px', fontWeight: '700', color: '#1e40af' }}>
                          {formatCOP(totales.efectivoEnCaja || 0)}
                        </div>
                        <div style={{ fontSize: '9px', color: totales.estaCuadrado ? '#22c55e' : '#f59e0b', marginTop: '4px' }}>
                          {totales.estaCuadrado ? '✅ Estaba cuadrado' : '⚠️ Tenía diferencia'}
                        </div>
                      </div>
                    </div>
                    
                    {/* Resultado de la comparación */}
                    {(() => {
                      const efectivoSaliente = Number(totales.efectivoEnCaja || 0);
                      const efectivoEntrante = Number(efectivoReceptor || 0);
                      const diferencia = efectivoEntrante - efectivoSaliente;
                      const coincide = Math.abs(diferencia) < 1;
                      
                      return (
                        <div style={{
                          padding: '12px',
                          backgroundColor: coincide ? '#d1fae5' : '#fef2f2',
                          borderRadius: '8px',
                          textAlign: 'center',
                          border: `2px solid ${coincide ? '#22c55e' : '#ef4444'}`
                        }}>
                          <div style={{ fontSize: '14px', fontWeight: '700', color: coincide ? '#166534' : '#dc2626' }}>
                            {coincide 
                              ? '✅ ¡Los valores coinciden!'
                              : diferencia > 0 
                                ? `⚠️ Hay ${formatCOP(diferencia)} MÁS de lo declarado`
                                : `🚨 Hay ${formatCOP(Math.abs(diferencia))} MENOS de lo declarado`
                            }
                          </div>
                        </div>
                      );
                    })()}
                  </>
                )}
              </div>
              
              {/* MOSTRAR RESÚMENES SOLO SI YA CONFIRMÓ EL EFECTIVO */}
              {efectivoReceptorConfirmado && (
                <>
                  {/* Resumen de ventas al precierre */}
                  <div style={{
                    padding: '14px',
                    backgroundColor: '#f0fdf4',
                    border: '1px solid #22c55e',
                    borderRadius: '10px',
                    marginBottom: '12px',
                    fontSize: '12px'
                  }}>
                    <h4 style={{ margin: '0 0 10px 0', color: '#166534', fontSize: '13px' }}>💰 VENTAS AL MOMENTO DEL PRECIERRE</h4>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4px' }}>
                      <span>Efectivo: <strong>{formatCOP(totales.ventaEfectivo)}</strong></span>
                      <span>Bancolombia: <strong>{formatCOP(totales.bancolombia)}</strong></span>
                      <span>Davivienda: <strong>{formatCOP(totales.davivienda)}</strong></span>
                      <span>Daviplata: <strong>{formatCOP(totales.daviplata)}</strong></span>
                      <span>Nequi: <strong>{formatCOP(totales.nequi)}</strong></span>
                      <span>Datáfono: <strong>{formatCOP(totales.totalDatafonos)}</strong></span>
                      <span>Online Rappi: <strong>{formatCOP(totales.onlineRappi)}</strong></span>
                    </div>
                    <div style={{ marginTop: '8px', fontWeight: '700', color: '#166534', fontSize: '14px', textAlign: 'right' }}>
                      TOTAL VENTAS: {formatCOP(totales.totalVentas)}
                    </div>
                  </div>
                  
                  {/* Resumen de facturas al precierre */}
                  <div style={{
                    padding: '14px',
                    backgroundColor: '#fef2f2',
                    border: '1px solid #f87171',
                    borderRadius: '10px',
                    marginBottom: '16px',
                    fontSize: '12px'
                  }}>
                    <h4 style={{ margin: '0 0 10px 0', color: '#991b1b', fontSize: '13px' }}>📋 FACTURAS AL MOMENTO DEL PRECIERRE</h4>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
                      <div style={{ padding: '8px', backgroundColor: '#fef3c7', borderRadius: '6px', textAlign: 'center', border: '1px solid #f59e0b' }}>
                        <div style={{ fontSize: '10px', color: '#92400e', marginBottom: '2px' }}>⏳ Pendientes</div>
                        <strong style={{ color: '#ea580c', fontSize: '13px' }}>{formatCOP(totales.totalFacturasPendientes)}</strong>
                      </div>
                      <div style={{ padding: '8px', backgroundColor: '#d1fae5', borderRadius: '6px', textAlign: 'center', border: '1px solid #10b981' }}>
                        <div style={{ fontSize: '10px', color: '#065f46', marginBottom: '2px' }}>💵 Pagadas Caja</div>
                        <strong style={{ color: '#166534', fontSize: '13px' }}>{formatCOP(totales.totalFacturasCaja)}</strong>
                      </div>
                      <div style={{ padding: '8px', backgroundColor: '#dbeafe', borderRadius: '6px', textAlign: 'center', border: '1px solid #3b82f6' }}>
                        <div style={{ fontSize: '10px', color: '#1e40af', marginBottom: '2px' }}>🏦 Pagadas Transfer</div>
                        <strong style={{ color: '#0369a1', fontSize: '13px' }}>{formatCOP(totales.totalFacturasTransferencia)}</strong>
                      </div>
                    </div>
                  </div>
                </>
              )}
              
              {/* Mensaje de confirmación */}
              <div style={{
                padding: '16px',
                backgroundColor: '#e0f2fe',
                border: '2px solid #0ea5e9',
                borderRadius: '12px',
                marginBottom: '20px',
                textAlign: 'center'
              }}>
                <p style={{ margin: 0, fontSize: '14px', color: '#0c4a6e' }}>
                  <strong>Al confirmar</strong>, asumes la responsabilidad del cuadre desde este momento.
                  <br/>
                  El turno de <strong>{p.porNombre}</strong> quedará registrado como cerrado correctamente.
                </p>
              </div>
              
              {/* Lista de empleados con acceso al cuadre */}
              {(() => {
                // Usar solo los empleados con acceso AUTORIZADO (solicitud aprobada)
                const empleadosConAccesoAutorizado = accesosDelCuadre
                  .filter(a => a.estado === 'aprobado')
                  .map(a => ({
                    id: a.solicitante_id,
                    nombre: a.solicitante_nombre,
                    fechaAprobacion: a.fecha_respuesta
                  }));
                  
                const empleadoQueHizoPrecierre = empleados.find(e => e.id === p.porId);
                const empleadoReceptor = empleados.find(e => e.id === p.asignadoAId);
                
                // Filtrar los que no son el que hizo precierre ni el receptor
                const otrosEmpleadosConAcceso = empleadosConAccesoAutorizado.filter(
                  e => e.id !== p.porId && e.id !== p.asignadoAId
                );
                
                return (
                  <div style={{
                    padding: '14px',
                    backgroundColor: '#f1f5f9',
                    border: '1px solid #cbd5e1',
                    borderRadius: '10px',
                    marginBottom: '16px',
                    fontSize: '12px'
                  }}>
                    <strong style={{ color: '#475569', fontSize: '13px' }}>👥 Información de empleados:</strong>
                    
                    {/* Quién hizo el precierre y quién recibe */}
                    <div style={{ 
                      display: 'grid', 
                      gridTemplateColumns: '1fr 1fr', 
                      gap: '10px', 
                      marginTop: '10px',
                      marginBottom: '12px'
                    }}>
                      <div style={{
                        padding: '8px 12px',
                        backgroundColor: '#fef3c7',
                        borderRadius: '8px',
                        border: '1px solid #f59e0b'
                      }}>
                        <div style={{ fontSize: '10px', color: '#92400e', fontWeight: '600' }}>📤 TURNO SALIENTE</div>
                        <div style={{ fontSize: '13px', color: '#78350f', fontWeight: '700', marginTop: '2px' }}>
                          {empleadoQueHizoPrecierre?.nombre || p.porNombre}
                        </div>
                        <div style={{ fontSize: '10px', color: '#a16207' }}>
                          {empleadoQueHizoPrecierre?.perfil || ""}
                        </div>
                      </div>
                      <div style={{
                        padding: '8px 12px',
                        backgroundColor: '#dcfce7',
                        borderRadius: '8px',
                        border: '1px solid #22c55e'
                      }}>
                        <div style={{ fontSize: '10px', color: '#166534', fontWeight: '600' }}>📥 TURNO ENTRANTE (TÚ)</div>
                        <div style={{ fontSize: '13px', color: '#14532d', fontWeight: '700', marginTop: '2px' }}>
                          {empleadoReceptor?.nombre || p.asignadoANombre}
                        </div>
                        <div style={{ fontSize: '10px', color: '#15803d' }}>
                          {empleadoReceptor?.perfil || ""}
                        </div>
                      </div>
                    </div>
                    
                    {/* Lista de otros empleados con acceso AUTORIZADO */}
                    <div style={{ fontSize: '11px', color: '#64748b', marginBottom: '6px' }}>
                      🔐 Otros empleados con acceso autorizado a este cuadre:
                    </div>
                    {otrosEmpleadosConAcceso.length > 0 ? (
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '5px' }}>
                        {otrosEmpleadosConAcceso.slice(0, 8).map(e => (
                          <span key={e.id} style={{
                            padding: '3px 8px',
                            backgroundColor: '#e2e8f0',
                            borderRadius: '10px',
                            fontSize: '10px',
                            color: '#334155'
                          }}>
                            {e.nombre}
                          </span>
                        ))}
                        {otrosEmpleadosConAcceso.length > 8 && (
                          <span style={{ fontSize: '10px', color: '#64748b' }}>
                            +{otrosEmpleadosConAcceso.length - 8} más
                          </span>
                        )}
                      </div>
                    ) : (
                      <div style={{ 
                        padding: '8px 12px',
                        backgroundColor: '#fef2f2',
                        borderRadius: '6px',
                        fontSize: '11px',
                        color: '#991b1b',
                        textAlign: 'center'
                      }}>
                        ⚠️ No hay otros empleados con acceso autorizado a este cuadre
                      </div>
                    )}
                  </div>
                );
              })()}
              
              {/* Opción de reasignación - SOLO GERENCIA y NO el empleado receptor */}
              {esGerente && (empleadoActual?.id || usuarioActual?.id) !== cuadreActivo?.precierre?.asignadoAId && (
                <div style={{
                  padding: '14px',
                  backgroundColor: '#fef3c7',
                  border: '2px dashed #f59e0b',
                  borderRadius: '10px',
                  marginBottom: '20px'
                }}>
                  <h4 style={{ margin: '0 0 10px 0', color: '#92400e', fontSize: '13px' }}>
                    🔄 Reasignar cuadre a otro empleado (Solo Gerencia)
                  </h4>
                  <select
                    value={reasignarACuadre}
                    onChange={(e) => setReasignarACuadre(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '10px 12px',
                      border: '2px solid #f59e0b',
                      borderRadius: '8px',
                      fontSize: '14px',
                      backgroundColor: 'white'
                    }}
                  >
                    <option value="">-- Mantener asignación actual --</option>
                    {empleados
                      .filter(e => e.id !== cuadreActivo?.empleadoId)
                      .map(e => (
                        <option key={e.id} value={e.id}>{e.nombre} ({e.perfil || 'Sin perfil'})</option>
                      ))
                    }
                  </select>
                  {reasignarACuadre && (
                    <button
                      onClick={() => {
                        const nuevoEmpleado = empleados.find(e => e.id === reasignarACuadre);
                        if (!nuevoEmpleado) return;
                        
                        const notaReasignacion = `\n\n🔄 **REASIGNACIÓN POR GERENCIA**\n` +
                          `• Fecha: ${new Date().toLocaleString("es-CO")}\n` +
                          `• Reasignado por: ${empleadoActual?.nombre || usuarioActual?.nombre || "Gerencia"}\n` +
                          `• Nuevo responsable: ${nuevoEmpleado.nombre}\n` +
                          `• Motivo: Reasignación durante confirmación de precierre`;
                        
                        actualizarCuadre(cuadreActivo.id, { 
                          empleadoId: reasignarACuadre,
                          precierre: {
                            ...cuadreActivo.precierre,
                            asignadoAId: reasignarACuadre,
                            asignadoANombre: nuevoEmpleado.nombre
                          },
                          comentarioModificacion: (cuadreActivo.comentarioModificacion || "") + notaReasignacion
                        });
                        
                        setReasignarACuadre("");
                        setMostrarAlertaConfirmarPrecierre(false);
                        setCuadreActivoId(null);
                        alert(`✅ Cuadre reasignado a: ${nuevoEmpleado.nombre}\n\nEl empleado deberá confirmar el precierre cuando abra el cuadre.`);
                      }}
                      style={{
                        marginTop: '10px',
                        padding: '10px 20px',
                        background: 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)',
                        color: 'white',
                        border: 'none',
                        borderRadius: '8px',
                        cursor: 'pointer',
                        fontWeight: '600',
                        width: '100%'
                      }}
                    >
                      🔄 Reasignar a {empleados.find(e => e.id === reasignarACuadre)?.nombre || ""}
                    </button>
                  )}
                </div>
              )}
              
              {/* Botones */}
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'center' }}>
                <button
                  disabled={!efectivoReceptorConfirmado}
                  onClick={() => {
                    if (!efectivoReceptorConfirmado) {
                      alert("⚠️ Debes confirmar cuánto efectivo recibes antes de continuar.");
                      return;
                    }
                    
                    // Confirmar el precierre
                    const fechaConfirmacion = new Date().toISOString();
                    const nombreConfirmador = empleadoActual?.nombre || usuarioActual?.nombre || "Usuario";
                    
                    // Calcular diferencia entre efectivo saliente y entrante
                    const efectivoSaliente = Number(totales.efectivoEnCaja || 0);
                    const efectivoEntrante = Number(efectivoReceptor || 0);
                    const diferenciaRecepcion = efectivoEntrante - efectivoSaliente;
                    const coincide = Math.abs(diferenciaRecepcion) < 1;
                    
                    const notaConfirmacion = `\n\n✅ **PRECIERRE CONFIRMADO**\n` +
                      `• Fecha: ${new Date().toLocaleString("es-CO")}\n` +
                      `• Confirmado por: ${nombreConfirmador}\n` +
                      `• El turno de ${p.porNombre} fue aceptado como correcto.\n` +
                      `\n💵 **VERIFICACIÓN DE EFECTIVO EN RECEPCIÓN:**\n` +
                      `• Efectivo según turno saliente: ${formatCOP(efectivoSaliente)}\n` +
                      `• Efectivo contado por receptor: ${formatCOP(efectivoEntrante)}\n` +
                      `• Diferencia: ${coincide ? '✅ Coincide' : `${diferenciaRecepcion > 0 ? '+' : ''}${formatCOP(diferenciaRecepcion)}`}\n` +
                      `• Estado: ${coincide ? 'CUADRADO' : 'CON DIFERENCIA'}`;
                    
                    const precierreActualizado = {
                      ...cuadreActivo.precierre,
                      confirmadoPorReceptor: true,
                      fechaConfirmacion: fechaConfirmacion,
                      confirmadoPorNombre: nombreConfirmador,
                      // Guardar verificación de efectivo del receptor
                      verificacionReceptor: {
                        efectivoSaliente: efectivoSaliente,
                        efectivoRecibido: efectivoEntrante,
                        diferencia: diferenciaRecepcion,
                        coincide: coincide,
                        fechaVerificacion: fechaConfirmacion
                      }
                    };
                    
                    actualizarCuadre(cuadreActivo.id, { 
                      precierre: precierreActualizado,
                      precierrePendienteConfirmacion: false,
                      comentarioModificacion: (cuadreActivo.comentarioModificacion || "") + notaConfirmacion
                    });
                    
                    // Resetear estados
                    setEfectivoReceptor("");
                    setEfectivoReceptorConfirmado(false);
                    setMostrarAlertaConfirmarPrecierre(false);
                    
                    const mensajeAlerta = coincide 
                      ? "✅ Has confirmado que el turno anterior está correcto.\n\n✅ El efectivo coincide con lo declarado por el turno saliente.\n\nAhora eres responsable del cuadre desde este momento."
                      : `✅ Has confirmado que el turno anterior está correcto.\n\n⚠️ Hay una diferencia de ${formatCOP(Math.abs(diferenciaRecepcion))} en el efectivo.\n\nAhora eres responsable del cuadre desde este momento.`;
                    
                    alert(mensajeAlerta);
                  }}
                  style={{
                    padding: '14px 32px',
                    background: efectivoReceptorConfirmado 
                      ? 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)'
                      : 'linear-gradient(135deg, #94a3b8 0%, #64748b 100%)',
                    color: 'white',
                    border: 'none',
                    borderRadius: '10px',
                    cursor: efectivoReceptorConfirmado ? 'pointer' : 'not-allowed',
                    fontWeight: '700',
                    fontSize: '16px',
                    boxShadow: efectivoReceptorConfirmado 
                      ? '0 4px 12px rgba(34, 197, 94, 0.4)'
                      : 'none',
                    opacity: efectivoReceptorConfirmado ? 1 : 0.7
                  }}
                >
                  {efectivoReceptorConfirmado ? '✅ CUADRE ANTERIOR CORRECTO' : '⏳ Confirma el efectivo primero'}
                </button>
              </div>
              
              <p style={{ 
                textAlign: 'center', 
                marginTop: '16px', 
                fontSize: '11px', 
                color: '#666' 
              }}>
                Si hay algún problema con el turno anterior, comunícalo a tu supervisor antes de confirmar.
              </p>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

/* ====================== MODAL GENÉRICO ====================== */

function ModalCuadre({ isOpen, onClose, title, children }) {
  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 9999
    }}>
      <div style={{
        backgroundColor: 'white',
        borderRadius: '12px',
        padding: '20px',
        maxWidth: '90%',
        maxHeight: '85vh',
        overflowY: 'auto',
        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
        minWidth: '400px'
      }}>
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          marginBottom: '16px',
          borderBottom: '1px solid #e2e8f0',
          paddingBottom: '12px'
        }}>
          <h3 style={{ margin: 0, color: '#1e293b', fontWeight: '700' }}>{title}</h3>
          <button 
            onClick={onClose}
            style={{
              background: 'none',
              border: 'none',
              fontSize: '24px',
              cursor: 'pointer',
              color: '#64748b',
              padding: '4px 8px',
              borderRadius: '4px'
            }}
          >
            ×
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

/* ====================== MENÚ ACCIONES RÁPIDAS ====================== */

function MenuAccionesCuadre({ 
  cuadreActivo, 
  actualizarCuadre, 
  bloqueado,
  tienePermiso
}) {
  const [modalActivo, setModalActivo] = useState(null);

  const acciones = [
    { 
      id: 'turnos', 
      label: 'Turnos', 
      icon: '👥', 
      color: '#8b5cf6',
      permiso: 'admin_cuadre_turnos',
      activo: cuadreActivo.turnosActivos
    },
    { 
      id: 'adelantos', 
      label: 'Adelantos', 
      icon: '💰', 
      color: '#f59e0b',
      permiso: 'admin_cuadre_adelantos',
      activo: cuadreActivo.adelantosActivos
    },
    { 
      id: 'denominaciones', 
      label: 'Denominaciones', 
      icon: '💵', 
      color: '#10b981',
      permiso: 'admin_cuadre_denominaciones',
      activo: cuadreActivo.denominacionesActivas
    },
    { 
      id: 'novedades', 
      label: 'Novedades', 
      icon: '📝', 
      color: '#ef4444',
      permiso: null, // Siempre visible
      activo: cuadreActivo.novedadesActivas
    },
    { 
      id: 'basesDomicilios', 
      label: 'Bases Domicilios', 
      icon: '🚴', 
      color: '#3b82f6',
      permiso: null, // Siempre visible
      activo: cuadreActivo.basesDomiciliosActivas
    },
    { 
      id: 'ingresosVarios', 
      label: 'Ingresos Varios', 
      icon: '💲', 
      color: '#059669',
      permiso: null, // Siempre visible
      activo: cuadreActivo.ingresosVariosActivos
    },
    { 
      id: 'descuadres', 
      label: 'Descuadres', 
      icon: '⚠️', 
      color: '#dc2626',
      permiso: null, // Siempre visible
      activo: cuadreActivo.ventas?.huboDescuadreTransferencia === 'Sí' || cuadreActivo.ventas?.huboDescuadreDatafono === 'Sí'
    }
  ];

  const renderModalContent = () => {
    switch(modalActivo) {
      case 'turnos':
        return (
          <CuadroTurnosModal
            turnos={cuadreActivo.turnos || []}
            onChange={(turnos) => {
              actualizarCuadre(cuadreActivo.id, { turnosActivos: true, turnos });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'adelantos':
        return (
          <CuadroAdelantosModal
            adelantos={cuadreActivo.adelantos || []}
            onChange={(adelantos) => {
              actualizarCuadre(cuadreActivo.id, { adelantosActivos: true, adelantos });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'denominaciones':
        return (
          <CuadroDenominacionesModal
            denoms={cuadreActivo.denoms || DENOMINACIONES.map((v) => ({ valor: v, cantidad: 0, subtotal: 0 }))}
            onChange={(denoms) => {
              actualizarCuadre(cuadreActivo.id, { denominacionesActivas: true, denoms });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'novedades':
        return (
          <CuadroNovedadesModal
            novedades={cuadreActivo.novedades || []}
            onChange={(novedades) => {
              actualizarCuadre(cuadreActivo.id, { novedadesActivas: true, novedades });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'basesDomicilios':
        return (
          <CuadroBasesDomiciliosModal
            basesDomicilios={cuadreActivo.basesDomicilios || []}
            onChange={(basesDomicilios) => {
              actualizarCuadre(cuadreActivo.id, { basesDomiciliosActivas: true, basesDomicilios });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'ingresosVarios':
        return (
          <CuadroIngresosVariosModal
            ingresosVarios={cuadreActivo.ingresosVarios || []}
            onChange={(ingresosVarios) => {
              actualizarCuadre(cuadreActivo.id, { ingresosVariosActivos: true, ingresosVarios });
            }}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      case 'descuadres':
        return (
          <CuadroDescuadresModal
            cuadreActivo={cuadreActivo}
            actualizarCuadre={actualizarCuadre}
            onClose={() => setModalActivo(null)}
            disabled={bloqueado}
          />
        );
      default:
        return null;
    }
  };

  const getTituloModal = () => {
    switch(modalActivo) {
      case 'turnos': return '👥 Pago de Turnos';
      case 'adelantos': return '💰 Adelantos';
      case 'denominaciones': return '💵 Denominaciones de Efectivo';
      case 'novedades': return '📝 Novedades';
      case 'basesDomicilios': return '🚴 Bases Domicilios';
      case 'ingresosVarios': return '💲 Ingresos Varios';
      case 'descuadres': return '⚠️ Descuadres de Caja';
      default: return '';
    }
  };

  return (
    <>
      <div style={{
        marginBottom: '16px',
        padding: '16px',
        backgroundColor: '#f8fafc',
        borderRadius: '12px',
        border: '1px solid #e2e8f0'
      }}>
        <div style={{ 
          fontSize: '13px', 
          fontWeight: '600', 
          color: '#64748b',
          marginBottom: '12px',
          display: 'flex',
          alignItems: 'center',
          gap: '6px'
        }}>
          ⚡ Acciones rápidas:
        </div>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(4, 1fr)',
          gap: '10px'
        }}>
          {acciones.map((accion) => {
            if (accion.permiso && !tienePermiso(accion.permiso)) return null;
            
            return (
              <button
                key={accion.id}
                onClick={() => !bloqueado && setModalActivo(accion.id)}
                disabled={bloqueado}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '6px',
                  padding: '12px 8px',
                  borderRadius: '10px',
                  border: `2px solid ${accion.activo ? accion.color : '#cbd5e1'}`,
                  backgroundColor: accion.activo ? `${accion.color}15` : 'white',
                  color: accion.activo ? accion.color : '#475569',
                  fontWeight: '600',
                  fontSize: '11px',
                  cursor: bloqueado ? 'not-allowed' : 'pointer',
                  transition: 'all 0.2s',
                  opacity: bloqueado ? 0.6 : 1,
                  minHeight: '70px',
                  position: 'relative'
                }}
              >
                <span style={{ fontSize: '20px' }}>{accion.icon}</span>
                <span style={{ textAlign: 'center' }}>{accion.label}</span>
                {accion.activo && (
                  <span style={{
                    position: 'absolute',
                    top: '4px',
                    right: '4px',
                    backgroundColor: accion.color,
                    color: 'white',
                    padding: '2px 6px',
                    borderRadius: '10px',
                    fontSize: '9px'
                  }}>
                    ✓
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <ModalCuadre 
        isOpen={modalActivo !== null} 
        onClose={() => setModalActivo(null)}
        title={getTituloModal()}
      >
        {renderModalContent()}
      </ModalCuadre>
    </>
  );
}

/* ====================== COMPONENTES MODAL INTERNOS ====================== */

function CuadroTurnosModal({ turnos, onChange, onClose, disabled }) {
  const [data, setData] = useState(turnos.length > 0 ? turnos : [
    { id: uid(), empleado: "", valor: "", pagado: false }
  ]);

  const total = useMemo(
    () => data.reduce((s, t) => s + Number(t.valor || 0), 0),
    [data]
  );

  function cambiar(idx, campo, valor) {
    const copia = data.map((t, i) =>
      i === idx ? { ...t, [campo]: valor } : t
    );
    setData(copia);
  }

  function agregarFila() {
    setData([...data, { id: uid(), empleado: "", valor: "", pagado: false }]);
  }

  function guardar() {
    onChange(data);
    onClose();
  }

  return (
    <div>
      <table className="table" style={{ marginBottom: '16px' }}>
        <thead>
          <tr>
            <th>Empleado</th>
            <th>Valor turno</th>
            <th>¿Pagado?</th>
          </tr>
        </thead>
        <tbody>
          {data.map((t, idx) => (
            <tr key={t.id}>
              <td>
                <input
                  className="input"
                  disabled={disabled}
                  value={t.empleado}
                  onChange={(e) => cambiar(idx, "empleado", e.target.value)}
                  placeholder="Nombre empleado"
                />
              </td>
              <td>
                <input
                  className="input"
                  type="number"
                  disabled={disabled}
                  value={t.valor}
                  onChange={(e) => cambiar(idx, "valor", e.target.value)}
                  placeholder="0"
                />
              </td>
              <td>
                <select
                  className="input"
                  disabled={disabled}
                  value={t.pagado ? "Sí" : "No"}
                  onChange={(e) => cambiar(idx, "pagado", e.target.value === "Sí")}
                >
                  <option value="No">No</option>
                  <option value="Sí">Sí</option>
                </select>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        padding: '12px',
        backgroundColor: '#f0fdf4',
        borderRadius: '8px',
        marginBottom: '16px'
      }}>
        <Button variant="outline" onClick={agregarFila} disabled={disabled}>
          + Agregar turno
        </Button>
        <span style={{ fontWeight: '700', color: '#166534' }}>
          Total: {new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(total)}
        </span>
      </div>
      <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
        <Button variant="outline" onClick={onClose}>Cancelar</Button>
        <Button variant="solid" onClick={guardar} disabled={disabled}>
          💾 Guardar turnos
        </Button>
      </div>
    </div>
  );
}

