function CuadroDenominacionesModal({ denoms, onChange, onClose, disabled }) {
  const [data, setData] = useState(denoms);

  const total = useMemo(
    () => data.reduce((s, d) => s + Number(d.subtotal || 0), 0),
    [data]
  );

  function cambiar(idx, cantidad) {
    const cant = Number(cantidad) || 0;
    const copia = data.map((d, i) =>
      i === idx ? { ...d, cantidad: cant, subtotal: cant * d.valor } : d
    );
    setData(copia);
  }

  function guardar() {
    onChange(data);
    onClose();
  }

  return (
    <div>
      <p className="muted" style={{ marginBottom: '12px' }}>
        Ingresa la cantidad de billetes/monedas de cada denominación (COP).
      </p>
      <table className="table" style={{ marginBottom: '16px', maxWidth: '400px' }}>
        <thead>
          <tr>
            <th>Denominación</th>
            <th>Cantidad</th>
            <th>Subtotal</th>
          </tr>
        </thead>
        <tbody>
          {data.map((d, idx) => (
            <tr key={d.valor}>
              <td style={{ fontWeight: '600' }}>
                {new Intl.NumberFormat("es-CO").format(d.valor)}
              </td>
              <td>
                <input
                  className="input"
                  type="number"
                  disabled={disabled}
                  value={d.cantidad || ""}
                  onChange={(e) => cambiar(idx, e.target.value)}
                  style={{ width: '80px' }}
                />
              </td>
              <td style={{ fontWeight: '500' }}>
                {new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(d.subtotal || 0)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'flex-end', 
        alignItems: 'center',
        padding: '12px',
        backgroundColor: '#f0fdf4',
        borderRadius: '8px',
        marginBottom: '16px'
      }}>
        <span style={{ fontWeight: '700', color: '#166534', fontSize: '1.1em' }}>
          TOTAL EFECTIVO: {new Intl.NumberFormat("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 }).format(total)}
        </span>
      </div>
      <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
        <Button variant="outline" onClick={onClose}>Cancelar</Button>
        <Button variant="solid" onClick={guardar} disabled={disabled}>
          💾 Guardar denominaciones
        </Button>
      </div>
    </div>
  );
}

