function GastosRoot({ sedes, empleados, usuarioActual = null, empleadoActual = null, esGerente = false, tienePermiso = () => true, filtroEmpresa = null }) {
  const [modo, setModo] = useState("consultar"); // "consultar" | "manual" | "resumen" | "recurrentes"
  const [cargando, setCargando] = useState(false);
  const [gastosPorSede, setGastosPorSede] = useState({});
  const [gastosDetalle, setGastosDetalle] = useState([]);
  const [resumenGenerado, setResumenGenerado] = useState(null);
  const [resumenesGuardados, setResumenesGuardados] = useState([]);
  
  // ========== ESTADOS PARA GASTOS RECURRENTES ==========
  const [gastosRecurrentes, setGastosRecurrentes] = useState([]);
  const [cargandoRecurrentes, setCargandoRecurrentes] = useState(false);
  const [mesRecurrente, setMesRecurrente] = useState(() => {
    const hoy = new Date();
    return `${hoy.getFullYear()}-${String(hoy.getMonth() + 1).padStart(2, '0')}`;
  });
  const [modalRecurrente, setModalRecurrente] = useState(null); // { gasto, accion: 'vencimiento' | 'pago' | 'confirmar' }
  const [formRecurrente, setFormRecurrente] = useState({
    fechaVencimiento: '',
    valor: '',
    fechaPago: '',
    adjuntos: []
  });
  const [subiendoAdjunto, setSubiendoAdjunto] = useState(false);
  const [sedeRecurrente, setSedeRecurrente] = useState("todas"); // "todas" | sede específica
  const [modalDetallesGasto, setModalDetallesGasto] = useState(null); // Para ver detalles del gasto con adjuntos
  const [vistaVencimientos, setVistaVencimientos] = useState(false); // Vista simplificada de vencimientos
  
  // ========== ESTADOS PARA SMS DE GASTOS RECURRENTES ==========
  const [mostrarConfigSMSGastos, setMostrarConfigSMSGastos] = useState(false);
  const [configSMSGastos, setConfigSMSGastos] = useState({ telefono: "", nombre: "" });
  const [guardandoConfigSMSGastos, setGuardandoConfigSMSGastos] = useState(false);
  
  // Sedes únicas de los gastos recurrentes
  const sedesRecurrentes = useMemo(() => {
    const sedesSet = new Set();
    GASTOS_RECURRENTES_CONFIG.forEach(g => sedesSet.add(g.sede));
    return Array.from(sedesSet).sort();
  }, []);
  
  // Fechas de consulta actualmente mostradas
  const [fechaConsultaDesde, setFechaConsultaDesde] = useState("");
  const [fechaConsultaHasta, setFechaConsultaHasta] = useState("");
  const [fechasPorSede, setFechasPorSede] = useState({});
  const [cargaInicial, setCargaInicial] = useState(false);
  
  // Filtros de consulta - inicializar con mes en curso
  const [tipoConsulta, setTipoConsulta] = useState("todas"); // "todas" | "sede"
  const [sedeSeleccionada, setSedeSeleccionada] = useState("");
  const [tipoFecha, setTipoFecha] = useState("rango"); // "especifica" | "rango"
  const [fechaEspecifica, setFechaEspecifica] = useState("");
  const [fechaDesde, setFechaDesde] = useState(() => {
    const hoy = new Date();
    return new Date(hoy.getFullYear(), hoy.getMonth(), 1).toISOString().slice(0, 10);
  });
  const [fechaHasta, setFechaHasta] = useState(() => new Date().toISOString().slice(0, 10));
  
  // Gastos manuales
  const [gastosManualeas, setGastosManuales] = useState([]);
  const [mostrarModalGastoManual, setMostrarModalGastoManual] = useState(false);
  const [gastoManualSede, setGastoManualSede] = useState("");
  const [gastoManualFecha, setGastoManualFecha] = useState("");
  const [gastoManualProveedor, setGastoManualProveedor] = useState("");
  const [gastoManualConcepto, setGastoManualConcepto] = useState("");
  const [gastoManualValor, setGastoManualValor] = useState("");
  const [guardandoGasto, setGuardandoGasto] = useState(false);
  const [gastoEditandoId, setGastoEditandoId] = useState(null); // Para editar gastos

  // Conceptos predefinidos para gastos manuales
  const conceptosGastos = [
    "Energía",
    "Agua",
    "Gas",
    "Internet",
    "Arriendo",
    "Nómina",
    "Salud",
    "Arreglos",
    "Solomos",
    "Mayonesa",
    "House",
    "Coca-Cola",
    "Devolución a Clientes",
    "Pago de Regalías Julian",
    "Pago de Regalías Jonnier",
    "Pago de Regalías Andres",
    "Pago de Regalías Daniel",
    "Otros Gastos"
  ];

  const formatearMoneda = (valor) => {
    const num = parseFloat(valor) || 0;
    return num.toLocaleString('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0, maximumFractionDigits: 0 });
  };

  // Cargar gastos manuales
  const cargarGastosManuales = async (filtros = {}) => {
    try {
      let query = supabase.from('gastos_manuales').select('*');
      // Filtrar por empresa
      if (filtroEmpresa) query = query.eq('empresa_id', filtroEmpresa);
      if (filtros.sede) query = query.eq('sede', filtros.sede);
      if (filtros.fechaDesde) query = query.gte('fecha', filtros.fechaDesde);
      if (filtros.fechaHasta) query = query.lte('fecha', filtros.fechaHasta);
      
      const { data, error } = await query.order('fecha', { ascending: false });
      
      if (error) {
        console.error("❌ Error cargando gastos manuales:", error);
        return [];
      }
      
      console.log("📦 Gastos manuales cargados:", data?.length || 0, data);
      setGastosManuales(data || []);
      return data || [];
    } catch (e) {
      console.warn("Tabla gastos_manuales no disponible:", e);
      return [];
    }
  };

  // Cargar gastos desde cuadres cerrados
  const cargarGastosDesdeCuadres = async () => {
    setCargando(true);
    try {
      // Construir filtros de fecha
      let fechaInicio, fechaFin;
      if (tipoFecha === "especifica" && fechaEspecifica) {
        fechaInicio = fechaEspecifica;
        fechaFin = fechaEspecifica;
      } else if (tipoFecha === "rango" && fechaDesde && fechaHasta) {
        fechaInicio = fechaDesde;
        fechaFin = fechaHasta;
      } else {
        // Por defecto, último mes
        const hoy = new Date();
        fechaFin = hoy.toISOString().slice(0, 10);
        hoy.setMonth(hoy.getMonth() - 1);
        fechaInicio = hoy.toISOString().slice(0, 10);
      }

      // Cargar cuadres diarios cerrados (estado Final)
      // Nota: si agregas columna fue_reabierto, puedes filtrar con: .or('fue_reabierto.is.null,fue_reabierto.eq.false')
      let query = supabase
        .from('cuadres_diarios')
        .select('*')
        .eq('estado', 'Final')
        .gte('fecha', fechaInicio)
        .lte('fecha', fechaFin);
      
      if (filtroEmpresa) query = query.eq('empresa_id', filtroEmpresa);
      if (tipoConsulta === "sede" && sedeSeleccionada) {
        query = query.eq('sede', sedeSeleccionada);
      }

      const { data: cuadresCerrados, error } = await query;
      
      if (error) {
        console.error("Error cargando cuadres:", error);
        setCargando(false);
        return;
      }

      console.log("✅ Cuadres cerrados cargados:", cuadresCerrados?.length || 0);

      // Cargar gastos manuales con los mismos filtros
      const filtrosGastos = {};
      if (tipoConsulta === "sede" && sedeSeleccionada) filtrosGastos.sede = sedeSeleccionada;
      filtrosGastos.fechaDesde = fechaInicio;
      filtrosGastos.fechaHasta = fechaFin;
      const gastosManualesData = await cargarGastosManuales(filtrosGastos);

      // Función helper para parsear JSON si es string
      const parseJsonSafe = (data, defaultVal = []) => {
        if (!data) return defaultVal;
        if (typeof data === 'string') {
          try { return JSON.parse(data); } catch { return defaultVal; }
        }
        return data;
      };

      // Procesar datos de cuadres cerrados
      const gastosPorSedeTemp = {};
      const detalleTemp = [];

      console.log("📋 Procesando", cuadresCerrados?.length || 0, "cuadres cerrados");

      (cuadresCerrados || []).forEach(cuadre => {
        const sede = cuadre.sede || "Sin sede";
        if (!gastosPorSedeTemp[sede]) {
          gastosPorSedeTemp[sede] = {
            facturasCaja: 0,
            facturasTransferencia: 0,
            domicilios: 0,
            turnos: 0,
            adelantos: 0,
            manuales: 0,
            manualesPorConcepto: {},
            total: 0,
            detalle: []
          };
        }

        // Parsear datos siguiendo la misma estructura que mapearRowCuadreDesdeSupabase
        const ventasRaw = parseJsonSafe(cuadre.ventas, {});
        const facturasRaw = parseJsonSafe(cuadre.facturas, []);
        const domiciliosRaw = parseJsonSafe(cuadre.domicilios, {});
        const descuentosRaw = parseJsonSafe(cuadre.descuentos, {});

        // 1. Facturas - separadas por tipo de pago (caja vs transferencia)
        // Estructura: {proveedor, valor, fechaFactura, facturaEntregada, estado}
        const facturas = Array.isArray(facturasRaw) ? facturasRaw : [];
        const facturasCaja = facturas
          .filter(f => f.estado === "Pagada de caja")
          .reduce((sum, f) => sum + (parseFloat(f.valor) || 0), 0);
        const facturasTransferencia = facturas
          .filter(f => f.estado === "Pagada transferencia")
          .reduce((sum, f) => sum + (parseFloat(f.valor) || 0), 0);
        
        // 2. Domicilios - puede estar en domiciliosRaw.domicilios o ser array directo
        const domiciliosArray = Array.isArray(domiciliosRaw?.domicilios) 
          ? domiciliosRaw.domicilios 
          : Array.isArray(domiciliosRaw) 
            ? domiciliosRaw 
            : [];
        const costoDomicilios = domiciliosArray.reduce((sum, d) => {
          const valor = parseFloat(d.valor_domicilio) || parseFloat(d.valorDomicilio) || parseFloat(d.costo) || parseFloat(d.valor) || 0;
          return sum + valor;
        }, 0);
        
        // 3. Turnos - puede estar en domiciliosRaw.turnos o ventasRaw.turnos
        const turnosArray = Array.isArray(domiciliosRaw?.turnos) 
          ? domiciliosRaw.turnos 
          : Array.isArray(ventasRaw?.turnos) 
            ? ventasRaw.turnos 
            : [];
        const costoTurnos = turnosArray.reduce((sum, t) => sum + (parseFloat(t.valor) || 0), 0);
        
        // 4. Adelantos - puede estar en domiciliosRaw.adelantos o ventasRaw.adelantos
        const adelantosArray = Array.isArray(domiciliosRaw?.adelantos) 
          ? domiciliosRaw.adelantos 
          : Array.isArray(ventasRaw?.adelantos) 
            ? ventasRaw.adelantos 
            : [];
        const costoAdelantos = adelantosArray.reduce((sum, a) => sum + (parseFloat(a.valor) || 0), 0);

        console.log(`  📊 ${sede} - Fecha: ${cuadre.fecha} | Facturas Caja: ${facturasCaja} | Facturas Transf: ${facturasTransferencia} | Dom: ${costoDomicilios} | Turnos: ${costoTurnos} | Adelantos: ${costoAdelantos}`);

        gastosPorSedeTemp[sede].facturasCaja += facturasCaja;
        gastosPorSedeTemp[sede].facturasTransferencia += facturasTransferencia;
        gastosPorSedeTemp[sede].domicilios += costoDomicilios;
        gastosPorSedeTemp[sede].turnos += costoTurnos;
        gastosPorSedeTemp[sede].adelantos += costoAdelantos;

        detalleTemp.push({
          fecha: cuadre.fecha,
          sede: sede,
          facturasCaja,
          domicilios: costoDomicilios,
          turnos: costoTurnos,
          adelantos: costoAdelantos,
          tipo: 'cuadre'
        });
      });

      // Agregar gastos manuales agrupados por concepto
      console.log("📝 Procesando gastos manuales:", gastosManualesData?.length || 0);
      (gastosManualesData || []).forEach(gm => {
        console.log("  📌 Gasto manual:", gm.sede, gm.concepto, gm.valor);
        const sede = gm.sede || "Sin sede";
        const concepto = gm.concepto || "Sin concepto";
        
        if (!gastosPorSedeTemp[sede]) {
          gastosPorSedeTemp[sede] = {
            facturasCaja: 0,
            facturasTransferencia: 0,
            domicilios: 0,
            turnos: 0,
            adelantos: 0,
            manuales: 0,
            manualesPorConcepto: {},
            total: 0,
            detalle: []
          };
        }
        
        // Inicializar manualesPorConcepto si no existe
        if (!gastosPorSedeTemp[sede].manualesPorConcepto) {
          gastosPorSedeTemp[sede].manualesPorConcepto = {};
        }
        
        const valor = parseFloat(gm.valor) || 0;
        gastosPorSedeTemp[sede].manuales += valor;
        
        // Agrupar por concepto
        if (!gastosPorSedeTemp[sede].manualesPorConcepto[concepto]) {
          gastosPorSedeTemp[sede].manualesPorConcepto[concepto] = 0;
        }
        gastosPorSedeTemp[sede].manualesPorConcepto[concepto] += valor;
        
        detalleTemp.push({
          fecha: gm.fecha,
          sede: sede,
          proveedor: gm.proveedor_beneficiario,
          concepto: concepto,
          valor: valor,
          tipo: 'manual'
        });
      });

      // Calcular totales por sede y fechas min/max por sede
      const fechasPorSedeTemp = {};
      Object.keys(gastosPorSedeTemp).forEach(sede => {
        const g = gastosPorSedeTemp[sede];
        g.total = g.facturasCaja + g.facturasTransferencia + g.domicilios + g.turnos + g.adelantos + g.manuales;
      });

      // Calcular fechas min/max por sede desde el detalle
      detalleTemp.forEach(d => {
        const sede = d.sede;
        if (!fechasPorSedeTemp[sede]) {
          fechasPorSedeTemp[sede] = { min: d.fecha, max: d.fecha };
        } else {
          if (d.fecha < fechasPorSedeTemp[sede].min) fechasPorSedeTemp[sede].min = d.fecha;
          if (d.fecha > fechasPorSedeTemp[sede].max) fechasPorSedeTemp[sede].max = d.fecha;
        }
      });

      setGastosPorSede(gastosPorSedeTemp);
      setGastosDetalle(detalleTemp);
      setFechaConsultaDesde(fechaInicio);
      setFechaConsultaHasta(fechaFin);
      setFechasPorSede(fechasPorSedeTemp);
      
    } catch (e) {
      console.error("Error cargando gastos:", e);
    }
    setCargando(false);
  };

  // Guardar gasto manual
  const guardarGastoManual = async () => {
    if (!gastoManualSede || !gastoManualFecha || !gastoManualConcepto || !gastoManualValor) {
      alert("Por favor completa todos los campos obligatorios: Sede, Fecha, Concepto y Valor");
      return;
    }
    
    setGuardandoGasto(true);
    try {
      const datosGasto = {
        sede: gastoManualSede,
        fecha: gastoManualFecha,
        concepto: gastoManualConcepto,
        valor: parseFloat(gastoManualValor) || 0,
        proveedor_beneficiario: gastoManualProveedor || gastoManualConcepto, // Si no hay proveedor, usa el concepto
        categoria: 'manual',
        empresa_id: filtroEmpresa || null,
        created_by_nombre: usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema'
      };
      
      console.log("📝 Guardando gasto manual:", datosGasto);
      
      const { data, error } = await supabase.from('gastos_manuales').insert(datosGasto).select();

      if (error) {
        console.error("❌ Error Supabase completo:", JSON.stringify(error, null, 2));
        console.error("❌ Código:", error.code);
        console.error("❌ Mensaje:", error.message);
        console.error("❌ Detalles:", error.details);
        console.error("❌ Hint:", error.hint);
        
        if (error.code === '42P01' || error.message?.includes('does not exist')) {
          alert("❌ La tabla 'gastos_manuales' no existe en Supabase.\n\nDebes crearla ejecutando el SQL en Supabase.");
        } else {
          alert(`❌ Error: ${error.message || 'Error desconocido'}`);
        }
        throw error;
      }
      
      console.log("✅ Gasto guardado:", data);

      alert("✅ Gasto registrado correctamente");
      setMostrarModalGastoManual(false);
      setGastoManualSede("");
      setGastoManualFecha("");
      setGastoManualProveedor("");
      setGastoManualConcepto("");
      setGastoManualValor("");
      cargarGastosDesdeCuadres();
    } catch (e) {
      console.error("Error guardando gasto:", e);
      alert("❌ Error al guardar el gasto");
    }
    setGuardandoGasto(false);
  };

  // Eliminar gasto manual
  const eliminarGastoManual = async (id) => {
    if (!window.confirm("¿Estás seguro de eliminar este gasto?")) return;
    
    try {
      const { error } = await supabase.from('gastos_manuales').delete().eq('id', id);
      if (error) throw error;
      alert("✅ Gasto eliminado correctamente");
      cargarGastosDesdeCuadres();
    } catch (e) {
      console.error("Error eliminando gasto:", e);
      alert("❌ Error al eliminar el gasto");
    }
  };

  // Editar gasto manual (abrir modal con datos)
  const editarGastoManual = (gasto) => {
    setGastoEditandoId(gasto.id);
    setGastoManualSede(gasto.sede || "");
    setGastoManualFecha(gasto.fecha || "");
    setGastoManualConcepto(gasto.concepto || "");
    setGastoManualProveedor(gasto.proveedor_beneficiario || "");
    setGastoManualValor(gasto.valor?.toString() || "");
    setMostrarModalGastoManual(true);
  };

  // Actualizar gasto manual existente
  const actualizarGastoManual = async () => {
    if (!gastoManualSede || !gastoManualFecha || !gastoManualConcepto || !gastoManualValor) {
      alert("Por favor completa todos los campos obligatorios");
      return;
    }
    
    setGuardandoGasto(true);
    try {
      const datosGasto = {
        sede: gastoManualSede,
        fecha: gastoManualFecha,
        concepto: gastoManualConcepto,
        valor: parseFloat(gastoManualValor) || 0,
        proveedor_beneficiario: gastoManualProveedor || gastoManualConcepto
      };
      
      const { error } = await supabase.from('gastos_manuales')
        .update(datosGasto)
        .eq('id', gastoEditandoId);

      if (error) throw error;

      alert("✅ Gasto actualizado correctamente");
      setMostrarModalGastoManual(false);
      setGastoEditandoId(null);
      setGastoManualSede("");
      setGastoManualFecha("");
      setGastoManualProveedor("");
      setGastoManualConcepto("");
      setGastoManualValor("");
      cargarGastosDesdeCuadres();
    } catch (e) {
      console.error("Error actualizando gasto:", e);
      alert("❌ Error al actualizar el gasto");
    }
    setGuardandoGasto(false);
  };

  // Generar resumen ejecutivo
  const generarResumenEjecutivo = async () => {
    if (Object.keys(gastosPorSede).length === 0) {
      alert("Primero debes consultar los gastos");
      return;
    }

    const detallePorDia = {};
    const detallePorCategoria = { facturasCaja: 0, domicilios: 0, turnos: 0, adelantos: 0, manuales: 0 };
    const manualesPorConcepto = {}; // Desglose de manuales por concepto
    let totalGeneral = 0;

    // Agrupar por día de la semana
    gastosDetalle.forEach(g => {
      const fecha = new Date(g.fecha + 'T12:00:00');
      const diaSemana = fecha.toLocaleDateString('es-CO', { weekday: 'long' });
      
      if (!detallePorDia[diaSemana]) detallePorDia[diaSemana] = 0;
      
      if (g.tipo === 'cuadre') {
        detallePorDia[diaSemana] += (g.facturasCaja || 0) + (g.domicilios || 0) + (g.turnos || 0) + (g.adelantos || 0);
        detallePorCategoria.facturasCaja += g.facturasCaja || 0;
        detallePorCategoria.domicilios += g.domicilios || 0;
        detallePorCategoria.turnos += g.turnos || 0;
        detallePorCategoria.adelantos += g.adelantos || 0;
      } else {
        detallePorDia[diaSemana] += g.valor || 0;
        detallePorCategoria.manuales += g.valor || 0;
        // Agrupar por concepto
        const concepto = g.concepto || 'Sin concepto';
        if (!manualesPorConcepto[concepto]) manualesPorConcepto[concepto] = 0;
        manualesPorConcepto[concepto] += g.valor || 0;
      }
    });

    // Calcular totales
    Object.values(gastosPorSede).forEach(s => totalGeneral += s.total);

    // Encontrar día con más gastos
    let diaMaxGasto = '';
    let maxGasto = 0;
    Object.entries(detallePorDia).forEach(([dia, valor]) => {
      if (valor > maxGasto) {
        maxGasto = valor;
        diaMaxGasto = dia;
      }
    });

    // Encontrar categoría con más gastos
    let categoriaMax = '';
    let maxCategoria = 0;
    Object.entries(detallePorCategoria).forEach(([cat, valor]) => {
      if (valor > maxCategoria) {
        maxCategoria = valor;
        categoriaMax = cat;
      }
    });

    const categoriasNombres = {
      facturasCaja: 'Facturas pagadas por caja',
      domicilios: 'Costo domicilios',
      turnos: 'Turnos',
      adelantos: 'Adelantos',
      manuales: 'Gastos manuales'
    };

    // Generar análisis
    let analisis = `📊 RESUMEN EJECUTIVO DE GASTOS\n`;
    analisis += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;
    analisis += `📅 Período: ${tipoFecha === 'especifica' ? fechaEspecifica : `${fechaDesde} al ${fechaHasta}`}\n`;
    analisis += `🏢 Alcance: ${tipoConsulta === 'todas' ? 'Todas las sedes' : sedeSeleccionada}\n\n`;
    
    analisis += `💰 TOTAL GASTOS: ${formatearMoneda(totalGeneral)}\n\n`;
    
    analisis += `📈 DESGLOSE POR CATEGORÍA:\n`;
    analisis += `   • Facturas Caja: ${formatearMoneda(detallePorCategoria.facturasCaja)} (${((detallePorCategoria.facturasCaja/totalGeneral)*100 || 0).toFixed(1)}%)\n`;
    analisis += `   • Costo Domicilios: ${formatearMoneda(detallePorCategoria.domicilios)} (${((detallePorCategoria.domicilios/totalGeneral)*100 || 0).toFixed(1)}%)\n`;
    analisis += `   • Turnos: ${formatearMoneda(detallePorCategoria.turnos)} (${((detallePorCategoria.turnos/totalGeneral)*100 || 0).toFixed(1)}%)\n`;
    analisis += `   • Adelantos: ${formatearMoneda(detallePorCategoria.adelantos)} (${((detallePorCategoria.adelantos/totalGeneral)*100 || 0).toFixed(1)}%)\n`;
    analisis += `   • Gastos Manuales: ${formatearMoneda(detallePorCategoria.manuales)} (${((detallePorCategoria.manuales/totalGeneral)*100 || 0).toFixed(1)}%)\n`;
    
    // Desglose de gastos manuales por concepto
    if (Object.keys(manualesPorConcepto).length > 0) {
      analisis += `\n📝 DESGLOSE GASTOS MANUALES POR CONCEPTO:\n`;
      Object.entries(manualesPorConcepto)
        .sort((a, b) => b[1] - a[1])
        .forEach(([concepto, valor]) => {
          const porcentaje = ((valor/detallePorCategoria.manuales)*100 || 0).toFixed(1);
          analisis += `      → ${concepto}: ${formatearMoneda(valor)} (${porcentaje}% de manuales)\n`;
        });
    }
    analisis += `\n`;
    
    analisis += `📅 GASTOS POR DÍA DE LA SEMANA:\n`;
    const diasOrdenados = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
    diasOrdenados.forEach(dia => {
      if (detallePorDia[dia]) {
        analisis += `   • ${dia.charAt(0).toUpperCase() + dia.slice(1)}: ${formatearMoneda(detallePorDia[dia])}\n`;
      }
    });
    
    analisis += `\n🔍 ANÁLISIS:\n`;
    analisis += `   • El día con más gastos es: ${diaMaxGasto.toUpperCase()} (${formatearMoneda(maxGasto)})\n`;
    analisis += `   • La categoría con mayor gasto es: ${categoriasNombres[categoriaMax]} (${formatearMoneda(maxCategoria)})\n`;
    
    if (tipoConsulta === 'todas' && Object.keys(gastosPorSede).length > 1) {
      analisis += `\n🏢 GASTOS POR SEDE:\n`;
      Object.entries(gastosPorSede)
        .sort((a, b) => b[1].total - a[1].total)
        .forEach(([sede, datos]) => {
          analisis += `   • ${sede}: ${formatearMoneda(datos.total)}\n`;
        });
    }

    const resumen = {
      periodo: tipoFecha === 'especifica' ? fechaEspecifica : `${fechaDesde} al ${fechaHasta}`,
      tipo: tipoConsulta,
      sede: sedeSeleccionada,
      totalGeneral,
      detallePorCategoria,
      manualesPorConcepto,
      detallePorDia,
      analisis,
      gastosPorSede: { ...gastosPorSede }
    };

    setResumenGenerado(resumen);
    setModo("resumen");
  };

  // Guardar resumen
  const guardarResumen = async () => {
    if (!resumenGenerado) return;
    
    try {
      const { error } = await supabase.from('resumenes_gastos').insert({
        empresa_id: filtroEmpresa,
        tipo: tipoConsulta,
        sede: sedeSeleccionada || null,
        fecha_desde: tipoFecha === 'especifica' ? fechaEspecifica : fechaDesde,
        fecha_hasta: tipoFecha === 'especifica' ? fechaEspecifica : fechaHasta,
        resumen: resumenGenerado,
        analisis: resumenGenerado.analisis,
        total_gastos: resumenGenerado.totalGeneral,
        created_by: usuarioActual?.id || empleadoActual?.id,
        created_by_nombre: usuarioActual?.nombre || empleadoActual?.nombre
      });

      if (error) throw error;
      alert("✅ Resumen guardado correctamente");
      cargarResumenesGuardados();
    } catch (e) {
      console.error("Error guardando resumen:", e);
      alert("❌ Error al guardar el resumen");
    }
  };

  // Cargar resúmenes guardados
  const cargarResumenesGuardados = async () => {
    try {
      let query = supabase.from('resumenes_gastos').select('*').order('created_at', { ascending: false }).limit(20);
      if (filtroEmpresa) query = query.eq('empresa_id', filtroEmpresa);
      const { data } = await query;
      setResumenesGuardados(data || []);
    } catch (e) {
      console.warn("Tabla resumenes_gastos no disponible:", e);
    }
  };

  useEffect(() => {
    cargarResumenesGuardados();
  }, [filtroEmpresa]);

  // Cargar automáticamente al abrir el módulo
  useEffect(() => {
    if (!cargaInicial && fechaDesde && fechaHasta) {
      setCargaInicial(true);
      cargarGastosDesdeCuadres();
    }
  }, [fechaDesde, fechaHasta]);

  // Calcular total general
  const totalGeneral = Object.values(gastosPorSede).reduce((sum, s) => sum + s.total, 0);
  
  // Función para formatear fecha legible
  const formatearFecha = (fecha) => {
    if (!fecha) return '';
    const f = new Date(fecha + 'T12:00:00');
    return f.toLocaleDateString('es-CO', { day: 'numeric', month: 'short', year: 'numeric' });
  };

  // ========== FUNCIONES PARA GASTOS RECURRENTES ==========
  
  // Cargar configuración de SMS para gastos recurrentes (desde tabla empresas)
  const cargarConfigSMSGastos = async () => {
    if (!filtroEmpresa) {
      console.warn("📱 No hay empresa seleccionada para cargar config SMS");
      return;
    }
    try {
      const { data, error } = await supabase
        .from('empresas')
        .select('telefono_sms_gastos, nombre_receptor_sms')
        .eq('id', filtroEmpresa)
        .single();
      
      console.log("📱 Cargando config SMS gastos desde empresas:", data, error);
      
      if (!error && data) {
        setConfigSMSGastos({
          telefono: data.telefono_sms_gastos || "",
          nombre: data.nombre_receptor_sms || ""
        });
      }
    } catch (e) {
      console.warn("Error cargando config SMS gastos:", e);
    }
  };

  // Guardar configuración de SMS para gastos recurrentes (en tabla empresas)
  const guardarConfigSMSGastos = async () => {
    if (!filtroEmpresa) {
      alert("❌ No hay empresa seleccionada");
      return;
    }
    setGuardandoConfigSMSGastos(true);
    try {
      const { error } = await supabase
        .from('empresas')
        .update({
          telefono_sms_gastos: configSMSGastos.telefono,
          nombre_receptor_sms: configSMSGastos.nombre
        })
        .eq('id', filtroEmpresa);
      
      if (error) {
        console.error("Error actualizando empresa:", error);
        throw error;
      }
      
      console.log("✅ Config SMS gastos guardada en empresa:", filtroEmpresa, configSMSGastos);
      alert("✅ Configuración de SMS guardada correctamente");
      setMostrarConfigSMSGastos(false);
    } catch (e) {
      console.error("Error guardando config SMS gastos:", e);
      alert("❌ Error al guardar: " + e.message);
    } finally {
      setGuardandoConfigSMSGastos(false);
    }
  };

  // Enviar SMS de vencimiento de gasto (1 día antes)
  const enviarSMSVencimientoGasto = async (gasto, telefono, fechaVencimiento) => {
    if (!telefono) {
      console.warn("📱 No hay teléfono configurado para notificaciones de gastos");
      return { ok: false, error: "Teléfono no configurado" };
    }

    const valor = gasto.valor || 0;
    // Formatear valor sin símbolo $ (usar solo números con separadores)
    const valorFormateado = new Intl.NumberFormat('es-CO', { minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(valor);
    const nombreGasto = gasto.nombre_gasto || gasto.nombre || 'Gasto sin nombre';
    const sedeGasto = gasto.sede || 'Sin sede';
    const categoriaGasto = gasto.categoria || 'General';
    
    const mensaje = `Recordatorio de Pago
${nombreGasto}
Sede: ${sedeGasto}
Valor: ${valorFormateado} pesos
Vence: ${fechaVencimiento}
Categoria: ${categoriaGasto}
Recuerde pagar manana.`;

    console.log("📱 Enviando SMS de vencimiento:", { nombreGasto, sedeGasto, valor, telefono });
    return enviarSMS(telefono, mensaje);
  };

  // Verificar y notificar vencimientos del DÍA SIGUIENTE (1 día antes)
  // Se ejecuta automáticamente cuando alguien abre el sistema después de las 8 AM
  const verificarVencimientosManana = async () => {
    const ahora = new Date();
    const horaActual = ahora.getHours();
    
    // Solo ejecutar si ya son las 8 AM o más tarde
    if (horaActual < 8) {
      console.log("📅 Aún no son las 8 AM, no se verifican vencimientos");
      return { esperando: true };
    }
    
    const hoyISO = ahora.toISOString().slice(0, 10);
    
    // Calcular fecha de MAÑANA
    const manana = new Date(ahora);
    manana.setDate(manana.getDate() + 1);
    const mananaISO = manana.toISOString().slice(0, 10);
    
    console.log("📅 Verificando vencimientos para MAÑANA:", mananaISO, "(hoy es", hoyISO, ")");
    
    // Verificar si ya se notificó hoy
    const ultimaNotificacion = localStorage.getItem('ultimaNotificacionGastosVencimiento');
    if (ultimaNotificacion === hoyISO) {
      console.log("📅 Ya se verificaron los vencimientos hoy");
      return { yaNotificado: true };
    }

    try {
      // Buscar gastos que vencen MAÑANA
      const { data: gastosVencenManana, error } = await supabase
        .from('gastos_recurrentes')
        .select('*')
        .eq('fecha_vencimiento', mananaISO)
        .neq('estado', 'pagado');
      
      if (error) {
        console.error("Error buscando vencimientos:", error);
        return { error: error.message };
      }

      if (!gastosVencenManana || gastosVencenManana.length === 0) {
        console.log("📅 No hay gastos que venzan mañana:", mananaISO);
        localStorage.setItem('ultimaNotificacionGastosVencimiento', hoyISO);
        return { encontrados: 0, mensaje: "No hay gastos que venzan mañana" };
      }

      // Obtener teléfono configurado
      const { data: configData, error: configError } = await supabase
        .from('configuracion_sistema')
        .select('telefono_notificaciones_gastos')
        .limit(1);
      
      console.log("📱 Config SMS gastos:", configData, configError);
      
      const telefonoNotif = configData?.[0]?.telefono_notificaciones_gastos;
      
      if (!telefonoNotif) {
        console.warn("📱 No hay teléfono configurado para notificaciones de gastos");
        localStorage.setItem('ultimaNotificacionGastosVencimiento', hoyISO);
        return { encontrados: gastosVencenManana.length, sinTelefono: true, mensaje: "No hay teléfono configurado" };
      }

      console.log(`📅 Se encontraron ${gastosVencenManana.length} gastos que vencen MAÑANA, enviando a: ${telefonoNotif}`);

      let enviados = 0;
      let errores = [];
      
      // Enviar SMS por cada gasto que vence mañana
      for (const gasto of gastosVencenManana) {
        console.log("📤 Enviando SMS para gasto:", gasto);
        const resultado = await enviarSMSVencimientoGasto(gasto, telefonoNotif, mananaISO);
        if (resultado.ok) {
          console.log(`✅ SMS enviado para: ${gasto.nombre_gasto}`);
          enviados++;
        } else {
          console.warn(`❌ Error enviando SMS para: ${gasto.nombre_gasto}`, resultado.error);
          errores.push({ gasto: gasto.nombre_gasto, error: resultado.error });
        }
        // Pequeña pausa entre SMS para no saturar
        await new Promise(resolve => setTimeout(resolve, 1000));
      }

      // Marcar como notificado hoy
      localStorage.setItem('ultimaNotificacionGastosVencimiento', hoyISO);
      
      return { encontrados: gastosVencenManana.length, enviados, errores };
      
    } catch (e) {
      console.error("Error en verificarVencimientosManana:", e);
      return { error: e.message };
    }
  };

  // Cargar config SMS al montar el componente y verificar vencimientos automáticamente
  useEffect(() => {
    if (filtroEmpresa) {
      cargarConfigSMSGastos();
    }
    // Verificar vencimientos del DÍA SIGUIENTE automáticamente (solo después de las 8 AM)
    verificarVencimientosManana();
  }, [filtroEmpresa]);
  
  // Cargar gastos recurrentes del mes seleccionado
  const cargarGastosRecurrentes = async () => {
    setCargandoRecurrentes(true);
    try {
      const [anio, mes] = mesRecurrente.split('-');
      const primerDia = `${anio}-${mes}-01`;
      
      // Calcular el último día del mes correctamente
      const ultimoDiaDate = new Date(parseInt(anio), parseInt(mes), 0);
      const ultimoDia = ultimoDiaDate.toISOString().slice(0, 10);
      
      console.log("📅 Buscando gastos recurrentes:", { primerDia, ultimoDia });
      
      // Consultar gastos recurrentes del mes
      const { data, error } = await supabase
        .from('gastos_recurrentes')
        .select('*')
        .gte('periodo_mes', primerDia)
        .lte('periodo_mes', ultimoDia);
      
      if (error) {
        console.error("❌ Error cargando gastos recurrentes:", error);
        setGastosRecurrentes([]);
      } else {
        console.log("✅ Gastos recurrentes cargados:", data?.length || 0, data);
        setGastosRecurrentes(data || []);
      }
    } catch (e) {
      console.error("❌ Error:", e);
      setGastosRecurrentes([]);
    }
    setCargandoRecurrentes(false);
  };

  // Cargar gastos recurrentes cuando cambia el mes
  useEffect(() => {
    if (modo === "recurrentes") {
      cargarGastosRecurrentes();
    }
  }, [mesRecurrente, modo]);

  // Mapear sede desde config a sede real
  const mapearSedeAReal = (sedeConfig) => {
    const mapeo = {
      "SEDE CORALES": "Corales",
      "SEDE AV SUR": "Av Sur",
      "SEDE VILLA DEL PRADO": "Villa del Prado"
    };
    // Buscar en las sedes reales
    const sedeReal = sedes.find(s => 
      s.nombre?.toLowerCase().includes(sedeConfig.replace("SEDE ", "").toLowerCase()) ||
      sedeConfig.toLowerCase().includes(s.nombre?.toLowerCase())
    );
    return sedeReal?.nombre || mapeo[sedeConfig] || sedeConfig;
  };

  // Obtener gasto recurrente del mes actual por id_gasto
  const obtenerGastoMes = (idGasto) => {
    const encontrado = gastosRecurrentes.find(g => g.id_gasto === idGasto);
    return encontrado;
  };

  // Guardar/actualizar información de vencimiento y valor
  const guardarVencimientoGasto = async () => {
    if (!modalRecurrente?.gasto) return;
    
    const gastoConfig = modalRecurrente.gasto;
    const gastoExistente = obtenerGastoMes(gastoConfig.id);
    const [anio, mes] = mesRecurrente.split('-');
    
    try {
      const datosGasto = {
        id_gasto: gastoConfig.id,
        nombre_gasto: gastoConfig.nombre,
        sede: gastoConfig.sede,
        categoria: gastoConfig.categoria,
        matricula: gastoConfig.matricula || null,
        referencia: gastoConfig.referencia || null,
        periodo_mes: `${anio}-${mes}-01`,
        fecha_vencimiento: formRecurrente.fechaVencimiento || null,
        valor: parseFloat(formRecurrente.valor) || 0,
        empresa_id: filtroEmpresa,
        updated_at: new Date().toISOString(),
        updated_by: usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema'
      };
      
      if (gastoExistente) {
        // Actualizar existente
        const { error } = await supabase.from('gastos_recurrentes')
          .update(datosGasto)
          .eq('id', gastoExistente.id);
        
        if (error) throw error;
      } else {
        // Crear nuevo
        datosGasto.estado = 'pendiente';
        datosGasto.created_at = new Date().toISOString();
        datosGasto.created_by = usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema';
        
        const { error } = await supabase.from('gastos_recurrentes').insert(datosGasto);
        if (error) throw error;
      }
      
      alert("✅ Información guardada correctamente");
      setModalRecurrente(null);
      setFormRecurrente({ fechaVencimiento: '', valor: '', fechaPago: '', adjuntos: [] });
      cargarGastosRecurrentes();
    } catch (e) {
      console.error("Error guardando vencimiento:", e);
      alert("❌ Error al guardar: " + (e.message || "Error desconocido"));
    }
  };

  // Guardar fecha de pago y adjuntos
  const guardarPagoGasto = async () => {
    if (!modalRecurrente?.gasto) return;
    
    const gastoConfig = modalRecurrente.gasto;
    const gastoExistente = obtenerGastoMes(gastoConfig.id);
    
    if (!gastoExistente) {
      alert("⚠️ Primero debes registrar el vencimiento y valor del gasto");
      return;
    }
    
    try {
      const datosActualizar = {
        fecha_pago: formRecurrente.fechaPago || null,
        adjuntos: formRecurrente.adjuntos || [],
        updated_at: new Date().toISOString(),
        updated_by: usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema'
      };
      
      const { error } = await supabase.from('gastos_recurrentes')
        .update(datosActualizar)
        .eq('id', gastoExistente.id);
      
      if (error) throw error;
      
      alert("✅ Información de pago guardada");
      setModalRecurrente(null);
      setFormRecurrente({ fechaVencimiento: '', valor: '', fechaPago: '', adjuntos: [] });
      cargarGastosRecurrentes();
    } catch (e) {
      console.error("Error guardando pago:", e);
      alert("❌ Error al guardar: " + (e.message || "Error desconocido"));
    }
  };

  // Subir adjunto para gasto recurrente
  const subirAdjuntoRecurrente = async (archivo) => {
    if (!archivo) return null;
    
    setSubiendoAdjunto(true);
    try {
      const gastoConfig = modalRecurrente?.gasto;
      const extension = archivo.name.split('.').pop();
      const nombreArchivo = `recurrentes/${gastoConfig?.id || 'gasto'}_${Date.now()}.${extension}`;
      
      const { data, error } = await supabase.storage
        .from(SUPABASE_BUCKET_DOCS)
        .upload(nombreArchivo, archivo, { upsert: true });
      
      if (error) throw error;
      
      const { data: urlData } = supabase.storage
        .from(SUPABASE_BUCKET_DOCS)
        .getPublicUrl(nombreArchivo);
      
      const nuevoAdjunto = {
        nombre: archivo.name,
        url: urlData.publicUrl,
        tipo: archivo.type,
        fecha: new Date().toISOString()
      };
      
      setFormRecurrente(prev => ({
        ...prev,
        adjuntos: [...(prev.adjuntos || []), nuevoAdjunto]
      }));
      
      return nuevoAdjunto;
    } catch (e) {
      console.error("Error subiendo archivo:", e);
      alert("❌ Error al subir archivo: " + e.message);
      return null;
    } finally {
      setSubiendoAdjunto(false);
    }
  };

  // Confirmar pago y enviar a gastos manuales
  const confirmarPagoYEnviar = async () => {
    if (!modalRecurrente?.gasto) return;
    
    const gastoConfig = modalRecurrente.gasto;
    const gastoExistente = obtenerGastoMes(gastoConfig.id);
    
    if (!gastoExistente) {
      alert("⚠️ Primero debes registrar la información del gasto");
      return;
    }
    
    if (!gastoExistente.fecha_pago) {
      alert("⚠️ Debes registrar la fecha de pago antes de confirmar");
      return;
    }
    
    if (!gastoExistente.valor || gastoExistente.valor <= 0) {
      alert("⚠️ El valor del gasto debe ser mayor a 0");
      return;
    }
    
    try {
      // 1. Crear gasto manual correspondiente
      const sedeReal = mapearSedeAReal(gastoConfig.sede);
      const datosGastoManual = {
        sede: sedeReal,
        fecha: gastoExistente.fecha_pago,
        concepto: gastoConfig.categoria,
        valor: gastoExistente.valor,
        proveedor_beneficiario: `${gastoConfig.nombre} - ${gastoConfig.sede} - Período: ${mesRecurrente}`,
        categoria: 'recurrente',
        created_by_nombre: usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema'
      };
      
      // Solo agregar empresa_id si existe
      if (filtroEmpresa) {
        datosGastoManual.empresa_id = filtroEmpresa;
      }
      
      const { error: errorManual } = await supabase.from('gastos_manuales').insert(datosGastoManual);
      if (errorManual) throw errorManual;
      
      // 2. Marcar gasto recurrente como pagado
      const { error: errorUpdate } = await supabase.from('gastos_recurrentes')
        .update({
          estado: 'pagado',
          enviado_a_manuales: true,
          fecha_envio_manuales: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          updated_by: usuarioActual?.nombre || empleadoActual?.nombre || 'Sistema'
        })
        .eq('id', gastoExistente.id);
      
      if (errorUpdate) throw errorUpdate;
      
      alert("✅ Pago confirmado y enviado a Gastos Manuales de " + sedeReal);
      setModalRecurrente(null);
      setFormRecurrente({ fechaVencimiento: '', valor: '', fechaPago: '', adjuntos: [] });
      cargarGastosRecurrentes();
    } catch (e) {
      console.error("Error confirmando pago:", e);
      alert("❌ Error: " + (e.message || "Error desconocido"));
    }
  };

  // Abrir modal con datos existentes
  const abrirModalRecurrente = (gasto, accion) => {
    const gastoExistente = obtenerGastoMes(gasto.id);
    
    setFormRecurrente({
      fechaVencimiento: gastoExistente?.fecha_vencimiento || '',
      valor: gastoExistente?.valor?.toString() || '',
      fechaPago: gastoExistente?.fecha_pago || '',
      adjuntos: gastoExistente?.adjuntos || []
    });
    
    setModalRecurrente({ gasto, accion });
  };

  // Agrupar gastos por sede
  const gastosAgrupados = useMemo(() => {
    const agrupados = {};
    GASTOS_RECURRENTES_CONFIG.forEach(g => {
      if (!agrupados[g.sede]) agrupados[g.sede] = [];
      agrupados[g.sede].push(g);
    });
    return agrupados;
  }, []);

  // Separar gastos en pendientes y pagados (con filtro de sede)
  const gastosSeparados = useMemo(() => {
    const pendientes = [];
    const pagados = [];
    
    GASTOS_RECURRENTES_CONFIG.forEach(config => {
      // Aplicar filtro de sede
      if (sedeRecurrente !== "todas" && config.sede !== sedeRecurrente) {
        return; // Saltar este gasto si no coincide con la sede filtrada
      }
      
      const gastoMes = obtenerGastoMes(config.id);
      const item = { ...config, datosDelMes: gastoMes };
      
      if (gastoMes?.estado === 'pagado') {
        pagados.push(item);
      } else {
        pendientes.push(item);
      }
    });
    
    return { pendientes, pagados };
  }, [gastosRecurrentes, sedeRecurrente]);

  return (
    <div style={{ padding: 16 }}>
      {/* Header */}
      <div style={{
        background: 'linear-gradient(135deg, #7b1fa2 0%, #9c27b0 100%)',
        color: 'white',
        padding: 20,
        borderRadius: 16,
        marginBottom: 24
      }}>
        <h2 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: 28 }}>💸</span>
          Gestión de Gastos
        </h2>
        <p style={{ margin: '8px 0 0', opacity: 0.9, fontSize: 14 }}>
          Análisis de gastos por sede basado en cuadres cerrados
        </p>
      </div>

      {/* Tabs de navegación */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 24 }}>
        <button
          onClick={() => setModo("consultar")}
          style={{
            padding: '12px 20px',
            backgroundColor: modo === "consultar" ? '#7b1fa2' : '#f5f5f5',
            color: modo === "consultar" ? 'white' : '#333',
            border: 'none',
            borderRadius: 8,
            cursor: 'pointer',
            fontWeight: 600
          }}
        >
          📊 Consultar Gastos
        </button>
        <button
          onClick={() => setModo("manual")}
          style={{
            padding: '12px 20px',
            backgroundColor: modo === "manual" ? '#7b1fa2' : '#f5f5f5',
            color: modo === "manual" ? 'white' : '#333',
            border: 'none',
            borderRadius: 8,
            cursor: 'pointer',
            fontWeight: 600
          }}
        >
          ➕ Gastos Manuales
        </button>
        <button
          onClick={() => { cargarResumenesGuardados(); setModo("resumen"); }}
          style={{
            padding: '12px 20px',
            backgroundColor: modo === "resumen" ? '#7b1fa2' : '#f5f5f5',
            color: modo === "resumen" ? 'white' : '#333',
            border: 'none',
            borderRadius: 8,
            cursor: 'pointer',
            fontWeight: 600
          }}
        >
          📈 Resumen Ejecutivo
        </button>
        {(tienePermiso("admin_gastos_recurrentes") || tienePermiso("admin_gastos")) && (
        <button
          onClick={() => { cargarGastosRecurrentes(); setModo("recurrentes"); }}
          style={{
            padding: '12px 20px',
            backgroundColor: modo === "recurrentes" ? '#2e7d32' : '#f5f5f5',
            color: modo === "recurrentes" ? 'white' : '#333',
            border: modo === "recurrentes" ? 'none' : '2px solid #2e7d32',
            borderRadius: 8,
            cursor: 'pointer',
            fontWeight: 600
          }}
        >
          🔄 Gastos Recurrentes
        </button>
        )}
      </div>

      {/* Vista: Consultar Gastos */}
      {modo === "consultar" && (
        <div>
          {/* Filtros */}
          <div style={{ 
            backgroundColor: 'white', 
            padding: 20, 
            borderRadius: 12, 
            marginBottom: 24,
            border: '1px solid #e0e0e0'
          }}>
            <h3 style={{ margin: '0 0 16px', color: '#7b1fa2' }}>🔍 Filtros de Consulta</h3>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16 }}>
              {/* Tipo de consulta */}
              <div>
                <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                  Consultar por:
                </label>
                <select
                  value={tipoConsulta}
                  onChange={(e) => setTipoConsulta(e.target.value)}
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd' }}
                >
                  <option value="todas">📊 Todas las sedes</option>
                  <option value="sede">🏢 Sede específica</option>
                </select>
              </div>

              {/* Sede */}
              {tipoConsulta === "sede" && (
                <div>
                  <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                    Sede:
                  </label>
                  <select
                    value={sedeSeleccionada}
                    onChange={(e) => setSedeSeleccionada(e.target.value)}
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd' }}
                  >
                    <option value="">Seleccionar...</option>
                    {sedes.map(s => (
                      <option key={s.id || s.nombre} value={s.nombre}>{s.nombre}</option>
                    ))}
                  </select>
                </div>
              )}

              {/* Tipo de fecha */}
              <div>
                <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                  Período:
                </label>
                <select
                  value={tipoFecha}
                  onChange={(e) => setTipoFecha(e.target.value)}
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd' }}
                >
                  <option value="rango">📅 Rango de fechas</option>
                  <option value="especifica">📆 Fecha específica</option>
                </select>
              </div>

              {/* Fechas */}
              {tipoFecha === "especifica" ? (
                <div>
                  <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                    Fecha:
                  </label>
                  <input
                    type="date"
                    value={fechaEspecifica}
                    onChange={(e) => setFechaEspecifica(e.target.value)}
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                  />
                </div>
              ) : (
                <>
                  <div>
                    <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                      Desde:
                    </label>
                    <input
                      type="date"
                      value={fechaDesde}
                      onChange={(e) => setFechaDesde(e.target.value)}
                      style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                    />
                  </div>
                  <div>
                    <label style={{ display: 'block', marginBottom: 8, fontWeight: 'bold', fontSize: 13 }}>
                      Hasta:
                    </label>
                    <input
                      type="date"
                      value={fechaHasta}
                      onChange={(e) => setFechaHasta(e.target.value)}
                      style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                    />
                  </div>
                </>
              )}
            </div>

            <div style={{ display: 'flex', gap: 12, marginTop: 20 }}>
              <button
                onClick={cargarGastosDesdeCuadres}
                disabled={cargando}
                style={{
                  padding: '12px 24px',
                  backgroundColor: '#7b1fa2',
                  color: 'white',
                  border: 'none',
                  borderRadius: 8,
                  cursor: cargando ? 'wait' : 'pointer',
                  fontWeight: 'bold'
                }}
              >
                {cargando ? '⏳ Cargando...' : '🔍 Consultar Gastos'}
              </button>
              {Object.keys(gastosPorSede).length > 0 && (
                <button
                  onClick={generarResumenEjecutivo}
                  style={{
                    padding: '12px 24px',
                    backgroundColor: '#4caf50',
                    color: 'white',
                    border: 'none',
                    borderRadius: 8,
                    cursor: 'pointer',
                    fontWeight: 'bold'
                  }}
                >
                  📈 Generar Resumen Ejecutivo
                </button>
              )}
            </div>
          </div>

          {/* Resultados */}
          {Object.keys(gastosPorSede).length > 0 && (
            <div>
              {/* Total General */}
              <div style={{
                backgroundColor: '#7b1fa2',
                color: 'white',
                padding: 20,
                borderRadius: 12,
                marginBottom: 20,
                textAlign: 'center'
              }}>
                <div style={{ fontSize: 14, opacity: 0.9 }}>💰 TOTAL GASTOS - TODAS LAS SEDES</div>
                <div style={{ fontSize: 32, fontWeight: 'bold' }}>{formatearMoneda(totalGeneral)}</div>
                <div style={{ fontSize: 13, opacity: 0.85, marginTop: 8 }}>
                  📅 {formatearFecha(fechaConsultaDesde)} — {formatearFecha(fechaConsultaHasta)}
                </div>
              </div>

              {/* Gastos por sede */}
              <div style={{ display: 'grid', gap: 16 }}>
                {Object.entries(gastosPorSede).map(([sede, datos]) => (
                  <div key={sede} style={{
                    backgroundColor: 'white',
                    border: '1px solid #e0e0e0',
                    borderRadius: 12,
                    overflow: 'hidden'
                  }}>
                    <div style={{
                      padding: 16,
                      backgroundColor: '#f3e5f5',
                      borderBottom: '1px solid #e0e0e0'
                    }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <h4 style={{ margin: 0, color: '#7b1fa2' }}>🏢 {sede}</h4>
                        <span style={{ 
                          fontSize: 18, 
                          fontWeight: 'bold', 
                          color: '#7b1fa2' 
                        }}>
                          {formatearMoneda(datos.total)}
                        </span>
                      </div>
                      {fechasPorSede[sede] && (
                        <div style={{ fontSize: 12, color: '#7b1fa2', opacity: 0.8, marginTop: 6 }}>
                          📅 {formatearFecha(fechasPorSede[sede].min)} — {formatearFecha(fechasPorSede[sede].max)}
                        </div>
                      )}
                    </div>
                    <div style={{ padding: 16 }}>
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 12 }}>
                        <div style={{ padding: 12, backgroundColor: '#e3f2fd', borderRadius: 8, textAlign: 'center' }}>
                          <div style={{ fontSize: 12, color: '#1565c0' }}>💵 Facturas Caja</div>
                          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#1565c0' }}>
                            {formatearMoneda(datos.facturasCaja)}
                          </div>
                        </div>
                        <div style={{ padding: 12, backgroundColor: '#e8eaf6', borderRadius: 8, textAlign: 'center' }}>
                          <div style={{ fontSize: 12, color: '#3949ab' }}>🏦 Facturas Transfer</div>
                          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#3949ab' }}>
                            {formatearMoneda(datos.facturasTransferencia)}
                          </div>
                        </div>
                        <div style={{ padding: 12, backgroundColor: '#fff3e0', borderRadius: 8, textAlign: 'center' }}>
                          <div style={{ fontSize: 12, color: '#e65100' }}>🛵 Costo Domicilios</div>
                          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#e65100' }}>
                            {formatearMoneda(datos.domicilios)}
                          </div>
                        </div>
                        <div style={{ padding: 12, backgroundColor: '#e8f5e9', borderRadius: 8, textAlign: 'center' }}>
                          <div style={{ fontSize: 12, color: '#2e7d32' }}>👥 Turnos</div>
                          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#2e7d32' }}>
                            {formatearMoneda(datos.turnos)}
                          </div>
                        </div>
                        <div style={{ padding: 12, backgroundColor: '#fce4ec', borderRadius: 8, textAlign: 'center' }}>
                          <div style={{ fontSize: 12, color: '#c2185b' }}>💵 Adelantos</div>
                          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#c2185b' }}>
                            {formatearMoneda(datos.adelantos)}
                          </div>
                        </div>
                      </div>
                      
                      {/* Gastos Manuales por Concepto */}
                      {datos.manuales > 0 && datos.manualesPorConcepto && Object.keys(datos.manualesPorConcepto).length > 0 && (
                        <div style={{ marginTop: 16 }}>
                          <h5 style={{ margin: '0 0 12px', color: '#512da8', fontSize: 14, display: 'flex', alignItems: 'center', gap: 8 }}>
                            📝 Gastos Manuales: {formatearMoneda(datos.manuales)}
                          </h5>
                          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 8 }}>
                            {Object.entries(datos.manualesPorConcepto)
                              .sort((a, b) => b[1] - a[1])
                              .map(([concepto, valor]) => (
                              <div key={concepto} style={{ 
                                padding: 10, 
                                backgroundColor: '#ede7f6', 
                                borderRadius: 8, 
                                textAlign: 'center',
                                border: '1px solid #d1c4e9'
                              }}>
                                <div style={{ fontSize: 11, color: '#512da8', fontWeight: 500, marginBottom: 4 }}>
                                  {concepto}
                                </div>
                                <div style={{ fontSize: 14, fontWeight: 'bold', color: '#512da8' }}>
                                  {formatearMoneda(valor)}
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Vista: Gastos Manuales */}
      {modo === "manual" && (
        <div>
          <div style={{
            backgroundColor: 'white',
            padding: 20,
            borderRadius: 12,
            marginBottom: 24,
            border: '1px solid #e0e0e0'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <h3 style={{ margin: 0, color: '#7b1fa2' }}>➕ Registrar Gasto Manual</h3>
              <button
                onClick={() => {
                  setGastoEditandoId(null);
                  setGastoManualSede("");
                  setGastoManualFecha("");
                  setGastoManualConcepto("");
                  setGastoManualProveedor("");
                  setGastoManualValor("");
                  setMostrarModalGastoManual(true);
                }}
                style={{
                  padding: '10px 20px',
                  backgroundColor: '#7b1fa2',
                  color: 'white',
                  border: 'none',
                  borderRadius: 8,
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                ➕ Nuevo Gasto
              </button>
            </div>

            <p style={{ color: '#666', fontSize: 14 }}>
              Registra gastos adicionales que no están incluidos en los cuadres diarios 
              (proveedores, servicios, compras, etc.)
            </p>
          </div>

          {/* Lista de gastos manuales recientes */}
          <div style={{
            backgroundColor: 'white',
            padding: 20,
            borderRadius: 12,
            border: '1px solid #e0e0e0'
          }}>
            <h4 style={{ margin: '0 0 16px', color: '#333' }}>📋 Gastos Manuales Registrados</h4>
            {gastosManualeas.length === 0 ? (
              <p style={{ color: '#999', textAlign: 'center', padding: 20 }}>
                No hay gastos manuales registrados
              </p>
            ) : (
              <div style={{ display: 'grid', gap: 8 }}>
                {gastosManualeas.slice(0, 20).map(gm => (
                  <div key={gm.id} style={{
                    padding: 12,
                    backgroundColor: '#f5f5f5',
                    borderRadius: 8,
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center'
                  }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 'bold', color: '#512da8' }}>{gm.concepto || "Sin concepto"}</div>
                      <div style={{ fontSize: 12, color: '#666' }}>
                        🏢 {gm.sede} | 📅 {gm.fecha} {gm.proveedor_beneficiario && gm.proveedor_beneficiario !== gm.concepto && `| 👤 ${gm.proveedor_beneficiario}`}
                      </div>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                      <div style={{ fontWeight: 'bold', color: '#7b1fa2', fontSize: 16 }}>
                        {formatearMoneda(gm.valor)}
                      </div>
                      <div style={{ display: 'flex', gap: 4 }}>
                        <button
                          onClick={() => editarGastoManual(gm)}
                          style={{
                            padding: '6px 10px',
                            backgroundColor: '#ff9800',
                            color: 'white',
                            border: 'none',
                            borderRadius: 4,
                            cursor: 'pointer',
                            fontSize: 12,
                            fontWeight: 'bold'
                          }}
                          title="Editar gasto"
                        >
                          ✏️
                        </button>
                        <button
                          onClick={() => eliminarGastoManual(gm.id)}
                          style={{
                            padding: '6px 10px',
                            backgroundColor: '#f44336',
                            color: 'white',
                            border: 'none',
                            borderRadius: 4,
                            cursor: 'pointer',
                            fontSize: 12,
                            fontWeight: 'bold'
                          }}
                          title="Eliminar gasto"
                        >
                          🗑️
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* Vista: Resumen Ejecutivo */}
      {modo === "resumen" && (
        <div>
          {resumenGenerado ? (
            <div id="resumen-ejecutivo-print" style={{
              fontFamily: 'Arial, Helvetica, sans-serif',
              fontSize: 14,
              color: '#333',
              lineHeight: 1.5
            }}>
              {/* Botones de acción (no se imprimen) */}
              <div className="no-print" style={{ 
                display: 'flex', 
                justifyContent: 'flex-end', 
                gap: 8, 
                marginBottom: 16 
              }}>
                <button
                  onClick={() => window.print()}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#1976d2',
                    color: 'white',
                    border: 'none',
                    borderRadius: 6,
                    cursor: 'pointer',
                    fontWeight: 'bold',
                    fontSize: 14,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 6
                  }}
                >
                  🖨️ Imprimir
                </button>
                <button
                  onClick={guardarResumen}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#4caf50',
                    color: 'white',
                    border: 'none',
                    borderRadius: 6,
                    cursor: 'pointer',
                    fontWeight: 'bold',
                    fontSize: 14
                  }}
                >
                  💾 Guardar
                </button>
                <button
                  onClick={() => setResumenGenerado(null)}
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#757575',
                    color: 'white',
                    border: 'none',
                    borderRadius: 6,
                    cursor: 'pointer',
                    fontSize: 14
                  }}
                >
                  ✖️ Cerrar
                </button>
              </div>

              {/* Contenido del Informe */}
              <div style={{
                backgroundColor: 'white',
                padding: 32,
                borderRadius: 12,
                border: '1px solid #e0e0e0',
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
              }}>
                {/* Encabezado */}
                <div style={{ 
                  textAlign: 'center', 
                  borderBottom: '3px solid #7b1fa2',
                  paddingBottom: 20,
                  marginBottom: 24
                }}>
                  <h1 style={{ 
                    margin: 0, 
                    fontSize: 24, 
                    fontWeight: 'bold',
                    color: '#7b1fa2',
                    letterSpacing: 1
                  }}>
                    INFORME DE GASTOS
                  </h1>
                  <p style={{ margin: '8px 0 0', fontSize: 14, color: '#666' }}>
                    Resumen Ejecutivo
                  </p>
                </div>

                {/* Información del período */}
                <div style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                  gap: 16,
                  backgroundColor: '#f8f9fa',
                  padding: 16,
                  borderRadius: 8,
                  marginBottom: 24
                }}>
                  <div>
                    <span style={{ fontSize: 12, color: '#666', display: 'block' }}>Período</span>
                    <span style={{ fontWeight: 'bold', fontSize: 15 }}>{resumenGenerado.periodo}</span>
                  </div>
                  <div>
                    <span style={{ fontSize: 12, color: '#666', display: 'block' }}>Alcance</span>
                    <span style={{ fontWeight: 'bold', fontSize: 15 }}>
                      {resumenGenerado.tipo === 'todas' ? 'Todas las sedes' : resumenGenerado.sede}
                    </span>
                  </div>
                  <div>
                    <span style={{ fontSize: 12, color: '#666', display: 'block' }}>Fecha de generación</span>
                    <span style={{ fontWeight: 'bold', fontSize: 15 }}>
                      {new Date().toLocaleDateString('es-CO', { day: 'numeric', month: 'long', year: 'numeric' })}
                    </span>
                  </div>
                </div>

                {/* Total General */}
                <div style={{
                  backgroundColor: '#7b1fa2',
                  color: 'white',
                  padding: 20,
                  borderRadius: 8,
                  textAlign: 'center',
                  marginBottom: 24
                }}>
                  <span style={{ fontSize: 14, opacity: 0.9 }}>TOTAL GASTOS DEL PERÍODO</span>
                  <div style={{ fontSize: 32, fontWeight: 'bold', marginTop: 4 }}>
                    {formatearMoneda(resumenGenerado.totalGeneral)}
                  </div>
                </div>

                {/* Sección: Desglose por Categoría */}
                <div style={{ marginBottom: 32 }}>
                  <h2 style={{ 
                    fontSize: 16, 
                    fontWeight: 'bold', 
                    color: '#333',
                    borderBottom: '2px solid #7b1fa2',
                    paddingBottom: 8,
                    marginBottom: 16
                  }}>
                    DESGLOSE POR CATEGORÍA
                  </h2>
                  
                  <table style={{ 
                    width: '100%', 
                    borderCollapse: 'collapse',
                    fontSize: 14
                  }}>
                    <thead>
                      <tr style={{ backgroundColor: '#f5f5f5' }}>
                        <th style={{ padding: 12, textAlign: 'left', borderBottom: '1px solid #ddd' }}>Categoría</th>
                        <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #ddd' }}>Valor</th>
                        <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #ddd' }}>Porcentaje</th>
                        <th style={{ padding: 12, textAlign: 'left', borderBottom: '1px solid #ddd', width: '30%' }}>Distribución</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[
                        { key: 'facturasCaja', label: 'Facturas pagadas por caja', color: '#e91e63' },
                        { key: 'domicilios', label: 'Costo de domicilios', color: '#9c27b0' },
                        { key: 'turnos', label: 'Pago de turnos', color: '#673ab7' },
                        { key: 'adelantos', label: 'Adelantos a empleados', color: '#3f51b5' },
                        { key: 'manuales', label: 'Gastos manuales', color: '#2196f3' }
                      ].map(cat => {
                        const valor = resumenGenerado.detallePorCategoria?.[cat.key] || 0;
                        const porcentaje = resumenGenerado.totalGeneral > 0 
                          ? (valor / resumenGenerado.totalGeneral) * 100 
                          : 0;
                        return (
                          <tr key={cat.key}>
                            <td style={{ padding: 12, borderBottom: '1px solid #eee' }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                <div style={{ width: 12, height: 12, borderRadius: 2, backgroundColor: cat.color }} />
                                {cat.label}
                              </div>
                            </td>
                            <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee', fontWeight: 'bold' }}>
                              {formatearMoneda(valor)}
                            </td>
                            <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee' }}>
                              {porcentaje.toFixed(1)}%
                            </td>
                            <td style={{ padding: 12, borderBottom: '1px solid #eee' }}>
                              <div style={{ 
                                height: 16, 
                                backgroundColor: '#f0f0f0', 
                                borderRadius: 8, 
                                overflow: 'hidden' 
                              }}>
                                <div style={{
                                  height: '100%',
                                  width: `${Math.min(porcentaje, 100)}%`,
                                  backgroundColor: cat.color,
                                  borderRadius: 8
                                }} />
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                    <tfoot>
                      <tr style={{ backgroundColor: '#f5f5f5', fontWeight: 'bold' }}>
                        <td style={{ padding: 12 }}>TOTAL</td>
                        <td style={{ padding: 12, textAlign: 'right' }}>{formatearMoneda(resumenGenerado.totalGeneral)}</td>
                        <td style={{ padding: 12, textAlign: 'right' }}>100%</td>
                        <td style={{ padding: 12 }}></td>
                      </tr>
                    </tfoot>
                  </table>
                </div>

                {/* Sección: Gastos Manuales por Concepto */}
                {resumenGenerado.manualesPorConcepto && Object.keys(resumenGenerado.manualesPorConcepto).length > 0 && (
                  <div style={{ marginBottom: 32 }}>
                    <h2 style={{ 
                      fontSize: 16, 
                      fontWeight: 'bold', 
                      color: '#333',
                      borderBottom: '2px solid #2196f3',
                      paddingBottom: 8,
                      marginBottom: 16
                    }}>
                      DETALLE DE GASTOS MANUALES
                    </h2>
                    
                    <table style={{ 
                      width: '100%', 
                      borderCollapse: 'collapse',
                      fontSize: 14
                    }}>
                      <thead>
                        <tr style={{ backgroundColor: '#e3f2fd' }}>
                          <th style={{ padding: 12, textAlign: 'left', borderBottom: '1px solid #90caf9' }}>Concepto</th>
                          <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #90caf9' }}>Valor</th>
                          <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #90caf9' }}>% del Total Manuales</th>
                        </tr>
                      </thead>
                      <tbody>
                        {Object.entries(resumenGenerado.manualesPorConcepto)
                          .sort((a, b) => b[1] - a[1])
                          .map(([concepto, valor]) => {
                            const porcentaje = resumenGenerado.detallePorCategoria?.manuales > 0
                              ? (valor / resumenGenerado.detallePorCategoria.manuales) * 100
                              : 0;
                            return (
                              <tr key={concepto}>
                                <td style={{ padding: 12, borderBottom: '1px solid #eee' }}>{concepto}</td>
                                <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee', fontWeight: 'bold' }}>
                                  {formatearMoneda(valor)}
                                </td>
                                <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee' }}>
                                  {porcentaje.toFixed(1)}%
                                </td>
                              </tr>
                            );
                          })}
                      </tbody>
                      <tfoot>
                        <tr style={{ backgroundColor: '#e3f2fd', fontWeight: 'bold' }}>
                          <td style={{ padding: 12 }}>SUBTOTAL MANUALES</td>
                          <td style={{ padding: 12, textAlign: 'right' }}>
                            {formatearMoneda(resumenGenerado.detallePorCategoria?.manuales || 0)}
                          </td>
                          <td style={{ padding: 12, textAlign: 'right' }}>100%</td>
                        </tr>
                      </tfoot>
                    </table>
                  </div>
                )}

                {/* Sección: Gastos por Día de la Semana */}
                {resumenGenerado.detallePorDia && Object.keys(resumenGenerado.detallePorDia).length > 0 && (
                  <div style={{ marginBottom: 32 }}>
                    <h2 style={{ 
                      fontSize: 16, 
                      fontWeight: 'bold', 
                      color: '#333',
                      borderBottom: '2px solid #ff9800',
                      paddingBottom: 8,
                      marginBottom: 16
                    }}>
                      DISTRIBUCIÓN POR DÍA DE LA SEMANA
                    </h2>
                    
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: 12 }}>
                      {['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'].map(dia => {
                        const valor = resumenGenerado.detallePorDia[dia] || 0;
                        const maxValor = Math.max(...Object.values(resumenGenerado.detallePorDia), 1);
                        const altura = (valor / maxValor) * 80;
                        return (
                          <div key={dia} style={{ textAlign: 'center' }}>
                            <div style={{ 
                              height: 100, 
                              display: 'flex', 
                              alignItems: 'flex-end', 
                              justifyContent: 'center',
                              marginBottom: 8
                            }}>
                              <div style={{
                                width: '60%',
                                height: altura,
                                backgroundColor: valor === Math.max(...Object.values(resumenGenerado.detallePorDia)) ? '#ff9800' : '#ffcc80',
                                borderRadius: '4px 4px 0 0',
                                minHeight: valor > 0 ? 8 : 0
                              }} />
                            </div>
                            <div style={{ fontSize: 12, fontWeight: 'bold', textTransform: 'capitalize' }}>{dia}</div>
                            <div style={{ fontSize: 11, color: '#666' }}>{formatearMoneda(valor)}</div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                {/* Sección: Gastos por Sede (si aplica) */}
                {resumenGenerado.tipo === 'todas' && resumenGenerado.gastosPorSede && Object.keys(resumenGenerado.gastosPorSede).length > 1 && (
                  <div style={{ marginBottom: 32 }}>
                    <h2 style={{ 
                      fontSize: 16, 
                      fontWeight: 'bold', 
                      color: '#333',
                      borderBottom: '2px solid #4caf50',
                      paddingBottom: 8,
                      marginBottom: 16
                    }}>
                      GASTOS POR SEDE
                    </h2>
                    
                    <table style={{ 
                      width: '100%', 
                      borderCollapse: 'collapse',
                      fontSize: 14
                    }}>
                      <thead>
                        <tr style={{ backgroundColor: '#e8f5e9' }}>
                          <th style={{ padding: 12, textAlign: 'left', borderBottom: '1px solid #a5d6a7' }}>Sede</th>
                          <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #a5d6a7' }}>Total Gastos</th>
                          <th style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #a5d6a7' }}>Porcentaje</th>
                        </tr>
                      </thead>
                      <tbody>
                        {Object.entries(resumenGenerado.gastosPorSede)
                          .sort((a, b) => b[1].total - a[1].total)
                          .map(([sede, datos]) => {
                            const porcentaje = resumenGenerado.totalGeneral > 0
                              ? (datos.total / resumenGenerado.totalGeneral) * 100
                              : 0;
                            return (
                              <tr key={sede}>
                                <td style={{ padding: 12, borderBottom: '1px solid #eee', fontWeight: 500 }}>{sede}</td>
                                <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee', fontWeight: 'bold' }}>
                                  {formatearMoneda(datos.total)}
                                </td>
                                <td style={{ padding: 12, textAlign: 'right', borderBottom: '1px solid #eee' }}>
                                  {porcentaje.toFixed(1)}%
                                </td>
                              </tr>
                            );
                          })}
                      </tbody>
                    </table>
                  </div>
                )}

                {/* Gráfico Circular */}
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'center', 
                  alignItems: 'center',
                  gap: 32,
                  padding: 24,
                  backgroundColor: '#fafafa',
                  borderRadius: 8,
                  marginBottom: 24
                }}>
                  <div style={{
                    width: 160,
                    height: 160,
                    borderRadius: '50%',
                    background: (() => {
                      const cats = resumenGenerado.detallePorCategoria || {};
                      const total = resumenGenerado.totalGeneral || 1;
                      const p1 = ((cats.facturasCaja || 0) / total) * 100;
                      const p2 = p1 + ((cats.domicilios || 0) / total) * 100;
                      const p3 = p2 + ((cats.turnos || 0) / total) * 100;
                      const p4 = p3 + ((cats.adelantos || 0) / total) * 100;
                      return `conic-gradient(
                        #e91e63 0% ${p1}%,
                        #9c27b0 ${p1}% ${p2}%,
                        #673ab7 ${p2}% ${p3}%,
                        #3f51b5 ${p3}% ${p4}%,
                        #2196f3 ${p4}% 100%
                      )`;
                    })(),
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                  }} />
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 'bold', marginBottom: 12, color: '#333' }}>Leyenda:</div>
                    {[
                      { label: 'Facturas Caja', color: '#e91e63' },
                      { label: 'Domicilios', color: '#9c27b0' },
                      { label: 'Turnos', color: '#673ab7' },
                      { label: 'Adelantos', color: '#3f51b5' },
                      { label: 'Manuales', color: '#2196f3' }
                    ].map(item => (
                      <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                        <div style={{ width: 14, height: 14, borderRadius: 3, backgroundColor: item.color }} />
                        <span style={{ fontSize: 13 }}>{item.label}</span>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Pie de página */}
                <div style={{ 
                  textAlign: 'center', 
                  paddingTop: 20, 
                  borderTop: '1px solid #e0e0e0',
                  color: '#999',
                  fontSize: 12
                }}>
                  <p style={{ margin: 0 }}>
                    Informe generado automáticamente por el Sistema de Gestión de Gastos
                  </p>
                  <p style={{ margin: '4px 0 0' }}>
                    {new Date().toLocaleString('es-CO')}
                  </p>
                </div>
              </div>

              {/* Estilos para impresión */}
              <style>{`
                @media print {
                  body * {
                    visibility: hidden;
                  }
                  #resumen-ejecutivo-print, #resumen-ejecutivo-print * {
                    visibility: visible;
                  }
                  #resumen-ejecutivo-print {
                    position: absolute;
                    left: 0;
                    top: 0;
                    width: 100%;
                  }
                  .no-print {
                    display: none !important;
                  }
                  @page {
                    margin: 1cm;
                    size: A4;
                  }
                }
              `}</style>
            </div>
          ) : (
            <div>
              {/* Resúmenes guardados */}
              <div style={{
                backgroundColor: 'white',
                padding: 20,
                borderRadius: 12,
                border: '1px solid #e0e0e0'
              }}>
                <h3 style={{ margin: '0 0 16px', color: '#7b1fa2' }}>📚 Resúmenes Guardados</h3>
                {resumenesGuardados.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
                    <div style={{ fontSize: 48, marginBottom: 16 }}>📊</div>
                    <p>No hay resúmenes guardados</p>
                    <p style={{ fontSize: 13 }}>Consulta gastos y genera un resumen ejecutivo para guardarlo</p>
                    <button
                      onClick={() => setModo("consultar")}
                      style={{
                        marginTop: 16,
                        padding: '12px 24px',
                        backgroundColor: '#7b1fa2',
                        color: 'white',
                        border: 'none',
                        borderRadius: 8,
                        cursor: 'pointer'
                      }}
                    >
                      🔍 Ir a Consultar Gastos
                    </button>
                  </div>
                ) : (
                  <div style={{ display: 'grid', gap: 12 }}>
                    {resumenesGuardados.map(r => (
                      <div key={r.id} style={{
                        padding: 16,
                        backgroundColor: '#f5f5f5',
                        borderRadius: 8,
                        cursor: 'pointer'
                      }}
                      onClick={() => {
                        const resumenParsed = typeof r.resumen === 'string' ? JSON.parse(r.resumen) : r.resumen;
                        setResumenGenerado(resumenParsed);
                      }}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div>
                            <div style={{ fontWeight: 'bold', color: '#7b1fa2' }}>
                              {r.tipo === 'todas' ? '📊 Todas las sedes' : `🏢 ${r.sede}`}
                            </div>
                            <div style={{ fontSize: 12, color: '#666' }}>
                              📅 {r.fecha_desde} al {r.fecha_hasta}
                            </div>
                          </div>
                          <div style={{ textAlign: 'right' }}>
                            <div style={{ fontWeight: 'bold', color: '#333' }}>
                              {formatearMoneda(r.total_gastos)}
                            </div>
                            <div style={{ fontSize: 11, color: '#999' }}>
                              {new Date(r.created_at).toLocaleDateString('es-CO')}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Vista: Gastos Recurrentes */}
      {modo === "recurrentes" && (
        <div>
          {/* Selector de mes y sede */}
          <div style={{
            backgroundColor: 'white',
            padding: 20,
            borderRadius: 12,
            marginBottom: 24,
            border: '2px solid #2e7d32'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 16 }}>
              <div>
                <h3 style={{ margin: 0, color: '#2e7d32', display: 'flex', alignItems: 'center', gap: 8 }}>
                  🔄 Gastos Recurrentes
                </h3>
                <p style={{ margin: '4px 0 0', color: '#666', fontSize: 13 }}>
                  Gestiona los gastos fijos mensuales de cada sede
                </p>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                  <label style={{ fontWeight: 'bold', fontSize: 13 }}>📅 Período:</label>
                  <input
                    type="month"
                    value={mesRecurrente}
                    onChange={(e) => setMesRecurrente(e.target.value)}
                    style={{ padding: 10, borderRadius: 8, border: '2px solid #2e7d32', fontWeight: 'bold' }}
                  />
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                  <label style={{ fontWeight: 'bold', fontSize: 13 }}>🏢 Sede:</label>
                  <select
                    value={sedeRecurrente}
                    onChange={(e) => setSedeRecurrente(e.target.value)}
                    style={{ padding: 10, borderRadius: 8, border: '2px solid #2e7d32', fontWeight: 'bold', minWidth: 160 }}
                  >
                    <option value="todas">📊 Todas las sedes</option>
                    {sedesRecurrentes.map(sede => (
                      <option key={sede} value={sede}>{sede}</option>
                    ))}
                  </select>
                </div>
                <button
                  onClick={cargarGastosRecurrentes}
                  disabled={cargandoRecurrentes}
                  style={{
                    padding: '10px 16px',
                    backgroundColor: '#2e7d32',
                    color: 'white',
                    border: 'none',
                    borderRadius: 8,
                    cursor: 'pointer',
                    fontWeight: 600
                  }}
                >
                  {cargandoRecurrentes ? '⏳ Cargando...' : '🔄 Actualizar'}
                </button>
                <button
                  onClick={() => setVistaVencimientos(!vistaVencimientos)}
                  style={{
                    padding: '10px 16px',
                    backgroundColor: vistaVencimientos ? '#ff5722' : '#1976d2',
                    color: 'white',
                    border: 'none',
                    borderRadius: 8,
                    cursor: 'pointer',
                    fontWeight: 600
                  }}
                >
                  {vistaVencimientos ? '📋 Vista Completa' : '📅 Fechas de Vencimiento'}
                </button>
                <button
                  onClick={() => setMostrarConfigSMSGastos(true)}
                  style={{
                    padding: '10px 16px',
                    backgroundColor: configSMSGastos.telefono ? '#4caf50' : '#ff9800',
                    color: 'white',
                    border: 'none',
                    borderRadius: 8,
                    cursor: 'pointer',
                    fontWeight: 600,
                    display: 'flex',
                    alignItems: 'center',
                    gap: 6
                  }}
                >
                  📱 {configSMSGastos.telefono ? 'SMS Configurado' : 'Configurar SMS'}
                </button>
              </div>
            </div>
          </div>

          {/* Modal Configuración SMS para Gastos */}
          {mostrarConfigSMSGastos && (
            <div style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: 'rgba(0,0,0,0.6)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 9999
            }}>
              <div style={{
                backgroundColor: 'white',
                borderRadius: 16,
                padding: 24,
                width: '450px',
                maxWidth: '95vw',
                boxShadow: '0 8px 32px rgba(0,0,0,0.3)'
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                  <h3 style={{ margin: 0, color: '#2e7d32', display: 'flex', alignItems: 'center', gap: 8 }}>
                    📱 Configurar Notificaciones SMS
                  </h3>
                  <button onClick={() => setMostrarConfigSMSGastos(false)} style={{ background: 'none', border: 'none', fontSize: 24, cursor: 'pointer' }}>×</button>
                </div>
                
                <div style={{ 
                  backgroundColor: '#e8f5e9', 
                  padding: 16, 
                  borderRadius: 12, 
                  marginBottom: 20,
                  border: '1px solid #a5d6a7'
                }}>
                  <p style={{ margin: 0, fontSize: 13, color: '#2e7d32' }}>
                    <strong>📅 Notificación Automática:</strong> El sistema enviará un SMS automáticamente cada día que haya un gasto con fecha de vencimiento ese mismo día.
                  </p>
                </div>

                <div style={{ marginBottom: 16 }}>
                  <label style={{ display: 'block', fontWeight: 'bold', marginBottom: 6, color: '#333' }}>
                    📞 Teléfono para notificaciones:
                  </label>
                  <input
                    type="tel"
                    value={configSMSGastos.telefono}
                    onChange={(e) => setConfigSMSGastos({ ...configSMSGastos, telefono: e.target.value })}
                    placeholder="Ej: 3001234567"
                    style={{
                      width: '100%',
                      padding: 12,
                      fontSize: 16,
                      borderRadius: 8,
                      border: '2px solid #2e7d32',
                      boxSizing: 'border-box'
                    }}
                  />
                </div>

                <div style={{ marginBottom: 20 }}>
                  <label style={{ display: 'block', fontWeight: 'bold', marginBottom: 6, color: '#333' }}>
                    👤 Nombre del receptor:
                  </label>
                  <input
                    type="text"
                    value={configSMSGastos.nombre}
                    onChange={(e) => setConfigSMSGastos({ ...configSMSGastos, nombre: e.target.value })}
                    placeholder="Ej: Administrador"
                    style={{
                      width: '100%',
                      padding: 12,
                      fontSize: 16,
                      borderRadius: 8,
                      border: '2px solid #ddd',
                      boxSizing: 'border-box'
                    }}
                  />
                </div>

                <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end' }}>
                  <button
                    onClick={() => setMostrarConfigSMSGastos(false)}
                    style={{
                      padding: '12px 24px',
                      backgroundColor: '#e0e0e0',
                      color: '#333',
                      border: 'none',
                      borderRadius: 8,
                      cursor: 'pointer',
                      fontWeight: 600
                    }}
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={guardarConfigSMSGastos}
                    disabled={guardandoConfigSMSGastos || !configSMSGastos.telefono}
                    style={{
                      padding: '12px 24px',
                      backgroundColor: '#2e7d32',
                      color: 'white',
                      border: 'none',
                      borderRadius: 8,
                      cursor: guardandoConfigSMSGastos || !configSMSGastos.telefono ? 'not-allowed' : 'pointer',
                      fontWeight: 600,
                      opacity: guardandoConfigSMSGastos || !configSMSGastos.telefono ? 0.6 : 1
                    }}
                  >
                    {guardandoConfigSMSGastos ? '⏳ Guardando...' : '💾 Guardar Configuración'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Vista Simplificada de Vencimientos */}
          {vistaVencimientos ? (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
              {/* Columna: Por Vencer / Vencidos */}
              <div style={{
                backgroundColor: 'white',
                borderRadius: 12,
                border: '2px solid #1976d2',
                padding: 16
              }}>
                <h3 style={{ margin: '0 0 16px', color: '#1565c0', display: 'flex', alignItems: 'center', gap: 8 }}>
                  📅 Estado de Vencimientos
                </h3>
                
                {gastosSeparados.pendientes.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
                    <div style={{ fontSize: 48, marginBottom: 16 }}>✨</div>
                    <p>No hay gastos pendientes</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {gastosSeparados.pendientes
                      .filter(g => g.datosDelMes?.fecha_vencimiento)
                      .sort((a, b) => new Date(a.datosDelMes.fecha_vencimiento) - new Date(b.datosDelMes.fecha_vencimiento))
                      .map(gasto => {
                        const fechaVenc = new Date(gasto.datosDelMes.fecha_vencimiento);
                        const hoy = new Date();
                        hoy.setHours(0, 0, 0, 0);
                        fechaVenc.setHours(0, 0, 0, 0);
                        const diffTime = fechaVenc - hoy;
                        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                        const estaVencido = diffDays < 0;
                        
                        return (
                          <div key={gasto.id} style={{
                            backgroundColor: estaVencido ? '#ffebee' : '#e8f5e9',
                            borderRadius: 8,
                            padding: 10,
                            border: estaVencido ? '1px solid #ef9a9a' : '1px solid #a5d6a7',
                            display: 'grid',
                            gridTemplateColumns: '1fr auto',
                            alignItems: 'center',
                            gap: 8
                          }}>
                            <div>
                              <div style={{ fontWeight: 'bold', fontSize: 13, color: estaVencido ? '#c62828' : '#2e7d32' }}>
                                {gasto.nombre}
                              </div>
                              <div style={{ fontSize: 11, color: '#666' }}>
                                📍 {gasto.sede} | 📅 {formatearFecha(gasto.datosDelMes.fecha_vencimiento)}
                              </div>
                              <div style={{ fontSize: 12, fontWeight: 'bold', color: '#1565c0' }}>
                                💰 {formatearMoneda(gasto.datosDelMes.valor || 0)}
                              </div>
                            </div>
                            <div style={{
                              padding: '6px 10px',
                              borderRadius: 6,
                              backgroundColor: estaVencido ? '#c62828' : '#2e7d32',
                              color: 'white',
                              fontSize: 11,
                              fontWeight: 'bold',
                              textAlign: 'center',
                              minWidth: 80
                            }}>
                              {estaVencido 
                                ? '❌ VENCIDA' 
                                : (diffDays === 0 
                                    ? '⚠️ Hoy vence' 
                                    : `⏳ ${diffDays} día${diffDays > 1 ? 's' : ''}`)
                              }
                            </div>
                          </div>
                        );
                      })
                    }
                    {/* Gastos sin fecha de vencimiento */}
                    {gastosSeparados.pendientes.filter(g => !g.datosDelMes?.fecha_vencimiento).length > 0 && (
                      <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px dashed #ccc' }}>
                        <div style={{ fontSize: 12, color: '#999', marginBottom: 8 }}>Sin fecha registrada:</div>
                        {gastosSeparados.pendientes.filter(g => !g.datosDelMes?.fecha_vencimiento).map(gasto => (
                          <div key={gasto.id} style={{
                            backgroundColor: '#f5f5f5',
                            borderRadius: 6,
                            padding: 8,
                            marginBottom: 4,
                            fontSize: 12,
                            color: '#666'
                          }}>
                            {gasto.nombre} - {gasto.sede}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Columna: Pagados (simplificada) */}
              <div style={{
                backgroundColor: 'white',
                borderRadius: 12,
                border: '2px solid #4caf50',
                padding: 16
              }}>
                <h3 style={{ margin: '0 0 16px', color: '#2e7d32', display: 'flex', alignItems: 'center', gap: 8 }}>
                  ✅ Pagados ({gastosSeparados.pagados.length})
                </h3>
                
                {gastosSeparados.pagados.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
                    <div style={{ fontSize: 48, marginBottom: 16 }}>💸</div>
                    <p>Aún no hay pagos este mes</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {gastosSeparados.pagados.map(gasto => (
                      <div key={gasto.id} style={{
                        backgroundColor: '#e8f5e9',
                        borderRadius: 8,
                        padding: 10,
                        border: '1px solid #a5d6a7',
                        display: 'grid',
                        gridTemplateColumns: '1fr auto',
                        alignItems: 'center',
                        gap: 8
                      }}>
                        <div>
                          <div style={{ fontWeight: 'bold', fontSize: 13, color: '#2e7d32' }}>
                            {gasto.nombre}
                          </div>
                          <div style={{ fontSize: 11, color: '#666' }}>
                            📍 {gasto.sede} | 📅 {formatearFecha(gasto.datosDelMes?.fecha_pago)}
                          </div>
                        </div>
                        <div style={{
                          padding: '6px 10px',
                          borderRadius: 6,
                          backgroundColor: '#2e7d32',
                          color: 'white',
                          fontSize: 11,
                          fontWeight: 'bold'
                        }}>
                          ✅ PAGADO
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ) : (
          /* Vista normal: Dos columnas: Pendientes y Pagados */
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
            {/* Columna: Pendientes de Pago */}
            <div style={{
              backgroundColor: 'white',
              borderRadius: 12,
              border: '1px solid #ffcc80',
              padding: 16
            }}>
              <h3 style={{ margin: '0 0 16px', color: '#e65100', display: 'flex', alignItems: 'center', gap: 8 }}>
                ⏳ Pendientes de Pago ({gastosSeparados.pendientes.length})
              </h3>
              
              {gastosSeparados.pendientes.length === 0 ? (
                <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
                  <div style={{ fontSize: 48, marginBottom: 16 }}>🎉</div>
                  <p>¡Todos los gastos del mes están pagados!</p>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {gastosSeparados.pendientes.map(gasto => {
                    const datosDelMes = gasto.datosDelMes;
                    const tieneVencimiento = datosDelMes?.fecha_vencimiento;
                    const tieneValor = datosDelMes?.valor > 0;
                    const tieneFechaPago = datosDelMes?.fecha_pago;
                    const tieneAdjuntos = datosDelMes?.adjuntos?.length > 0;
                    
                    return (
                      <div key={gasto.id} style={{
                        backgroundColor: '#fff8e1',
                        borderRadius: 8,
                        padding: 12,
                        border: '1px solid #ffcc80',
                        cursor: (tieneVencimiento || tieneAdjuntos) ? 'pointer' : 'default'
                      }}
                      onClick={() => {
                        if (tieneVencimiento || tieneAdjuntos) {
                          setModalDetallesGasto({ gasto, datosDelMes });
                        }
                      }}>
                        <div style={{ marginBottom: 8 }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                            <div style={{ fontWeight: 'bold', fontSize: 13, color: '#e65100' }}>
                              {gasto.nombre}
                            </div>
                            {(tieneVencimiento || tieneAdjuntos) && (
                              <span style={{ fontSize: 10, color: '#1976d2', fontWeight: '500' }}>👆 Ver</span>
                            )}
                          </div>
                          <div style={{ fontSize: 11, color: '#bf360c' }}>
                            📍 {gasto.sede} | 📁 {gasto.categoria}
                          </div>
                          {tieneVencimiento && (
                            <div style={{ fontSize: 11, marginTop: 4 }}>
                              📅 Vence: {formatearFecha(datosDelMes.fecha_vencimiento)} | 💰 {formatearMoneda(datosDelMes.valor || 0)}
                            </div>
                          )}
                          {tieneAdjuntos && (
                            <div style={{ fontSize: 10, marginTop: 4, color: '#1976d2', fontWeight: 'bold' }}>
                              📎 {datosDelMes.adjuntos.length} adjunto(s)
                            </div>
                          )}
                        </div>
                        
                        {/* Sub-botones */}
                        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                          {(tienePermiso("admin_gastos_recurrentes_vencimiento") || tienePermiso("admin_gastos_recurrentes") || tienePermiso("admin_gastos")) && (
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirModalRecurrente(gasto, 'vencimiento'); }}
                            style={{
                              padding: '4px 8px',
                              fontSize: 11,
                              backgroundColor: tieneVencimiento ? '#4caf50' : '#ff9800',
                              color: 'white',
                              border: 'none',
                              borderRadius: 4,
                              cursor: 'pointer'
                            }}
                          >
                            {tieneVencimiento ? '✅ Vencimiento' : '📅 Vencimiento/Valor'}
                          </button>
                          )}
                          
                          {(tienePermiso("admin_gastos_recurrentes_pago") || tienePermiso("admin_gastos_recurrentes") || tienePermiso("admin_gastos")) && (
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirModalRecurrente(gasto, 'pago'); }}
                            disabled={!tieneVencimiento}
                            style={{
                              padding: '4px 8px',
                              fontSize: 11,
                              backgroundColor: !tieneVencimiento ? '#ccc' : (tieneFechaPago ? '#4caf50' : '#2196f3'),
                              color: 'white',
                              border: 'none',
                              borderRadius: 4,
                              cursor: tieneVencimiento ? 'pointer' : 'not-allowed'
                            }}
                          >
                            {tieneFechaPago ? '✅ Pago registrado' : '💳 Fecha Pago/Adjuntos'}
                          </button>
                          )}
                          
                          {(tienePermiso("admin_gastos_recurrentes_confirmar") || tienePermiso("admin_gastos_recurrentes") || tienePermiso("admin_gastos")) && (
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirModalRecurrente(gasto, 'confirmar'); }}
                            disabled={!tieneFechaPago || !tieneValor}
                            style={{
                              padding: '4px 8px',
                              fontSize: 11,
                              backgroundColor: (!tieneFechaPago || !tieneValor) ? '#ccc' : '#7b1fa2',
                              color: 'white',
                              border: 'none',
                              borderRadius: 4,
                              cursor: (tieneFechaPago && tieneValor) ? 'pointer' : 'not-allowed'
                            }}
                          >
                            ✓ Confirmar Pago
                          </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Columna: Pagados */}
            <div style={{
              backgroundColor: 'white',
              borderRadius: 12,
              border: '2px solid #4caf50',
              padding: 16
            }}>
              <h3 style={{ margin: '0 0 16px', color: '#2e7d32', display: 'flex', alignItems: 'center', gap: 8 }}>
                ✅ Pagados ({gastosSeparados.pagados.length})
              </h3>
              
              {gastosSeparados.pagados.length === 0 ? (
                <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>
                  <div style={{ fontSize: 48, marginBottom: 16 }}>💸</div>
                  <p>Aún no hay gastos pagados este mes</p>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {gastosSeparados.pagados.map(gasto => {
                    const datosDelMes = gasto.datosDelMes;
                    
                    return (
                      <div key={gasto.id} style={{
                        backgroundColor: '#e8f5e9',
                        borderRadius: 8,
                        padding: 12,
                        border: '1px solid #a5d6a7',
                        cursor: 'pointer',
                        transition: 'all 0.2s'
                      }}
                      onClick={() => setModalDetallesGasto({ gasto, datosDelMes })}
                      onMouseOver={(e) => e.currentTarget.style.boxShadow = '0 2px 8px rgba(0,0,0,0.15)'}
                      onMouseOut={(e) => e.currentTarget.style.boxShadow = 'none'}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                          <div>
                            <div style={{ fontWeight: 'bold', fontSize: 13, color: '#2e7d32' }}>
                              ✅ {gasto.nombre}
                            </div>
                            <div style={{ fontSize: 11, color: '#1b5e20' }}>
                              📍 {gasto.sede} | 📁 {gasto.categoria}
                            </div>
                            <div style={{ fontSize: 11, marginTop: 4, color: '#388e3c' }}>
                              💰 {formatearMoneda(datosDelMes?.valor || 0)} | 📅 Pagado: {formatearFecha(datosDelMes?.fecha_pago)}
                            </div>
                            {datosDelMes?.adjuntos?.length > 0 && (
                              <div style={{ fontSize: 10, marginTop: 4, color: '#1976d2', fontWeight: 'bold' }}>
                                📎 {datosDelMes.adjuntos.length} adjunto(s) - Click para ver
                              </div>
                            )}
                          </div>
                          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                            <span style={{ fontSize: 24 }}>✅</span>
                            <span style={{ fontSize: 10, color: '#666' }}>👆 Ver</span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
          )}

          {/* Resumen por categoría */}
          <div style={{
            backgroundColor: 'white',
            borderRadius: 12,
            border: '1px solid #e0e0e0',
            padding: 16,
            marginTop: 24
          }}>
            <h3 style={{ margin: '0 0 16px', color: '#7b1fa2' }}>📊 Resumen del Período</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 12 }}>
              <div style={{ backgroundColor: '#fff3e0', padding: 12, borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 'bold', color: '#e65100' }}>
                  {gastosSeparados.pendientes.length}
                </div>
                <div style={{ fontSize: 12, color: '#bf360c' }}>Pendientes</div>
              </div>
              <div style={{ backgroundColor: '#e8f5e9', padding: 12, borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 'bold', color: '#2e7d32' }}>
                  {gastosSeparados.pagados.length}
                </div>
                <div style={{ fontSize: 12, color: '#1b5e20' }}>Pagados</div>
              </div>
              <div style={{ backgroundColor: '#e3f2fd', padding: 12, borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 'bold', color: '#1565c0' }}>
                  {formatearMoneda(gastosSeparados.pagados.reduce((sum, g) => sum + (g.datosDelMes?.valor || 0), 0))}
                </div>
                <div style={{ fontSize: 12, color: '#0d47a1' }}>Total Pagado</div>
              </div>
              <div style={{ backgroundColor: '#fce4ec', padding: 12, borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: 24, fontWeight: 'bold', color: '#c2185b' }}>
                  {formatearMoneda(gastosSeparados.pendientes.reduce((sum, g) => sum + (g.datosDelMes?.valor || 0), 0))}
                </div>
                <div style={{ fontSize: 12, color: '#880e4f' }}>Pendiente por Pagar</div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Gastos Recurrentes */}
      {modalRecurrente && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.5)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1000
        }}>
          <div style={{
            backgroundColor: 'white',
            borderRadius: 16,
            padding: 24,
            width: '100%',
            maxWidth: 500,
            maxHeight: '90vh',
            overflow: 'auto'
          }}>
            <h3 style={{ margin: '0 0 8px', color: '#2e7d32' }}>
              {modalRecurrente.accion === 'vencimiento' && '📅 Fecha de Vencimiento y Valor'}
              {modalRecurrente.accion === 'pago' && '💳 Registrar Pago y Adjuntos'}
              {modalRecurrente.accion === 'confirmar' && '✓ Confirmar Pago Realizado'}
            </h3>
            <div style={{ fontSize: 13, color: '#666', marginBottom: 16 }}>
              <strong>{modalRecurrente.gasto.nombre}</strong> - {modalRecurrente.gasto.sede}
            </div>

            {/* Formulario según acción */}
            {modalRecurrente.accion === 'vencimiento' && (
              <div style={{ display: 'grid', gap: 16 }}>
                <div>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                    Fecha de Vencimiento
                  </label>
                  <input
                    type="date"
                    value={formRecurrente.fechaVencimiento}
                    onChange={(e) => setFormRecurrente(prev => ({ ...prev, fechaVencimiento: e.target.value }))}
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                  />
                </div>
                <div>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                    Valor a Pagar
                  </label>
                  <input
                    type="number"
                    value={formRecurrente.valor}
                    onChange={(e) => setFormRecurrente(prev => ({ ...prev, valor: e.target.value }))}
                    placeholder="0"
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                  />
                </div>
              </div>
            )}

            {modalRecurrente.accion === 'pago' && (
              <div style={{ display: 'grid', gap: 16 }}>
                <div>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                    Fecha de Pago
                  </label>
                  <input
                    type="date"
                    value={formRecurrente.fechaPago}
                    onChange={(e) => setFormRecurrente(prev => ({ ...prev, fechaPago: e.target.value }))}
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                  />
                </div>
                <div>
                  <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                    Adjuntar Comprobantes (PDF o Imágenes)
                  </label>
                  <input
                    type="file"
                    accept=".pdf,.jpg,.jpeg,.png"
                    onChange={(e) => {
                      const archivo = e.target.files?.[0];
                      if (archivo) subirAdjuntoRecurrente(archivo);
                    }}
                    disabled={subiendoAdjunto}
                    style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                  />
                  {subiendoAdjunto && <p style={{ fontSize: 12, color: '#666' }}>⏳ Subiendo archivo...</p>}
                </div>
                {formRecurrente.adjuntos?.length > 0 && (
                  <div>
                    <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                      📎 Archivos adjuntos:
                    </label>
                    {formRecurrente.adjuntos.map((adj, idx) => (
                      <div key={idx} style={{ fontSize: 12, padding: 4, backgroundColor: '#f5f5f5', borderRadius: 4, marginBottom: 4 }}>
                        <a href={adj.url} target="_blank" rel="noopener noreferrer" style={{ color: '#1976d2' }}>
                          📄 {adj.nombre}
                        </a>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {modalRecurrente.accion === 'confirmar' && (
              <div style={{ backgroundColor: '#fff3e0', padding: 16, borderRadius: 8, marginBottom: 16 }}>
                <p style={{ margin: 0, fontSize: 13 }}>
                  <strong>⚠️ Confirmar pago realizado:</strong>
                </p>
                <ul style={{ margin: '8px 0 0', paddingLeft: 20, fontSize: 13 }}>
                  <li>Este gasto se marcará como <strong style={{ color: '#2e7d32' }}>PAGADO</strong></li>
                  <li>Se enviará automáticamente a <strong>Gastos Manuales</strong> de la sede correspondiente</li>
                  <li>Aparecerá en verde en la columna de pagados</li>
                </ul>
                <div style={{ marginTop: 12, padding: 12, backgroundColor: 'white', borderRadius: 8 }}>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, fontSize: 12 }}>
                    <div><strong>Valor:</strong> {formatearMoneda(obtenerGastoMes(modalRecurrente.gasto.id)?.valor || 0)}</div>
                    <div><strong>Fecha pago:</strong> {formatearFecha(obtenerGastoMes(modalRecurrente.gasto.id)?.fecha_pago)}</div>
                    <div><strong>Sede destino:</strong> {mapearSedeAReal(modalRecurrente.gasto.sede)}</div>
                    <div><strong>Concepto:</strong> {modalRecurrente.gasto.categoria}</div>
                  </div>
                </div>
              </div>
            )}

            {/* Botones del modal */}
            <div style={{ display: 'flex', gap: 12, marginTop: 24 }}>
              <button
                onClick={() => {
                  setModalRecurrente(null);
                  setFormRecurrente({ fechaVencimiento: '', valor: '', fechaPago: '', adjuntos: [] });
                }}
                style={{
                  flex: 1,
                  padding: '12px 16px',
                  backgroundColor: '#f5f5f5',
                  color: '#333',
                  border: '1px solid #ddd',
                  borderRadius: 8,
                  cursor: 'pointer'
                }}
              >
                Cancelar
              </button>
              <button
                onClick={() => {
                  if (modalRecurrente.accion === 'vencimiento') guardarVencimientoGasto();
                  else if (modalRecurrente.accion === 'pago') guardarPagoGasto();
                  else if (modalRecurrente.accion === 'confirmar') confirmarPagoYEnviar();
                }}
                style={{
                  flex: 1,
                  padding: '12px 16px',
                  backgroundColor: modalRecurrente.accion === 'confirmar' ? '#7b1fa2' : '#2e7d32',
                  color: 'white',
                  border: 'none',
                  borderRadius: 8,
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                {modalRecurrente.accion === 'vencimiento' && '💾 Guardar'}
                {modalRecurrente.accion === 'pago' && '💾 Guardar Pago'}
                {modalRecurrente.accion === 'confirmar' && '✓ Confirmar y Enviar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Detalles del Gasto Recurrente con Adjuntos */}
      {modalDetallesGasto && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.6)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1001
        }}
        onClick={(e) => {
          if (e.target === e.currentTarget) setModalDetallesGasto(null);
        }}>
          <div style={{
            backgroundColor: 'white',
            borderRadius: 16,
            padding: 24,
            width: '100%',
            maxWidth: 550,
            maxHeight: '85vh',
            overflow: 'auto',
            boxShadow: '0 8px 32px rgba(0,0,0,0.3)'
          }}>
            {/* Cabecera */}
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'flex-start',
              marginBottom: 20,
              paddingBottom: 16,
              borderBottom: '2px solid #e0e0e0'
            }}>
              <div>
                <h3 style={{ margin: 0, color: modalDetallesGasto.datosDelMes?.estado === 'pagado' ? '#2e7d32' : '#e65100' }}>
                  {modalDetallesGasto.datosDelMes?.estado === 'pagado' ? '✅' : '⏳'} {modalDetallesGasto.gasto.nombre}
                </h3>
                <div style={{ fontSize: 13, color: '#666', marginTop: 4 }}>
                  📍 {modalDetallesGasto.gasto.sede} | 📁 {modalDetallesGasto.gasto.categoria}
                </div>
              </div>
              <button
                onClick={() => setModalDetallesGasto(null)}
                style={{
                  padding: '8px 12px',
                  backgroundColor: '#f5f5f5',
                  border: '1px solid #ddd',
                  borderRadius: 8,
                  cursor: 'pointer',
                  fontSize: 16
                }}
              >
                ✕
              </button>
            </div>

            {/* Información del Gasto */}
            <div style={{
              backgroundColor: modalDetallesGasto.datosDelMes?.estado === 'pagado' ? '#e8f5e9' : '#fff8e1',
              borderRadius: 12,
              padding: 16,
              marginBottom: 20
            }}>
              <h4 style={{ margin: '0 0 12px', fontSize: 14, color: '#333' }}>📋 Información del Gasto</h4>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div>
                  <div style={{ fontSize: 11, color: '#666', marginBottom: 2 }}>Estado</div>
                  <div style={{
                    fontWeight: 'bold',
                    color: modalDetallesGasto.datosDelMes?.estado === 'pagado' ? '#2e7d32' : '#e65100',
                    fontSize: 14
                  }}>
                    {modalDetallesGasto.datosDelMes?.estado === 'pagado' ? '✅ PAGADO' : '⏳ PENDIENTE'}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: '#666', marginBottom: 2 }}>Valor</div>
                  <div style={{ fontWeight: 'bold', color: '#1565c0', fontSize: 16 }}>
                    {formatearMoneda(modalDetallesGasto.datosDelMes?.valor || 0)}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: '#666', marginBottom: 2 }}>Fecha Vencimiento</div>
                  <div style={{ fontWeight: '500', fontSize: 13 }}>
                    {modalDetallesGasto.datosDelMes?.fecha_vencimiento 
                      ? formatearFecha(modalDetallesGasto.datosDelMes.fecha_vencimiento) 
                      : '— Sin registrar'}
                  </div>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: '#666', marginBottom: 2 }}>Fecha de Pago</div>
                  <div style={{ fontWeight: '500', fontSize: 13 }}>
                    {modalDetallesGasto.datosDelMes?.fecha_pago 
                      ? formatearFecha(modalDetallesGasto.datosDelMes.fecha_pago) 
                      : '— Sin registrar'}
                  </div>
                </div>
              </div>
              
              {/* Info adicional si existe */}
              {(modalDetallesGasto.gasto.matricula || modalDetallesGasto.gasto.referencia) && (
                <div style={{ marginTop: 12, paddingTop: 12, borderTop: '1px dashed #ccc' }}>
                  {modalDetallesGasto.gasto.matricula && (
                    <div style={{ fontSize: 12, marginBottom: 4 }}>
                      <strong>🔢 Matrícula:</strong> {modalDetallesGasto.gasto.matricula}
                    </div>
                  )}
                  {modalDetallesGasto.gasto.referencia && (
                    <div style={{ fontSize: 12 }}>
                      <strong>📝 Referencia:</strong> {modalDetallesGasto.gasto.referencia}
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Sección de Adjuntos */}
            <div style={{
              backgroundColor: '#f5f5f5',
              borderRadius: 12,
              padding: 16
            }}>
              <h4 style={{ margin: '0 0 12px', fontSize: 14, color: '#333', display: 'flex', alignItems: 'center', gap: 8 }}>
                📎 Archivos Adjuntos
                {modalDetallesGasto.datosDelMes?.adjuntos?.length > 0 && (
                  <span style={{
                    backgroundColor: '#1976d2',
                    color: 'white',
                    padding: '2px 8px',
                    borderRadius: 12,
                    fontSize: 11
                  }}>
                    {modalDetallesGasto.datosDelMes.adjuntos.length}
                  </span>
                )}
              </h4>
              
              {(!modalDetallesGasto.datosDelMes?.adjuntos || modalDetallesGasto.datosDelMes.adjuntos.length === 0) ? (
                <div style={{ textAlign: 'center', padding: 24, color: '#999' }}>
                  <div style={{ fontSize: 32, marginBottom: 8 }}>📭</div>
                  <p style={{ margin: 0, fontSize: 13 }}>No hay archivos adjuntos</p>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {modalDetallesGasto.datosDelMes.adjuntos.map((adj, idx) => {
                    const esImagen = adj.nombre?.match(/\.(jpg|jpeg|png|gif|webp)$/i);
                    const esPDF = adj.nombre?.match(/\.pdf$/i);
                    
                    return (
                      <div key={idx} style={{
                        backgroundColor: 'white',
                        borderRadius: 8,
                        padding: 12,
                        border: '1px solid #e0e0e0',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center'
                      }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flex: 1 }}>
                          <div style={{
                            width: 40,
                            height: 40,
                            backgroundColor: esPDF ? '#f44336' : '#4caf50',
                            borderRadius: 8,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: 'white',
                            fontSize: 18
                          }}>
                            {esPDF ? '📄' : '🖼️'}
                          </div>
                          <div style={{ overflow: 'hidden' }}>
                            <div style={{
                              fontWeight: '500',
                              fontSize: 13,
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              maxWidth: 200
                            }}>
                              {adj.nombre || 'Archivo sin nombre'}
                            </div>
                            <div style={{ fontSize: 11, color: '#666' }}>
                              {esPDF ? 'Documento PDF' : (esImagen ? 'Imagen' : 'Archivo')}
                            </div>
                          </div>
                        </div>
                        <div style={{ display: 'flex', gap: 8 }}>
                          {/* Botón Ver */}
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              window.open(adj.url, '_blank');
                            }}
                            style={{
                              padding: '8px 16px',
                              backgroundColor: '#1976d2',
                              color: 'white',
                              border: 'none',
                              borderRadius: 6,
                              cursor: 'pointer',
                              fontSize: 12,
                              fontWeight: 'bold'
                            }}
                            title="Ver archivo"
                          >
                            Ver
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Botón Cerrar */}
            <div style={{ marginTop: 20, display: 'flex', justifyContent: 'center' }}>
              <button
                onClick={() => setModalDetallesGasto(null)}
                style={{
                  padding: '12px 32px',
                  backgroundColor: '#424242',
                  color: 'white',
                  border: 'none',
                  borderRadius: 8,
                  cursor: 'pointer',
                  fontWeight: 'bold',
                  fontSize: 14
                }}
              >
                Cerrar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: Nuevo Gasto Manual */}
      {mostrarModalGastoManual && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.5)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1000
        }}>
          <div style={{
            backgroundColor: 'white',
            borderRadius: 16,
            padding: 24,
            width: '100%',
            maxWidth: 450
          }}>
            <h3 style={{ margin: '0 0 20px', color: '#7b1fa2' }}>
              {gastoEditandoId ? '✏️ Editar Gasto Manual' : '➕ Nuevo Gasto Manual'}
            </h3>
            
            <div style={{ display: 'grid', gap: 16 }}>
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                  Sede *
                </label>
                <select
                  value={gastoManualSede}
                  onChange={(e) => setGastoManualSede(e.target.value)}
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd' }}
                >
                  <option value="">Seleccionar...</option>
                  {sedes.map(s => (
                    <option key={s.id || s.nombre} value={s.nombre}>{s.nombre}</option>
                  ))}
                </select>
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                  Fecha *
                </label>
                <input
                  type="date"
                  value={gastoManualFecha}
                  onChange={(e) => setGastoManualFecha(e.target.value)}
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                />
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                  Concepto *
                </label>
                <select
                  value={gastoManualConcepto}
                  onChange={(e) => setGastoManualConcepto(e.target.value)}
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd' }}
                >
                  <option value="">Seleccionar concepto...</option>
                  {conceptosGastos.map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                  Proveedor / Beneficiario (opcional)
                </label>
                <input
                  type="text"
                  value={gastoManualProveedor}
                  onChange={(e) => setGastoManualProveedor(e.target.value)}
                  placeholder="Nombre del proveedor o beneficiario"
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                />
              </div>
              
              <div>
                <label style={{ display: 'block', marginBottom: 6, fontWeight: 'bold', fontSize: 13 }}>
                  Valor *
                </label>
                <input
                  type="number"
                  value={gastoManualValor}
                  onChange={(e) => setGastoManualValor(e.target.value)}
                  placeholder="0"
                  style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', boxSizing: 'border-box' }}
                />
              </div>
            </div>

            <div style={{ display: 'flex', gap: 12, marginTop: 24 }}>
              <button
                onClick={() => {
                  setMostrarModalGastoManual(false);
                  setGastoEditandoId(null);
                }}
                style={{
                  flex: 1,
                  padding: '12px 16px',
                  backgroundColor: '#f5f5f5',
                  color: '#333',
                  border: '1px solid #ddd',
                  borderRadius: 8,
                  cursor: 'pointer'
                }}
              >
                Cancelar
              </button>
              <button
                onClick={gastoEditandoId ? actualizarGastoManual : guardarGastoManual}
                disabled={guardandoGasto}
                style={{
                  flex: 1,
                  padding: '12px 16px',
                  backgroundColor: gastoEditandoId ? '#ff9800' : '#7b1fa2',
                  color: 'white',
                  border: 'none',
                  borderRadius: 8,
                  cursor: guardandoGasto ? 'wait' : 'pointer',
                  fontWeight: 'bold'
                }}
              >
                {guardandoGasto ? '⏳ Guardando...' : (gastoEditandoId ? '💾 Actualizar' : '💾 Guardar')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ====================== SECRETARÍA DE SALUD ====================== */

// Configuración por defecto de items de limpieza
const ITEMS_LIMPIEZA_COCINA_DIARIO_DEFAULT = ["PISOS", "PARRILLA", "PLANCHA", "VAPORIZADOR", "PREPARACIÓN", "SALSEROS", "FREIDOR", "PAPERO", "MICROONDAS"];
const ITEMS_LIMPIEZA_COCINA_SEMANAL_DEFAULT = ["CONGELADOR PAPAS", "CONGELADOR CARNE", "CONGELADOR PULPA", "GABINETE COCINA", "CAMPANA", "PAREDES", "ESTUFA", "CANECAS BASURA"];
const ITEMS_LIMPIEZA_SALON_DIARIO_DEFAULT = ["PISOS", "MESAS Y SILLAS", "SALSEROS", "BAÑOS", "LICUADORAS", "BARRA", "LAVAMANOS"];
const ITEMS_LIMPIEZA_SALON_SEMANAL_DEFAULT = ["NEVERAS GASEOSAS", "PISO ENTRADA", "COMPUTADORES", "DISPENSADOR AGUA", "VIDRIOS", "PAREDES", "TELEVISORES", "HIELERA"];

// Bimestres fijos
const BIMESTRES = [
  { inicio: 1, fin: 2, nombre: "ENERO-FEBRERO" },
  { inicio: 3, fin: 4, nombre: "MARZO-ABRIL" },
  { inicio: 5, fin: 6, nombre: "MAYO-JUNIO" },
  { inicio: 7, fin: 8, nombre: "JULIO-AGOSTO" },
  { inicio: 9, fin: 10, nombre: "SEPTIEMBRE-OCTUBRE" },
  { inicio: 11, fin: 12, nombre: "NOVIEMBRE-DICIEMBRE" }
];

// Función para obtener el bimestre de un mes
function obtenerBimestre(mes) {
  return BIMESTRES.find(b => mes >= b.inicio && mes <= b.fin);
}

// Función para obtener último día del mes
function ultimoDiaDelMes(anio, mes) {
  return new Date(anio, mes, 0).getDate();
}

// Función para obtener días del mes
function obtenerDiasDelMes(anio, mes) {
  const ultimoDia = ultimoDiaDelMes(anio, mes);
  const dias = [];
  for (let d = 1; d <= ultimoDia; d++) {
    const fecha = new Date(anio, mes - 1, d);
    dias.push({
      dia: d,
      fecha: `${anio}-${String(mes).padStart(2, '0')}-${String(d).padStart(2, '0')}`,
      diaSemana: fecha.getDay(), // 0=Dom, 1=Lun, ..., 6=Sab
      nombreDia: ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"][fecha.getDay()]
    });
  }
  return dias;
}

// Función para generar temperatura aleatoria estable
function generarTemperaturaEstable(baseTemp, variacion = 1) {
  const delta = (Math.random() - 0.5) * variacion * 2;
  return Math.round((baseTemp + delta) * 10) / 10;
}

// Función para generar hora aleatoria entre 11:30 AM y 7:00 PM (formato AM/PM)
function generarHoraAleatoria() {
  const horaBase = 11 + Math.floor(Math.random() * 8); // 11 a 18
  const minutos = Math.floor(Math.random() * 60);
  // Si es 11, asegurar que sea al menos 11:30
  const minutosFinales = horaBase === 11 ? Math.max(30, minutos) : minutos;
  // Convertir a formato AM/PM
  const hora12 = horaBase > 12 ? horaBase - 12 : horaBase;
  const periodo = horaBase >= 12 ? 'PM' : 'AM';
  return `${hora12}:${String(minutosFinales).padStart(2, '0')} ${periodo}`;
}

// Cargar configuración de Secretaría de Salud por sede
async function cargarConfigSecretariaSalud(empresaId, sedeId = null) {
  try {
    let query = supabase.from("secretaria_salud_config").select("*");
    if (empresaId) query = query.eq("empresa_id", empresaId);
    if (sedeId) query = query.eq("sede_id", sedeId);
    const { data, error } = await query;
    if (error) {
      console.error("Error cargando config secretaría salud:", error);
      return [];
    }
    return data || [];
  } catch (e) {
    console.error("Error en cargarConfigSecretariaSalud:", e);
    return [];
  }
}

// Guardar configuración de Secretaría de Salud
async function guardarConfigSecretariaSalud(config) {
  try {
    const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const payload = {
      id: (config.id && UUID_REGEX.test(config.id)) ? config.id : crypto.randomUUID(),
      sede_id: config.sedeId,
      empresa_id: config.empresaId,
      num_congeladores: config.numCongeladores || 1,
      num_refrigeradores: config.numRefrigeradores || 1,
      tiene_tanque_reserva: config.tieneTanqueReserva || false,
      items_limpieza_cocina_diario: config.itemsLimpiezaCocinaDiario || ITEMS_LIMPIEZA_COCINA_DIARIO_DEFAULT,
      items_limpieza_cocina_semanal: config.itemsLimpiezaCocinaSemanal || ITEMS_LIMPIEZA_COCINA_SEMANAL_DEFAULT,
      items_limpieza_salon_diario: config.itemsLimpiezaSalonDiario || ITEMS_LIMPIEZA_SALON_DIARIO_DEFAULT,
      items_limpieza_salon_semanal: config.itemsLimpiezaSalonSemanal || ITEMS_LIMPIEZA_SALON_SEMANAL_DEFAULT,
      // Nuevas planillas - habilitación por sede
      aplica_residuos: config.aplicaResiduos !== undefined ? config.aplicaResiduos : true,
      aplica_agua_potable: config.aplicaAguaPotable !== undefined ? config.aplicaAguaPotable : true,
      aplica_plagas: config.aplicaPlagas !== undefined ? config.aplicaPlagas : true,
      updated_at: new Date().toISOString()
    };
    
    const { data: existente } = await supabase
      .from("secretaria_salud_config")
      .select("id")
      .eq("sede_id", config.sedeId)
      .maybeSingle();
    
    if (existente) {
      payload.id = existente.id;
      const { error } = await supabase.from("secretaria_salud_config").update(payload).eq("id", existente.id);
      if (error) throw error;
    } else {
      payload.created_at = new Date().toISOString();
      const { error } = await supabase.from("secretaria_salud_config").insert([payload]);
      if (error) throw error;
    }
    return true;
  } catch (e) {
    console.error("Error guardando config secretaría salud:", e);
    return false;
  }
}

// Cargar archivos de Secretaría de Salud
async function cargarArchivosSecretariaSalud(empresaId, sedeId = null) {
  try {
    let query = supabase.from("secretaria_salud_archivos").select("*").order("created_at", { ascending: false });
    if (empresaId) query = query.eq("empresa_id", empresaId);
    if (sedeId) query = query.eq("sede_id", sedeId);
    const { data, error } = await query;
    if (error) {
      console.error("Error cargando archivos secretaría salud:", error);
      return [];
    }
    return data || [];
  } catch (e) {
    console.error("Error en cargarArchivosSecretariaSalud:", e);
    return [];
  }
}

// Subir archivo de Secretaría de Salud
async function subirArchivoSecretariaSalud(archivo, nombre, sedeId, empresaId) {
  try {
    const ext = archivo.name.split('.').pop();
    const archivoId = crypto.randomUUID();
    const path = `secretaria-salud/${sedeId}/${Date.now()}-${slugifyPathSegment(nombre)}.${ext}`;
    
    const { error: uploadError } = await supabase.storage
      .from(SUPABASE_BUCKET_DOCS)
      .upload(path, archivo);
    
    if (uploadError) throw uploadError;
    
    const { data: urlData } = supabase.storage.from(SUPABASE_BUCKET_DOCS).getPublicUrl(path);
    
    const payload = {
      id: archivoId,
      sede_id: sedeId,
      empresa_id: empresaId,
      nombre: nombre,
      archivo_url: urlData.publicUrl,
      archivo_path: path,
      archivo_nombre_original: archivo.name,
      created_at: new Date().toISOString()
    };
    
    const { error: dbError } = await supabase.from("secretaria_salud_archivos").insert([payload]);
    if (dbError) throw dbError;
    
    return payload;
  } catch (e) {
    console.error("Error subiendo archivo:", e);
    return null;
  }
}

// Eliminar archivo de Secretaría de Salud
async function eliminarArchivoSecretariaSalud(archivoId, archivoPath) {
  try {
    if (archivoPath) {
      await supabase.storage.from(SUPABASE_BUCKET_DOCS).remove([archivoPath]);
    }
    const { error } = await supabase.from("secretaria_salud_archivos").delete().eq("id", archivoId);
    if (error) throw error;
    return true;
  } catch (e) {
    console.error("Error eliminando archivo:", e);
    return false;
  }
}

