      valorPrestamo: "",
      insumo: "",
      cantidadInsumo: "",
      sedePrestamo: "",
      // Campos para Afiliación a seguridad social
      empleadoAfiliacion: "",
      epsActual: "",
      fondoPensionActual: "",
      beneficiarios: "",
      documentosAdjuntos: [],
      // Campos para liquidaciones (vacaciones, cesantías, primas, contrato)
      todosEmpleados: false,
      empleadosSeleccionados: [],
      observacionesLiquidacion: "",
      // Campos para firma de documentos por empleados
      empleadosFirma: [],
      observacionesFirma: "",
      // Campos para tarea general
